// ============================================================
// Persistent subscription visual indicator (early init for availability)
// ============================================================

// Do not cache server time when displaying subscription — always fetch to keep consistent results across devices
let _serverTimeOffsetMs = null;
let _serverTimeCachedAt = 0;
const SERVER_TIME_CACHE_MS = 0;

// Compute days left from endDate using server timestamp only (device time is not trusted).
// If nowMs is unavailable, return null (do not show locally computed days).
function calculateDaysFromEndDate(endDateISO, nowMs) {
    if (!endDateISO || nowMs == null) return null;
    const endDate = new Date(endDateISO);
    const now = new Date(nowMs);
    const diffMs = endDate.getTime() - now.getTime();
    const days = Math.ceil(diffMs / (24 * 60 * 60 * 1000));
    return days > 0 ? days : 0;
}

// Fetch subscription from Firestore and compute days (single source of truth via server time)
async function getSubscriptionFromFirestoreForDisplay() {
    try {
        if (!window.firebaseDbInstance || !window.firebaseAuthInstance?.isAuthenticated()) return null;
        const user = window.firebaseAuthInstance.getCurrentUser();
        if (!user?.uid) return null;
        // For sub-users, always read the parent/admin subscription so UI matches admin account exactly.
        const subscriptionOwnerId = (typeof getEffectiveDataOwnerId === 'function' ? getEffectiveDataOwnerId() : null) || user.uid;
        const sub = await window.firebaseDbInstance.getSubscription(subscriptionOwnerId);
        if (!sub || !sub.activated) return null;
        if (sub.lifetime) return { activated: true, lifetime: true, daysLeft: null, endDate: null };
        // Always fetch server time from Firebase (no cache) to keep days identical on laptop/phone
        let nowMs = null;
        try {
            nowMs = await window.firebaseDbInstance.getServerTimeMs(subscriptionOwnerId);
        } catch (_) {}
        const daysLeft = nowMs != null ? calculateDaysFromEndDate(sub.endDate, nowMs) : null;
        return { activated: true, lifetime: false, daysLeft, endDate: sub.endDate };
    } catch (_) {}
    return null;
}

// Update subscription indicator UI (prefer Firestore as the single source of truth)
async function updateVisualSubscriptionIndicator() {
    try {
        const bar = document.getElementById('subscriptionBar');
        const indicator = document.getElementById('subscriptionIndicator');
        const daysEl = document.getElementById('subDays');
        const labelEl = document.getElementById('subLabel');
        if (!bar || !indicator || !daysEl || !labelEl) return;
        
        const currentLang = document.documentElement.lang || currentLanguage || 'en';
        const isEn = currentLang === 'en';
        
        // Single source of truth: Firestore (fixed expiration date). Days are computed from endDate on each device.
        const firestoreSub = await getSubscriptionFromFirestoreForDisplay();
        let daysLeft = null;
        let isLifetime = false;
        
        if (firestoreSub) {
            isLifetime = firestoreSub.lifetime;
            daysLeft = firestoreSub.daysLeft;
        }
        // If the internet is offline or Firestore isn't available: do not rely on local data — show "unconfirmed"
        
        if (isLifetime) {
            bar.className = 'safe';
            indicator.className = 'subscription-indicator safe';
            daysEl.textContent = '∞';
            labelEl.textContent = typeof getText === 'function' ? getText('msg-lifetime') : (isEn ? 'Lifetime' : 'مدى الحياة');
            return;
        }
        
        if (daysLeft === null) {
            bar.className = 'inactive';
            indicator.className = 'subscription-indicator inactive';
            daysEl.textContent = '--';
            labelEl.textContent = typeof getText === 'function' ? (firestoreSub ? getText('msg-not-active') : getText('msg-unconfirmed')) : (isEn ? (firestoreSub ? 'Not Active' : 'Unconfirmed') : (firestoreSub ? 'غير مفعل' : 'غير مؤكدة'));
            return;
        }
        
        // Determine status and colors
        let statusClass = 'safe';
        let statusText = typeof getText === 'function' ? getText('msg-active') : (isEn ? 'Active' : 'نشط');
        
        if (daysLeft <= 0) {
            statusClass = 'danger';
            statusText = typeof getText === 'function' ? getText('msg-expired').replace('!', '') : (isEn ? 'Expired' : 'منتهي');
            daysEl.textContent = '0';
            labelEl.textContent = typeof getText === 'function' ? getText('msg-expired') : (isEn ? 'Expired!' : 'منتهي!');
        } else if (daysLeft <= 3) {
            statusClass = 'danger';
            statusText = typeof getText === 'function' ? getText('msg-urgent') : (isEn ? 'Urgent!' : 'عاجل!');
            daysEl.textContent = daysLeft;
            labelEl.textContent = typeof getText === 'function' ? (daysLeft === 1 ? getText('msg-day') : getText('msg-days')) : (isEn ? (daysLeft === 1 ? 'day' : 'days') : 'يوم');
        } else if (daysLeft <= 7) {
            statusClass = 'warn';
            statusText = typeof getText === 'function' ? getText('msg-expiring-soon') : (isEn ? 'Expiring Soon' : 'ينتهي قريباً');
            daysEl.textContent = daysLeft;
            labelEl.textContent = typeof getText === 'function' ? getText('msg-days') : (isEn ? 'days' : 'أيام');
        } else {
            statusClass = 'safe';
            statusText = typeof getText === 'function' ? getText('msg-active') : (isEn ? 'Active' : 'نشط');
            daysEl.textContent = daysLeft;
            labelEl.textContent = typeof getText === 'function' ? getText('msg-days') : (isEn ? 'days' : 'أيام');
        }
        
        // Apply colors
        bar.className = statusClass;
        indicator.className = `subscription-indicator ${statusClass}`;
        
        console.log('✅ Visual indicator updated successfully:', {
            daysLeft,
            statusClass,
            statusText
        });
        
    } catch (error) {
        console.error('❌ Error updating visual subscription indicator:', error);
    }
}

// Shared update function to keep settings and the visual indicator in sync
async function updateSubscriptionDisplays() {
    console.log('Updating both subscription displays...');
    if (typeof updateSettingsLicenseDisplay === 'function') {
        await updateSettingsLicenseDisplay();
    }
    updateVisualSubscriptionIndicator();
    console.log('Both displays updated successfully');
}

// Lazy-load Super Admin module to reduce initial bundle execution cost.
let __superAdminModulePromise = null;
async function ensureSuperAdminModuleLoaded() {
    try {
        if (window.superAdminDashboard) return true;
        if (__superAdminModulePromise) return __superAdminModulePromise;
        __superAdminModulePromise = new Promise((resolve, reject) => {
            const existing = document.querySelector('script[data-super-admin-module="1"]');
            if (existing) {
                existing.addEventListener('load', () => resolve(true), { once: true });
                existing.addEventListener('error', () => reject(new Error('Failed to load super-admin.js')), { once: true });
                return;
            }
            const s = document.createElement('script');
            s.src = '/super-admin.js?v=' + encodeURIComponent(String(Number(window.__APP_VERSION_CODE || 0) || 61));
            s.async = true;
            s.defer = true;
            s.dataset.superAdminModule = '1';
            s.onload = () => resolve(true);
            s.onerror = () => reject(new Error('Failed to load super-admin.js'));
            document.body.appendChild(s);
        });
        return __superAdminModulePromise;
    } catch (_) {
        return false;
    }
}

function hideSuperAdminLink() {
    if (window.superAdminDashboard && typeof window.superAdminDashboard.hideSuperAdminLink === 'function') {
        window.superAdminDashboard.hideSuperAdminLink();
        return;
    }
    const superAdminNav = document.querySelector('.nav-item.super-admin-only');
    if (superAdminNav) superAdminNav.style.display = 'none';
}

// Super-admin utility helpers for controlled rollout (optional UI wiring later)
window.saSetFeatureFlagConfig = async function(flagKey, config) {
    if (!window.firebaseDbInstance || typeof window.firebaseDbInstance.setFeatureFlagConfig !== 'function') {
        throw new Error('Feature flag control is not available');
    }
    return await window.firebaseDbInstance.setFeatureFlagConfig(flagKey, config || {});
};

window.saGetFeatureFlags = async function() {
    if (!window.firebaseDbInstance || typeof window.firebaseDbInstance.getFeatureFlagsControl !== 'function') {
        return {};
    }
    return await window.firebaseDbInstance.getFeatureFlagsControl();
};

function getRuntimeAppVersionCode() {
    try {
        if (window.__APP_BUILD_META && window.__APP_BUILD_META.scriptVersion != null) {
            return Number(window.__APP_BUILD_META.scriptVersion || 0) || 0;
        }
        const scripts = Array.from(document.querySelectorAll('script[src]'));
        for (const s of scripts) {
            const src = String(s.getAttribute('src') || '');
            const m = src.match(/\/script\.js\?v=(\d+)/i);
            if (m) return Number(m[1] || 0) || 0;
        }
    } catch (_) {}
    return 0;
}

window.__APP_VERSION_CODE = getRuntimeAppVersionCode();
window.__APP_RELEASED_VERSION_CODE = 0;
window.__APP_VERSION_LABEL = window.__APP_VERSION_LABEL || '';
window.__APP_RELEASED_VERSION_LABEL = window.__APP_RELEASED_VERSION_LABEL || '';
try {
    const pendingReloadRaw = sessionStorage.getItem('app.update.reloadPending');
    if (pendingReloadRaw) {
        const pendingReload = JSON.parse(pendingReloadRaw);
        const localBuild = Number(window.__APP_VERSION_CODE || 0) || 0;
        if (pendingReload && pendingReload.targetBuild && localBuild >= Number(pendingReload.targetBuild)) {
            if (pendingReload.targetLabel) {
                window.__APP_VERSION_LABEL = String(pendingReload.targetLabel);
                if (window.__APP_BUILD_META) window.__APP_BUILD_META.appVersion = String(pendingReload.targetLabel);
            }
            sessionStorage.removeItem('app.update.reloadPending');
        }
    }
} catch (_) {}
// Ensure semantic versioning is used on the client by default.
// Start from 1.0.0 when no explicit label is provided.
try {
    const _semverRe = /^\d+\.\d+\.\d+$/;
    if (!String(window.__APP_VERSION_LABEL || '').trim() || !_semverRe.test(String(window.__APP_VERSION_LABEL || '').trim())) {
        window.__APP_VERSION_LABEL = '1.0.0';
    }
} catch (_) {}

const __SEMVER_RE = /^\d+\.\d+\.\d+$/;

function isValidSemverLabel(label) {
    return __SEMVER_RE.test(String(label || '').trim());
}

function normalizeSemverLabelClient(raw) {
    if (raw == null) return '';
    let s = String(raw).trim();
    if (!s) return '';
    if (/^v/i.test(s)) s = s.slice(1);
    if (isValidSemverLabel(s)) return s;
    const parts = s.match(/^(\d+)(?:\.(\d+))?(?:\.(\d+))?$/);
    if (!parts) return '';
    const candidate = `${parts[1]}.${parts[2] != null ? parts[2] : '0'}.${parts[3] != null ? parts[3] : '0'}`;
    return isValidSemverLabel(candidate) ? candidate : '';
}

function compareSemverLabels(a, b) {
    if (!isValidSemverLabel(a) || !isValidSemverLabel(b)) return 0;
    const pa = a.split('.').map((n) => Number(n));
    const pb = b.split('.').map((n) => Number(n));
    for (let i = 0; i < 3; i++) {
        if (pa[i] > pb[i]) return 1;
        if (pa[i] < pb[i]) return -1;
    }
    return 0;
}

function bumpPatchSemverLabel(label) {
    const normalized = normalizeSemverLabelClient(label) || '1.0.0';
    const parts = normalized.split('.').map((n) => Number(n));
    parts[2] = (Number(parts[2]) || 0) + 1;
    return parts.join('.');
}

function suggestNextPublishVersion(state) {
    const released = normalizeSemverLabelClient(
        (state && state.releasedVersionLabel) || window.__APP_RELEASED_VERSION_LABEL || '1.0.0'
    ) || '1.0.0';
    const pending = normalizeSemverLabelClient(state && state.pendingVersionLabel);
    const internal = state && state.channels && state.channels.internal
        ? normalizeSemverLabelClient(state.channels.internal.versionLabel)
        : '';
    for (const candidate of [pending, internal]) {
        if (candidate && compareSemverLabels(candidate, released) > 0) return candidate;
    }
    return bumpPatchSemverLabel(released);
}

function mapPublishUpdateError(err) {
    const code = String(err && err.code || '');
    const msg = String(err && err.message || err || '').trim();
    if (/Please enter a valid version number/i.test(msg)) return msg;
    if (/versionLabel must be semantic/i.test(msg)) return 'Please enter a valid version number like 1.0.1';
    if (/greater than current/i.test(msg) || /must be higher than the current release/i.test(msg)) {
        return 'The new version must be higher than the current release. Try increasing the patch number (for example 1.0.1).';
    }
    if (/No pending version|No update is ready to publish/i.test(msg)) {
        return 'No update is ready to publish yet. Deploy your changes to TEST first.';
    }
    if (/not authorized|not allowed to publish|Super admin access/i.test(msg) || code === 'permission-denied') {
        return 'Super admin access is required to release updates.';
    }
    if (/Production deploy required|Promote TEST build/i.test(msg)) return msg;
    if (/Production deploy failed/i.test(msg)) return msg;
    if (/Please select at least one user/i.test(msg)) return msg;
    if (/Invalid update target/i.test(msg)) return 'Invalid update target. Please try again.';
    if (msg) return msg;
    return 'Could not publish the update. Please try again.';
}

function syncPublishVersionInput(state) {
    try {
        refreshAppUpdatePublishControls(state || window.__lastAppUpdateControlState || {});
    } catch (_) {}
}

function canShowAppUpdatePublishControls() {
    return isCurrentSessionSuperAdmin();
}

function refreshAppUpdatePublishControls(state) {
    try {
        const panel = document.getElementById('testPublishControls');
        const selectedBtn = document.getElementById('testPublishSelectedBtn');
        if (!panel) return;

        const input = document.getElementById('testPublishVersionInput');
        if (input && document.activeElement !== input) {
            input.value = suggestNextPublishVersion(state || {});
            input.placeholder = '1.0.1';
        }
        updateAppUpdateSelectedCount();
        if (selectedBtn) {
            selectedBtn.disabled = !(window.__appUpdateSelectedUserIds && window.__appUpdateSelectedUserIds.size > 0);
        }
        if (canShowAppUpdatePublishControls() && !window.__appUpdateTargetUsersLoaded) {
            loadAppUpdateTargetUsers('');
        }

        // Publish controls stay in DOM for logic, but are never shown inside Settings.
        panel.style.display = 'none';
        panel.setAttribute('hidden', 'hidden');
        panel.setAttribute('aria-hidden', 'true');
    } catch (_) {}
}

function updateAppUpdateSelectedCount() {
    const countEl = document.getElementById('testPublishSelectedCount');
    const selectedBtn = document.getElementById('testPublishSelectedBtn');
    const count = window.__appUpdateSelectedUserIds ? window.__appUpdateSelectedUserIds.size : 0;
    if (countEl) countEl.textContent = `${count} user${count === 1 ? '' : 's'} selected`;
    if (selectedBtn) selectedBtn.disabled = count <= 0;
}

function escapeAppUpdateHtml(str) {
    if (str == null || str === '') return '';
    return String(str)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;');
}

function renderAppUpdateTargetUsers(users) {
    const root = document.getElementById('testPublishUserResults');
    if (!root) return;
    const rows = Array.isArray(users) ? users : [];
    window.__appUpdateTargetUsersCache = rows;
    if (!rows.length) {
        root.innerHTML = '<p class="settings-hint">No users found.</p>';
        return;
    }
    root.innerHTML = rows.map((u) => {
        const uid = String(u.uid || u.id || '').trim();
        const checked = window.__appUpdateSelectedUserIds && window.__appUpdateSelectedUserIds.has(uid) ? 'checked' : '';
        const name = u.fullName || u.name || 'User';
        const account = u.email || uid;
        const version = u.versionLabel || (u.versionCode ? `build ${u.versionCode}` : '-');
        const status = u.status || u.updateStatus || '-';
        return `
            <label class="app-update-user-row" role="option">
                <input type="checkbox" data-app-update-target-uid="${escapeAppUpdateHtml(uid)}" ${checked}>
                <span class="app-update-user-row__main">
                    <span class="app-update-user-row__name">${escapeAppUpdateHtml(name)}</span>
                    <span class="app-update-user-row__meta">${escapeAppUpdateHtml(account)}</span>
                </span>
                <span class="app-update-user-row__version">${escapeAppUpdateHtml(version)}</span>
                <span class="app-update-user-row__status">${escapeAppUpdateHtml(status)}</span>
            </label>
        `;
    }).join('');
    root.querySelectorAll('input[type="checkbox"][data-app-update-target-uid]').forEach((el) => {
        el.addEventListener('change', (e) => {
            const uid = String(e.target.getAttribute('data-app-update-target-uid') || '').trim();
            if (!uid) return;
            if (!window.__appUpdateSelectedUserIds) window.__appUpdateSelectedUserIds = new Set();
            if (e.target.checked) window.__appUpdateSelectedUserIds.add(uid);
            else window.__appUpdateSelectedUserIds.delete(uid);
            updateAppUpdateSelectedCount();
        });
    });
    updateAppUpdateSelectedCount();
}

async function loadAppUpdateTargetUsers(searchTerm) {
    try {
        if (!window.firebaseDbInstance || typeof window.firebaseDbInstance.listAppUpdateTargetUsersSecure !== 'function') {
            renderAppUpdateTargetUsers([]);
            return;
        }
        const data = await window.firebaseDbInstance.listAppUpdateTargetUsersSecure(String(searchTerm || ''), 100);
        window.__appUpdateTargetUsersLoaded = true;
        renderAppUpdateTargetUsers((data && data.users) || []);
    } catch (_) {
        renderAppUpdateTargetUsers([]);
    }
}

function getValidatedPublishVersionLabel() {
    const versionInput = document.getElementById('testPublishVersionInput');
    const rawVersion = String(versionInput && versionInput.value || '').trim();
    const versionLabel = normalizeSemverLabelClient(rawVersion);
    if (!versionLabel) {
        showNotification('Please enter a valid version number like 1.0.1', 'error', 5000);
        if (versionInput) versionInput.focus();
        return null;
    }
    const control = window.__lastAppUpdateControlState || null;
    const releasedLabel = normalizeSemverLabelClient(
        (control && control.releasedVersionLabel) || window.__APP_RELEASED_VERSION_LABEL || '1.0.0'
    );
    if (releasedLabel && compareSemverLabels(versionLabel, releasedLabel) <= 0) {
        showNotification(
            'The new version must be higher than the current release. Try increasing the patch number (for example 1.0.1).',
            'error',
            5000
        );
        if (versionInput) versionInput.focus();
        return null;
    }
    return versionLabel;
}

async function executeAppUpdatePublish(options) {
    if (!canShowAppUpdatePublishControls()) {
        showNotification('You are not allowed to publish updates from this account.', 'error', 5000);
        return false;
    }
    const opts = options || {};
    const versionLabel = getValidatedPublishVersionLabel();
    if (!versionLabel) return false;

    if (!window.firebaseDbInstance || typeof window.firebaseDbInstance.adminReleaseAppUpdateSecure !== 'function') {
        showNotification('Publishing is not available right now. Please refresh and try again.', 'error', 4000);
        return false;
    }

    const liveControl = await window.firebaseDbInstance.getAppUpdateControl();
    window.__lastAppUpdateControlState = liveControl || window.__lastAppUpdateControlState || {};
    const internal = (liveControl && liveControl.channels && liveControl.channels.internal) ? liveControl.channels.internal : null;
    const pendingCode = internal && internal.versionCode
        ? internal.versionCode
        : (liveControl && liveControl.pendingVersionCode ? liveControl.pendingVersionCode : getRuntimeAppVersionCode());
    if (!pendingCode) {
        showNotification('No update is ready to publish yet. Deploy your changes to TEST first.', 'error', 5000);
        return false;
    }

    const releasePayload = {
        versionCode: pendingCode,
        versionLabel: versionLabel,
        target: opts.target === 'selected_users' ? 'selected_users' : 'all',
        build: getBuildPayloadForRelease(versionLabel)
    };
    if (releasePayload.target === 'selected_users') {
        releasePayload.userIds = Array.from(window.__appUpdateSelectedUserIds || []);
        if (!releasePayload.userIds.length) {
            showNotification('Please select at least one user for a targeted update.', 'error', 4000);
            return false;
        }
    }

    showNotification('Publishing update...', 'info', 2000);
    let result = null;
    if (typeof window.firebaseDbInstance.testPublishToAllUsersSecure === 'function') {
        result = await window.firebaseDbInstance.testPublishToAllUsersSecure(releasePayload);
    } else {
        result = await window.firebaseDbInstance.adminReleaseAppUpdateSecure(releasePayload);
    }

    window.__APP_RELEASED_VERSION_LABEL = versionLabel;
    const versionInput = document.getElementById('testPublishVersionInput');
    if (versionInput) versionInput.value = bumpPatchSemverLabel(versionLabel);

    const selectedCount = Number(result && result.selectedUserCount) || (releasePayload.userIds ? releasePayload.userIds.length : 0);
    const target = String(result && result.target || releasePayload.target || 'all');
    if (target === 'selected_users' && selectedCount > 0) {
        showNotification(`Update published to ${selectedCount} selected user${selectedCount === 1 ? '' : 's'}.`, 'success', 4500);
    } else {
        showNotification('Update published to all users.', 'success', 4500);
    }
    return true;
}

function refreshTestPublishButton() {
    refreshAppUpdatePublishControls(window.__lastAppUpdateControlState || {});
}

function setupTestPublishAllButton() {
    try {
        if (window.__testPublishAllBound) return;
        if (!document.getElementById('testPublishAllBtn')) return;
        window.__testPublishAllBound = true;
        if (!window.__appUpdateSelectedUserIds) window.__appUpdateSelectedUserIds = new Set();
        refreshAppUpdatePublishControls(window.__lastAppUpdateControlState || {});

        const searchInput = document.getElementById('testPublishUserSearch');
        let searchTimer = null;
        if (searchInput) {
            searchInput.addEventListener('input', () => {
                clearTimeout(searchTimer);
                searchTimer = setTimeout(() => {
                    loadAppUpdateTargetUsers(searchInput.value || '');
                }, 250);
            });
        }

        const selectVisibleBtn = document.getElementById('testPublishSelectVisibleBtn');
        if (selectVisibleBtn) {
            selectVisibleBtn.addEventListener('click', () => {
                (window.__appUpdateTargetUsersCache || []).forEach((u) => {
                    const uid = String(u.uid || u.id || '').trim();
                    if (uid) window.__appUpdateSelectedUserIds.add(uid);
                });
                renderAppUpdateTargetUsers(window.__appUpdateTargetUsersCache || []);
            });
        }

        const clearBtn = document.getElementById('testPublishClearSelectedBtn');
        if (clearBtn) {
            clearBtn.addEventListener('click', () => {
                window.__appUpdateSelectedUserIds.clear();
                renderAppUpdateTargetUsers(window.__appUpdateTargetUsersCache || []);
            });
        }

        const selectedBtn = document.getElementById('testPublishSelectedBtn');
        if (selectedBtn) {
            selectedBtn.addEventListener('click', async () => {
                const count = window.__appUpdateSelectedUserIds ? window.__appUpdateSelectedUserIds.size : 0;
                if (!count) return;
                const ok = window.confirm(`Publish this update to ${count} selected user${count === 1 ? '' : 's'}?`);
                if (!ok) return;
                try {
                    await executeAppUpdatePublish({ target: 'selected_users' });
                } catch (err) {
                    showNotification(mapPublishUpdateError(err), 'error', 5000);
                }
            });
        }

        const allBtn = document.getElementById('testPublishAllBtn');
        if (allBtn) {
            allBtn.addEventListener('click', async () => {
                const ok = window.confirm('Publish this update to all users? Everyone will receive it after refresh.');
                if (!ok) return;
                try {
                    await executeAppUpdatePublish({ target: 'all' });
                } catch (err) {
                    showNotification(mapPublishUpdateError(err), 'error', 5000);
                }
            });
        }
    } catch (_) {}
}

function __updateRolloutList(raw) {
    return Array.isArray(raw) ? raw.map((v) => String(v || '').trim()).filter(Boolean) : [];
}

function __updateStableBucket(input) {
    const s = String(input || '').trim();
    if (!s) return 0;
    let hash = 0;
    for (let i = 0; i < s.length; i++) {
        hash = ((hash << 5) - hash) + s.charCodeAt(i);
        hash |= 0;
    }
    return Math.abs(hash % 100);
}

function getLocalBuildMeta() {
    const meta = (window.__APP_BUILD_META && typeof window.__APP_BUILD_META === 'object')
        ? window.__APP_BUILD_META
        : {};
    return {
        buildId: String(meta.buildId || meta.scriptVersion || window.__APP_VERSION_CODE || ''),
        appVersion: String(meta.appVersion || window.__APP_VERSION_LABEL || ''),
        scriptVersion: Number(meta.scriptVersion || window.__APP_VERSION_CODE || 0) || 0,
        cssVersion: Number(meta.cssVersion || 0) || 0,
        deployedAt: String(meta.deployedAt || '')
    };
}

function getCurrentClientEnv() {
    return window.__APP_ENV_IS_TEST ? 'test' : 'prod';
}

function releaseMatchesCurrentHosting(state) {
    const build = (state && state.releasedBuild && typeof state.releasedBuild === 'object')
        ? state.releasedBuild
        : {};
    const releaseEnv = String(build.env || '').trim().toLowerCase();
    if (!releaseEnv) return true;
    return releaseEnv === getCurrentClientEnv();
}

function getReleasedBuildMeta(state) {
    const s = state || window.__lastAppUpdateControlState || {};
    const build = (s.releasedBuild && typeof s.releasedBuild === 'object') ? s.releasedBuild : {};
    const scriptVersion = Math.max(
        0,
        Number(build.scriptVersion || s.releasedVersionCode || 0) || 0
    );
    return {
        buildId: String(build.buildId || scriptVersion || ''),
        appVersion: String(build.appVersion || s.releasedVersionLabel || ''),
        scriptVersion,
        cssVersion: Number(build.cssVersion || 0) || 0,
        deployedAt: String(build.deployedAt || ''),
        env: String(build.env || '').trim().toLowerCase()
    };
}

function clientNeedsBuildUpdate(state) {
    if (!releaseMatchesCurrentHosting(state)) return false;
    const released = getReleasedBuildMeta(state);
    const local = getLocalBuildMeta();
    const localCode = Number(local.scriptVersion || window.__APP_VERSION_CODE || 0) || 0;
    const releasedCode = Number(released.scriptVersion || 0) || 0;
    if (releasedCode > localCode) return true;

    const releasedLabel = normalizeSemverLabelClient(released.appVersion || (state && state.releasedVersionLabel));
    const localLabel = normalizeSemverLabelClient(local.appVersion || window.__APP_VERSION_LABEL);
    if (releasedLabel && localLabel && compareSemverLabels(releasedLabel, localLabel) > 0) {
        return true;
    }
    return false;
}

async function clearAppUpdateCaches() {
    try {
        if ('caches' in window) {
            const keys = await caches.keys();
            await Promise.all(keys.map((key) => caches.delete(key)));
        }
    } catch (_) {}
    try {
        if ('serviceWorker' in navigator) {
            const regs = await navigator.serviceWorker.getRegistrations();
            await Promise.all(regs.map((reg) => reg.unregister()));
        }
    } catch (_) {}
}

async function hardReloadForAppUpdate(state) {
    if (window.__appUpdateReloadInFlight) return;
    window.__appUpdateReloadInFlight = true;
    const released = getReleasedBuildMeta(state);
    try {
        await clearAppUpdateCaches();
    } catch (_) {}
    try {
        sessionStorage.setItem('app.update.reloadPending', JSON.stringify({
            targetBuild: released.scriptVersion,
            targetLabel: released.appVersion || (state && state.releasedVersionLabel) || '',
            at: Date.now()
        }));
    } catch (_) {}
    const url = new URL(window.location.href);
    url.searchParams.set('__app_build', String(released.scriptVersion || Date.now()));
    url.searchParams.set('_', String(Date.now()));
    window.location.replace(url.toString());
}
window.hardReloadForAppUpdate = hardReloadForAppUpdate;

function dismissAppUpdateReloadBanner() {
    const banner = document.getElementById('appUpdateReloadBanner');
    if (banner) banner.style.display = 'none';
}

function showAppUpdateReloadBanner(state, opts) {
    // User-facing popup removed: keep updates in Settings only.
    dismissAppUpdateReloadBanner();
    try {
        renderSimpleUpdateSettingsStatus(state || window.__lastAppUpdateControlState || null);
    } catch (_) {}
}
window.showAppUpdateReloadBanner = showAppUpdateReloadBanner;
window.dismissAppUpdateReloadBanner = dismissAppUpdateReloadBanner;

function renderAppBuildDebugPanel(state) {
    const panel = document.getElementById('appBuildDebugPanel');
    if (!panel) return;
    // Build/debug info belongs in Super Admin App Release — not Settings.
    panel.style.display = 'none';
}

function getBuildPayloadForRelease(versionLabelOverride) {
    const meta = getLocalBuildMeta();
    return {
        buildId: String(meta.buildId || meta.scriptVersion || ''),
        appVersion: String(versionLabelOverride || meta.appVersion || window.__APP_VERSION_LABEL || ''),
        scriptVersion: Number(meta.scriptVersion || window.__APP_VERSION_CODE || 0) || 0,
        cssVersion: Number(meta.cssVersion || 0) || 0,
        deployedAt: String(meta.deployedAt || new Date().toISOString()),
        env: String((window.__APP_ENV_IS_TEST ? 'test' : 'prod'))
    };
}

function __isEligibleForReleasedUpdate(state) {
    if (!state) return false;
    if (isCurrentSessionSuperAdmin()) return true;
    const rollout = (state && state.rollout && typeof state.rollout === 'object') ? state.rollout : {};
    const mode = String(rollout.mode || 'global').toLowerCase();
    const allowIds = __updateRolloutList(rollout.userIds || rollout.ownerIds || rollout.tenantIds || []);
    const uid = String((typeof getCurrentUserId === 'function' ? getCurrentUserId() : '') || (currentUser && currentUser.uid) || '').trim();
    const ownerId = String((typeof getEffectiveDataOwnerId === 'function' ? getEffectiveDataOwnerId() : uid) || uid).trim();
    const tenantId = String((currentUser && currentUser.tenantId) || ownerId || uid).trim();
    if (allowIds.some((id) => id === uid || id === ownerId || id === tenantId)) return true;
    if (mode === 'allow_list' || mode === 'targeted' || mode === 'selected') return false;
    const rolloutPercent = Math.max(0, Math.min(100, Number(rollout.rolloutPercent || 100) || 100));
    if (rolloutPercent >= 100) return true;
    return __updateStableBucket(ownerId || uid || tenantId) < rolloutPercent;
}

async function reportCurrentClientVersionStatus(status = 'installed', errorMessage = '') {
    try {
        if (!window.firebaseAuthInstance || !window.firebaseAuthInstance.isAuthenticated || !window.firebaseAuthInstance.isAuthenticated()) return;
        if (!window.firebaseDbInstance || typeof window.firebaseDbInstance.reportClientUpdateStatusSecure !== 'function') return;
        const versionCode = Number(window.__APP_VERSION_CODE || 0) || 0;
        if (!versionCode) return;
        const key = `${String(status)}:${versionCode}:${String(errorMessage || '')}`;
        if (window.__lastReportedUpdateStatusKey === key) return;
        window.__lastReportedUpdateStatusKey = key;
        await window.firebaseDbInstance.reportClientUpdateStatusSecure({
            currentVersionCode: versionCode,
            currentVersionLabel: String(window.__APP_VERSION_LABEL || getLocalBuildMeta().appVersion || '').trim(),
            status: String(status || 'installed'),
            errorMessage: String(errorMessage || '').slice(0, 300),
            source: 'web_client',
            clientTs: Date.now()
        });
    } catch (_) {}
}

function formatSettingsAppVersionLabel(label) {
    const normalized = normalizeSemverLabelClient(label);
    return normalized || '';
}

function renderSimpleUpdateSettingsStatus(state) {
    try {
        const currentEl = document.getElementById('settingsCurrentVersion');
        const latestEl = document.getElementById('settingsLatestVersion');
        const statusEl = document.getElementById('settingsUpdateStatus');
        const updateBtn = document.getElementById('settingsUpdateNowBtn');
        if (!currentEl || !latestEl || !statusEl || !updateBtn) return;
        const isAdmin = isCurrentSessionSuperAdmin();
        const currentNumeric = Number(window.__APP_VERSION_CODE || 0) || 0;
        const releasedMeta = getReleasedBuildMeta(state);
        const latestNumeric = Number(releasedMeta.scriptVersion || state && state.releasedVersionCode || 0) || 0;
        const currentLabel = formatSettingsAppVersionLabel(getLocalBuildMeta().appVersion || window.__APP_VERSION_LABEL || '');
        const latestLabel = formatSettingsAppVersionLabel(releasedMeta.appVersion || (state && state.releasedVersionLabel) || window.__APP_RELEASED_VERSION_LABEL || '');

        if (isAdmin) {
            currentEl.textContent = `${currentLabel || '-'} (build ${currentNumeric || '-'})`;
            latestEl.textContent = `${latestLabel || '-'} (build ${latestNumeric || '-'})`;
        } else {
            currentEl.textContent = currentLabel || '-';
            latestEl.textContent = latestLabel || '-';
        }
        const currentWrap = currentEl.closest('.sa-minimal-count');
        const latestWrap = latestEl.closest('.sa-minimal-count');
        if (currentWrap) currentWrap.style.display = isAdmin ? '' : 'none';
        if (latestWrap) latestWrap.style.display = isAdmin ? '' : 'none';

        const isValidSemverClient = isValidSemverLabel;
        const compareSemverClient = compareSemverLabels;

        const hasUpdate = clientNeedsBuildUpdate(state);
        const eligibleForUpdate = __isEligibleForReleasedUpdate(state);
        const canUpdateNow = hasUpdate && eligibleForUpdate;
        const releaseEnvMismatch = !releaseMatchesCurrentHosting(state);
        const releaseMeta = getReleasedBuildMeta(state);
        const labelOnlyUpdate = !hasUpdate && eligibleForUpdate && releaseMeta.scriptVersion > 0
            && releaseMeta.scriptVersion <= currentNumeric
            && isValidSemverClient(latestLabel) && isValidSemverClient(currentLabel)
            && compareSemverClient(latestLabel, currentLabel) > 0;

        if ((!latestLabel && !latestNumeric) || (!currentLabel && !currentNumeric)) {
            statusEl.textContent = isAdmin ? 'Status: checking...' : 'Checking for updates...';
        } else if (releaseEnvMismatch && eligibleForUpdate) {
            statusEl.textContent = isAdmin
                ? (getCurrentClientEnv() === 'prod' ? 'Status: Version assigned — waiting for production deploy' : 'Status: Release is for another environment')
                : 'Update will be available soon';
        } else if (currentLabel && latestLabel && ((isValidSemverClient(currentLabel) && compareSemverClient(currentLabel, latestLabel) > 0) || (currentNumeric > latestNumeric && !isValidSemverClient(currentLabel)))) {
            statusEl.textContent = isAdmin ? 'Status: Test build active' : 'You have the latest version';
        } else if (canUpdateNow) {
            statusEl.textContent = isAdmin ? 'Status: New update available' : 'An update is available';
        } else if (labelOnlyUpdate && getCurrentClientEnv() === 'prod') {
            statusEl.textContent = isAdmin ? 'Status: Version assigned — waiting for production deploy' : 'Update will be available soon';
        } else if (hasUpdate && !eligibleForUpdate) {
            statusEl.textContent = isAdmin ? 'Status: Up to date' : 'You have the latest version';
        } else {
            statusEl.textContent = isAdmin ? 'Status: Up to date' : 'You have the latest version';
        }
        try { updateBtn.style.display = canUpdateNow ? '' : 'none'; } catch (_) {}
        try { updateBtn.disabled = !canUpdateNow; } catch (_) {}
        try { updateBtn.classList.toggle('update-available', !!canUpdateNow); } catch (_) {}
        try { renderAppBuildDebugPanel(state); } catch (_) {}
    } catch (_) {}
}

function setupSimpleUpdateNowButton() {
    try {
        if (window.__simpleUpdateNowBound) return;
        const btn = document.getElementById('settingsUpdateNowBtn');
        if (!btn) return;
        // Show button hidden until an eligible update is detected.
        try { btn.style.display = 'none'; } catch (_) {}
        try { btn.disabled = true; } catch (_) {}
        try { renderSimpleUpdateSettingsStatus({ releasedVersionCode: Number(window.__APP_RELEASED_VERSION_CODE || 0) || 0 }); } catch (_) {}
        window.__simpleUpdateNowBound = true;
        btn.addEventListener('click', () => {
            try {
                showNotification('Applying update...', 'info', 1500);
            } catch (_) {}
            hardReloadForAppUpdate(window.__lastAppUpdateControlState || null);
        });
    } catch (_) {}
}

function monitorReleasedAppVersion() {
    try {
        if (!window.firebaseDbInstance || typeof window.firebaseDbInstance.subscribeAppUpdateControl !== 'function') return;
        if (window.__appUpdateMonitorUnsub) return;
        setupSimpleUpdateNowButton();
        try { setupTestPublishAllButton(); } catch (_) {}
        window.__appUpdateMonitorUnsub = window.firebaseDbInstance.subscribeAppUpdateControl(function (state) {
            window.__lastAppUpdateControlState = state || {};
            renderSimpleUpdateSettingsStatus(state || {});
            syncPublishVersionInput(state || {});
            const releasedMeta = getReleasedBuildMeta(state || {});
            const released = Number(releasedMeta.scriptVersion || state && state.releasedVersionCode || 0) || 0;
            window.__APP_RELEASED_VERSION_CODE = released;
            window.__APP_RELEASED_VERSION_LABEL = String(releasedMeta.appVersion || (state && state.releasedVersionLabel) || '');
            const current = Number(window.__APP_VERSION_CODE || 0) || 0;
            if (!released || !current) return;
            const needsUpdate = clientNeedsBuildUpdate(state) && __isEligibleForReleasedUpdate(state);
            try {
                reportCurrentClientVersionStatus(needsUpdate ? 'update_available' : 'installed', '');
            } catch (_) {}
            if (needsUpdate) {
                dismissAppUpdateReloadBanner();
            }
        });
    } catch (_) {}
}

// ============================================================
// System Error Monitoring (client-side -> Firestore)
// ============================================================
const __systemErrorRecentMap = new Map();
let __systemErrorLoggingInFlight = false;
let __obsLastHeartbeatAt = 0;
let __obsInFlight = false;

function __trimLogString(value, maxLen) {
    return String(value == null ? '' : value).slice(0, maxLen);
}

function __safeSerializeDetails(details) {
    try {
        if (details == null) return null;
        if (typeof details === 'string') return { value: __trimLogString(details, 2000) };
        if (typeof details === 'number' || typeof details === 'boolean') return { value: details };
        return JSON.parse(JSON.stringify(details));
    } catch (_) {
        return { value: __trimLogString(String(details), 2000) };
    }
}

function __normalizeLogErrorMessage(errorLike) {
    try {
        if (errorLike && typeof errorLike === 'object') {
            if (errorLike.message) return __trimLogString(errorLike.message, 4000);
            if (errorLike.code) return __trimLogString(errorLike.code, 4000);
        }
        return __trimLogString(String(errorLike || 'Unknown error'), 4000);
    } catch (_) {
        return 'Unknown error';
    }
}

async function logSystemError(errorPayload) {
    try {
        if (__systemErrorLoggingInFlight) return;
        if (!window.firebaseDbInstance || typeof window.firebaseDbInstance.logSystemError !== 'function') return;
        if (!window.firebaseAuthInstance || !window.firebaseAuthInstance.isAuthenticated || !window.firebaseAuthInstance.isAuthenticated()) return;

        const authUser = window.firebaseAuthInstance.getCurrentUser ? window.firebaseAuthInstance.getCurrentUser() : null;
        if (!authUser || !authUser.uid) return;

        const message = __normalizeLogErrorMessage(errorPayload && errorPayload.message);
        const type = __trimLogString((errorPayload && errorPayload.type) || 'runtime_error', 120);
        const dedupeKey = `${type}|${message}|${window.location.pathname}|${window.location.hash}`;
        const now = Date.now();
        const lastTs = __systemErrorRecentMap.get(dedupeKey) || 0;
        if (now - lastTs < 15000) return; // prevent log spam
        __systemErrorRecentMap.set(dedupeKey, now);
        if (__systemErrorRecentMap.size > 400) {
            const firstKey = __systemErrorRecentMap.keys().next().value;
            if (firstKey) __systemErrorRecentMap.delete(firstKey);
        }

        const actorRole = (typeof currentUser !== 'undefined' && currentUser && currentUser.role) ? currentUser.role : null;
        const payload = {
            type,
            source: __trimLogString((errorPayload && errorPayload.source) || 'web_client', 120),
            message,
            page: __trimLogString(`${window.location.pathname || ''}${window.location.hash || ''}`, 600),
            stack: __trimLogString((errorPayload && errorPayload.stack) || '', 12000),
            details: __safeSerializeDetails(errorPayload && errorPayload.details),
            actorRole: actorRole,
            userAgent: __trimLogString((typeof navigator !== 'undefined' ? navigator.userAgent : ''), 1000),
            language: __trimLogString((typeof navigator !== 'undefined' ? navigator.language : ''), 80),
            platform: __trimLogString((typeof navigator !== 'undefined' ? navigator.platform : ''), 120),
            clientTs: now
        };

        __systemErrorLoggingInFlight = true;
        await window.firebaseDbInstance.logSystemError(payload);
        trackObservabilityEvent({
            eventName: payload.type || 'system_error',
            category: 'error',
            source: payload.source || 'web_client',
            success: false,
            route: payload.page || '',
            clientTs: now
        });
    } catch (_) {
        // Never throw from telemetry pipeline
    } finally {
        __systemErrorLoggingInFlight = false;
    }
}

async function trackObservabilityEvent(eventPayload) {
    try {
        if (__obsInFlight) return;
        if (!window.firebaseDbInstance || typeof window.firebaseDbInstance.trackObservabilityEventSecure !== 'function') return;
        if (!window.firebaseAuthInstance || !window.firebaseAuthInstance.isAuthenticated || !window.firebaseAuthInstance.isAuthenticated()) return;
        __obsInFlight = true;
        await window.firebaseDbInstance.trackObservabilityEventSecure(eventPayload || {});
    } catch (_) {
        // Keep observability non-blocking
    } finally {
        __obsInFlight = false;
    }
}

if (typeof window !== 'undefined') {
    window.logSystemError = logSystemError;
    window.trackObservabilityEvent = trackObservabilityEvent;
}

(function installGlobalErrorMonitoring() {
    if (typeof window === 'undefined') return;
    if (window.__globalErrorMonitoringInstalled) return;
    window.__globalErrorMonitoringInstalled = true;

    window.addEventListener('error', function (event) {
        try {
            const err = event && event.error;
            logSystemError({
                type: 'javascript_error',
                source: 'window.onerror',
                message: err && err.message ? err.message : (event && event.message) || 'Unhandled JS error',
                stack: err && err.stack ? err.stack : '',
                details: {
                    filename: event && event.filename ? event.filename : null,
                    lineno: event && event.lineno ? event.lineno : null,
                    colno: event && event.colno ? event.colno : null
                }
            });
        } catch (_) {}
    });

    window.addEventListener('unhandledrejection', function (event) {
        try {
            const reason = event && event.reason;
            const message = (reason && reason.message) ? reason.message : String(reason || 'Unhandled promise rejection');
            logSystemError({
                type: 'unhandled_promise_rejection',
                source: 'window.unhandledrejection',
                message: message,
                stack: reason && reason.stack ? reason.stack : '',
                details: {
                    code: reason && reason.code ? reason.code : null
                }
            });
        } catch (_) {}
    });

    // Capture API/fetch failures (network and non-2xx status)
    if (typeof window.fetch === 'function' && !window.__fetchErrorMonitoringWrapped) {
        window.__fetchErrorMonitoringWrapped = true;
        const __nativeFetch = window.fetch.bind(window);
        const isTelemetryUrl = (url) => /getsystemobservabilitymetrics|trackobservabilityevent|adminrecalculateusagestats/i.test(String(url || ''));
        window.fetch = async function (...args) {
            const requestInfo = args && args[0];
            const requestUrl = (typeof requestInfo === 'string')
                ? requestInfo
                : (requestInfo && requestInfo.url) ? String(requestInfo.url) : '';
            const startedAt = Date.now();
            try {
                const response = await __nativeFetch(...args);
                const durationMs = Date.now() - startedAt;
                if (!/firestore|googleapis|gstatic/i.test(requestUrl) && !isTelemetryUrl(requestUrl)) {
                    trackObservabilityEvent({
                        eventName: 'http_fetch',
                        category: 'api',
                        source: 'fetch',
                        durationMs,
                        statusCode: Number(response.status || 0),
                        success: response.ok,
                        route: __trimLogString(requestUrl, 1200),
                        clientTs: Date.now()
                    });
                }
                if (!response.ok && !/firestore|googleapis|gstatic/i.test(requestUrl) && !isTelemetryUrl(requestUrl)) {
                    logSystemError({
                        type: 'api_http_error',
                        source: 'fetch',
                        message: `HTTP ${response.status} ${response.statusText || ''}`.trim(),
                        details: {
                            url: __trimLogString(requestUrl, 1200),
                            status: response.status,
                            statusText: response.statusText || ''
                        }
                    });
                }
                return response;
            } catch (error) {
                const durationMs = Date.now() - startedAt;
                if (!/firestore|googleapis|gstatic/i.test(requestUrl) && !isTelemetryUrl(requestUrl)) {
                    trackObservabilityEvent({
                        eventName: 'http_fetch',
                        category: 'api',
                        source: 'fetch',
                        durationMs,
                        statusCode: 0,
                        success: false,
                        route: __trimLogString(requestUrl, 1200),
                        clientTs: Date.now()
                    });
                }
                if (!/firestore|googleapis|gstatic/i.test(requestUrl) && !isTelemetryUrl(requestUrl)) {
                    logSystemError({
                        type: 'api_network_error',
                        source: 'fetch',
                        message: __normalizeLogErrorMessage(error),
                        stack: error && error.stack ? error.stack : '',
                        details: {
                            url: __trimLogString(requestUrl, 1200)
                        }
                    });
                }
                throw error;
            }
        };
    }

    // Capture Firebase-related handled errors that are logged via console.error.
    if (typeof console !== 'undefined' && typeof console.error === 'function' && !window.__consoleErrorMonitoringWrapped) {
        window.__consoleErrorMonitoringWrapped = true;
        const __nativeConsoleError = console.error.bind(console);
        console.error = function (...args) {
            try {
                __nativeConsoleError(...args);
            } finally {
                try {
                    const msg = __trimLogString(args.map((x) => {
                        if (x instanceof Error) return `${x.name}: ${x.message}`;
                        if (typeof x === 'string') return x;
                        try { return JSON.stringify(x); } catch (_) { return String(x); }
                    }).join(' '), 4000);
                    if (/firebase|firestore|permission-denied|auth\//i.test(msg)) {
                        logSystemError({
                            type: 'firebase_error',
                            source: 'console.error',
                            message: msg
                        });
                    }
                } catch (_) {}
            }
        };
    }
})();

(function installObservabilityHeartbeat() {
    if (typeof window === 'undefined') return;
    if (window.__observabilityHeartbeatInstalled) return;
    window.__observabilityHeartbeatInstalled = true;

    const sendHeartbeat = () => {
        try {
            const now = Date.now();
            if (now - __obsLastHeartbeatAt < 60000) return;
            __obsLastHeartbeatAt = now;
            const nav = (typeof performance !== 'undefined' && performance && performance.timing)
                ? performance.timing
                : null;
            const loadMs = nav && nav.navigationStart && nav.domComplete
                ? Math.max(0, Number(nav.domComplete - nav.navigationStart) || 0)
                : 0;
            const mem = (typeof performance !== 'undefined' && performance && performance.memory)
                ? performance.memory
                : null;
            trackObservabilityEvent({
                eventName: 'client_heartbeat',
                category: 'performance',
                source: 'web_client',
                durationMs: loadMs,
                success: true,
                route: `${window.location.pathname || ''}${window.location.hash || ''}`,
                metrics: {
                    dbReads: 0,
                    dbWrites: 0,
                    concurrentUsers: 1,
                    usedJsHeapSize: mem && mem.usedJSHeapSize ? Number(mem.usedJSHeapSize) : 0
                },
                clientTs: now
            });
        } catch (_) {}
    };

    window.addEventListener('load', sendHeartbeat);
    setInterval(sendHeartbeat, 60000);
})();

// Manual QA helpers for validating System Error Monitoring from browser console.
if (typeof window !== 'undefined') {
    window.errorMonitoringTest = {
        jsError: function () {
            setTimeout(() => {
                throw new Error('QA_JS_ERROR_TEST');
            }, 0);
            return 'Triggered JS error test';
        },
        promiseError: function () {
            Promise.reject(new Error('QA_PROMISE_ERROR_TEST'));
            return 'Triggered unhandled promise rejection test';
        },
        networkError: async function () {
            try {
                await fetch('/__qa_non_existing_endpoint__?t=' + Date.now(), { cache: 'no-store' });
            } catch (_) {}
            return 'Triggered network/API error test';
        },
        firebaseError: async function () {
            try {
                // This read is denied by rules (mail read = false), good for permission-denied telemetry test.
                if (!window.firebaseDb) return 'Firebase DB not ready';
                await window.firebaseDb.collection('mail').limit(1).get();
            } catch (e) {
                try {
                    await logSystemError({
                        type: 'firebase_error_test',
                        source: 'qa_helper',
                        message: (e && (e.message || e.code)) || 'QA_FIREBASE_ERROR_TEST',
                        stack: e && e.stack ? e.stack : '',
                        details: { code: e && e.code ? e.code : null }
                    });
                } catch (_) {}
                return 'Triggered firebase permission error test';
            }
            return 'Firebase test did not throw (unexpected)';
        }
    };
}

