function translateExpenseCategoryLabel(category) {
    if (!category) return '—';
    if (category === 'عام') return (document.documentElement.lang || 'ar') === 'en' ? 'General' : 'عام';
    if (category === getText('expense-category-products')) return getText('expense-category-products');
    return category;
}

// Render expenses report
function renderExpensesReport() {
    try {
        // Fetch expenses data from cash drawer transactions
        const expenses = getExpensesData();
        const filtered = applyExpensesFilters(expenses);
        
        // Display data
        displayExpensesTable(filtered);
        updateExpensesSummary(filtered);
        
        // Setup filters
        setupExpensesFilters();
        
    } catch(e) { 
        console.warn('Error rendering expenses report:', e); 
    }
}

// Fetch expenses data from cash drawer transactions
function getExpensesData() {
    try {
        const cashDrawer = loadFromStorage('cashDrawer', { transactions: [] });
        const transactions = cashDrawer.transactions || [];
        
        // Filter only expenses (expense, adjustment out)
        const expenses = transactions.filter(tr => {
            const type = String(tr.type || '').toLowerCase();
            return type === 'expense' || 
                   (type === 'adjustment' && (tr.amountUSD < 0 || tr.amountLBP < 0));
        });
        
        // Transform raw data into expenses report format
        return expenses.map(tr => {
            // Handle different data shapes
            let amount = 0;
            let currency = 'USD';
            
            if (tr.type === 'adjustment') {
                // adjustment uses amountUSD and amountLBP
                const amountUSD = Math.abs(tr.amountUSD || 0);
                const amountLBP = Math.abs(tr.amountLBP || 0);
                
                if (amountUSD > 0) {
                    amount = amountUSD;
                    currency = 'USD';
                } else if (amountLBP > 0) {
                    amount = amountLBP;
                    currency = 'LBP';
                }
            } else {
                // expense uses amount and currency
                amount = Math.abs(tr.amount || 0);
                currency = tr.currency || 'USD';
            }
            
            // Compute USD amount
            let expenseUSD = 0;
            let exchangeRate = tr.exchange_rate || settings?.exchangeRate || 89500;
            
            if (currency === 'USD') {
                expenseUSD = amount;
            } else if (currency === 'LBP') {
                expenseUSD = amount / exchangeRate;
            }
            
            // Ensure the amount is valid
            if (isNaN(expenseUSD) || expenseUSD < 0) {
                expenseUSD = 0;
            }
            
            return {
                id: tr.id || Date.now() + Math.random(),
                date: tr.timestamp || tr.date || new Date().toISOString(),
                category: tr.category || 'عام',
                description: tr.description || tr.note || '',
                originalAmount: amount,
                originalCurrency: currency,
                exchangeRate: currency === 'LBP' ? exchangeRate : null,
                expenseUSD: expenseUSD,
                user: tr.user || 'نظام'
            };
        }).sort((a, b) => new Date(b.date) - new Date(a.date));
        
    } catch(e) { 
        console.warn('Error getting expenses data:', e); 
        return []; 
    }
}

// Apply expenses filters
function applyExpensesFilters(expenses) {
    const category = document.getElementById('expensesCategoryFilter')?.value;
    const user = document.getElementById('expensesUserFilter')?.value;
    const search = document.getElementById('expensesSearch')?.value?.toLowerCase();
    
    let filtered = [...(expenses || [])];

    const range = getGlobalReportRange();
    if (range?.from && range?.to) {
        filtered = filterExpensesByRange(filtered, range);
    } else {
        const fromDate = document.getElementById('expensesFromDate')?.value;
        if (fromDate) {
            filtered = filtered.filter((e) => {
                try {
                    return new Date(e.date) >= new Date(fromDate);
                } catch (_) {
                    return false;
                }
            });
        }
    }
    
    // Category filter
    if (category && category !== 'all') {
        filtered = filtered.filter(e => e.category === category);
    }
    
    // User filter
    if (user && user !== 'all') {
        filtered = filtered.filter(e => e.user === user);
    }
    
    // Search filter
    if (search) {
        filtered = filtered.filter(e => 
            (e.description || '').toLowerCase().includes(search) ||
            (e.category || '').toLowerCase().includes(search)
        );
    }
    
    return filtered;
}

// Render expenses table
function displayExpensesTable(expenses) {
    const tbody = document.getElementById('expensesTable');
    if (!tbody) return;
    const isEn = (document.documentElement.lang || 'ar') === 'en';

    if (!expenses || expenses.length === 0) {
        tbody.innerHTML = `
            <tr><td colspan="5" class="expenses-report-empty">
                <div class="expenses-report-empty-title">${escapeHtml(getText('expenses-empty-title') || (isEn ? 'No expenses found' : 'لا توجد نفقات'))}</div>
                <div class="expenses-report-empty-hint">${escapeHtml(getText('expenses-empty-hint') || (isEn ? 'Try changing your filters.' : 'جرّب تغيير عوامل التصفية.'))}</div>
            </td></tr>`;
        updateExpensesCountInfo(0);
        return;
    }

    tbody.innerHTML = expenses.map((expense) => {
        const when = formatExpenseReportDateTime(expense.date);
        const translatedDescription = (expense.description === 'تعديل يدوي للصندوق من الإعدادات' || expense.description === 'Manual cashbox adjustment from Settings')
            ? getText('cashbox-manual-adjustment')
            : (expense.description || '—');
        const translatedCategory = translateExpenseCategoryLabel(expense.category);
        return `
            <tr>
                <td class="expenses-col-datetime">
                    <span class="expenses-date-line">${escapeHtml(when.date)}</span>
                    ${when.time ? `<span class="expenses-time-line">${escapeHtml(when.time)}</span>` : ''}
                </td>
                <td><span class="expenses-category-badge">${escapeHtml(translatedCategory)}</span></td>
                <td class="expenses-col-desc" title="${escapeAttr(translatedDescription)}">${escapeHtml(translatedDescription)}</td>
                <td class="expenses-col-amount">${formatCurrency(expense.expenseUSD || 0)}</td>
                <td>${escapeHtml(expense.user || (isEn ? 'System' : 'نظام'))}</td>
            </tr>`;
    }).join('');
    updateExpensesCountInfo(expenses.length);
}

function updateExpensesCountInfo(count) {
    const info = document.getElementById('expensesCountInfo');
    if (!info) return;
    const isEn = (document.documentElement.lang || 'ar') === 'en';
    info.textContent = count
        ? (isEn ? `${count} expense${count === 1 ? '' : 's'}` : `${count} نفقة`)
        : '';
}

// Update expenses summary
function updateExpensesSummary(expenses) {
    const totalElement = document.getElementById('expensesTotalAmount');
    if (!totalElement) return;
    
    const total = expenses.reduce((sum, expense) => {
        const amount = parseFloat(expense.expenseUSD) || 0;
        return sum + amount;
    }, 0);
    
    totalElement.textContent = formatCurrency(total);
    totalElement.style.color = total > 0 ? '#dc2626' : '#059669';
}

// Record automatic expense when adding a product
function recordProductSupplyExpense(productName, quantity, unitCost, currency = 'USD') {
    try {
        const totalCost = quantity * unitCost;
        
        // Load/sync cash drawer data in memory
        cashDrawer = loadFromStorage('cashDrawer', cashDrawer || { transactions: [] });
        if (!cashDrawer.transactions) cashDrawer.transactions = [];
        
        // Determine description based on current language
        const description = getText('expense-auto-product-add')
            .replace('{productName}', productName)
            .replace('{quantity}', quantity)
            .replace('{cost}', unitCost.toFixed(2));
        
        // Create expense transaction
        const expenseTransaction = {
            timestamp: new Date().toISOString(),
            type: 'expense',
            amount: totalCost,
            currency: currency,
            category: getText('expense-category-products'),
            description: description,
            note: description,
            user: (currentUser && currentUser.name) || 'النظام',
            exchange_rate: settings.exchangeRate || 89500,
            balanceAfter: {
                USD: cashDrawer.cashUSD || 0,
                LBP: cashDrawer.cashLBP || 0
            }
        };
        
        // Add transaction (with V2 sync via cashDrawerTx)
        addCashDrawerTransaction(expenseTransaction);
        cashDrawer.lastUpdate = new Date().toISOString();
        
        // Persist data
        saveToStorage('cashDrawer', cashDrawer);
        
        console.log('✅ Recorded automatic product supply expense:', {
            product: productName,
            quantity: quantity,
            unitCost: unitCost,
            totalCost: totalCost,
            currency: currency
        });
        
        return true;
    } catch (error) {
        console.error('Error recording product supply expense:', error);
        return false;
    }
}

// Setup expenses filters
function setupExpensesFilters() {
    const expenses = getExpensesData();
    const categoryFilter = document.getElementById('expensesCategoryFilter');
    if (categoryFilter) {
        const categories = [...new Set(expenses.map(e => e.category))];
        const allLabel = getText('expenses-category-all') || ((document.documentElement.lang || 'ar') === 'en' ? 'All Categories' : 'جميع التصنيفات');
        categoryFilter.innerHTML = `<option value="all">${escapeHtml(allLabel)}</option>`;
        categories.forEach((cat) => {
            const option = document.createElement('option');
            option.value = cat;
            option.textContent = translateExpenseCategoryLabel(cat);
            categoryFilter.appendChild(option);
        });
    }

    const userFilter = document.getElementById('expensesUserFilter');
    if (userFilter) {
        const users = [...new Set(expenses.map(e => e.user))];
        const allLabel = getText('expenses-user-all') || ((document.documentElement.lang || 'ar') === 'en' ? 'All Users' : 'جميع المستخدمين');
        userFilter.innerHTML = `<option value="all">${escapeHtml(allLabel)}</option>`;
        users.forEach((user) => {
            const option = document.createElement('option');
            option.value = user;
            option.textContent = user;
            userFilter.appendChild(option);
        });
    }
}

