// Export expenses report to CSV
function exportExpensesCsv() {
    const expenses = getExpensesData();
    const filtered = applyExpensesFilters(expenses);
    const isEn = (document.documentElement.lang || 'ar') === 'en';

    const headers = isEn
        ? ['Date & Time', 'Category', 'Description', 'Amount (USD)', 'User']
        : ['التاريخ والوقت', 'التصنيف', 'الوصف', 'المبلغ (USD)', 'المستخدم'];

    const rows = [headers];

    filtered.forEach((expense) => {
        const when = formatExpenseReportDateTime(expense.date);
        const date = when.time ? `${when.date} ${when.time}` : when.date;
        const translatedCategory = translateExpenseCategoryLabel(expense.category);
        const translatedDescription = (expense.description === 'تعديل يدوي للصندوق من الإعدادات' || expense.description === 'Manual cashbox adjustment from Settings')
            ? getText('cashbox-manual-adjustment')
            : (expense.description || '');
        rows.push([
            date,
            translatedCategory,
            translatedDescription,
            (expense.expenseUSD || 0).toFixed(2),
            expense.user || ''
        ]);
    });

    const total = filtered.reduce((sum, expense) => sum + (expense.expenseUSD || 0), 0);
    rows.push(['', '', isEn ? 'Total' : 'الإجمالي', total.toFixed(2), '']);

    const csv = rows.map(r => r.map(v => `"${String(v).replace(/"/g, '""')}"`).join(',')).join('\n');
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = isEn ? 'expenses_report.csv' : 'تقرير_النفقات.csv';
    a.click();
    URL.revokeObjectURL(url);
}

// Calculate date ranges
function getDateRange(preset) {
    console.log(`📋 Date range requested for preset: "${preset}"`);
    const today = new Date();
    
    // Compute start/end of week (improved)
    const startOfWeek = (() => {
        const d = new Date(today);
        // Weekday mapping: Sunday=0, Monday=1, ..., Saturday=6
        const currentDay = d.getDay();
        // Days to subtract to reach week start (Monday)
        // Sunday (0) => subtract 6 days
        // Monday (1) => subtract 0 days
        // Tuesday (2) => subtract 1 day ... etc.
        const daysToSubtract = currentDay === 0 ? 6 : currentDay - 1;
        
        d.setDate(d.getDate() - daysToSubtract);
        d.setHours(0, 0, 0, 0);
        
        console.log(`🗓️ Week start calculation: today ${today.toLocaleDateString()} (${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'][currentDay]}), week start: ${d.toLocaleDateString()}`);
        
        return d;
    })();
    
    const endOfWeek = new Date(startOfWeek);
    endOfWeek.setDate(startOfWeek.getDate() + 6);
    endOfWeek.setHours(23, 59, 59, 999);
    
    console.log(`📅 Current week range: ${startOfWeek.toLocaleDateString()} to ${endOfWeek.toLocaleDateString()}`);
    const startOfMonth = new Date(today.getFullYear(), today.getMonth(), 1);
    const endOfMonth = new Date(today.getFullYear(), today.getMonth()+1, 0, 23,59,59,999);
    const lastMonthStart = new Date(today.getFullYear(), today.getMonth()-1, 1);
    const lastMonthEnd = new Date(today.getFullYear(), today.getMonth(), 0, 23,59,59,999);
    switch(preset){
        case 'today': {
            // Use true local time (no UTC conversion)
            const now = new Date();
            
            // Start of day (00:00:00.000) in local timezone
            const startToday = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 0, 0, 0, 0);
            
            // End of day (23:59:59.999) in local timezone
            const endToday = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 23, 59, 59, 999);
            
            console.log(`📅 "Today" calculation: ${now.toLocaleDateString()} (${now.getHours()}:${String(now.getMinutes()).padStart(2, '0')})`);
            console.log(`📅 Today range: ${startToday.toLocaleDateString()} ${startToday.getHours()}:${String(startToday.getMinutes()).padStart(2, '0')} to ${endToday.toLocaleDateString()} ${endToday.getHours()}:${String(endToday.getMinutes()).padStart(2, '0')}`);
            console.log(`📅 Today range (ISO): ${startToday.toISOString()} to ${endToday.toISOString()}`);
            
            return [startToday, endToday];
        }
        case 'this_week': 
        case 'this-week': return [startOfWeek, endOfWeek];
        case 'last_week': { const s = new Date(startOfWeek); s.setDate(s.getDate()-7); const e = new Date(endOfWeek); e.setDate(e.getDate()-7); return [s,e]; }
        case 'this_month': 
        case 'this-month': return [startOfMonth, endOfMonth];
        case 'last_month': 
        case 'last-month': return [lastMonthStart, lastMonthEnd];
        default: 
            console.log(`⚠️ Unknown preset: "${preset}" - defaulting to this month`);
            return [startOfMonth, endOfMonth];
    }
}

function renderProfitReports() {
    console.log('🔍 Starting updated profit report calculation...');
    
    // Ensure we load the latest sales from storage (guard against in-memory resets)
    sales = getCurrentSales();
    
    const preset = document.getElementById('profitPreset')?.value || 'today';
    console.log(`🎯 Selected preset: "${preset}"`);
    const paymentFilter = document.getElementById('profitPaymentFilter')?.value || 'all';
    const pageSizeSel = document.getElementById('profitPageSize');
    const pageSize = parseInt(pageSizeSel?.value || localStorage.getItem('profit.pageSize') || '15') || 15;
    localStorage.setItem('profit.pageSize', String(pageSize));
    
    // Calculate date range precisely
    let [from, to] = getDateRange(preset);
    // Show date fields only for custom
    const fromEl = document.getElementById('profitFrom');
    const toEl = document.getElementById('profitTo');
    if (fromEl && toEl) {
        const custom = preset === 'custom';
        fromEl.classList.toggle('is-visible', custom);
        toEl.classList.toggle('is-visible', custom);
        if (custom) {
            const fV = fromEl.value ? new Date(fromEl.value) : from;
            const tV = toEl.value ? new Date(toEl.value) : to;
            from = fV; to = tV;
        }
    }
    // Validate dates
    if (!(from instanceof Date) || isNaN(from.getTime())) { 
        from = new Date(); 
        from.setHours(0, 0, 0, 0); 
    }
    if (!(to instanceof Date) || isNaN(to.getTime())) { 
        to = new Date(); 
        to.setHours(23, 59, 59, 999); 
    }
    
    // Normalize date range to avoid timezone issues
    const fromDate = new Date(from.getFullYear(), from.getMonth(), from.getDate(), 0, 0, 0, 0);
    const toDate = new Date(to.getFullYear(), to.getMonth(), to.getDate(), 23, 59, 59, 999);
    
    // Local-time diagnostics
    console.log(`📅 Local report range: ${fromDate.toLocaleDateString()} ${fromDate.getHours()}:${String(fromDate.getMinutes()).padStart(2, '0')} to ${toDate.toLocaleDateString()} ${toDate.getHours()}:${String(toDate.getMinutes()).padStart(2, '0')}`);
    console.log(`📊 Selected period: ${preset} - today: ${new Date().toLocaleDateString()}`);
    
    // Improved helper to parse/validate sale dates
    function parseSaleDate(sale) {
        const saleDateValue = sale.timestamp || sale.date || sale.returnDate;
        
        if (!saleDateValue) {
            return null; // No sale date available
        }
        
        try {
            let parsedDate;
            
            if (typeof saleDateValue === 'string' && saleDateValue.includes('T')) {
                // local timestamp without timezone
                if (!saleDateValue.includes('Z') && !saleDateValue.includes('+') && !saleDateValue.includes('-', 10)) {
                    const parts = saleDateValue.split('T');
                    if (parts.length === 2) {
                        const [datePart, timePart] = parts;
                        const [year, month, day] = datePart.split('-').map(Number);
                        const timeWithMs = timePart.includes('.') ? timePart : timePart + '.000';
                        const [timeOnly, ms] = timeWithMs.split('.');
                        const [hours, minutes, seconds] = timeOnly.split(':').map(Number);
                        parsedDate = new Date(year, month - 1, day, hours, minutes, seconds, Number(ms.padEnd(3, '0')));
                    } else {
                        parsedDate = new Date(saleDateValue);
                    }
                } else {
                    parsedDate = new Date(saleDateValue);
                }
            } else {
                parsedDate = new Date(saleDateValue);
            }
            
            return isNaN(parsedDate.getTime()) ? null : parsedDate;
        } catch (error) {
            console.warn('Error parsing sale date:', sale, error);
            return null;
        }
    }
    
    // Improved helper: range check with detailed diagnostics
    const isSaleInRange = (sale) => {
        const saleDate = parseSaleDate(sale);
        if (!saleDate) {
            console.log('❌ Sale without a valid date:', sale);
            return false; // Skip sales without a valid date
        }
        
        // Precise date comparison using local timezone boundaries
        const saleYear = saleDate.getFullYear();
        const saleMonth = saleDate.getMonth();
        const saleDay = saleDate.getDate();
        
        const fromYear = fromDate.getFullYear();
        const fromMonth = fromDate.getMonth();
        const fromDay = fromDate.getDate();
        
        const toYear = toDate.getFullYear();
        const toMonth = toDate.getMonth();
        const toDay = toDate.getDate();
        
        // Build range start/end in local timezone
        const rangeStart = new Date(fromYear, fromMonth, fromDay, 0, 0, 0, 0);
        const rangeEnd = new Date(toYear, toMonth, toDay, 23, 59, 59, 999);
        
        // Check if sale time is within the local range
        const isInRange = saleDate >= rangeStart && saleDate <= rangeEnd;
        
        // Detailed per-sale diagnostics (local time)
        if (sale.invoiceNumber) {
            // Use local time instead of ISO to avoid UTC issues
            const saleDateStr = `${saleDate.getFullYear()}-${String(saleDate.getMonth() + 1).padStart(2, '0')}-${String(saleDate.getDate()).padStart(2, '0')}`;
            const fromDateStr = `${fromDate.getFullYear()}-${String(fromDate.getMonth() + 1).padStart(2, '0')}-${String(fromDate.getDate()).padStart(2, '0')}`;
            const toDateStr = `${toDate.getFullYear()}-${String(toDate.getMonth() + 1).padStart(2, '0')}-${String(toDate.getDate()).padStart(2, '0')}`;
            
            if (window.__DEBUG_REPORTS === true) {
                console.log(`🔍 Checking sale ${sale.invoiceNumber}: ${saleDateStr} (from ${fromDateStr} to ${toDateStr}) - in range: ${isInRange}`);
            }
            
            if (!isInRange && window.__DEBUG_REPORTS === true) {
                console.log(`❌ Sale out of range: ${sale.invoiceNumber}`, {
                    saleDateLocal: saleDateStr,
                    saleTimestamp: sale.timestamp || sale.date,
                    fromDateLocal: fromDateStr,
                    toDateLocal: toDateStr,
                    preset: preset,
                    before: saleDate < fromDate,
                    after: saleDate > toDate,
                    saleTime: saleDate.getHours() + ':' + String(saleDate.getMinutes()).padStart(2, '0'),
                    fromTime: fromDate.getHours() + ':' + String(fromDate.getMinutes()).padStart(2, '0'),
                    toTime: toDate.getHours() + ':' + String(toDate.getMinutes()).padStart(2, '0')
                });
            }
        }
        
        return isInRange;
    };
    
    // Filter sales based on time range and selected filters
    let filteredSales = sales.filter(sale => {
        // Validate sale shape first
        if (!sale || !sale.items || !Array.isArray(sale.items) || sale.items.length === 0) {
            return false; // Skip invalid sales
        }
        
        // Check time range
        if (!isSaleInRange(sale)) {
            return false; // Out of range
        }
        
        // Check payment method filter
        if (paymentFilter !== 'all') {
            if (paymentFilter === 'cash' && !/نقدي|Cash/i.test(sale.paymentMethod)) {
                return false;
            }
            if (paymentFilter === 'credit' && !/دين|credit/i.test(sale.paymentMethod)) {
                return false;
            }
            if (paymentFilter === 'partial' && !sale.partialDetails) {
                return false;
            }
        }
        
        return true;
    });
    
    if (window.__DEBUG_REPORTS === true) console.log(`📊 Valid sales after filtering: ${filteredSales.length}`);
    
    // No sales in the selected period
    if (filteredSales.length === 0) {
        if (window.__DEBUG_REPORTS === true) console.log('⚠️ No sales in the selected period');
        // Show a user message when no sales exist
        const tbody = document.getElementById('profitTable');
        if (tbody) {
            tbody.innerHTML = '<tr><td colspan="5" style="text-align: center; padding: 20px; color: #666;">' + (typeof getText === 'function' ? getText('msg-no-sales-in-period') : 'لا توجد مبيعات في الفترة المحددة') + '</td></tr>';
        }
        // Reset summary to reflect no sales
        const sumEl = document.getElementById('profitSummary');
        if (sumEl) {
            sumEl.innerHTML = `
                <div class="profit-summary-item">
                    <div class="profit-summary-title" data-i18n="gross-sales">Gross Sales</div>
                    <div class="profit-summary-value">${formatCurrency(0,'USD')}</div>
                </div>
                <div class="profit-summary-item">
                    <div class="profit-summary-title" data-i18n="total-cogs">Total COGS</div>
                    <div class="profit-summary-value">${formatCurrency(0,'USD')}</div>
                </div>
                <div class="profit-summary-item">
                    <div class="profit-summary-title" data-i18n="net-profit">Net Profit</div>
                    <div class="profit-summary-value">${formatCurrency(0,'USD')}</div>
                </div>
                <div class="profit-summary-item">
                    <div class="profit-summary-title" data-i18n="invoices">Invoices</div>
                    <div class="profit-summary-value">0</div>
                </div>
                <div class="profit-summary-item">
                    <div class="profit-summary-title" data-i18n="refunds">Refunds</div>
                    <div class="profit-summary-value">0</div>
                </div>
            `;
            // Apply translations to titles
            const titles = sumEl.querySelectorAll('.profit-summary-title[data-i18n]');
            titles.forEach(title => {
                const key = title.getAttribute('data-i18n');
                title.textContent = getText(key);
            });
        }
        return; // Stop when there are no sales
    }
    // === منطق الحساب الجديد المبني على البيانات الفعلية ===
    
    // === Unified helper: compute final item price with correct currency conversion ===
    function getItemFinalPrice(item) {
        // Priority: updated prices (line-level)
        if (item.finalPriceUSD !== null && item.finalPriceUSD !== undefined) {
            return parseFloat(item.finalPriceUSD) || 0;
        }
        
        // Use the base stored line price as a legacy fallback
        if (item.priceUSD !== null && item.priceUSD !== undefined) {
            return parseFloat(item.priceUSD) || 0;
        }
        
        // Find the product in the database/cache and use the current price by price type
        const product = products.find(p => p.id === item.id);
        if (product) {
            try {
                // Use unified price function to take the latest updated USD price
                return getProductPrice(product, currentPriceType, 'USD');
            } catch (e) {
                // If something fails, fall back to priceUSD if available
                if (product.priceUSD !== null && product.priceUSD !== undefined) {
                    return parseFloat(product.priceUSD) || 0;
                }
            }
        }
        
        return 0;
    }
    
    // === Unified helper: compute item cost with correct currency conversion ===
    function getItemCost(item) {
        // Priority: specific item cost
        if (item.costUSD !== null && item.costUSD !== undefined && item.costUSD > 0) {
            return parseFloat(item.costUSD);
        }
        
        // Find the product in the database/cache
        const product = products.find(p => p.id === item.id);
        if (product && product.costUSD) {
            return parseFloat(product.costUSD) || 0;
        }
        
        return 0;
    }
    
    // Totals (will be recalculated from the table)
    let totalGrossSales = 0;
    let totalCostOfGoods = 0;
    let totalInvoices = 0;
    let totalRefunds = 0;
    
    // Per-day data structure (empty until we have real data)
    const dailyData = {};
    
    console.log(`🔄 Starting processing for ${filteredSales.length} valid sale(s)...`);
    
    // Process each sale separately
    filteredSales.forEach((sale, index) => {
        try {
            // Validate sale shape first
            if (!sale || !sale.items || !Array.isArray(sale.items) || sale.items.length === 0) {
                console.warn(`Skipping sale ${index + 1}: no valid items`, sale);
                return;
            }
            
            // Determine whether this is a refund invoice (based on invoice type/payment method, not only the returned flag)
            const pmLower = String(sale.paymentMethod || '').toLowerCase();
            const isRefund = pmLower.includes('refund') || (sale.invoiceNumber && String(sale.invoiceNumber).startsWith('RF-'));
            const sign = isRefund ? -1 : 1;
            
            // Get the correct sale date
            const saleDate = parseSaleDate(sale);
            if (!saleDate) {
                console.warn(`Skipping sale ${index + 1}: invalid date`, sale);
                return;
            }
            
            // Compute day key using local time
            const dayKey = `${saleDate.getFullYear()}-${String(saleDate.getMonth() + 1).padStart(2, '0')}-${String(saleDate.getDate()).padStart(2, '0')}`;
            
            console.log(`📅 Day key: ${dayKey} from sale date: ${saleDate.toLocaleDateString()}`);
            
            // Initialize day bucket if missing
            if (!dailyData[dayKey]) {
                dailyData[dayKey] = {
                    date: dayKey,
                    invoiceCount: 0,
                    refundCount: 0,
                    grossSales: 0,
                    costOfGoods: 0,
                    netProfit: 0,
                    sales: []
                };
            }
            
            // Compute this sale amounts
            let saleGross = 0;
            let saleCost = 0;
            let hasValidItems = false;
            
            // Process each line item in the sale
            sale.items.forEach(item => {
                const quantity = parseInt(item.quantity) || 1;
                const itemPrice = getItemFinalPrice(item);
                const itemCost = getItemCost(item);
                
                // Apply correct formulas
                // sales_total = SUM(line.qty * line.price_after_discount_tax_included)
                // cost_total = SUM(line.qty * line.cost)
                const totalPrice = itemPrice * quantity;
                const totalCost = itemCost * quantity;
                
                saleGross += totalPrice;
                saleCost += totalCost;
                hasValidItems = true;
                
                console.log(`📊 Item: ${item.name || item.id}, qty: ${quantity}, price: $${itemPrice.toFixed(2)}, cost: $${itemCost.toFixed(2)}, total: $${totalPrice.toFixed(2)}, total cost: $${totalCost.toFixed(2)}`);
            });
            
            // If there are valid items, add them to the day totals
            if (hasValidItems) {
                // Apply sign for refunds
                const finalGross = saleGross * sign;
                const finalCost = saleCost * sign;
                
                // Update day totals
                dailyData[dayKey].grossSales += finalGross;
                dailyData[dayKey].costOfGoods += finalCost;
                dailyData[dayKey].netProfit = dailyData[dayKey].grossSales - dailyData[dayKey].costOfGoods;
                
                if (isRefund) {
                    dailyData[dayKey].refundCount++;
                    totalRefunds++;
                } else {
                    dailyData[dayKey].invoiceCount++;
                    totalInvoices++;
                }
                
                // إضافة البيع إلى قائمة مبيعات اليوم
                dailyData[dayKey].sales.push({
                    invoiceNumber: sale.invoiceNumber || `INV-${sale.id}`,
                    timestamp: saleDate,
                    gross: finalGross,
                    cost: finalCost,
                    profit: finalGross - finalCost,
                    isRefund: isRefund
                });
                
                // تحديث الإجمالي العام
                totalGrossSales += finalGross;
                totalCostOfGoods += finalCost;
                
                console.log(`✅ Processed ${isRefund ? 'refund' : 'sale'} ${sale.invoiceNumber || sale.id}: gross $${finalGross.toFixed(2)} cost $${finalCost.toFixed(2)}`);
            }
        } catch (error) {
            console.error(`Error processing sale ${index + 1}:`, error, sale);
        }
    });
    
    // === الحل الجذري: حساب المجاميع من نفس البيانات المعروضة في الجدول ===
    
    // الحصول على الأيام التي تحتوي على بيانات فعلية فقط (نفس منطق الجدول)
    const validDays = Object.values(dailyData).filter(day => {
        // اليوم صالح فقط إذا كان لديه مبيعات فعلية أو إيرادات
        return day.invoiceCount > 0 || day.grossSales > 0 || day.refundCount > 0;
    });
    
    // ترتيب الأيام من الأحدث للأقدم
    validDays.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    
    console.log(`📋 Displaying ${validDays.length} day(s) with real data`);
    
    // === حساب المجاميع من نفس البيانات المعروضة في الجدول ===
    
    // إعادة حساب المجاميع من صفوف الجدول الفعلية فقط
    totalGrossSales = 0;
    totalCostOfGoods = 0;
    totalInvoices = 0;
    totalRefunds = 0;
    
    // حساب المجاميع من نفس البيانات المعروضة في الجدول
    validDays.forEach(day => {
        totalGrossSales += day.grossSales;
        totalCostOfGoods += day.costOfGoods;
        totalInvoices += day.invoiceCount;
        totalRefunds += day.refundCount;
    });
    
    // حساب الربح الصافي الإجمالي
    const totalNetProfit = totalGrossSales - totalCostOfGoods;
    
    console.log(`📊 Final report summary (computed from the same table data):`, {
        totalGrossSales: totalGrossSales.toFixed(2),
        totalCostOfGoods: totalCostOfGoods.toFixed(2),
        totalNetProfit: totalNetProfit.toFixed(2),
        totalInvoices: totalInvoices,
        totalRefunds: totalRefunds,
        daysWithSales: validDays.length
    });
    
    // عرض الملخص باستخدام البيانات المحسوبة من نفس بيانات الجدول
    const sumEl = document.getElementById('profitSummary');
    if (sumEl) {
        const netClass = totalNetProfit >= 0 ? 'is-positive' : 'is-negative';
        sumEl.innerHTML = `
            <div class="report-modal-summary-card">
                <div class="report-modal-summary-label">${escapeHtml(reportT('gross-sales', 'Gross Sales', 'إجمالي المبيعات'))}</div>
                <div class="report-modal-summary-value">${formatCurrency(totalGrossSales,'USD')}</div>
            </div>
            <div class="report-modal-summary-card">
                <div class="report-modal-summary-label">${escapeHtml(reportT('total-cogs', 'Total COGS', 'إجمالي COGS'))}</div>
                <div class="report-modal-summary-value">${formatCurrency(totalCostOfGoods,'USD')}</div>
            </div>
            <div class="report-modal-summary-card">
                <div class="report-modal-summary-label">${escapeHtml(reportT('net-profit', 'Net Profit', 'صافي الربح'))}</div>
                <div class="report-modal-summary-value ${netClass}">${formatCurrency(totalNetProfit,'USD')}</div>
            </div>
            <div class="report-modal-summary-card">
                <div class="report-modal-summary-label">${escapeHtml(reportT('invoices', 'Invoices', 'الفواتير'))}</div>
                <div class="report-modal-summary-value">${totalInvoices}</div>
            </div>
            <div class="report-modal-summary-card">
                <div class="report-modal-summary-label">${escapeHtml(reportT('refunds', 'Refunds', 'المرتجعات'))}</div>
                <div class="report-modal-summary-value">${totalRefunds}</div>
            </div>`;
    }
    
    // تطبيق التنقل بالصفحات
    const totalDays = validDays.length;
    const totalPages = Math.max(1, Math.ceil(totalDays / pageSize));
    let currentPage = parseInt(sessionStorage.getItem('profit.currentPage') || '1') || 1;
    currentPage = Math.max(1, Math.min(totalPages, currentPage));
    const start = (currentPage - 1) * pageSize;
    const end = start + pageSize;
    const pageDays = validDays.slice(start, end);
    
    // عرض الجدول
    const tbody = document.getElementById('profitTable');
    if (tbody) {
        if (pageDays.length === 0) {
            tbody.innerHTML = '<tr><td colspan="5" style="text-align: center; padding: 20px; color: #666;">' + (typeof getText === 'function' ? getText('msg-no-data-to-display') : 'لا توجد بيانات للعرض') + '</td></tr>';
        } else {
            tbody.innerHTML = pageDays.map(day => {
                const totalInvoices = day.invoiceCount + day.refundCount;
                const profitClass = day.netProfit >= 0 ? 'is-positive' : 'is-negative';
                const dateLabel = formatExpenseReportDateTime(day.date).date;
                return `
                    <tr>
                        <td>${escapeHtml(dateLabel)}</td>
                        <td class="report-col-center">${totalInvoices}</td>
                        <td class="report-col-amount">${formatCurrency(day.grossSales, 'USD')}</td>
                        <td class="report-col-amount">${formatCurrency(day.costOfGoods, 'USD')}</td>
                        <td class="report-col-amount ${profitClass}">${formatCurrency(day.netProfit, 'USD')}</td>
                    </tr>`;
            }).join('');
        }
    }
    
    // === التحقق من التطابق الدقيق بين المجاميع والجدول ===
    
    // حساب المجاميع من صفوف الجدول المعروضة للتأكد من التطابق
    let tableGrossSales = 0;
    let tableCostOfGoods = 0;
    let tableInvoices = 0;
    let tableRefunds = 0;
    
    validDays.forEach(day => {
        tableGrossSales += day.grossSales;
        tableCostOfGoods += day.costOfGoods;
        tableInvoices += day.invoiceCount;
        tableRefunds += day.refundCount;
    });
    
    const tableNetProfit = tableGrossSales - tableCostOfGoods;
    
    // التحقق من التطابق الدقيق
    const grossMatch = Math.abs(totalGrossSales - tableGrossSales) < 0.01;
    const costMatch = Math.abs(totalCostOfGoods - tableCostOfGoods) < 0.01;
    const profitMatch = Math.abs(totalNetProfit - tableNetProfit) < 0.01;
    const invoiceMatch = totalInvoices === tableInvoices;
    const refundMatch = totalRefunds === tableRefunds;
    
    console.log(`🔍 Exact match verification:`, {
        'summary totals': {
            grossSales: totalGrossSales.toFixed(2),
            costOfGoods: totalCostOfGoods.toFixed(2),
            netProfit: totalNetProfit.toFixed(2),
            invoices: totalInvoices,
            refunds: totalRefunds
        },
        'table totals': {
            grossSales: tableGrossSales.toFixed(2),
            costOfGoods: tableCostOfGoods.toFixed(2),
            netProfit: tableNetProfit.toFixed(2),
            invoices: tableInvoices,
            refunds: tableRefunds
        },
        'match': {
            grossSales: grossMatch ? '✅' : '❌',
            costOfGoods: costMatch ? '✅' : '❌',
            netProfit: profitMatch ? '✅' : '❌',
            invoices: invoiceMatch ? '✅' : '❌',
            refunds: refundMatch ? '✅' : '❌'
        }
    });
    
    if (!grossMatch || !costMatch || !profitMatch || !invoiceMatch || !refundMatch) {
        console.error('❌ Totals mismatch: summary does not match table!');
        console.error('Summary totals:', totalGrossSales, totalCostOfGoods, totalNetProfit, totalInvoices, totalRefunds);
        console.error('Table totals:', tableGrossSales, tableCostOfGoods, tableNetProfit, tableInvoices, tableRefunds);
    } else {
        console.log('✅ Verified: summary totals match table exactly');
    }
    // عداد وترقيم
    const info = document.getElementById('profitCountInfo');
    if (info) {
        const endRange = totalDays ? Math.min(totalDays, start + pageSize) : 0;
        info.textContent = formatReportPagerText(totalDays ? start + 1 : 0, endRange, totalDays);
    }
    
    const pager = document.getElementById('profitPager');
    if (pager) {
        let controls = document.getElementById('profitPagerControls');
        if (!controls) {
            controls = document.createElement('div');
            controls.id = 'profitPagerControls';
            controls.className = 'report-modal-pager-controls';
            pager.appendChild(controls);
        }
        controls.innerHTML = '';
        if (totalPages > 1) {
            const prevLbl = reportT('previous', 'Previous', 'السابق');
            const nextLbl = reportT('next', 'Next', 'التالي');
            controls.appendChild(createReportPagerButton(prevLbl, Math.max(1, currentPage - 1), currentPage === 1, () => {
                sessionStorage.setItem('profit.currentPage', String(Math.max(1, currentPage - 1)));
                renderProfitReports();
            }));
            controls.appendChild(createReportPagerButton(nextLbl, Math.min(totalPages, currentPage + 1), currentPage === totalPages, () => {
                sessionStorage.setItem('profit.currentPage', String(Math.min(totalPages, currentPage + 1)));
                renderProfitReports();
            }));
        }
    }
}

function renderInventoryCapital() {
    const pageSizeSel = document.getElementById('capitalPageSize');
    const searchInput = document.getElementById('capitalSearch');
    const pageSize = parseInt(pageSizeSel?.value || localStorage.getItem('capital.pageSize') || '15', 10) || 15;
    localStorage.setItem('capital.pageSize', String(pageSize));
    const search = String(searchInput?.value || '').trim().toLowerCase();

    let rows = (Array.isArray(products) ? products : []).map((p) => ({
        name: p.name || '',
        qty: getProductSellableStock(p),
        unitCost: p.costUSD || 0,
        value: getProductSellableStock(p) * (p.costUSD || 0)
    }));

    if (search) {
        rows = rows.filter((r) => String(r.name).toLowerCase().includes(search));
    }

    rows.sort((a, b) => b.value - a.value);
    const total = rows.length;
    const totalCapital = rows.reduce((s, r) => s + r.value, 0);
    const totalPages = Math.max(1, Math.ceil(total / pageSize));
    let currentPage = parseInt(sessionStorage.getItem('capital.currentPage') || '1', 10) || 1;
    currentPage = Math.max(1, Math.min(totalPages, currentPage));
    const start = (currentPage - 1) * pageSize;
    const pageRows = rows.slice(start, start + pageSize);
    const tbody = document.getElementById('capitalTable');
    const isEn = (document.documentElement.lang || 'ar') === 'en';

    if (tbody) {
        if (!rows.length) {
            tbody.innerHTML = `
                <tr><td colspan="4" class="inventory-capital-empty">
                    <div class="inventory-capital-empty-title">${escapeHtml(getText('capital-empty-title') || (isEn ? 'No inventory data' : 'لا توجد بيانات مخزون'))}</div>
                    <div class="inventory-capital-empty-hint">${escapeHtml(getText('capital-empty-hint') || (isEn ? 'Add products with cost and stock to see capital value.' : 'أضف منتجات بتكلفة ومخزون لعرض رأس المال.'))}</div>
                </td></tr>`;
        } else {
            tbody.innerHTML = pageRows.map((r) => `
                <tr>
                    <td class="inv-cap-col-name">${escapeHtml(r.name)}</td>
                    <td class="inv-cap-col-qty">${escapeHtml(String(r.qty))}</td>
                    <td class="inv-cap-col-cost">${formatCurrency(r.unitCost, 'USD')}</td>
                    <td class="inv-cap-col-value">${formatCurrency(r.value, 'USD')}</td>
                </tr>`).join('');
        }
    }

    const sumEl = document.getElementById('capitalSummary');
    if (sumEl) {
        sumEl.innerHTML = `
            <div class="inventory-capital-summary-label">${escapeHtml(getText('capital-total-label') || (isEn ? 'Total Inventory Capital' : 'إجمالي رأس مال المخزون'))}</div>
            <div class="inventory-capital-summary-value">${formatCurrency(totalCapital, 'USD')}</div>
            <div class="inventory-capital-summary-hint">${escapeHtml(getText('capital-total-hint') || (isEn ? 'Calculated from current quantity × unit cost.' : 'محسوب من الكمية الحالية × تكلفة الوحدة.'))}</div>
        `;
    }

    const info = document.getElementById('capitalCountInfo');
    if (info) {
        if (!total) {
            info.textContent = '';
        } else {
            const from = start + 1;
            const to = Math.min(total, start + pageSize);
            const tpl = getText('capital-showing-products', { from, to, total });
            info.textContent = (tpl && tpl !== 'capital-showing-products')
                ? tpl
                : (isEn ? `Showing ${from}–${to} of ${total} products` : `عرض ${from}–${to} من ${total} منتج`);
        }
    }

    const pager = document.getElementById('capitalPager');
    if (pager) {
        let controls = document.getElementById('capitalPagerControls');
        if (!controls) {
            controls = document.createElement('div');
            controls.id = 'capitalPagerControls';
            controls.className = 'inventory-capital-pager-controls';
            pager.appendChild(controls);
        }
        controls.innerHTML = '';
        if (total > pageSize) {
            const btn = (lbl, p, dis) => {
                const b = document.createElement('button');
                b.type = 'button';
                b.textContent = lbl;
                b.className = 'report-polish-btn report-polish-btn--secondary report-polish-btn--compact';
                b.disabled = !!dis;
                b.onclick = () => { sessionStorage.setItem('capital.currentPage', String(p)); renderInventoryCapital(); };
                return b;
            };
            controls.appendChild(btn(getText('previous') || (isEn ? 'Previous' : 'السابق'), Math.max(1, currentPage - 1), currentPage === 1));
            controls.appendChild(btn(getText('next') || (isEn ? 'Next' : 'التالي'), Math.min(totalPages, currentPage + 1), currentPage === totalPages));
        }
    }
}

function exportCapitalCSV() {
    try {
        const search = String(document.getElementById('capitalSearch')?.value || '').trim().toLowerCase();
        let rows = (Array.isArray(products) ? products : []).map((p) => ({
            name: p.name || '',
            qty: getProductSellableStock(p),
            unitCost: p.costUSD || 0,
            value: getProductSellableStock(p) * (p.costUSD || 0)
        }));
        if (search) rows = rows.filter((r) => String(r.name).toLowerCase().includes(search));
        const isEn = (document.documentElement.lang || 'ar') === 'en';
        const headers = isEn
            ? ['Product', 'Quantity', 'Unit Cost (USD)', 'Inventory Value (USD)']
            : ['المنتج', 'الكمية', 'كلفة الوحدة (USD)', 'قيمة المخزون (USD)'];
        let csv = headers.join(',') + '\n';
        rows.forEach((r) => {
            csv += `"${String(r.name).replace(/"/g, '""')}",${r.qty},${(r.unitCost || 0).toFixed(2)},${(r.value || 0).toFixed(2)}\n`;
        });
        const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = isEn ? 'inventory_capital.csv' : 'رأس_مال_المخزون.csv';
        a.click();
        URL.revokeObjectURL(url);
    } catch (e) {
        console.warn('exportCapitalCSV failed:', e);
    }
}
window.exportCapitalCSV = exportCapitalCSV;

