// تعديل سعر عنصر في العربة وإظهار مقدار الخصم
// Enhanced price editing flow: allow typing freely, validate on blur/enter/confirm
function updateItemCustomPrice(index, value, options = {}) {
    // options: {confirmFlow:false} internal flag
    const item = cart[index];
    if (!item) return;
    const currencySel = document.getElementById('currency');
    const currency = currencySel ? currencySel.value : 'USD';

    // store previous price for possible rollback
    if (typeof item._previousPriceUSD !== 'number') {
        item._previousPriceUSD = (typeof item.customPriceUSD === 'number') ? item.customPriceUSD : getProductPrice(item, item.selectedPriceType || currentPriceType, 'USD');
    }

    // do not block typing: just set a temp typed value on the item for display
    const typedRaw = String(value || '').trim();
    // parse numeric value safely
    const parsedNumber = Number(String(typedRaw).replace(/[^0-9.]/g, ''));
    const typedNumeric = isNaN(parsedNumber) ? null : parsedNumber;

    // when called from oninput, just set a temporary display value and return
    if (!options || !options.confirmFlow) {
        // set a transient property to reflect in UI rendering if needed
        item._typedPriceDisplay = typedRaw;
        // do not set item.customPriceUSD yet
        // if typedNumeric is null, do not update
        if (typedNumeric == null) return;
        // set a working value for immediate preview but do not validate
        item._workingPriceUSD = (currency === 'USD') ? typedNumeric : (typedNumeric / (settings.exchangeRate || 1));
        // Update totals live without re-rendering the whole cart (keeps input focus)
        try {
            const currencyNow = document.getElementById('currency')?.value || 'USD';
            const totals = sumPosCartTotalsFromScratch(currencyNow);
            const ft = document.getElementById('finalTotal');
            if (ft) ft.textContent = formatCurrency(totals.finalTotal, currencyNow);
            setFinalTotalBoxAmount(totals.finalTotal, currencyNow);
            if (typeof updateHorizontalCartSummary === 'function') {
                updateHorizontalCartSummary(totals.totalItems, totals.subtotal);
            }
        } catch (e) {
            console.warn('Live totals update failed:', e);
        }
        // DO NOT re-render the whole cart here (that causes the input to re-render and blur while typing)
        // Instead rely on autosizePriceInput(...) already called by the input event to adjust width.
        return;
    }

    // confirmFlow: user pressed Enter/blur or saved -> perform validation and commit
    // If user left the field empty (or invalid) don't treat it as 0, just rollback to previous
    if (!typedRaw || typedNumeric == null) {
        item.customPriceUSD = item._previousPriceUSD;
        delete item._workingPriceUSD; delete item._typedPriceDisplay; delete item._previousPriceUSD;
        updateCart();
        return;
    }

    const newNum = typedNumeric;
    const newPriceUSD = currency === 'USD' ? newNum : (newNum / (settings.exchangeRate || 1));
    const basePriceUSD = getProductPrice(item, item.selectedPriceType || currentPriceType, 'USD');
    const cost = item.costUSD || 0;

    // if new price is less than cost, show modal confirm
    if (cost && newPriceUSD < cost) {
        // prepare modal
        const modal = document.getElementById('priceWarningModal');
        const text = document.getElementById('priceWarningText');
        const langNow = (document.documentElement.lang || currentLanguage || 'en');
        const isEn = langNow === 'en';

        // Ensure modal title/buttons follow current language (HTML has Arabic defaults)
        if (modal) {
            const titleEl = modal.querySelector('.modal-header h3');
            if (titleEl) {
                titleEl.innerHTML = `<i class="fas fa-exclamation-triangle"></i> ${typeof getText === 'function' ? getText('msg-price-below-cost') : (isEn ? 'Price below cost' : 'تنبيه سعر أقل من الكلفة')}`;
            }
        }
        const yesBtn = document.getElementById('priceWarningYes');
        const noBtn = document.getElementById('priceWarningNo');
        if (yesBtn) yesBtn.textContent = typeof getText === 'function' ? getText('msg-proceed') : (isEn ? 'Proceed' : 'نعم، متابعة');
        if (noBtn) noBtn.textContent = isEn ? 'Cancel' : 'لا، تراجع';

        if (text) {
            text.textContent = isEn
                ? `Warning: The price you entered (${formatCurrency(newNum, currency)}) is below cost (${formatCurrency(cost, 'USD')}). Proceed?`
                : `تنبيه: السعر الذي أدخلته (${formatCurrency(newNum, currency)}) أقل من سعر الكلفة (${formatCurrency(cost, 'USD')}). هل تريد المتابعة؟`;
        }
        // show modal
        if (modal) modal.style.display = 'block';

        // handlers
        const closeBtn = document.getElementById('closePriceWarningModal');

        function cleanup() {
            if (modal) modal.style.display = 'none';
            if (yesBtn) yesBtn.onclick = null;
            if (noBtn) noBtn.onclick = null;
            if (closeBtn) closeBtn.onclick = null;
        }

        if (yesBtn) yesBtn.onclick = function(){
            // accept new price
            item.customPriceUSD = newPriceUSD;
            // remove temp fields
            delete item._workingPriceUSD; delete item._typedPriceDisplay; delete item._previousPriceUSD;
            cleanup(); updateCart();
        };
        if (noBtn) noBtn.onclick = function(){
            // rollback to previous price
            item.customPriceUSD = item._previousPriceUSD;
            delete item._workingPriceUSD; delete item._typedPriceDisplay; delete item._previousPriceUSD;
            cleanup(); updateCart();
        };
        if (closeBtn) closeBtn.onclick = function(){
            // treat as cancel
            if (noBtn) noBtn.onclick();
        };

        return;
    }

    // otherwise commit silently
    console.log(`🔄 Updating custom price for ${item.name}: from $${item.customPriceUSD || 'N/A'} to $${newPriceUSD}`);
    item.customPriceUSD = newPriceUSD;
    delete item._workingPriceUSD; delete item._typedPriceDisplay; delete item._previousPriceUSD;
    console.log(`✅ Custom price saved: $${item.customPriceUSD}`);
    updateCart();
    console.log('🔄 Cart updated after price change');
}

// ضبط عرض + حجم خط حقل السعر تلقائياً لمنع قص الأرقام الكبيرة
function autosizePriceInput(el) {
    if (!el) return;

    const rawValue = String(el.value ?? '').trim();
    const normalized = rawValue.replace(/[^\d.]/g, '');
    const len = normalized.length || 1;

    // width مرن حسب عدد الأرقام، لكن يبقى داخل الكرت
    const ch = Math.max(6, Math.min(15, len + 1));
    el.style.width = ch + 'ch';
    el.style.maxWidth = '100%';

    // تصغير تلقائي تدريجي مع زيادة الأرقام
    const maxFont = 21;
    const minFont = 12;
    let fontSize = maxFont;
    if (len >= 7) fontSize = 19;
    if (len >= 8) fontSize = 18;
    if (len >= 9) fontSize = 16;
    if (len >= 10) fontSize = 15;
    if (len >= 11) fontSize = 14;
    if (len >= 12) fontSize = 13;

    el.style.fontSize = `${Math.max(minFont, Math.min(maxFont, fontSize))}px`;
    el.style.letterSpacing = len >= 9 ? '0' : '0.2px';
    el.title = rawValue;

    // حماية أخيرة: إذا النص ما زال أعرض من المساحة، صغّر حتى يركب
    let guard = 0;
    while (el.scrollWidth > el.clientWidth && guard < 12) {
        const current = parseFloat(el.style.fontSize || `${maxFont}`);
        if (current <= minFont) break;
        el.style.fontSize = `${current - 1}px`;
        guard += 1;
    }
}

// دالة لزيادة السعر
function increasePrice(index) {
    const el = document.getElementById(`customPrice_${index}`);
    if (!el) return;
    
    const currentValue = parseFloat(el.value) || 0;
    const newValue = currentValue + 1;
    el.value = newValue;
    autosizePriceInput(el);
    updateItemCustomPrice(index, el.value);
}

// دالة لتقليل السعر
function decreasePrice(index) {
    const el = document.getElementById(`customPrice_${index}`);
    if (!el) return;
    
    const currentValue = parseFloat(el.value) || 0;
    const newValue = Math.max(0, currentValue - 1);
    el.value = newValue;
    autosizePriceInput(el);
    updateItemCustomPrice(index, el.value);
}

// تسجيل حركة مخزون بسيطة (بيع/استرجاع/تحويل)
function recordStockMovement(type, productId, quantity, invoiceNumber, note, extra) {
    try {
        const movements = loadFromStorage('stockMovements', []);
        movements.push({
            timestamp: new Date().toISOString(),
            type, // 'sale' | 'refund' | 'adjustment'
            productId,
            quantity,
            invoiceNumber,
            note,
            ...(extra && typeof extra === 'object' ? extra : {})
        });
        saveToStorage('stockMovements', movements);
    } catch (e) {
        console.warn('recordStockMovement failed:', e);
    }
}

function _normalizeImeiValue(v) {
    return String(v || '').replace(/\s/g, '');
}

function _buildCartStockDemand(cartItems) {
    const demandByProduct = new Map();
    (Array.isArray(cartItems) ? cartItems : []).forEach((item) => {
        if (!item || item.type === 'previous_account') return;
        const productId = item.id;
        if (productId == null) return;
        const qty = Math.max(0, Number(item.quantity) || 0);
        if (qty <= 0) return;
        if (!demandByProduct.has(productId)) {
            demandByProduct.set(productId, { qty: 0, imeis: [] });
        }
        const demand = demandByProduct.get(productId);
        demand.qty += qty;
        if (item.imei) demand.imeis.push(_normalizeImeiValue(item.imei));
    });
    return demandByProduct;
}

function validateCartStockAvailability(cartItems) {
    const latestProducts = getCurrentProducts();
    const demandByProduct = _buildCartStockDemand(cartItems);
    for (const [productId, demand] of demandByProduct.entries()) {
        const product = latestProducts.find(p => String(p.id) === String(productId));
        if (!product) {
            return { ok: false, message: getText('msg-cart-has-deleted-product') || 'منتج في العربة غير موجود' };
        }
        if (product.imeiTracking && Array.isArray(product.imeiList)) {
            const availableImeiEntries = product.imeiList.filter(e => e && (e.status === 'available' || e.status === 'returned'));
            if (demand.imeis.length) {
                const availableSet = new Set(availableImeiEntries.map(e => _normalizeImeiValue(e.imei)));
                for (const imei of demand.imeis) {
                    if (!availableSet.has(imei)) {
                        return {
                            ok: false,
                            message: getText('msg-cannot-sell-qty', { product: product.name || 'Item', stock: availableImeiEntries.length })
                        };
                    }
                }
            } else if (availableImeiEntries.length < demand.qty) {
                return {
                    ok: false,
                    message: getText('msg-cannot-sell-qty', { product: product.name || 'Item', stock: availableImeiEntries.length })
                };
            }
        } else {
            const currentStock = getProductSellableStock(product);
            if (currentStock < demand.qty) {
                return {
                    ok: false,
                    message: getText('msg-cannot-sell-qty', { product: product.name || 'Item', stock: currentStock })
                };
            }
        }
    }
    return { ok: true };
}

function applySaleStockDeduction(cartItems, movementNotePrefix) {
    const validation = validateCartStockAvailability(cartItems);
    if (!validation.ok) return validation;

    const latestProducts = getCurrentProducts();
    const modified = [];
    (Array.isArray(cartItems) ? cartItems : []).forEach((item) => {
        if (!item || item.type === 'previous_account') return;
        const product = latestProducts.find(p => String(p.id) === String(item.id));
        if (!product) return;
        const qty = Math.max(0, Number(item.quantity) || 0);
        if (qty <= 0) return;

        if (product.imeiTracking && Array.isArray(product.imeiList) && item.imei) {
            const imeiNorm = _normalizeImeiValue(item.imei);
            const entry = product.imeiList.find(e => _normalizeImeiValue(e.imei) === imeiNorm);
            if (entry) entry.status = 'sold';
            product.stock = product.imeiList.filter(e => e.status === 'available' || e.status === 'returned').length;
        } else {
            product.stock = Math.max(0, (Number(product.stock) || 0) - qty);
        }

        touchProductClientTimestamp(product);
        modified.push(product);
        recordStockMovement('sale', product.id, -qty, 'PENDING', `${movementNotePrefix || 'خصم بيع'} ${item.name || ''}`.trim());
    });

    saveToStorage('products', latestProducts);
    products = latestProducts;
    modified.forEach((p) => {
        try { enqueueSyncOp('products', 'upsert', p.id, p); } catch (_) {}
    });
    if (modified.length) scheduleSyncFlush();
    return { ok: true };
}

function cloneForRollback(value) {
    try {
        return JSON.parse(JSON.stringify(value));
    } catch (_) {
        if (Array.isArray(value)) return value.slice();
        if (value && typeof value === 'object') return { ...value };
        return value;
    }
}

function captureProductSnapshotsForCart(cartItems) {
    const latestProducts = getCurrentProducts();
    const ids = [...new Set((Array.isArray(cartItems) ? cartItems : [])
        .filter((item) => item && item.type !== 'previous_account' && item.id != null)
        .map((item) => String(item.id)))];
    return ids
        .map((id) => latestProducts.find((p) => String(p.id) === id))
        .filter(Boolean)
        .map((product) => cloneForRollback(product));
}

function restoreProductSnapshots(snapshots) {
    if (!Array.isArray(snapshots) || snapshots.length === 0) return;
    const latestProducts = getCurrentProducts();
    snapshots.forEach((snapshot) => {
        const idx = latestProducts.findIndex((p) => String(p.id) === String(snapshot.id));
        if (idx >= 0) latestProducts[idx] = cloneForRollback(snapshot);
        else latestProducts.push(cloneForRollback(snapshot));
    });
    products = latestProducts;
    saveToStorage('products', latestProducts);
    snapshots.forEach((snapshot) => {
        try { enqueueSyncOp('products', 'upsert', snapshot.id, cloneForRollback(snapshot)); } catch (_) {}
    });
    try { scheduleSyncFlush(); } catch (_) {}
}

function captureStockMovementsSnapshot() {
    return cloneForRollback(loadFromStorage('stockMovements', []));
}

function restoreStockMovementsSnapshot(snapshot) {
    const safe = Array.isArray(snapshot) ? cloneForRollback(snapshot) : [];
    saveToStorage('stockMovements', safe);
}

function restoreCustomerSnapshot(snapshot) {
    if (!snapshot || snapshot.id == null) return null;
    const idx = customers.findIndex((c) => String(c.id) === String(snapshot.id));
    if (idx >= 0) customers[idx] = cloneForRollback(snapshot);
    else customers.push(cloneForRollback(snapshot));
    saveToStorage('customers', customers);
    try { enqueueSyncOp('customers', 'upsert', snapshot.id, cloneForRollback(snapshot)); } catch (_) {}
    try { scheduleSyncFlush(); } catch (_) {}
    return customers.find((c) => String(c.id) === String(snapshot.id)) || null;
}

// إظهار/إخفاء حقل تعديل السعر
function togglePriceEdit(index) {
    const wrap = document.getElementById(`editPriceWrap_${index}`);
    if (!wrap) return;
    const visible = wrap.style.display !== 'none';
    wrap.style.display = visible ? 'none' : 'flex';
    if (!visible) {
        const input = document.getElementById(`customPrice_${index}`);
        if (input) {
            input.focus();
            input.select();
        }
    }
}

// تحرير سريع عبر نافذة منبثقة (مناسب للزوم المنخفض)
// بيانات النظام
let currentUser = null;
let __featureFlagsState = {};
let __featureFlagsUnsub = null;
let __resolvedFeatureFlagsState = {};
let __featureFlagsDeploymentGate = { lockedForCurrentUser: false };
const FEATURE_FLAGS_SESSION_CACHE_KEY = 'featureFlags.resolved.v1';
const FEATURE_FLAGS_SESSION_TTL_MS = 5 * 60 * 1000;

function isCurrentSessionSuperAdmin() {
    try {
        if (window.firebaseAuthInstance && typeof window.firebaseAuthInstance.isSuperAdmin === 'function') {
            if (window.firebaseAuthInstance.isSuperAdmin()) return true;
        }
        const u = (typeof currentUser === 'object' && currentUser) ? currentUser : (window.currentUser || null);
        if (!u) return false;
        if (u.isSuperAdmin === true) return true;
        const role = String((u && u.role) || '').toLowerCase();
        if (role === 'superadmin' || role === 'super_admin') return true;
        const claims = (u && u.claims) ? u.claims : {};
        return !!(claims.super_admin === true || claims.superAdmin === true);
    } catch (_) {
        return false;
    }
}

function stopFeatureFlagsWatcher() {
    try { if (typeof __featureFlagsUnsub === 'function') __featureFlagsUnsub(); } catch (_) {}
    __featureFlagsUnsub = null;
    __featureFlagsState = {};
    __resolvedFeatureFlagsState = {};
    __featureFlagsDeploymentGate = { lockedForCurrentUser: false };
    try { sessionStorage.removeItem(FEATURE_FLAGS_SESSION_CACHE_KEY); } catch (_) {}
}

function __loadResolvedFeatureFlagsFromSession() {
    try {
        const raw = sessionStorage.getItem(FEATURE_FLAGS_SESSION_CACHE_KEY);
        if (!raw) return null;
        const parsed = JSON.parse(raw);
        if (!parsed || typeof parsed !== 'object') return null;
        const uid = String((parsed.uid || '')).trim();
        const me = String((getCurrentUserId ? getCurrentUserId() : '') || '').trim();
        if (!uid || !me || uid !== me) return null;
        const expiresAt = Number(parsed.expiresAt || 0);
        if (!Number.isFinite(expiresAt) || Date.now() > expiresAt) return null;
        if (parsed.deploymentGate && typeof parsed.deploymentGate === 'object') {
            __featureFlagsDeploymentGate = parsed.deploymentGate;
        }
        return (parsed.resolved && typeof parsed.resolved === 'object') ? parsed.resolved : null;
    } catch (_) {
        return null;
    }
}

async function refreshResolvedFeatureFlagsSecure(force = false) {
    const db = window.firebaseDbInstance;
    if (!db || typeof db.resolveFeatureFlagsSecure !== 'function') return;
    if (!force) {
        const cached = __loadResolvedFeatureFlagsFromSession();
        if (cached) {
            __resolvedFeatureFlagsState = cached;
            return;
        }
    }
    try {
        const res = await db.resolveFeatureFlagsSecure({
            fallback: false,
            forceRefresh: !!force,
            currentVersionCode: Number(window.__APP_VERSION_CODE || 0) || 0
        });
        const resolved = res && res.resolved && typeof res.resolved === 'object' ? res.resolved : {};
        const deploymentGate = res && res.deploymentGate && typeof res.deploymentGate === 'object'
            ? res.deploymentGate
            : { lockedForCurrentUser: false };
        __resolvedFeatureFlagsState = resolved;
        __featureFlagsDeploymentGate = deploymentGate;
        const uid = String((getCurrentUserId ? getCurrentUserId() : '') || '').trim();
        if (uid) {
            const payload = {
                uid,
                resolved,
                deploymentGate,
                expiresAt: Date.now() + FEATURE_FLAGS_SESSION_TTL_MS
            };
            try { sessionStorage.setItem(FEATURE_FLAGS_SESSION_CACHE_KEY, JSON.stringify(payload)); } catch (_) {}
        }
    } catch (error) {
        console.warn('refreshResolvedFeatureFlagsSecure failed:', error && (error.message || error.code || error));
    }
}

function startFeatureFlagsWatcher() {
    stopFeatureFlagsWatcher();
    const db = window.firebaseDbInstance;
    if (!db || typeof db.subscribeFeatureFlagsControl !== 'function') return;
    refreshResolvedFeatureFlagsSecure(false);
    __featureFlagsUnsub = db.subscribeFeatureFlagsControl((payload) => {
        const ff = payload && payload.featureFlags && typeof payload.featureFlags === 'object'
            ? payload.featureFlags
            : {};
        __featureFlagsState = ff;
        window.__featureFlagsState = ff;
        refreshResolvedFeatureFlagsSecure(true);
    });
}

function isFeatureEnabled(flagKey, fallback = false) {
    const key = String(flagKey || '').trim();
    if (!key) return !!fallback;
    if (__resolvedFeatureFlagsState && Object.prototype.hasOwnProperty.call(__resolvedFeatureFlagsState, key)) {
        return !!__resolvedFeatureFlagsState[key];
    }
    if (__featureFlagsDeploymentGate && __featureFlagsDeploymentGate.lockedForCurrentUser === true) {
        // Admin-first deployment model: any unknown/new feature stays OFF for non-super-admin
        // while this build is still in admin-only stage.
        return false;
    }
    const rule = (__featureFlagsState && Object.prototype.hasOwnProperty.call(__featureFlagsState, key))
        ? __featureFlagsState[key]
        : undefined;
    if (rule === undefined || rule === null) return !!fallback;
    if (typeof rule === 'boolean') return !!rule;
    if (typeof rule !== 'object') return !!fallback;

    const mode = String(rule.mode || '').toLowerCase();
    if (mode === 'off') return false;
    if (mode === 'global' || mode === 'all' || mode === 'on') return true;
    if (mode === 'super_admin_only') return isCurrentSessionSuperAdmin();

    const uid = getCurrentUserId ? String(getCurrentUserId() || '') : '';
    const ownerId = getEffectiveDataOwnerId ? String(getEffectiveDataOwnerId() || '') : '';
    const tenantId = getSharedCashboxDocId ? String(getSharedCashboxDocId() || '') : '';

    const pickList = (x) => Array.isArray(x) ? x.map(v => String(v || '').trim()).filter(Boolean) : [];
    const userIds = pickList(rule.userIds || rule.allowUids || rule.allowedUsers);
    const ownerIds = pickList(rule.ownerIds || rule.allowOwnerIds || rule.allowedOwners);
    const tenantIds = pickList(rule.tenantIds || rule.allowTenantIds || rule.allowedTenants);

    if (mode === 'allow_list' || mode === 'targeted' || mode === 'selected') {
        return userIds.includes(uid) || ownerIds.includes(ownerId) || tenantIds.includes(tenantId);
    }
    if (mode === 'owner_only') return ownerIds.includes(ownerId);
    if (mode === 'tenant_only') return tenantIds.includes(tenantId);
    if (mode === 'user_only') return userIds.includes(uid);

    // Generic object fallback:
    // enabled=true means globally enabled, unless restricted by allow-list arrays.
    const enabled = !!rule.enabled;
    if (!enabled) return false;
    const hasScopedLists = userIds.length > 0 || ownerIds.length > 0 || tenantIds.length > 0;
    if (!hasScopedLists) return true;
    return userIds.includes(uid) || ownerIds.includes(ownerId) || tenantIds.includes(tenantId);
}

window.isFeatureEnabled = isFeatureEnabled;
