// ---------------- License management ----------------
const LICENSE_STATE_KEY = 'license_state';
const ACTIVATION_TOKEN_KEY = 'delta_activation_token'; // مفتاح التفعيل الجديد
/** آخر حالة تفعيل مؤكدة للمستخدم الحالي (لا يُمسح إلا عند تسجيل الخروج أو عند تأكيد عدم التفعيل من السيرفر) */
const ACTIVATION_LAST_KNOWN_KEY = 'activation_last_known_v1';

function readActivationLastKnown(uid) {
    try {
        if (!uid) return null;
        const raw = localStorage.getItem(ACTIVATION_LAST_KNOWN_KEY);
        if (!raw) return null;
        const o = JSON.parse(raw);
        if (!o || o.uid !== uid) return null;
        return o;
    } catch (_) {
        return null;
    }
}

function persistActivationLastKnown(uid, extra = {}) {
    try {
        if (!uid) return;
        localStorage.setItem(ACTIVATION_LAST_KNOWN_KEY, JSON.stringify({
            uid,
            activated: true,
            atMs: Date.now(),
            ...extra
        }));
    } catch (_) {}
}

function clearActivationLastKnown() {
    try { localStorage.removeItem(ACTIVATION_LAST_KNOWN_KEY); } catch (_) {}
}

function isConnectivityOffline() {
    return (typeof navigator !== 'undefined' && navigator.onLine === false) ||
        (typeof window !== 'undefined' && window.__posNetOffline === true);
}

function isFirestoreOfflineLikeError(err) {
    if (!err) return false;
    const code = (err.code || '').toString();
    const msg = (err.message || '').toString().toLowerCase();
    if (code === 'unavailable' || code === 'deadline-exceeded') return true;
    if (msg.includes('offline') || msg.includes('client is offline') || msg.includes('failed to get document')) return true;
    if (msg.includes('network') || msg.includes('fetch') || msg.includes('internet') || msg.includes('connection failed')) return true;
    if (msg.includes('err_internet_disconnected') || msg.includes('quic') || msg.includes('econnreset')) return true;
    return false;
}

// دالة مركزية للتحقق من التفعيل — السيرفر مصدر الحقيقة عند الاتصال؛ عند انقطاع الشبكة لا يُلغى التفعيل
async function isActivated() {
    try { window.__activationCheckWasOffline = false; } catch (_) {}

    try {
        if (!window.firebaseAuthInstance || !window.firebaseAuthInstance.isAuthenticated() || !window.firebaseDbInstance) {
            return false;
        }
        const currentUser = window.firebaseAuthInstance.getCurrentUser();
        if (!currentUser || !currentUser.uid) return false;
        const subUserId = (typeof getEffectiveDataOwnerId === 'function' ? getEffectiveDataOwnerId() : null) || currentUser.uid;

        // المتصفح يُبلّغ offline: لا نستدعي Firestore ولا نُلغي التفعيل
        if (isConnectivityOffline()) {
            try { window.__activationCheckWasOffline = true; } catch (_) {}
            const last = readActivationLastKnown(subUserId);
            if (last && last.activated) return true;
            if (window.__lastActivationStatus && window.__lastActivationStatus.activated) return true;
            return true;
        }

        const getSub = window.firebaseDbInstance.getSubscriptionForActivationCheck
            ? window.firebaseDbInstance.getSubscriptionForActivationCheck.bind(window.firebaseDbInstance)
            : window.firebaseDbInstance.getSubscription.bind(window.firebaseDbInstance);
        const firestoreSubscription = await getSub(subUserId);

        // null: إما لا وثيقة، أو فشل شبكة — يميّز getSubscription عبر __firebaseSubReadOfflineGuess
        if (!firestoreSubscription) {
            const offlineGuess = (typeof window !== 'undefined' && window.__firebaseSubReadOfflineGuess === true);
            try { window.__activationCheckWasOffline = true; } catch (_) {}
            const last = readActivationLastKnown(subUserId);
            if (last && last.activated) return true;
            if (window.__lastActivationStatus && window.__lastActivationStatus.activated) return true;
            if (offlineGuess) return true;
            return false;
        }

        if (!firestoreSubscription.activated) {
            clearActivationLastKnown();
            try { window.__lastActivationStatus = { activated: false, at: Date.now() }; } catch (_) {}
            return false;
        }

        if (firestoreSubscription.lifetime) {
            persistActivationLastKnown(subUserId, { lifetime: true });
            try { window.__lastActivationStatus = { activated: true, at: Date.now(), lifetime: true }; } catch (_) {}
            return true;
        }
        if (!firestoreSubscription.endDate) {
            return false;
        }
        const endDate = new Date(firestoreSubscription.endDate);
        let nowMs = null;
        try {
            nowMs = await window.firebaseDbInstance.getServerTimeMs(subUserId);
        } catch (e) {
            nowMs = Date.now();
        }
        if (nowMs == null) return false;
        const activated = endDate.getTime() >= nowMs;
        try {
            window.__lastActivationStatus = { activated, at: Date.now(), lifetime: false };
        } catch (_) {}
        if (activated) {
            persistActivationLastKnown(subUserId, { endDate: firestoreSubscription.endDate });
        } else {
            clearActivationLastKnown();
        }
        return activated;
    } catch (error) {
        if (isFirestoreOfflineLikeError(error)) {
            try { window.__activationCheckWasOffline = true; } catch (_) {}
            const subUserId = (typeof getEffectiveDataOwnerId === 'function' ? getEffectiveDataOwnerId() : null) ||
                (window.firebaseAuthInstance && window.firebaseAuthInstance.getCurrentUser && window.firebaseAuthInstance.getCurrentUser()?.uid);
            if (subUserId) {
                const last = readActivationLastKnown(subUserId);
                if (last && last.activated) return true;
            }
            if (window.__lastActivationStatus && window.__lastActivationStatus.activated) return true;
            return true;
        }
        if (error.code !== 'unavailable' && !error.message?.includes('offline') && !error.message?.includes('network')) {
            console.warn('⚠️ Error checking Firestore subscription:', error);
        }
        return false;
    }
}

