// Activation guard on page load
async function checkActivationOnPageLoad() {
    console.log('🔍 Checking activation on page load...');
    
    // Wait for Firebase to be ready if not already
    if (!window.firebaseDbInstance || !window.firebaseAuthInstance) {
        console.log('⏳ Waiting for Firebase initialization...');
        // Wait up to 5 seconds for Firebase to initialize
        let attempts = 0;
        while ((!window.firebaseDbInstance || !window.firebaseAuthInstance) && attempts < 10) {
            await new Promise(resolve => setTimeout(resolve, 500));
            attempts++;
        }
    }
    
    // إذا المستخدم غير مسجّل: نعرض شاشة الدخول فقط ولا نعطّل زر الدخول (التحقق من الاشتراك بعد الدخول)
    const loginBtn = document.querySelector('#loginForm button[type="submit"]');
    if (loginBtn) { loginBtn.style.opacity = '1'; loginBtn.style.cursor = 'pointer'; loginBtn.title = ''; }
    const isLoggedIn = !!(window.firebaseAuthInstance && window.firebaseAuthInstance.isAuthenticated());
    if (!isLoggedIn) {
        const mainScreen = document.getElementById('mainScreen');
        const loginScreen = document.getElementById('loginScreen');
        if (mainScreen) mainScreen.classList.remove('active');
        if (loginScreen) loginScreen.classList.add('active');
        return;
    }
    // المستخدم مسجّل: التحقق من الاشتراك من Firebase — مع إعادة محاولة لتجنب ظهور "غير مفعّل" بالخطأ عند Refresh (قبل جاهزية Firestore)
    async function showActivationScreenAndMessage() {
        console.log('❌ System not activated — showing activation screen');
        const mainScreen = document.getElementById('mainScreen');
        const loginScreen = document.getElementById('loginScreen');
        const activationCard = document.getElementById('activationCard');
        if (mainScreen) mainScreen.classList.remove('active');
        if (loginScreen) loginScreen.classList.add('active');
        if (activationCard) {
            activationCard.style.display = '';
            const activationCardMessage = document.getElementById('activationCardMessage');
            if (activationCardMessage) { activationCardMessage.style.display = 'none'; activationCardMessage.textContent = ''; }
            const activationCardTitle = document.getElementById('activationCardTitle');
            const activationCardDesc = document.getElementById('activationCardDesc');
            if (activationCardTitle) activationCardTitle.textContent = 'Account Not Activated';
            if (activationCardDesc) activationCardDesc.textContent = 'Use Free Activation (first month) or contact admin (Super Admin) to get your subscription.';
        }
        if (loginBtn) { loginBtn.style.opacity = '1'; loginBtn.style.cursor = 'pointer'; loginBtn.title = ''; }
        setTimeout(function() {
            showMessage('🔒 Account not activated. Use Free Activation (first month) or contact admin to get subscription.', 'warning');
        }, 800);
    }
    
    let activated = await isActivated();
    if (activated) {
        console.log('✅ System activated — continuing normal load');
        const activationCard = document.getElementById('activationCard');
        if (activationCard) activationCard.style.display = 'none';
        if (loginBtn) { loginBtn.style.opacity = '1'; loginBtn.style.cursor = 'pointer'; loginBtn.title = ''; }
        return;
    }
    // إعادة محاولة بعد تأخير قصير (عند Refresh قد لا يكون Firestore جاهزاً بعد)
    await new Promise(function(r) { setTimeout(r, 1200); });
    activated = await isActivated();
    if (activated) {
        console.log('✅ System activated after retry');
        const activationCard = document.getElementById('activationCard');
        if (activationCard) activationCard.style.display = 'none';
        if (loginBtn) { loginBtn.style.opacity = '1'; loginBtn.style.cursor = 'pointer'; loginBtn.title = ''; }
        return;
    }
    // محاولة أخيرة قبل عرض رسالة التفعيل
    await new Promise(function(r) { setTimeout(r, 1500); });
    activated = await isActivated();
    if (activated) {
        console.log('✅ System activated after second retry');
        const activationCard = document.getElementById('activationCard');
        if (activationCard) activationCard.style.display = 'none';
        if (loginBtn) { loginBtn.style.opacity = '1'; loginBtn.style.cursor = 'pointer'; loginBtn.title = ''; }
        return;
    }
    if (isConnectivityOffline() || (typeof window !== 'undefined' && window.__activationCheckWasOffline === true)) {
        console.log('⏭️ Skipping activation screen — offline or network read failure (not treating as deactivated)');
        const activationCard = document.getElementById('activationCard');
        if (activationCard) activationCard.style.display = 'none';
        return;
    }
    showActivationScreenAndMessage();
}

// حارس التفعيل المستمر أثناء الجلسة — لا يُلغى التفعيل بسبب انقطاع الشبكة
async function checkActivationDuringSession() {
    if (!currentUser) {
        return;
    }
    if (isConnectivityOffline()) {
        return;
    }
    const activationStatus = await isActivated();
    if (!activationStatus) {
        if (typeof window !== 'undefined' && window.__activationCheckWasOffline === true) {
            console.log('🌐 Activation inconclusive (network) — not showing activation UI');
            return;
        }
        const uid = window.firebaseAuthInstance?.getCurrentUser()?.uid;
        if (uid && readActivationLastKnown(uid)?.activated) {
            console.log('📦 Last known activation OK — not showing activation UI');
            return;
        }
        try {
            const cachedSub = await window.firebaseDbInstance?.getSubscriptionForActivationCheck?.(uid);
            if (cachedSub && cachedSub.activated) {
                console.log('✅ Found activated subscription in cache');
                return;
            }
        } catch (e) {}
        
        console.log('🚨 Activation lost during session — showing activation UI');
        
        // إخفاء الشاشة الرئيسية
        const mainScreen = document.getElementById('mainScreen');
        if (mainScreen) {
            mainScreen.classList.remove('active');
        }
        
        // إظهار شاشة تسجيل الدخول
        const loginScreen = document.getElementById('loginScreen');
        if (loginScreen) {
            loginScreen.classList.add('active');
        }
        
        const activationCard = document.getElementById('activationCard');
        if (activationCard) {
            activationCard.style.display = '';
            const activationCardMessage = document.getElementById('activationCardMessage');
            if (activationCardMessage) {
                activationCardMessage.style.display = 'none';
                activationCardMessage.textContent = '';
            }
            const activationCardTitle = document.getElementById('activationCardTitle');
            const activationCardDesc = document.getElementById('activationCardDesc');
            if (activationCardTitle) activationCardTitle.textContent = 'Account Not Activated';
            if (activationCardDesc) activationCardDesc.textContent = 'Use Free Activation (first month) or contact admin (Super Admin) to get your subscription.';
        }
        
        const message = '🚨 Account not activated. Use Free Activation or contact admin.';
        showMessage(message, 'error');
    } else {
        const activationCard = document.getElementById('activationCard');
        if (activationCard) activationCard.style.display = 'none';
    }
}

// نظام التخزين الآمن للترخيص (مستقل عن localStorage)
class SecureLicenseStorage {
    constructor() {
        this.storageKey = 'catch_pos_license';
        this.fileName = 'license.dat';
    }

    // حفظ الترخيص في ملف محلي
    async saveLicense(licenseData) {
        try {
            // حفظ في localStorage
            try {
                localStorage.setItem(this.storageKey, JSON.stringify(licenseData));
                console.log('License saved to localStorage');
            } catch (e) {
                console.warn('LocalStorage save failed:', e);
            }
            
            // نسخ احتياطي في sessionStorage
            try {
                sessionStorage.setItem(this.storageKey, JSON.stringify(licenseData));
                console.log('License saved to sessionStorage');
            } catch (e) {
                console.warn('SessionStorage save failed:', e);
            }
            
            console.log('License saved securely');
            return true;
        } catch (e) {
            console.error('Failed to save license securely:', e);
            return false;
        }
    }

    // تحميل الترخيص من الملف المحلي
    async loadLicense() {
        try {
            // محاولة تحميل من localStorage أولاً
            try {
                const localData = localStorage.getItem(this.storageKey);
                if (localData) {
                    const parsed = JSON.parse(localData);
                    if (parsed && parsed.activated) {
                        console.log('License loaded from localStorage');
                        return parsed;
                    }
                }
            } catch (e) {
                console.warn('LocalStorage load failed:', e);
            }

            // محاولة تحميل من sessionStorage كنسخة احتياطية
            try {
                const sessionData = sessionStorage.getItem(this.storageKey);
                if (sessionData) {
                    const parsed = JSON.parse(sessionData);
                    if (parsed && parsed.activated) {
                        console.log('License loaded from sessionStorage');
                        // نسخ إلى localStorage
                        this.saveLicense(parsed);
                        return parsed;
                    }
                }
            } catch (e) {
                console.warn('SessionStorage load failed:', e);
            }

            console.log('No valid license found');
            return null;
        } catch (e) {
            console.error('Failed to load license:', e);
            return null;
        }
    }

    // حفظ في IndexedDB (معطل مؤقتاً)
    async saveToIndexedDB(data) {
        // تعطيل IndexedDB مؤقتاً لتجنب المشاكل
        console.log('IndexedDB save disabled temporarily');
        return false;
    }

    // تحميل من IndexedDB (معطل مؤقتاً)
    async loadFromIndexedDB() {
        // تعطيل IndexedDB مؤقتاً لتجنب المشاكل
        console.log('IndexedDB load disabled temporarily');
        return null;
    }

}

