// Load subscription from Firestore and update localStorage
async function loadSubscriptionFromFirestore(userId) {
    if (!userId) {
        console.warn('⚠️ Cannot load subscription: userId missing');
        return false;
    }
    
    // Wait for Firebase DB to be ready
    if (!window.firebaseDbInstance) {
        console.log('⏳ Waiting for Firebase DB initialization...');
        let attempts = 0;
        while (!window.firebaseDbInstance && attempts < 10) {
            await new Promise(resolve => setTimeout(resolve, 500));
            attempts++;
        }
        if (!window.firebaseDbInstance) {
            console.warn('⚠️ Cannot load subscription: Firebase DB not initialized after waiting');
            return false;
        }
    }

    // Verify user is authenticated
    if (!window.firebaseAuthInstance || !window.firebaseAuthInstance.isAuthenticated()) {
        console.warn('⚠️ Cannot load subscription: User not authenticated');
        return false;
    }

    // Verify userId matches current user
    const currentUser = window.firebaseAuthInstance.getCurrentUser();
    if (!currentUser || currentUser.uid !== userId) {
        console.warn('⚠️ Cannot load subscription: userId mismatch');
        return false;
    }

    try {
        // Get subscription from Firestore
        const firestoreSubscription = await window.firebaseDbInstance.getSubscription(userId);
        
        if (firestoreSubscription && firestoreSubscription.activated) {
            console.log('✅ Found active subscription in Firestore');
            return true;
        } else {
            console.log('ℹ️ No active subscription found in Firestore');
            return false;
        }
    } catch (error) {
        console.error('❌ Error loading subscription from Firestore:', error);
        // Don't show error to user if it's just a permissions issue
        if (error.code !== 'permission-denied') {
            console.error('Full error details:', error);
        }
        return false;
    }
}

