async function getCurrentAuthClaims() {
    try {
        const auth = window.firebaseAuth || (window.firebaseAuthInstance && window.firebaseAuthInstance.auth);
        const u = auth && auth.currentUser;
        if (!u || typeof u.getIdTokenResult !== 'function') return {};
        const tokenResult = await u.getIdTokenResult(true);
        return (tokenResult && tokenResult.claims) ? tokenResult.claims : {};
    } catch (_) {
        return {};
    }
}

async function hasPrivilegedRole(requiredPermission) {
    const claims = await getCurrentAuthClaims();
    const isClaimSuperAdmin = !!(claims && (claims.super_admin === true || claims.superAdmin === true));
    if (isClaimSuperAdmin) return true;
    const role = String((currentUser && currentUser.role) || '').toLowerCase();
    if (role === 'admin' || role === 'superadmin') return true;
    if (requiredPermission && currentUser && currentUser.permissions) {
        if (Array.isArray(requiredPermission)) {
            for (const perm of requiredPermission) {
                if (perm && currentUser.permissions[perm] === true) return true;
            }
        } else if (currentUser.permissions[requiredPermission] === true) {
            return true;
        }
    }
    return false;
}

function getManualSecurityCodeValue() {
    const candidateIds = [
        'headerSecurityCodeInput',
        'quickSecurityCodeInput',
        'securityCodeInput'
    ];
    for (const id of candidateIds) {
        const el = document.getElementById(id);
        if (!el) continue;
        const value = String(el.value || '').trim();
        if (value) return value;
    }
    return '';
}

async function requirePrivilegedActionAuth(options = {}) {
    const currentLang = document.documentElement.lang || localStorage.getItem('appLanguage') || 'ar';
    const isEn = currentLang === 'en';
    const requiredPermission = options.requiredPermission || '';
    const accessDeniedMsg = options.accessDeniedMessage || (isEn ? 'Access denied.' : 'تم رفض الوصول.');

    // Manual override: typing code "00" in the dedicated input accepts immediately.
    if (getManualSecurityCodeValue() === '00') {
        return true;
    }

    if (!(await hasPrivilegedRole(requiredPermission))) {
        showNotification('❌ ' + accessDeniedMsg, 'error', 3000);
        return false;
    }
    return true;
}

window.requirePrivilegedActionAuth = requirePrivilegedActionAuth;

