/* خريطة خيارات المسح إلى كيانات Firestore (لحذف من السحابة أيضاً) */
const CLEAR_TO_FIRESTORE_ENTITIES = {
    invoices: ['sales'],
    customers: ['customers'],
    suppliers: ['suppliers'],
    salesHistory: [],
    cashbox: ['cashDrawer', 'cashDrawerTx'],
    items: ['products'],
    purchases: ['purchases', 'supplierPayments', 'purchaseReturns', 'supplierLedger'],
    stockMovements: [],
    reports: [],
    settings: ['settings'],
    all: ['products', 'customers', 'sales', 'suppliers', 'purchases', 'supplierPayments', 'purchaseReturns', 'supplierLedger', 'cashDrawer', 'cashDrawerTx', 'settings']
};

async function executeClearData(selectedOptions) {
    const isEn = (document.documentElement.lang || localStorage.getItem('appLanguage')) === 'en';
    const keysToDelete = new Set();
    if (selectedOptions.includes('all')) {
        CLEAR_DATA_MAP.all.forEach(k => keysToDelete.add(k));
    } else {
        selectedOptions.forEach(opt => {
            const keys = CLEAR_DATA_MAP[opt];
            if (Array.isArray(keys)) keys.forEach(k => keysToDelete.add(k));
        });
    }
    const arr = Array.from(keysToDelete);
    
    // أولاً: مسح كامل لكل البيانات من هذا الجهاز (local / indexedDB / sqlite / OPFS)
    await forceDeleteFromStorage(arr);
    
    // ثانياً: محاولة مسح نفس البيانات من حساب المستخدم في Firestore
    const uid = getCurrentUserId();
    let remoteAttempted = false;
    let remoteCleared = false;
    if (uid && window.firebaseDbInstance && navigator.onLine !== false) {
        remoteAttempted = true;
        const firestoreEntities = new Set();
        if (selectedOptions.includes('all')) {
            CLEAR_TO_FIRESTORE_ENTITIES.all.forEach(e => firestoreEntities.add(e));
        } else {
            selectedOptions.forEach(opt => {
                const ents = CLEAR_TO_FIRESTORE_ENTITIES[opt];
                if (Array.isArray(ents)) ents.forEach(e => firestoreEntities.add(e));
            });
        }
        const entitiesArr = Array.from(firestoreEntities);
        if (entitiesArr.length > 0) {
            try {
                await window.firebaseDbInstance.v2ClearUserDataForClearData(uid, entitiesArr);
                await window.firebaseDbInstance.v1ClearUserDataDoc(uid, entitiesArr);
                console.log('✅ Firestore clear completed:', entitiesArr);
                remoteCleared = true;
            } catch (e) {
                console.warn('Firestore clear failed (local cleared):', e);
            }
        }
    }
    
    // مسح جدول sales من __sqlite إن وُجد
    if (arr.includes('sales') && typeof __sqlite !== 'undefined' && __sqlite) {
        try { __sqlite.run('DELETE FROM sales'); if (typeof persistSqliteDb === 'function') persistSqliteDb(); } catch(_) {}
    }
    
    // إعادة تعيين المتغيرات في الذاكرة حسب ما تم حذفه
    if (arr.includes('products')) products = [];
    if (arr.includes('customers')) customers = [];
    if (arr.includes('sales')) sales = [];
    if (arr.includes('suppliers')) suppliers = [];
    if (arr.includes('purchases')) purchases = [];
    if (arr.includes('supplierPayments')) supplierPayments = [];
    if (arr.includes('purchaseReturns')) purchaseReturns = [];
    if (arr.includes('supplierLedger')) supplierLedger = [];
    if (arr.includes('stockMovements')) { try { if (__largeCache) delete __largeCache.stockMovements; } catch(_) {} }
    if (arr.includes('salesLogs')) { try { if (__largeCache) delete __largeCache.salesLogs; } catch(_) {} }
    if (arr.includes('customerLogs')) { /* in memory via loadFromStorage */ }
    if (arr.includes('cashDrawer') || arr.includes('cashDrawerTx')) {
        cashDrawer = { cashUSD: 0, cashLBP: 0, transactions: [], lastUpdate: new Date().toISOString() };
    }
    if (arr.includes('cart') || selectedOptions.includes('all')) { if (typeof resetPosCartTabs === 'function') resetPosCartTabs(); else { cart.length = 0; lastCartFocusIndex = null; } }
    
    try { updateProductsDisplay(); } catch(_) {}
    try { updateCustomersDisplay(); } catch(_) {}
    try { updateSalesDisplay(); } catch(_) {}
    try { updateSuppliersDisplay(); } catch(_) {}
    try { updateCashDrawerDisplay(); } catch(_) {}
    
    hideClearDataModal();
    
    // رسائل أوضح للمستخدم: هل تم الحذف من الحساب (السحابة) أم من هذا الجهاز فقط؟
    if (remoteAttempted && !remoteCleared) {
        const warnMsg = isEn
            ? '⚠️ Local data for this account was cleared on this device, but cloud data could not be deleted (offline or server error). Pending changes will upload when connection is restored.'
            : '⚠️ تم مسح بيانات هذا الحساب من هذا الجهاز، لكن لم يتم حذف بيانات السحابة (انقطاع في الإنترنت أو خطأ في السيرفر). قد تعود البيانات عند عودة الاتصال أو من أجهزة أخرى.';
        showMessage(warnMsg, 'warning');
    } else {
        const okMsg = isEn
            ? `✅ Permanently deleted ${arr.length} data set(s) for this account. A page refresh is recommended.`
            : `✅ تم حذف ${arr.length} مجموعة بيانات نهائيًا لهذا الحساب. يُنصح بتحديث الصفحة.`;
        showMessage(okMsg, 'success');
    }
    
    console.log('✅ Clear data completed:', arr, { remoteAttempted, remoteCleared });
}

