function computeDaysLeft(state) {
    if (!state) return null;
    if (state.lifetime) return null;
    if (!state.end_at) return 0;
    const now = new Date();
    const end = new Date(state.end_at);
    const diffMs = end.getTime() - now.getTime();
    const days = Math.floor(diffMs / (1000*60*60*24));
    return Math.max(0, days);
}

function dailyTick() {
    const state = loadLicenseState();
    const now = new Date();
    const todayUtcStr = now.toISOString().split('T')[0];
    const lastTick = state.last_tick_utc ? (state.last_tick_utc.split('T')[0]) : null;
    // if clock went backwards, do nothing
    if (lastTick && todayUtcStr < lastTick) {
        // ignore tampering
        return state;
    }
    if (!lastTick || todayUtcStr > lastTick) {
        // recalc
        state.days_left = computeDaysLeft(state);
        state.last_tick_utc = now.toISOString();
        saveLicenseState(state);
    }
    return state;
}

async function isLicenseActive() {
    return await isActivated();
}

async function showActivationUIIfNeeded() {
    const activationCard = document.getElementById('activationCard');
    const activateBtn = document.getElementById('activateBtn');
    const isLoggedIn = !!(window.firebaseAuthInstance && window.firebaseAuthInstance.isAuthenticated());
    if (!isLoggedIn) {
        if (activationCard) activationCard.style.display = 'none';
        if (activateBtn) activateBtn.style.display = 'none';
        updateSettingsLicenseDisplay();
        return;
    }
    if (!(await isLicenseActive())) {
        if (activationCard) activationCard.style.display = '';
        if (activateBtn) activateBtn.style.display = 'inline-block';
    } else {
        if (activationCard) activationCard.style.display = 'none';
        if (activateBtn) activateBtn.style.display = 'none';
    }
    updateSettingsLicenseDisplay();
}

async function updateSettingsLicenseDisplay() {
    const el = document.getElementById('licenseDaysLeft');
    if (!el) {
        setTimeout(updateSettingsLicenseDisplay, 200);
        return;
    }
    
    const currentLang = document.documentElement.lang || localStorage.getItem('appLanguage') || currentLanguage || 'ar';
    const isEn = currentLang === 'en';
    
    // المصدر الموحد: Firestore (عند تسجيل الدخول) - يضمن نفس العدد على جميع الأجهزة
    const firestoreSub = await getSubscriptionFromFirestoreForDisplay();
    if (firestoreSub) {
        if (firestoreSub.lifetime) {
            el.textContent = typeof getText === 'function' ? getText('license-activated-lifetime') : (isEn ? 'Activated: Lifetime' : 'مفعّل: مدى الحياة');
            el.className = 'license-days safe';
        } else if (firestoreSub.daysLeft !== null) {
            const daysLeft = firestoreSub.daysLeft;
            const dayText = typeof getText === 'function' ? (daysLeft === 1 ? getText('msg-day') : getText('msg-days')) : (isEn ? (daysLeft === 1 ? 'day' : 'days') : 'يوم');
            el.textContent = typeof getText === 'function' ? getText('license-days-left', { count: daysLeft, days: dayText }) : (isEn ? `${daysLeft} ${dayText} left` : `${daysLeft} ${dayText} متبقي`);
            el.className = daysLeft <= 3 ? 'license-days danger' : daysLeft <= 10 ? 'license-days warn' : 'license-days safe';
            checkSubscriptionWarnings(daysLeft);
            if (daysLeft === 0) showExpiredAndForceActivation();
        }
        if (typeof updateVisualSubscriptionIndicator === 'function') updateVisualSubscriptionIndicator();
        return;
    }
    
    // لا اعتماد على التخزين المحلي - عند عدم توفر Firestore نعرض "غير مؤكدة"
    el.textContent = isEn ? 'Unconfirmed (connect to verify)' : 'غير مؤكدة (اتصل للتحقق)';
    el.className = 'license-days inactive';
    if (typeof updateVisualSubscriptionIndicator === 'function') updateVisualSubscriptionIndicator();
}

function showExpiredAndForceActivation() {
    // hide main screen and show login
    document.getElementById('mainScreen').classList.remove('active');
    document.getElementById('loginScreen').classList.add('active');
    const activationCard = document.getElementById('activationCard');
    if (activationCard) activationCard.style.display = '';
    const msgEl = document.getElementById('activationMessage');
    const currentLang = document.documentElement.lang || currentLanguage || 'ar';
    const isEn = currentLang === 'en';
    if (msgEl) { msgEl.style.display = ''; msgEl.textContent = isEn ? 'Subscription expired. Please enter a new code.' : 'انتهى الاشتراك، الرجاء إدخال كود جديد.'; }
}

// دالة لإصلاح الزر مباشرة
function fixCashMovementButton() {
    const cashMovementBtn = document.querySelector('#openCashMove');
    if (cashMovementBtn) {
        const currentLang = document.documentElement.lang || 'en';
        const isEn = currentLang === 'en';
        const text = isEn ? 'Cash Movement' : 'حركة الصندوق';
        
        // إزالة النص القديم والاحتفاظ بالأيقونة
        const icon = cashMovementBtn.querySelector('i');
        cashMovementBtn.innerHTML = '';
        if (icon) {
            cashMovementBtn.appendChild(icon);
        }
        cashMovementBtn.appendChild(document.createTextNode(' ' + text));
        
        return text;
    } else {
        return null;
    }
}

// دالة لتحديث ترجمة الزر عند تغيير اللغة
function updateCashMovementButtonTranslation() {
    const cashMovementBtn = document.querySelector('#openCashMove');
    if (cashMovementBtn) {
        const currentLang = document.documentElement.lang || 'en';
        const isEn = currentLang === 'en';
        const text = isEn ? 'Cash Movement' : 'حركة الصندوق';
        
        // تحديث النص فقط
        const textNode = cashMovementBtn.childNodes[cashMovementBtn.childNodes.length - 1];
        if (textNode && textNode.nodeType === Node.TEXT_NODE) {
            textNode.textContent = ' ' + text;
        } else {
            // إذا لم يوجد نص، أضفه
            cashMovementBtn.appendChild(document.createTextNode(' ' + text));
        }
    }
}

// دالة لإصلاح نافذة حركة الصندوق
function fixCashMoveModal() {
    const title = document.querySelector('#cashMoveModal .modal-header h3');
    if (title) title.textContent = getText('cash_move_title');

    const lblType = document.querySelector('#cashMoveModal label[for="cashMoveType"]');
    if (lblType) lblType.textContent = getText('cash_move_type');
    const lblAmount = document.querySelector('#cashMoveModal label[for="cashMoveAmount"]');
    if (lblAmount) lblAmount.textContent = getText('cash_move_amount');
    const lblCurrency = document.querySelector('#cashMoveModal label[for="cashMoveCurrency"]');
    if (lblCurrency) lblCurrency.textContent = getText('cash_move_currency');
    const lblDesc = document.querySelector('#cashMoveModal label[for="cashMoveNote"]');
    if (lblDesc) lblDesc.textContent = getText('cash_move_description');

    const descInput = document.getElementById('cashMoveNote');
    if (descInput) descInput.placeholder = getText('cash_move_placeholder');

    const confirmBtn = document.getElementById('confirmCashMove');
    if (confirmBtn) {
        confirmBtn.innerHTML = '<i class="fas fa-check"></i> ' + getText('cash_move_confirm');
    }

    const cancelBtn = document.querySelector('#cashMoveModal .cancel-btn');
    if (cancelBtn) {
        cancelBtn.innerHTML = '<i class="fas fa-times"></i> ' + getText('cash_move_cancel');
    }

    const selectOptions = document.querySelectorAll('#cashMoveType option');
    if (selectOptions.length >= 3) {
        selectOptions[0].textContent = getText('cash-move-type-deposit');
        selectOptions[1].textContent = getText('cash-move-type-expense');
        selectOptions[2].textContent = getText('cash-move-type-transfer');
    }
}

// UI bindings for activation
document.addEventListener('DOMContentLoaded', function(){
    // Wait for Firebase DB to be ready before checking activation
    function tryCheckActivation() {
        if (window.firebaseDbInstance && window.firebaseAuthInstance) {
            checkActivationOnPageLoad();
        } else {
            // Wait for Firebase DB ready event
            window.addEventListener('firebaseDBReady', function onDBReady() {
                window.removeEventListener('firebaseDBReady', onDBReady);
                checkActivationOnPageLoad();
            }, { once: true });
            // Also wait for Auth ready
            window.addEventListener('firebaseAuthReady', function onAuthReady() {
                window.removeEventListener('firebaseAuthReady', onAuthReady);
                if (window.firebaseDbInstance) {
                    checkActivationOnPageLoad();
                }
            }, { once: true });
        }
    }
    
    // حارس التفعيل - التحقق من التفعيل عند تحميل الصفحة
    tryCheckActivation();
    
    // إصلاح فوري للزر
    fixCashMovementButton();
    
    // ضمان تحميل الترخيص الآمن أولاً
    ensureSecureLicenseLoaded().catch(e => console.warn('Failed to load secure license:', e));
    
    // تحميل وقت آخر تحذير
    loadLastWarningTime();
    
    // إعداد مؤقت للتحقق من التحذيرات كل دقيقة
    setInterval(checkSubscriptionWarnings, 60000); // كل دقيقة
    
    // حارس التفعيل المستمر — فقط عند الاتصال؛ لا يُفترض فقدان التفعيل كل ثوانٍ
    setInterval(async () => {
        if (typeof navigator !== 'undefined' && navigator.onLine === false) return;
        if (typeof window !== 'undefined' && window.__posNetOffline === true) return;
        await checkActivationDuringSession();
    }, 300000); // كل 5 دقائق عند الاتصال
    
    // ضمان تحديث عرض الترخيص عند تحميل الصفحة
    setTimeout(() => {
        updateSettingsLicenseDisplay();
    }, 1000);
    
    // إصلاح إضافي للزر
    setTimeout(() => {
        fixCashMovementButton();
    }, 500);
    
    // إصلاح أزرار الإعدادات عند تحميل الصفحة
    setTimeout(() => {
        if (typeof window.fixSettingsButtonsText === 'function') {
            window.fixSettingsButtonsText();
        }
    }, 1500);
    
    // إصلاح إضافي بعد فترة أطول
    setTimeout(() => {
        if (typeof window.fixSettingsButtonsText === 'function') {
            window.fixSettingsButtonsText();
        }
    }, 3000);
    
    // تحديث عرض الترخيص عند فتح صفحة الإعدادات
    document.addEventListener('click', function(e) {
        if (e.target && e.target.id === 'settingsBtn') {
            setTimeout(() => {
                updateSettingsLicenseDisplay();
                fixSettingsElements();
                // إصلاح نص الأزرار عند تحميل الصفحة
                if (typeof window.fixSettingsButtonsText === 'function') {
                    window.fixSettingsButtonsText();
                }
                
                // إصلاح إضافي بعد فترة أطول
                setTimeout(() => {
                    if (typeof window.fixSettingsButtonsText === 'function') {
                        window.fixSettingsButtonsText();
                    }
                }, 1000);
            }, 300);
        }
    });
    
    // show activation when needed
    showActivationUIIfNeeded().catch(e => console.warn('Failed to check activation:', e));
    // Self-service activation is intentionally disabled (Super Admin only).
    const renewBtn = document.getElementById('renewLicenseBtn');
    if (renewBtn) {
        renewBtn.style.display = 'none';
    }
    
    // Activation card: Free month is now automatic on first signup; no button. Card shows for users who need subscription/code.
});


