// تهريب النص لعرض آمن في HTML (منع XSS)
function escapeHtml(str) {
    if (str == null || str === '') return '';
    const s = String(str);
    return s
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#39;');
}
function escapeAttr(str) {
    return escapeHtml(str).replace(/`/g, '&#96;');
}

function fitTextToContainer(el, options = {}) {
    if (!el) return;
    const parent = el.parentElement;
    if (!parent) return;
    const max = Number(options.max || el.dataset.maxFontSize || 36);
    const min = Number(options.min || el.dataset.minFontSize || 10);
    const step = Number(options.step || 1);

    // Reset any previous horizontal squeeze before recalculation
    const isRtl = ((document.documentElement.getAttribute('dir') || '').toLowerCase() === 'rtl');
    el.style.setProperty('transform', 'scaleX(1)', 'important');
    el.style.setProperty('transform-origin', isRtl ? 'right center' : 'left center', 'important');
    el.style.setProperty('display', 'inline-block', 'important');

    el.style.setProperty('font-size', `${max}px`, 'important');
    const availableWidth = Math.max(0, Number(options.availableWidth || (parent.clientWidth - 4)));
    let current = max;

    while (current > min && el.scrollWidth > availableWidth) {
        current -= step;
        el.style.setProperty('font-size', `${current}px`, 'important');
    }

    if (el.scrollWidth > availableWidth) {
        el.style.setProperty('font-size', `${min}px`, 'important');
    }

    // Hard fallback: squeeze horizontally only if still overflowing at minimum size
    if (el.scrollWidth > availableWidth && availableWidth > 0) {
        const ratio = availableWidth / el.scrollWidth;
        const safeRatio = Math.max(0.72, Math.min(1, ratio));
        el.style.setProperty('transform', `scaleX(${safeRatio})`, 'important');
    }
}

function setFinalTotalBoxAmount(value, currency) {
    const box = document.getElementById('finalTotalBoxAmount');
    if (!box) return;
    const amount = Number(value) || 0;

    if (currency === 'USD') {
        const sign = amount < 0 ? '-' : '';
        const abs = Math.abs(amount);
        const intPart = Math.floor(abs).toLocaleString();
        const decPart = '.' + (abs.toFixed(2).split('.')[1] || '00');
        box.innerHTML = `<span class="amount-main">${sign}$${intPart}</span><span class="amount-decimal">${decPart}</span>`;
    } else {
        box.innerHTML = `<span class="amount-main">${Math.round(amount).toLocaleString()}</span><span class="amount-decimal"> L</span>`;
    }
    fitPosFinalTotalText();
}

function fitPosFinalTotalText() {
    const box = document.getElementById('finalTotalBoxAmount');
    if (!box) return;
    requestAnimationFrame(function () {
        const main = box.querySelector('.amount-main');
        const decimal = box.querySelector('.amount-decimal');
        if (main) {
            const decimalWidth = decimal ? decimal.offsetWidth : 0;
            const available = Math.max(0, box.clientWidth - decimalWidth - 6);
            fitTextToContainer(main, { max: 36, min: 10, step: 1, availableWidth: available });
        } else {
            fitTextToContainer(box, { max: 36, min: 10, step: 1 });
        }
    });
}

function setupPosFinalTotalAutofit() {
    if (window.__posFinalTotalAutofitSetup) return;
    const el = document.getElementById('finalTotalBoxAmount');
    if (!el) return;
    window.__posFinalTotalAutofitSetup = true;

    fitPosFinalTotalText();

    try {
        const mo = new MutationObserver(function () {
            fitPosFinalTotalText();
        });
        mo.observe(el, { childList: true, characterData: true, subtree: true });
    } catch (_) {}

    try {
        if (typeof ResizeObserver !== 'undefined') {
            const ro = new ResizeObserver(function () {
                fitPosFinalTotalText();
            });
            if (el.parentElement) ro.observe(el.parentElement);
            ro.observe(el);
        }
    } catch (_) {}

    try {
        window.addEventListener('resize', fitPosFinalTotalText, { passive: true });
    } catch (_) {}
}

if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', setupPosFinalTotalAutofit);
} else {
    setupPosFinalTotalAutofit();
}

// دالة الحصول على النص المترجم (قيم البدائل تُهَرَّب لمنع XSS عند العرض)
function getText(key, replacements = {}) {
    let text = translations[currentLanguage][key] || key;
    for (const [placeholder, value] of Object.entries(replacements)) {
        const safe = (value != null && value !== '') ? escapeHtml(String(value)) : '';
        text = text.replace(new RegExp(`\\{${placeholder}\\}`, 'g'), safe);
    }
    return text;
}

