function getReportsPageMetrics() {
    const isEn = (document.documentElement.lang || 'ar') === 'en';
    const noDataText = getText('reports-metric-no-data') || (isEn ? 'No data for selected period' : 'لا توجد بيانات للفترة المحددة');
    const currentLabel = getText('reports-metric-current') || (isEn ? 'Current' : 'حالي');
    const salesList = Array.isArray(sales) ? sales : [];
    const productList = Array.isArray(products) ? products : [];
    const customerList = Array.isArray(customers) ? customers : [];
    const threshold = Number(settings?.lowStockThreshold || 10);
    const range = getGlobalReportRange();

    const periodSummary = calculateCompletedSalesSummaryForRange(range, salesList);
    const customerPeriod = getCustomerPeriodStats(range, salesList, customerList);

    let lowStock = 0;
    let outOfStock = 0;
    productList.forEach((p) => {
        const stock = getProductSellableStock(p);
        const minS = Number(p.minStock != null ? p.minStock : threshold);
        if (stock <= 0) outOfStock += 1;
        else if (stock <= minS) lowStock += 1;
    });

    const totalCapital = productList.reduce((sum, p) => sum + (getProductSellableStock(p) * (Number(p.costUSD) || 0)), 0);
    const periodExpenses = filterExpensesByRange(getExpensesData(), range);
    const totalPeriodExpenses = periodExpenses.reduce((sum, e) => sum + (Number(e.expenseUSD) || 0), 0);

    const periodSalesLabel = getText('reports-metric-period-sales') || (isEn ? 'Period sales' : 'مبيعات الفترة');
    const transactionsLabel = getText('reports-metric-period-transactions') || (isEn ? 'Transactions' : 'معاملات');
    const netProfitLabel = getText('reports-metric-net-profit') || (isEn ? 'Net profit' : 'صافي الربح');
    const activeCustomersLabel = getText('reports-metric-active-customers') || (isEn ? 'Active customers' : 'عملاء نشطون');
    const periodPurchasesLabel = getText('reports-metric-period-purchases') || (isEn ? 'Period purchases' : 'مشتريات الفترة');
    const lowStockLabel = getText('reports-metric-low-stock') || (isEn ? 'Low stock' : 'مخزون منخفض');
    const outOfStockLabel = getText('reports-metric-out-of-stock') || (isEn ? 'Out of stock' : 'نفد المخزون');
    const totalCapitalLabel = getText('reports-metric-total-capital') || (isEn ? 'Total capital' : 'إجمالي رأس المال');
    const totalExpensesLabel = getText('reports-metric-total-expenses') || (isEn ? 'Total expenses' : 'إجمالي النفقات');

    let salesMetric = noDataText;
    if (periodSummary.totalTransactions > 0 || periodSummary.totalSales > 0) {
        salesMetric = `${periodSalesLabel}: ${formatCurrency(periodSummary.totalSales)} · ${transactionsLabel}: ${periodSummary.totalTransactions}`;
    }

    const inventoryMetric = `${currentLabel} · ${lowStockLabel}: ${lowStock} · ${outOfStockLabel}: ${outOfStock}`;

    let customersMetric = noDataText;
    if (customerPeriod.activeCustomers > 0 || customerPeriod.totalPurchases > 0) {
        customersMetric = `${activeCustomersLabel}: ${customerPeriod.activeCustomers} · ${periodPurchasesLabel}: ${formatCurrency(customerPeriod.totalPurchases)}`;
    }

    let profitMetric = noDataText;
    if (periodSummary.totalTransactions > 0 || periodSummary.totalProfit !== 0) {
        profitMetric = `${netProfitLabel}: ${formatCurrency(periodSummary.totalProfit, 'USD')}`;
    }

    let capitalMetric = `${currentLabel} · ${totalCapitalLabel}: ${formatCurrency(totalCapital, 'USD')}`;
    if (totalCapital <= 0 && productList.length === 0) capitalMetric = noDataText;

    let expensesMetric = noDataText;
    if (totalPeriodExpenses > 0 || periodExpenses.length > 0) {
        expensesMetric = `${totalExpensesLabel}: ${formatCurrency(totalPeriodExpenses, 'USD')}`;
    }

    return {
        sales: salesMetric,
        inventory: inventoryMetric,
        customers: customersMetric,
        profit: profitMetric,
        capital: capitalMetric,
        expenses: expensesMetric,
        _placeholders: {
            sales: salesMetric === noDataText,
            customers: customersMetric === noDataText,
            profit: profitMetric === noDataText,
            capital: capitalMetric === noDataText,
            expenses: expensesMetric === noDataText
        }
    };
}

function updateReportsPageMetrics() {
    const metrics = getReportsPageMetrics();
    const map = {
        sales: 'reportMetricSales',
        inventory: 'reportMetricInventory',
        customers: 'reportMetricCustomers',
        profit: 'reportMetricProfit',
        capital: 'reportMetricCapital',
        expenses: 'reportMetricExpenses'
    };
    Object.entries(map).forEach(([key, id]) => {
        const el = document.getElementById(id);
        if (!el) return;
        el.textContent = metrics[key] || '—';
        el.classList.remove('report-card-metric--loading');
        const isPlaceholder = metrics._placeholders && metrics._placeholders[key];
        el.classList.toggle('report-card-metric--empty', !!isPlaceholder);
    });
}

