// ============================================================
// User data isolation (Multi-Account Safety)
// Each account on the same device has its own data: storage key = pos_{uid}_{key}
// On logout: clearUserDataInMemory() clears memory + __largeCache + UI session state (pagination, etc.)
// On login: load only the current user's data from Firestore and local storage
// See MULTI_ACCOUNT_SAFETY.md for details.
// ============================================================
const USER_SPECIFIC_KEYS = ['products', 'customers', 'sales', 'suppliers', 'purchases', 'cashDrawer', 'cashDrawerTx', 'supplierPayments', 'purchaseReturns', 'supplierLedger', 'settings', 'stockMovements', 'salesLogs', 'customerLogs'];

function getCurrentUserId() {
    try {
        if (window.firebaseAuthInstance && typeof window.firebaseAuthInstance.getCurrentUser === 'function') {
            const u = window.firebaseAuthInstance.getCurrentUser();
            return u && u.uid ? u.uid : null;
        }
    } catch (_) {}
    // Fallbacks (important for edge cases where firebaseAuthInstance isn't ready)
    try {
        // Firebase compat auth
        if (typeof firebase !== 'undefined' && firebase.auth && typeof firebase.auth === 'function') {
            const cu = firebase.auth().currentUser;
            if (cu && cu.uid) return cu.uid;
        }
    } catch (_) {}
    try {
        // Our app-level user object
        if (typeof currentUser === 'object' && currentUser && currentUser.uid) return currentUser.uid;
        if (typeof window !== 'undefined' && window.currentUser && window.currentUser.uid) return window.currentUser.uid;
    } catch (_) {}
    return null;
}

function getParentAdminId(u) {
    if (!u || typeof u !== 'object') return null;
    return (
        u.parentAdminId ||
        u.parentAdminID ||
        u.parentId ||
        u.parent ||
        u.parentUid ||
        u.parentUserId ||
        u.mainAdminId ||
        u.mainAdminUID ||
        u.adminId ||
        u.ownerId ||
        u.ownerUid ||
        u.ownerID ||
        u.storeOwnerId ||
        u.storeId ||
        u.createdBy ||
        u.createdByUid ||
        null
    );
}

function getTenantId(u) {
    if (!u || typeof u !== 'object') return null;
    return (
        u.tenantId ||
        u.tenantID ||
        u.tenant ||
        u.storeTenantId ||
        u.accountTenantId ||
        null
    );
}

/** اليوزر الذي تخصّص له البيانات (الأدمين/المتجر). اليوزر الفرعي يستخدم parentAdminId. */
function getEffectiveDataOwnerId() {
    try {
        const u = (typeof currentUser === 'object' && currentUser) ? currentUser : (window.currentUser || null);
        const parentId = getParentAdminId(u);
        if (parentId) return parentId;
        return getCurrentUserId();
    } catch (_) {}
    return getCurrentUserId();
}

/** Shared cashbox scope per tenant; fallback to effective owner for legacy users without tenantId. */
function getEffectiveTenantId() {
    try {
        const u = (typeof currentUser === 'object' && currentUser) ? currentUser : (window.currentUser || null);
        const tenantId = getTenantId(u);
        if (tenantId) return String(tenantId);
        const owner = getEffectiveDataOwnerId();
        return owner ? String(owner) : null;
    } catch (_) {}
    const owner = getEffectiveDataOwnerId();
    return owner ? String(owner) : null;
}

/** Firestore `cashbox/{id}` + local cashDrawer keys: always the store owner (admin) uid — matches rules `isSubUserOf(owner)` and avoids split docs when profile `tenantId` differs per user. */
function getSharedCashboxDocId() {
    try {
        const oid = typeof getEffectiveDataOwnerId === 'function' ? getEffectiveDataOwnerId() : null;
        if (oid) return String(oid);
    } catch (_) {}
    try {
        const uid = typeof getCurrentUserId === 'function' ? getCurrentUserId() : null;
        return uid ? String(uid) : null;
    } catch (_) {}
    return null;
}

/** Single comparable "when" for drawer docs (userData summary or `cashbox/{tenant}`) — avoids fake `new Date()` beating local sale timestamps. */
function getCashDrawerDocLastUpdateIso(data) {
    if (!data || typeof data !== 'object') return null;
    if (data.lastUpdate) return String(data.lastUpdate);
    if (data.lastUpdated) return String(data.lastUpdated);
    const ua = data.updatedAt;
    if (ua && typeof ua.toDate === 'function') {
        try { return ua.toDate().toISOString(); } catch (_) {}
    }
    return null;
}

/** يوضح إذا المستخدم الحالي يوزر فرعي */
function isSubUser() {
    try {
        const u = (typeof currentUser === 'object' && currentUser) ? currentUser : (window.currentUser || null);
        return !!(u && (u.role === 'subUser' || getParentAdminId(u)));
    } catch (_) {}
    return false;
}

/** التحقق من صلاحية محددة */
function hasPermission(perm) {
    try {
        const u = (typeof currentUser === 'object' && currentUser) ? currentUser : (window.currentUser || null);
        if (!u) return false;
        const claims = (u && u.claims) || {};
        if (claims.super_admin === true || claims.superAdmin === true) return true;
        if (u.role === 'subUser' || getParentAdminId(u)) {
            const p = u.permissions || {};
            if (Object.prototype.hasOwnProperty.call(p, perm)) return p[perm] === true;
            const defaultSubUserPerms = {
                canViewSettings: false,
                canEditSettings: false,
                canViewSensitiveData: false,
                canViewCosts: false,
                canAddProducts: false,
                canEditProducts: false,
                canDeleteProducts: false,
                canImportProducts: false,
                canExportProducts: false
            };
            if (Object.prototype.hasOwnProperty.call(defaultSubUserPerms, perm)) {
                return defaultSubUserPerms[perm] === true;
            }
            return false;
        }
        return true;
    } catch (_) {}
    return false;
}

function canCurrentUserViewSensitiveData() {
    try { return !(typeof isSubUser === 'function' && isSubUser()) || hasPermission('canViewSensitiveData'); } catch (_) { return true; }
}

function canCurrentUserEditSettings() {
    try { return !(typeof isSubUser === 'function' && isSubUser()) || hasPermission('canEditSettings'); } catch (_) { return true; }
}

function canCurrentUserViewCosts() {
    try { return !(typeof isSubUser === 'function' && isSubUser()) || hasPermission('canViewCosts'); } catch (_) { return true; }
}

function hasProductPermission(perm) {
    try {
        if (typeof isSubUser === 'function' && !isSubUser()) return true;
        return typeof hasPermission === 'function' ? hasPermission(perm) : false;
    } catch (_) {
        return false;
    }
}

function showPermissionDeniedMessage(actionAr, actionEn) {
    const isEn = (document.documentElement.lang || 'ar') === 'en';
    const msg = isEn
        ? ('You do not have permission to ' + actionEn + '.')
        : ('ليس لديك صلاحية ' + actionAr);
    showMessage(msg, 'error');
}

const SCREEN_PERMISSION_MAP = {
    pos: 'canSell',
    cashboxHistory: 'canManageCashDrawer',
    products: 'canViewProducts',
    expiryManagement: 'canViewProducts',
    sales: 'canViewSales',
    customers: 'canViewCustomers',
    suppliers: 'canViewSuppliers',
    purchases: 'canViewSuppliers',
    users: 'canManageUsers',
    settings: 'canViewSettings'
};

function canCurrentUserAccessScreen(screen, navItemEl) {
    try {
        if (!screen) return false;
        const u = (typeof currentUser === 'object' && currentUser) ? currentUser : (window.currentUser || null);
        if (!u) return false;
        const claims = (u && u.claims) || {};
        if (claims.super_admin === true || claims.superAdmin === true) return true;
        if (screen === 'superAdmin') return false;

        if (typeof isSubUser === 'function' && isSubUser()) {
            const navPerm = navItemEl && navItemEl.getAttribute ? navItemEl.getAttribute('data-permission') : null;
            const perm = navPerm || SCREEN_PERMISSION_MAP[screen] || null;
            if (!perm) return true;
            return typeof hasPermission === 'function' ? hasPermission(perm) : false;
        }
        return true;
    } catch (_) {
        return false;
    }
}

function applyProductPermissionsUI() {
    const canViewProducts = hasProductPermission('canViewProducts');
    const canAddProducts = hasProductPermission('canAddProducts');
    const canImportProducts = hasProductPermission('canImportProducts');
    const canExportProducts = hasProductPermission('canExportProducts');

    const addProductBtn = document.getElementById('addProductBtn');
    if (addProductBtn) {
        addProductBtn.style.display = (canViewProducts && canAddProducts) ? '' : 'none';
    }

    const aiInvoiceImportBtn = document.getElementById('aiInvoiceImportBtn');
    if (aiInvoiceImportBtn) {
        const canInvoiceImport = canAddProducts || canImportProducts;
        aiInvoiceImportBtn.style.display = (canViewProducts && canInvoiceImport) ? '' : 'none';
    }
    try { if (typeof initAiInvoiceImport === 'function') initAiInvoiceImport(); } catch (_) {}

    const exportDataBtn = document.getElementById('exportDataBtn');
    if (exportDataBtn) {
        exportDataBtn.style.display = canExportProducts ? '' : 'none';
    }

    const importDataLabel = document.querySelector('label[for="importFile"]');
    if (importDataLabel) {
        importDataLabel.style.display = canImportProducts ? '' : 'none';
    }
    const importDataInput = document.getElementById('importFile');
    if (importDataInput) {
        importDataInput.disabled = !canImportProducts;
    }

    const importImagesLabel = document.querySelector('label[for="importProductImagesFile"]');
    if (importImagesLabel) {
        importImagesLabel.style.display = canImportProducts ? '' : 'none';
    }
    const importImagesInput = document.getElementById('importProductImagesFile');
    if (importImagesInput) {
        importImagesInput.disabled = !canImportProducts;
    }

}

let _subUserPermSyncTimer = null;
async function refreshCurrentSubUserPermissionsFromCloud() {
    try {
        if (!window.firebaseDbInstance || !currentUser || !currentUser.uid) return;
        if (!isSubUser()) return;
        const latest = await window.firebaseDbInstance.getUser(currentUser.uid);
        if (!latest) return;
        if (latest.isActive === false) {
            await logout(true);
            return;
        }
        const latestName = (latest.fullName && String(latest.fullName).trim()) || (latest.name && String(latest.name).trim()) || '';
        if (latestName && latestName !== String(currentUser.name || '').trim()) {
            currentUser.name = latestName;
            if (typeof refreshWelcomeHeaderDisplay === 'function') refreshWelcomeHeaderDisplay();
        }
        const latestPerms = latest.permissions || {};
        const currentPerms = currentUser.permissions || {};
        if (JSON.stringify(latestPerms) !== JSON.stringify(currentPerms)) {
            currentUser.permissions = latestPerms;
            if (typeof applyNavPermissions === 'function') applyNavPermissions();
            if (typeof applyCostVisibility === 'function') applyCostVisibility();
            try { if (typeof renderProductsTable === 'function') renderProductsTable(); } catch (_) {}
            try { if (typeof loadCustomers === 'function') loadCustomers(); } catch (_) {}
        }
    } catch (_) {}
}

function startSubUserPermissionSync() {
    try {
        if (_subUserPermSyncTimer) clearInterval(_subUserPermSyncTimer);
        _subUserPermSyncTimer = null;
        if (!isSubUser()) return;
        refreshCurrentSubUserPermissionsFromCloud();
        _subUserPermSyncTimer = setInterval(refreshCurrentSubUserPermissionsFromCloud, 5000);
    } catch (_) {}
}

function stopSubUserPermissionSync() {
    try {
        if (_subUserPermSyncTimer) clearInterval(_subUserPermSyncTimer);
        _subUserPermSyncTimer = null;
    } catch (_) {}
}

function getScopedStorageKey(key) {
    const isTenantShared = (key === 'cashDrawer' || key === 'cashDrawerTx');
    const uid = isTenantShared
        ? getSharedCashboxDocId()
        : (USER_SPECIFIC_KEYS.includes(key) ? getEffectiveDataOwnerId() : getCurrentUserId());
    if (!uid) return null;
    if (USER_SPECIFIC_KEYS.includes(key)) return `pos_${uid}_${key}`;
    return key;
}

function removeFromStorage(key) {
    const actualKey = getScopedStorageKey(key);
    if (USER_SPECIFIC_KEYS.includes(key) && !actualKey) return;
    const storageKey = actualKey || key;
    try {
        localStorage.removeItem(storageKey);
        localStorage.removeItem(storageKey + '.meta');
    } catch (_) {}
}

// sessionStorage keys that reflect UI state (pagination, etc.) — cleared on logout to isolate accounts
const SESSION_UI_KEYS = ['productsPaginationState', 'customersPaginationState', 'sales.currentPage', 'salesPaginationState', 'inventoryPaginationState', 'profit.currentPage', 'capital.currentPage'];

function clearUserDataInMemory() {
    if (typeof window !== 'undefined') {
        window.__dataLoadedForUserId = null;
        window.__deletedProductIds = new Set();
        stopPeriodicSyncFromCloud();
        try { stopTenantCashboxRealtimeSync(); } catch (_) {}
        if (_syncFlushTimer) {
            clearTimeout(_syncFlushTimer);
            _syncFlushTimer = null;
        }
        // Prevent previous user's data leaking via large cache (getCurrentProducts, etc. merge from it)
        try {
            if (typeof USER_SPECIFIC_KEYS !== 'undefined' && Array.isArray(USER_SPECIFIC_KEYS) && typeof __largeCache !== 'undefined' && __largeCache) {
                USER_SPECIFIC_KEYS.forEach(function(k) { if (__largeCache.hasOwnProperty(k)) delete __largeCache[k]; });
            }
        } catch (_) {}
        // Clear pagination UI state so the next user doesn't see the previous user's page
        try {
            if (typeof SESSION_UI_KEYS !== 'undefined') {
                SESSION_UI_KEYS.forEach(function(k) { try { sessionStorage.removeItem(k); } catch(_) {} });
            }
        } catch (_) {}
    }
    products = [];
    customers = [];
    sales = [];
    suppliers = [];
    purchases = [];
    supplierPayments = [];
    purchaseReturns = [];
    supplierLedger = [];
    cashDrawer = {
        cashUSD: 0,
        cashLBP: 0,
        lastUpdate: new Date().toISOString(),
        transactions: []
    };
    if (typeof resetPosCartTabs === 'function') resetPosCartTabs(); else { cart.length = 0; lastCartFocusIndex = null; }
    // Reset cashbox history UI state (account isolation)
    if (typeof __cashboxState !== 'undefined') {
        __cashboxState.currentPage = 1;
        __cashboxState.pageSize = 50;
        __cashboxState.data = [];
    }
}

// Helper: always return the latest products list
function getCurrentProducts() {
    try {
        const storedProducts = loadFromStorage('products', []);
        const stored = Array.isArray(storedProducts) ? storedProducts : [];
        const mem = (typeof products !== 'undefined' && Array.isArray(products)) ? products : [];
        const cache = (typeof __largeCache !== 'undefined' && __largeCache && Array.isArray(__largeCache.products))
            ? __largeCache.products : [];
        if (!Array.isArray(storedProducts) && storedProducts != null) {
            console.warn('⚠️ Products in storage is not an array — falling back to memory/cache');
        }
        let merged = _mergeProductsById(stored, cache);
        merged = _mergeProductsById(merged, mem);
        merged = merged.map((product) => normalizeProductStockModel(product));
        const deletedSet = window.__deletedProductIds;
        if (deletedSet && deletedSet.size) {
            merged = filterOutDeletedProducts(merged, deletedSet);
        }
        if (merged.length < Math.max(stored.length, mem.length, cache.length)) {
            try {
                console.warn('[POS catalog] Catalog merge:', { stored: stored.length, cache: cache.length, mem: mem.length, merged: merged.length });
            } catch (_) {}
        }
        return merged;
    } catch (error) {
        console.error('Error loading products:', error);
        /* Never clear storage on errors — it used to delete all products */
        try {
            const fb = Array.isArray(products) ? products : [];
            if (fb.length) return fb;
            const st = loadFromStorage('products', []);
            return Array.isArray(st) ? st : [];
        } catch (_) {
            return [];
        }
    }
}

function getCurrentCustomers() {
    try {
        if (typeof window !== 'undefined' && window.__dataLoadedForUserId) {
            const arr = Array.isArray(customers) ? customers : [];
            logCustomerBalanceSnapshot('getCurrentCustomers_memory', arr);
            return arr;
        }
        const data = loadFromStorage('customers', []);
        const arr = Array.isArray(data) ? data : [];
        logCustomerBalanceSnapshot('getCurrentCustomers_storage', arr);
        return arr;
    } catch (_) {}
    const arr = Array.isArray(customers) ? customers : [];
    logCustomerBalanceSnapshot('getCurrentCustomers_fallback', arr);
    return arr;
}

// Data variables — remain empty until login (strict account isolation)
let products = [];
let customers = [];
let sales = [];
let suppliers = [];
/** عدة عربات POS — كل تبويبة `items` منفصلة؛ `cart` يشير دائماً لعربة التبويب النشط */
const MAX_POS_CART_TABS = 10;
let posCartTabSlots = [ { id: 'cart_slot_1', items: [], activeCustomerId: null } ];
let activePosCartTabIndex = 0;
let cart = posCartTabSlots[0].items;
let lastCartFocusIndex = null;
let activePosCartTabId = posCartTabSlots[0].id;
let selectedCustomerId = null;
/** When true, ignore customerSelect/creditCustomerSelect `change` (rebuilding options fires spurious changes in some browsers). */
let __posCustomerSelectProgrammaticUpdate = false;
let posTabAutoSwitchLock = null;
let lastManualPosTabSwitchAt = 0;
let __posActiveTabRestoredOnce = false;

function getPosActiveTabStorageKey() {
    try {
        const uid = typeof getCurrentUserId === 'function' ? getCurrentUserId() : null;
        return uid ? `pos_${uid}_activeTabId` : 'pos_activeTabId';
    } catch (_) {
        return 'pos_activeTabId';
    }
}

function persistActivePosTabId() {
    try {
        if (!activePosCartTabId) return;
        localStorage.setItem(getPosActiveTabStorageKey(), String(activePosCartTabId));
    } catch (_) {}
}

function restoreActivePosTabIdFromStorage() {
    try {
        const saved = localStorage.getItem(getPosActiveTabStorageKey());
        if (saved && typeof saved === 'string' && saved.trim()) {
            activePosCartTabId = saved.trim();
        }
    } catch (_) {}
}

/** Per-cart-tab active customer (survives UI rebuilds / stray change events). Keyed by logged-in user. */
function getPosSlotCustomerMapStorageKey() {
    try {
        const uid = typeof getCurrentUserId === 'function' ? getCurrentUserId() : null;
        return uid ? `pos_${uid}_slotCustomerMap` : 'pos_slotCustomerMap';
    } catch (_) {
        return 'pos_slotCustomerMap';
    }
}

function readPosSlotCustomerMap() {
    try {
        const raw = localStorage.getItem(getPosSlotCustomerMapStorageKey());
        if (!raw) return {};
        const o = JSON.parse(raw);
        return o && typeof o === 'object' && !Array.isArray(o) ? o : {};
    } catch (_) {
        return {};
    }
}

function persistPosSlotCustomerMapEntry(slotId, customerIdOrNull) {
    try {
        if (!slotId) return;
        const map = readPosSlotCustomerMap();
        if (customerIdOrNull == null || !Number.isFinite(Number(customerIdOrNull)) || Number(customerIdOrNull) <= 0) {
            delete map[slotId];
        } else {
            map[slotId] = Number(customerIdOrNull);
        }
        localStorage.setItem(getPosSlotCustomerMapStorageKey(), JSON.stringify(map));
    } catch (_) {}
}

function clearPosSlotCustomerMapStorage() {
    try {
        localStorage.removeItem(getPosSlotCustomerMapStorageKey());
    } catch (_) {}
}

function prunePosSlotCustomerMapToExistingSlots() {
    try {
        const map = readPosSlotCustomerMap();
        const valid = new Set((Array.isArray(posCartTabSlots) ? posCartTabSlots : []).map(function (s) {
            return s && s.id ? String(s.id) : null;
        }).filter(Boolean));
        let dirty = false;
        Object.keys(map).forEach(function (k) {
            if (!valid.has(String(k))) {
                delete map[k];
                dirty = true;
            }
        });
        if (dirty) {
            localStorage.setItem(getPosSlotCustomerMapStorageKey(), JSON.stringify(map));
        }
    } catch (_) {}
}

function createPosCartSlot() {
    return {
        id: (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function')
            ? ('cart_slot_' + crypto.randomUUID())
            : ('cart_slot_' + Date.now() + '_' + Math.random().toString(36).slice(2, 10)),
        items: [],
        activeCustomerId: null
    };
}

function ensureActivePosCartTabState() {
    if (!Array.isArray(posCartTabSlots) || !posCartTabSlots.length) {
        posCartTabSlots = [createPosCartSlot()];
    }
    if (!__posActiveTabRestoredOnce) {
        __posActiveTabRestoredOnce = true;
        restoreActivePosTabIdFromStorage();
    }
    const activeByIdIndex = activePosCartTabId
        ? posCartTabSlots.findIndex(slot => slot && slot.id === activePosCartTabId)
        : -1;
    if (activeByIdIndex >= 0) {
        activePosCartTabIndex = activeByIdIndex;
    } else if (activePosCartTabIndex >= 0 && activePosCartTabIndex < posCartTabSlots.length) {
        const slot = posCartTabSlots[activePosCartTabIndex];
        activePosCartTabId = slot && slot.id ? slot.id : posCartTabSlots[0].id;
    } else {
        activePosCartTabIndex = 0;
        activePosCartTabId = posCartTabSlots[0].id;
    }
    persistActivePosTabId();

    // Prevent unwanted automatic jumps after adding product:
    // if any async/re-render path changes active tab, restore locked tab,
    // unless the user just clicked manually.
    const lock = posTabAutoSwitchLock;
    if (lock && lock.tabId && Date.now() < lock.untilMs) {
        const userJustSwitched = (Date.now() - lastManualPosTabSwitchAt) < 500;
        if (!userJustSwitched && activePosCartTabId !== lock.tabId) {
            const lockIdx = posCartTabSlots.findIndex(slot => slot && slot.id === lock.tabId);
            if (lockIdx >= 0) {
                activePosCartTabIndex = lockIdx;
                activePosCartTabId = lock.tabId;
            }
        }
    } else if (lock && Date.now() >= lock.untilMs) {
        posTabAutoSwitchLock = null;
    }
}

function bindActiveCartReference() {
    ensureActivePosCartTabState();
    const slot = posCartTabSlots[activePosCartTabIndex];
    cart = slot && Array.isArray(slot.items) ? slot.items : posCartTabSlots[0].items;
}

function getActivePosCartSlot() {
    ensureActivePosCartTabState();
    const slot = posCartTabSlots[activePosCartTabIndex];
    return slot && typeof slot === 'object' ? slot : null;
}

function getActiveCustomerIdForPosCart() {
    const slot = getActivePosCartSlot();
    let id = null;
    if (slot && slot.activeCustomerId != null && slot.activeCustomerId !== '') {
        const n = Number(slot.activeCustomerId);
        if (Number.isFinite(n) && n > 0) id = n;
    }
    if (!id && selectedCustomerId != null) {
        const n = Number(selectedCustomerId);
        if (Number.isFinite(n) && n > 0) id = n;
    }
    if (!id && slot && slot.id) {
        const map = readPosSlotCustomerMap();
        const p = Number(map[slot.id]);
        if (Number.isFinite(p) && p > 0) id = p;
    }
    if (!id) return null;

    const listReady = Array.isArray(customers) && customers.length > 0;
    // Never auto-clear the active customer during normal UI refreshes/re-renders.
    // `customers` can be briefly stale or incomplete while data is reloading.
    // Clearing is allowed only from explicit user/system actions
    // (e.g. complete sale, delete selected customer, manual unselect).
    if (listReady && typeof customerRecordExistsByNumericId === 'function' && !customerRecordExistsByNumericId(id)) {
        return id;
    }
    if (slot) slot.activeCustomerId = id;
    selectedCustomerId = id;
    return id;
}

function setActiveCustomerIdForPosCart(customerId) {
    const slot = getActivePosCartSlot();
    if (!slot) return;
    const numericId = Number(customerId);
    const nextId = Number.isFinite(numericId) && numericId > 0 ? numericId : null;
    slot.activeCustomerId = nextId;
    selectedCustomerId = nextId;
    try {
        persistPosSlotCustomerMapEntry(slot.id, nextId);
    } catch (_) {}
}

/** Full customer row when the catalog is loaded; never use this alone to clear global selection (customers[] can be briefly empty during refresh). */
function getActiveCustomerForPosCart() {
    const activeId = getActiveCustomerIdForPosCart();
    if (!activeId || !Array.isArray(customers) || customers.length === 0) return null;
    return customers.find(c => Number(c.id) === activeId) || null;
}

function customerRecordExistsByNumericId(id) {
    const n = Number(id);
    if (!Number.isFinite(n) || n <= 0) return false;
    return Array.isArray(customers) && customers.some(c => Number(c.id) === n);
}

/** Prefer global/slot selection, then existing <select> value — never default to customers[0]. */
function resolvePosCustomerIdToPreserveBeforeSelectRebuild(selEl) {
    const domRaw = selEl && selEl.value ? parseInt(selEl.value, 10) : NaN;
    const slot = typeof getActivePosCartSlot === 'function' ? getActivePosCartSlot() : null;
    const fromMap = slot && slot.id ? Number(readPosSlotCustomerMap()[slot.id]) : NaN;
    const ordered = [
        selectedCustomerId,
        getActiveCustomerIdForPosCart(),
        Number.isFinite(fromMap) && fromMap > 0 ? fromMap : null,
        Number.isFinite(domRaw) && domRaw > 0 ? domRaw : null
    ];
    const listReady = Array.isArray(customers) && customers.length > 0;
    for (let i = 0; i < ordered.length; i++) {
        const cand = ordered[i];
        if (cand == null || !Number.isFinite(Number(cand)) || Number(cand) <= 0) continue;
        if (listReady) {
            if (customerRecordExistsByNumericId(cand)) return Number(cand);
        } else {
            return Number(cand);
        }
    }
    return null;
}

function updateActiveCustomerIndicator() {
    const activeId = getActiveCustomerIdForPosCart();
    const listReady = Array.isArray(customers) && customers.length > 0;
    const activeCustomer = listReady && activeId
        ? customers.find(c => Number(c.id) === activeId) || null
        : null;
    const activeName = activeCustomer ? getCustomerDisplayName(activeCustomer.name) : '';
    const placeholder = getText('search-customer') || ((document.documentElement.lang || 'en') === 'en' ? 'Search customer...' : 'ابحث عن عميل...');
    const partialSearch = document.getElementById('customerSearch');
    const creditSearch = document.getElementById('creditCustomerSearch');

    [partialSearch, creditSearch].forEach(function (input) {
        if (!input) return;
        input.dataset.activeCustomerId = activeId ? String(activeId) : '';
        const activeCustomerLabel = activeCustomer
            ? (((document.documentElement.lang || 'en') === 'en' ? 'Active customer: ' : 'العميل النشط: ') + activeName)
            : (activeId
                ? (((document.documentElement.lang || 'en') === 'en' ? 'Active customer id: ' : 'معرف العميل النشط: ') + String(activeId))
                : '');
        // Avoid browser tooltips overlapping the compact partial-payment layout.
        input.removeAttribute('title');
        if (activeCustomerLabel) input.setAttribute('aria-label', activeCustomerLabel);
        else input.removeAttribute('aria-label');
        const hasActive = !!(activeCustomer || activeId);
        input.style.borderColor = hasActive ? '#10b981' : '';
        input.style.boxShadow = hasActive ? '0 0 0 2px rgba(16,185,129,0.12)' : '';
        if (!document.activeElement || document.activeElement !== input) {
            input.value = activeName;
        }
        input.placeholder = activeName || placeholder;
    });
}

function syncPosCustomerSelectorsFromActiveState() {
    const activeId = getActiveCustomerIdForPosCart();
    const listReady = Array.isArray(customers) && customers.length > 0;
    let activeCustomer = null;
    if (activeId && listReady) {
        activeCustomer = customers.find(c => Number(c.id) === activeId) || null;
    }

    if (activeId && Number.isFinite(Number(activeId)) && Number(activeId) > 0) {
        selectedCustomerId = Number(activeId);
    } else {
        selectedCustomerId = null;
    }

    const partialSelect = document.getElementById('customerSelect');
    const creditSelect = document.getElementById('creditCustomerSelect');

    __posCustomerSelectProgrammaticUpdate = true;
    try {
        if (partialSelect) {
            if (activeCustomer) partialSelect.value = String(activeCustomer.id);
            else if (listReady && activeId && customerRecordExistsByNumericId(activeId)) partialSelect.value = String(activeId);
            else if (!listReady && activeId) { /* avoid assigning invalid option while customers[] is empty */ }
            else partialSelect.value = '';
        }
        if (creditSelect) {
            if (activeCustomer) creditSelect.value = String(activeCustomer.id);
            else if (listReady && activeId && customerRecordExistsByNumericId(activeId)) creditSelect.value = String(activeId);
            else if (!listReady && activeId) { /* same as partial */ }
            else creditSelect.value = '';
        }
    } finally {
        __posCustomerSelectProgrammaticUpdate = false;
    }

    updateActiveCustomerIndicator();

    if (typeof togglePreviousAccountButton === 'function') {
        togglePreviousAccountButton(activeCustomer ? activeCustomer.id : (selectedCustomerId || ''));
    }
    if (activeCustomer && typeof updateCreditInfo === 'function') {
        updateCreditInfo(activeCustomer.id);
    }
}

function resetPosCartTabs() {
    clearPosSlotCustomerMapStorage();
    posCartTabSlots = [createPosCartSlot()];
    activePosCartTabIndex = 0;
    activePosCartTabId = posCartTabSlots[0].id;
    selectedCustomerId = null;
    persistActivePosTabId();
    cart = posCartTabSlots[0].items;
    lastCartFocusIndex = null;
    try { renderPosCartTabs(); } catch (_) {}
}

function renderPosCartTabs() {
    ensureActivePosCartTabState();
    const bar = document.getElementById('posCartTabsBar');
    if (!bar) return;
    bar.innerHTML = '';
    const atMax = posCartTabSlots.length >= MAX_POS_CART_TABS;
    const frag = document.createDocumentFragment();
    posCartTabSlots.forEach((slot, idx) => {
        const t = document.createElement('button');
        t.type = 'button';
        t.className = 'pos-cart-tab' + (idx === activePosCartTabIndex ? ' is-active' : '');
        t.setAttribute('role', 'tab');
        t.setAttribute('aria-selected', idx === activePosCartTabIndex ? 'true' : 'false');
        t.dataset.tabIndex = String(idx);
        t.dataset.slotId = slot && slot.id ? String(slot.id) : '';
        const label = idx === 0
            ? (typeof getText === 'function' ? getText('cart') : 'Cart')
            : (typeof getText === 'function' ? getText('pos-cart-tab-label', { n: idx + 1 }) : ('Cart ' + (idx + 1)));
        const labelSpan = document.createElement('span');
        labelSpan.className = 'pos-cart-tab-label';
        labelSpan.textContent = label;
        t.appendChild(labelSpan);

        const close = document.createElement('span');
        close.className = 'pos-cart-tab-close';
        close.setAttribute('role', 'button');
        close.setAttribute('aria-label', (typeof getText === 'function' ? getText('pos-cart-delete-tab') : 'Delete cart'));
        close.dataset.tabRemove = String(idx);
        close.textContent = '×';
        t.appendChild(close);

        t.addEventListener('click', function(e) {
            const removeEl = e.target && e.target.closest ? e.target.closest('.pos-cart-tab-close') : null;
            if (removeEl) {
                e.preventDefault();
                e.stopPropagation();
                removePosCartTab(idx);
                return;
            }
            lastManualPosTabSwitchAt = Date.now();
            posTabAutoSwitchLock = null;
            switchPosCartTab(idx);
        });
        frag.appendChild(t);
    });
    const p = document.createElement('button');
    p.type = 'button';
    p.className = 'pos-cart-tab-add-inline';
    p.textContent = '+';
    p.title = (typeof getText === 'function' ? getText('pos-cart-add-tab') : 'Add cart');
    p.setAttribute('aria-label', (typeof getText === 'function' ? getText('pos-cart-add-tab') : 'Add cart'));
    p.disabled = atMax;
    p.addEventListener('click', function(e) {
        e.preventDefault();
        addPosCartTab();
    });
    frag.appendChild(p);
    try {
        bar.setAttribute('aria-label', typeof getText === 'function' ? getText('cart') : 'Carts');
    } catch (_) {}
    bar.appendChild(frag);
}

function switchPosCartTab(idx) {
    ensureActivePosCartTabState();
    if (idx === activePosCartTabIndex) return;
    if (idx < 0 || idx >= posCartTabSlots.length) return;
    activePosCartTabIndex = idx;
    activePosCartTabId = posCartTabSlots[idx] && posCartTabSlots[idx].id ? posCartTabSlots[idx].id : activePosCartTabId;
    selectedCustomerId = posCartTabSlots[idx] && posCartTabSlots[idx].activeCustomerId != null
        ? Number(posCartTabSlots[idx].activeCustomerId)
        : null;
    persistActivePosTabId();
    bindActiveCartReference();
    renderPosCartTabs();
    try { updateCart(); } catch (_) {}
    try { syncPosCustomerSelectorsFromActiveState(); } catch (_) {}
    try {
        const ap = document.getElementById('amountPaid');
        if (ap) ap.value = '';
        if (typeof calculateAndDisplayChange === 'function') calculateAndDisplayChange();
    } catch (_) {}
}

function addPosCartTab() {
    if (posCartTabSlots.length >= MAX_POS_CART_TABS) {
        try { showMessage((typeof getText === 'function' ? getText('pos-cart-tab-limit') : 'Maximum carts reached'), 'warning'); } catch (_) {}
        return;
    }
    posCartTabSlots.push(createPosCartSlot());
    activePosCartTabIndex = posCartTabSlots.length - 1;
    activePosCartTabId = posCartTabSlots[activePosCartTabIndex].id;
    selectedCustomerId = null;
    persistActivePosTabId();
    bindActiveCartReference();
    renderPosCartTabs();
    try { updateCart(); } catch (_) {}
    try { syncPosCustomerSelectorsFromActiveState(); } catch (_) {}
    try {
        const ap = document.getElementById('amountPaid');
        if (ap) ap.value = '';
        if (typeof calculateAndDisplayChange === 'function') calculateAndDisplayChange();
    } catch (_) {}
}

function removePosCartTab(idx) {
    ensureActivePosCartTabState();
    if (idx < 0 || idx >= posCartTabSlots.length) return;
    if (posCartTabSlots.length <= 1) {
        try { showMessage((typeof getText === 'function' ? getText('pos-cart-delete-last-blocked') : 'Cannot delete the last cart'), 'warning'); } catch (_) {}
        return;
    }
    const slot = posCartTabSlots[idx];
    if (slot && Array.isArray(slot.items) && slot.items.length > 0) {
        try { showMessage((typeof getText === 'function' ? getText('pos-cart-delete-blocked') : 'Cannot delete a cart that contains items'), 'warning'); } catch (_) {}
        return;
    }

    posCartTabSlots.splice(idx, 1);
    if (activePosCartTabIndex > idx) activePosCartTabIndex -= 1;
    if (activePosCartTabIndex >= posCartTabSlots.length) activePosCartTabIndex = posCartTabSlots.length - 1;
    if (activePosCartTabIndex < 0) activePosCartTabIndex = 0;
    activePosCartTabId = posCartTabSlots[activePosCartTabIndex] && posCartTabSlots[activePosCartTabIndex].id
        ? posCartTabSlots[activePosCartTabIndex].id
        : (posCartTabSlots[0] && posCartTabSlots[0].id ? posCartTabSlots[0].id : null);
    selectedCustomerId = posCartTabSlots[activePosCartTabIndex] && posCartTabSlots[activePosCartTabIndex].activeCustomerId != null
        ? Number(posCartTabSlots[activePosCartTabIndex].activeCustomerId)
        : null;
    persistActivePosTabId();
    try { prunePosSlotCustomerMapToExistingSlots(); } catch (_) {}

    bindActiveCartReference();
    renderPosCartTabs();
    try { updateCart(); } catch (_) {}
    try { syncPosCustomerSelectorsFromActiveState(); } catch (_) {}
    try {
        const ap = document.getElementById('amountPaid');
        if (ap) ap.value = '';
        if (typeof calculateAndDisplayChange === 'function') calculateAndDisplayChange();
    } catch (_) {}
}
