// Load settings from local storage on startup (exchange rate, etc.)
try {
    const stored = loadFromStorage('settings', null);
    if (stored && typeof stored === 'object') {
        settings = { ...settings, ...getSanitizedSettingsForCurrentUser(stored) };
    }
} catch (e) {}

function formatDisplayName(name) {
    const s = String(name || '').trim();
    if (!s) return 'User';
    if (s.includes('@')) {
        const parts = s.split('@');
        const local = parts[0] || '';
        const domain = parts.slice(1).join('@');
        const capLocal = local ? local.charAt(0).toUpperCase() + local.slice(1).toLowerCase() : '';
        return domain ? `${capLocal}@${domain}` : capLocal;
    }
    return s.split(/\s+/).filter(Boolean).map((part) => {
        return part.charAt(0).toUpperCase() + part.slice(1).toLowerCase();
    }).join(' ');
}

function getCurrentUserName() {
    try {
        const auth = window.firebaseAuthInstance;
        const fu = auth && auth.auth && auth.auth.currentUser;
        if (fu && fu.displayName && String(fu.displayName).trim()) {
            return String(fu.displayName).trim();
        }
    } catch (_) {}
    if (typeof currentUser === 'object' && currentUser) {
        if (currentUser.name && String(currentUser.name).trim()) return String(currentUser.name).trim();
        if (currentUser.email && String(currentUser.email).trim()) return String(currentUser.email).trim();
        if (currentUser.displayName && String(currentUser.displayName).trim()) return String(currentUser.displayName).trim();
    }
    return typeof currentUser === 'string' ? currentUser : 'User';
}

/** يحدّث سطر الترحيب في الهيدر بعد تسجيل الدخول أو تغيير اللغة (translatePOS يستدعي نفس المنطق). */
function refreshWelcomeHeaderDisplay() {
    try {
        const el = document.getElementById('currentUser');
        if (!el || typeof getText !== 'function' || typeof getCurrentUserName !== 'function') return;
        el.textContent = getText('welcome', { name: formatDisplayName(getCurrentUserName()) });
    } catch (_) {}
}

function _normalizeFeatureIdentity(value) {
    return String(value || '')
        .toLowerCase()
        .trim()
        .replace(/\s+/g, ' ')
        .replace(/[^a-z0-9 ]/g, '');
}

function isCartonConversionTargetUser(userLike) {
    if (!userLike || typeof userLike !== 'object') return false;
    const nameCandidates = [
        userLike.fullName,
        userLike.name,
        userLike.email ? String(userLike.email).split('@')[0] : ''
    ];
    const storeCandidates = [
        userLike.storeName,
        userLike.subdomain
    ];
    const allowedPairs = [
        { user: 'andre', stores: ['abou charbel', 'aboucharbel'] },
        { user: 'johny', stores: ['todayslook', 'todays look'] }
    ];
    return allowedPairs.some((pair) => {
        const hasUserMatch = nameCandidates.some((value) => _normalizeFeatureIdentity(value) === pair.user);
        const hasStoreMatch = storeCandidates.some((value) => pair.stores.includes(_normalizeFeatureIdentity(value)));
        return hasUserMatch && hasStoreMatch;
    });
}

function getCurrentClientFeatures() {
    const base = (currentUser && currentUser.features && typeof currentUser.features === 'object')
        ? { ...currentUser.features }
        : {};
    if (isCartonConversionTargetUser(currentUser)) {
        base.cartonConversion = true;
    }
    return base;
}

function isCartonConversionEnabled() {
    return !!getCurrentClientFeatures().cartonConversion;
}

function toSafeInt(value, fallback = 0) {
    const parsed = Number(value);
    if (!Number.isFinite(parsed)) return fallback;
    return Math.max(0, Math.floor(parsed));
}

function normalizeProductStockModel(product) {
    if (!product || typeof product !== 'object') return product;
    if (product.stock && typeof product.stock === 'object' && !Array.isArray(product.stock)) {
        const unitsPerCarton = toSafeInt(product && product.conversion && product.conversion.carton_to_pack, 0);
        const cartonQty = toSafeInt(product.stock.carton, 0);
        const packQty = toSafeInt(product.stock.pack, 0);
        const legacyTotal = packQty + (cartonQty * unitsPerCarton);
        return {
            ...product,
            stock: legacyTotal,
            legacyStructuredStock: { carton: cartonQty, pack: packQty },
            legacyConversion: product.conversion || null
        };
    }
    return {
        ...product,
        stock: Math.max(0, Number(product.stock) || 0)
    };
}

function getProductUnitType(product) {
    return String((product && product.unitType) || 'standard').toLowerCase();
}

function isCartonLinkedProduct(product) {
    return !!product && getProductUnitType(product) === 'carton';
}

function isPackLinkedProduct(product) {
    return !!product && getProductUnitType(product) === 'pack';
}

function getUnitsPerCarton(product) {
    return toSafeInt(product && product.units_per_carton, 0);
}

function getLinkedPackProductId(product) {
    if (!product || product.linked_pack_product_id == null) return '';
    return String(product.linked_pack_product_id);
}

function findLinkedPackProduct(cartonProduct, sourceProducts) {
    const linkedId = getLinkedPackProductId(cartonProduct);
    if (!linkedId) return null;
    const list = Array.isArray(sourceProducts) ? sourceProducts : getCurrentProducts();
    return list.find((item) => String(item && item.id) === linkedId) || null;
}

function isCartonConversionActiveForProduct(product) {
    return isCartonConversionEnabled() && isCartonLinkedProduct(product) && !!getLinkedPackProductId(product) && getUnitsPerCarton(product) > 0;
}

function getProductSellableStock(product) {
    return Math.max(0, Number(product && product.stock) || 0);
}

function getProductStockDisplay(product) {
    return String(getProductSellableStock(product));
}

function getProductStockNumericForThreshold(product) {
    return getProductSellableStock(product);
}

function addPackStockToProduct(product, quantity) {
    const qty = toSafeInt(quantity, 0);
    if (!product || qty <= 0) return;
    product.stock = Math.max(0, (Number(product.stock) || 0) + qty);
}

function removePackStockFromProduct(product, quantity) {
    const qty = toSafeInt(quantity, 0);
    if (!product || qty <= 0) return;
    product.stock = Math.max(0, (Number(product.stock) || 0) - qty);
}

function openCartonForProductStock(product, options) {
    const opts = options || {};
    if (!isCartonConversionEnabled()) {
        return {
            ok: false,
            message: (document.documentElement.lang || 'ar') === 'en'
                ? 'Carton conversion is not enabled for this client.'
                : 'ميزة تحويل الكروز غير مفعلة لهذا الزبون.'
        };
    }
    if (!isCartonLinkedProduct(product)) {
        return {
            ok: false,
            message: (document.documentElement.lang || 'ar') === 'en'
                ? 'This product is not a carton item.'
                : 'هذا المنتج ليس منتج علبة.'
        };
    }
    const cartonQty = getProductSellableStock(product);
    if (cartonQty <= 0) {
        return {
            ok: false,
            message: (document.documentElement.lang || 'ar') === 'en' ? 'No cartons available' : 'لا يوجد علب'
        };
    }
    const packProduct = findLinkedPackProduct(product, opts.productsList);
    if (!packProduct) {
        return {
            ok: false,
            message: (document.documentElement.lang || 'ar') === 'en'
                ? 'Linked pack product not found.'
                : 'منتج الـ Pack المرتبط غير موجود.'
        };
    }
    const units = getUnitsPerCarton(product);
    if (units <= 0) {
        return {
            ok: false,
            message: (document.documentElement.lang || 'ar') === 'en'
                ? 'Units per carton must be greater than 0.'
                : 'عدد الـ Pack داخل العلبة يجب أن يكون أكبر من 0.'
        };
    }
    product.stock = cartonQty - 1;
    packProduct.stock = getProductSellableStock(packProduct) + units;
    if (opts.logMovement) {
        recordStockMovement(
            'conversion',
            product.id,
            1,
            opts.invoiceNumber || 'PENDING',
            opts.note || `فتح علبة ${product.name || ''}`.trim(),
            {
                from: 'carton',
                to: 'pack',
                fromQuantity: 1,
                toQuantity: units,
                mode: opts.mode || 'manual',
                linkedPackProductId: packProduct.id
            }
        );
    }
    return {
        ok: true,
        unitsAdded: units,
        cartonStock: product.stock,
        packStock: packProduct.stock,
        linkedPackProductId: packProduct.id
    };
}

function populateLinkedPackProductOptions(selectId, selectedValue, excludeProductId) {
    const select = document.getElementById(selectId);
    if (!select) return;
    const lang = document.documentElement.lang || 'ar';
    const currentValue = selectedValue != null ? String(selectedValue) : String(select.value || '');
    const list = getCurrentProducts()
        .filter((product) => product && String(product.id) !== String(excludeProductId || '') && isPackLinkedProduct(product))
        .sort((a, b) => String(a.name || '').localeCompare(String(b.name || '')));
    const defaultLabel = lang === 'en' ? 'Select linked pack product' : 'اختر منتج الـ Pack المرتبط';
    select.innerHTML = `<option value="">${escapeHtml(defaultLabel)}</option>` + list.map((product) => {
        return `<option value="${escapeAttr(String(product.id))}">${escapeHtml(product.name || ('#' + product.id))}</option>`;
    }).join('');
    select.value = list.some((product) => String(product.id) === currentValue) ? currentValue : '';
}

function updateLinkedProductFields(prefix) {
    const isEdit = prefix === 'edit';
    const unitType = document.getElementById(isEdit ? 'editProductUnitType' : 'productUnitType');
    const linkGroup = document.getElementById(isEdit ? 'editLinkedPackFields' : 'linkedPackFields');
    const linkedPack = document.getElementById(isEdit ? 'editLinkedPackProductId' : 'productLinkedPackProductId');
    const unitsInput = document.getElementById(isEdit ? 'editProductUnitsPerCarton' : 'productUnitsPerCarton');
    const isCarton = unitType && unitType.value === 'carton';
    if (linkGroup) linkGroup.style.display = isCarton ? 'grid' : 'none';
    if (linkedPack) linkedPack.required = !!isCarton;
    if (unitsInput) unitsInput.required = !!isCarton;
}

function syncCartonConversionFormState() {
    const enabled = isCartonConversionEnabled();
    const addGroup = document.getElementById('productStockManagementGroup');
    const editGroup = document.getElementById('editProductStockManagementGroup');
    if (addGroup) addGroup.style.display = enabled ? 'block' : 'none';
    if (editGroup) editGroup.style.display = enabled ? 'block' : 'none';

    const addType = document.getElementById('productUnitType');
    const editType = document.getElementById('editProductUnitType');
    if (addType) addType.required = enabled;
    if (editType) editType.required = enabled;

    populateLinkedPackProductOptions('productLinkedPackProductId', null, null);
    const editId = document.getElementById('editProductForm')?.dataset?.editId || null;
    populateLinkedPackProductOptions('editLinkedPackProductId', null, editId);
    updateLinkedProductFields('');
    updateLinkedProductFields('edit');
}

function readCartonConversionInputs(prefix, currentProductId) {
    const isEdit = prefix === 'edit';
    const typeEl = document.getElementById(isEdit ? 'editProductUnitType' : 'productUnitType');
    const packEl = document.getElementById(isEdit ? 'editLinkedPackProductId' : 'productLinkedPackProductId');
    const unitsEl = document.getElementById(isEdit ? 'editProductUnitsPerCarton' : 'productUnitsPerCarton');
    const unitType = String(typeEl && typeEl.value || 'standard');
    const linkedPackId = String(packEl && packEl.value || '');
    const unitsPerCarton = Number(unitsEl && unitsEl.value);
    const lang = document.documentElement.lang || 'ar';

    if (!isCartonConversionEnabled()) {
        return { ok: true, unitType: 'standard', linkedPackProductId: '', unitsPerCarton: null };
    }
    if (!['standard', 'carton', 'pack'].includes(unitType)) {
        return { ok: false, message: lang === 'en' ? 'Select product type.' : 'يرجى اختيار نوع المنتج.' };
    }
    if (unitType !== 'carton') {
        return { ok: true, unitType, linkedPackProductId: '', unitsPerCarton: null };
    }
    if (!linkedPackId) {
        return { ok: false, message: lang === 'en' ? 'Linked pack product is required.' : 'منتج الـ Pack المرتبط مطلوب.' };
    }
    if (currentProductId != null && String(currentProductId) === linkedPackId) {
        return { ok: false, message: lang === 'en' ? 'A carton product cannot link to itself.' : 'لا يمكن ربط منتج العلبة بنفسه.' };
    }
    const linkedProduct = getCurrentProducts().find((product) => String(product && product.id) === linkedPackId);
    if (!linkedProduct || !isPackLinkedProduct(linkedProduct)) {
        return { ok: false, message: lang === 'en' ? 'Choose a valid pack product.' : 'يرجى اختيار منتج Pack صالح.' };
    }
    if (!Number.isFinite(unitsPerCarton) || unitsPerCarton <= 0 || !Number.isInteger(unitsPerCarton)) {
        return { ok: false, message: lang === 'en' ? 'Units per carton must be greater than 0.' : 'عدد الـ Pack داخل العلبة يجب أن يكون أكبر من 0.' };
    }
    return {
        ok: true,
        unitType,
        linkedPackProductId: linkedPackId,
        unitsPerCarton: unitsPerCarton
    };
}

document.addEventListener('DOMContentLoaded', syncCartonConversionFormState);
document.addEventListener('DOMContentLoaded', function () {
    const addType = document.getElementById('productUnitType');
    const editType = document.getElementById('editProductUnitType');
    if (addType && !addType.dataset.cartonUnitBound) {
        addType.dataset.cartonUnitBound = '1';
        addType.addEventListener('change', function () {
            updateLinkedProductFields('');
            populateLinkedPackProductOptions('productLinkedPackProductId', null, null);
        });
    }
    if (editType && !editType.dataset.cartonUnitBound) {
        editType.dataset.cartonUnitBound = '1';
        editType.addEventListener('change', function () {
            const editId = document.getElementById('editProductForm')?.dataset?.editId || null;
            updateLinkedProductFields('edit');
            populateLinkedPackProductOptions('editLinkedPackProductId', null, editId);
        });
    }
});

function formatTelegramDateTime(isoOrDate) {
    var d = isoOrDate;
    if (typeof d === 'string') {
        d = new Date(d);
        if (isNaN(d.getTime())) return isoOrDate;
    }
    if (!(d instanceof Date)) d = new Date();
    var day = String(d.getDate()).padStart(2, '0');
    var month = String(d.getMonth() + 1).padStart(2, '0');
    var year = d.getFullYear();
    var h = d.getHours();
    var m = String(d.getMinutes()).padStart(2, '0');
    var s = String(d.getSeconds()).padStart(2, '0');
    return day + '/' + month + '/' + year + ' ' + h + ':' + m + ':' + s;
}

function getTelegramMessageText(type, payload) {
    var user = payload.sellerName || getCurrentUserName();
    var dt = payload.dateTime != null ? formatTelegramDateTime(payload.dateTime) : formatTelegramDateTime(new Date());
    var currency = payload.currency || 'USD';
    var amount = payload.amount != null ? (Number(payload.amount).toFixed(2) + ' ' + currency) : '';
    var inv = payload.invoiceNumber || payload.invoice || '-';
    var lines = ['🔔 ' + (payload.operationLabel || type), '👤 Seller: ' + user, '📅 ' + dt];
    if (payload.branchName) lines.splice(2, 0, '🏪 Branch: ' + payload.branchName);
    if (inv !== '-') lines.push('📄 ' + inv);
    if (payload.productsText) lines.push('🛒 ' + payload.productsText);
    if (amount) lines.push('💰 Total: ' + amount);
    if (payload.priceType) lines.push('🏷 Price Type: ' + payload.priceType);
    if (payload.subtotal != null && payload.subtotal > 0) lines.push('📊 Subtotal: ' + Number(payload.subtotal).toFixed(2) + ' ' + (payload.currency || 'USD'));
    if (payload.discount != null && Number(payload.discount) > 0) lines.push('💸 Discount: ' + Number(payload.discount).toFixed(2) + ' ' + (payload.currency || 'USD'));
    if (payload.profit != null) lines.push('📈 Profit: ' + Number(payload.profit).toFixed(2) + ' USD');
    if (payload.note) lines.push('📝 ' + payload.note);
    if (type === 'supplier_payment') {
        lines = ['🔔 ' + (payload.operationLabel || 'Supplier payment'), '👤 ' + user, '📅 ' + dt];
        if (payload.supplierName) lines.push('🏭 Supplier: ' + payload.supplierName);
        if (payload.productName) lines.push('📦 Product: ' + payload.productName);
        if (payload.totalCost != null) lines.push('📊 Purchase total: $' + Number(payload.totalCost).toFixed(2));
        if (payload.amountPaid != null) lines.push('💵 Paid now: $' + Number(payload.amountPaid).toFixed(2));
        if (payload.remaining != null) lines.push('⏳ Still owed: $' + Number(payload.remaining).toFixed(2));
        if (payload.note) lines.push('📝 ' + payload.note);
        return lines.join('\n');
    }
    // رسالة تحديث الصندوق: قبل، التغيير، بعد
    if (payload.balanceBefore && payload.balanceAfter) {
        var bf = payload.balanceBefore;
        var ba = payload.balanceAfter;
        var beforeParts = [];
        if (bf.USD != null) beforeParts.push('USD ' + formatCurrency(bf.USD, 'USD'));
        if (bf.LBP != null) beforeParts.push('LBP ' + formatCurrency(bf.LBP, 'LBP'));
        if (beforeParts.length) lines.push('💵 Before: ' + beforeParts.join(' | '));
        var ch = payload.balanceChange || {};
        var chUSD = ch.USD != null ? Number(ch.USD) : 0;
        var chLBP = ch.LBP != null ? Number(ch.LBP) : 0;
        var changeParts = [];
        if (chUSD !== 0) changeParts.push('USD ' + (chUSD >= 0 ? '+' : '') + Number(chUSD).toFixed(2));
        if (chLBP !== 0) changeParts.push('LBP ' + (chLBP >= 0 ? '+' : '') + Math.round(chLBP).toLocaleString());
        if (changeParts.length) lines.push('➕ Changed: ' + changeParts.join(' | ')); else lines.push('➕ Changed: USD 0.00 | LBP 0');
        var afterParts = [];
        if (ba.USD != null) afterParts.push('USD ' + formatCurrency(ba.USD, 'USD'));
        if (ba.LBP != null) afterParts.push('LBP ' + formatCurrency(ba.LBP, 'LBP'));
        if (afterParts.length) lines.push('💰 After: ' + afterParts.join(' | '));
    } else if (payload.balanceAfter) {
        var b = payload.balanceAfter;
        if (b.USD != null || b.LBP != null) {
            var balParts = [];
            if (b.USD != null) balParts.push('USD: ' + Number(b.USD).toFixed(2));
            if (b.LBP != null) balParts.push('LBP: ' + Number(b.LBP).toLocaleString());
            if (balParts.length) lines.push('💵 Balance after: ' + balParts.join(' | '));
        }
    }
    return lines.join('\n');
}

/** وسيط إرسال Telegram */
var TELEGRAM_FIREBASE_FN = 'https://us-central1-pos-catch.cloudfunctions.net/telegramSendMessage';
var TELEGRAM_SEND_DOCUMENT_FN = 'https://us-central1-pos-catch.cloudfunctions.net/telegramSendDocument';

const TELEGRAM_LOG_KEY = 'telegramLogsV1';
function appendTelegramLog(entry) {
    try {
        const raw = localStorage.getItem(TELEGRAM_LOG_KEY);
        const list = raw ? JSON.parse(raw) : [];
        list.push(Object.assign({ at: Date.now() }, entry || {}));
        // keep last 200
        if (list.length > 200) list.splice(0, list.length - 200);
        localStorage.setItem(TELEGRAM_LOG_KEY, JSON.stringify(list));
    } catch (_) {}
}

function isUnauthenticatedLikeResult(res) {
    try {
        if (!res) return false;
        const httpStatus = res.httpStatus || res.status;
        if (httpStatus === 401) return true;

        const desc = (res.description || res.error || '').toString().toLowerCase();
        if (!desc) return false;
        if (desc.includes('unauthenticated')) return true;
        if (desc.includes('bearer token required')) return true;
        if (desc.includes('unauth')) return true;
        return false;
    } catch (_) {
        return false;
    }
}

async function getFreshFirebaseIdToken() {
    try {
        const auth = window.firebaseAuthInstance;
        const cachedToken = window.__latestFirebaseIdToken || null;
        const cachedAt = window.__latestFirebaseIdTokenAt || 0;
        const cacheAgeMs = Date.now() - cachedAt;
        const canUseCache = !!cachedToken && cachedAt && cacheAgeMs >= 0 && cacheAgeMs < (55 * 60 * 1000); // idToken ~ 1 hour

        // Some flows rely on a "currentUser" wrapper that may briefly return null while
        // Firebase persistence restores the session. Wait briefly for a real firebase user.
        const getUser = function () {
            try {
                if (auth && auth.auth && auth.auth.currentUser && typeof auth.auth.currentUser.getIdToken === 'function') {
                    return auth.auth.currentUser;
                }
                if (auth && auth.getCurrentUser && typeof auth.getCurrentUser === 'function') {
                    const u = auth.getCurrentUser();
                    if (u && typeof u.getIdToken === 'function') return u;
                }
            } catch (_) {}
            return null;
        };

        let user = getUser();
        if (!user) {
            // If auth restoration is temporarily in-flight, fall back to the last token
            // we captured via onIdTokenChanged (prevents Telegram from failing with auth_unavailable).
            if (canUseCache) return cachedToken;

            const startedAt = Date.now();
            const timeoutMs = 8000;
            while (Date.now() - startedAt < timeoutMs) {
                await new Promise(resolve => setTimeout(resolve, 250));
                user = getUser();
                if (user) break;
            }
        }

        if (!user || typeof user.getIdToken !== 'function') return null;

        // Force refresh to guarantee a valid token before backend calls.
        const idToken = await user.getIdToken(true);
        window.__latestFirebaseIdToken = idToken || null;
        window.__latestFirebaseIdTokenAt = Date.now();
        return idToken || null;
    } catch (_) {
        return null;
    }
}

function sendTelegramMessageRequest(token, chatId, text) {
    token = String(token || '').trim();
    chatId = String(chatId || '').trim();
    text = String(text || '');
    if (!token || !chatId || !text) return Promise.resolve({ ok: false, description: 'missing' });

    var customUrl = String(settings.telegramProxyUrl || '').trim().replace(/\/$/, '');
    var customSecret = String(settings.telegramProxySecret || '').trim();

    function doJsonProxy(url, headers, body) {
        var controller = typeof AbortController !== 'undefined' ? new AbortController() : null;
        var timeoutId = null;
        try {
            if (controller) {
                timeoutId = setTimeout(function() {
                    try { controller.abort(); } catch (_) {}
                }, 9000);
            }
        } catch (_) {}

        var fetchOptions = { method: 'POST', headers: headers, body: JSON.stringify(body) };
        if (controller) fetchOptions.signal = controller.signal;

        return fetch(url, fetchOptions)
            .then(function (r) {
                return r.json().then(function (data) {
                    return { r: r, data: data };
                }).catch(function () {
                    return {
                        r: r,
                        data: { ok: false, error: r.status === 404 ? 'function_not_deployed' : 'bad_response', description: '' }
                    };
                });
            })
            .then(function (payload) {
                const r = payload && payload.r ? payload.r : null;
                const data = payload ? payload.data : null;
                const httpStatus = r && r.status ? r.status : undefined;

                if (data && data.ok === true) return { ok: true, httpStatus: httpStatus };
                if (data && data.ok === false) {
                    return {
                        ok: false,
                        httpStatus: httpStatus,
                        description: data.description || data.error || 'telegram_api',
                        error: data.error || null
                    };
                }
                return { ok: false, httpStatus: httpStatus, description: data && data.error ? data.error : 'proxy_failed' };
            })
            .catch(function () {
                // Abort due to timeout or network error
                try {
                    if (controller && controller.signal && controller.signal.aborted) return { ok: false, description: 'timeout' };
                } catch (_) {}
                return { ok: false, description: 'proxy_unreachable' };
            })
            .finally(function () {
                try { if (timeoutId) clearTimeout(timeoutId); } catch (_) {}
            });
    }

    if (customUrl && customSecret) {
        return doJsonProxy(customUrl, {
            'Content-Type': 'application/json',
            'X-Telegram-Proxy-Secret': customSecret,
        }, { botToken: token, chatId: chatId, text: text });
    }

    // Final fix for net::ERR_NAME_NOT_RESOLVED with api.telegram.org:
    // Disable direct Telegram calls from the browser and always use a proxy (custom proxy or Cloud Function).
    // This prevents the frontend from ever calling api.telegram.org directly (even if Telegram is blocked).

    // 1) If a custom proxy is configured, use it
    if (customUrl && customSecret) {
        return doJsonProxy(
            customUrl,
            {
                'Content-Type': 'application/json',
                'X-Telegram-Proxy-Secret': customSecret,
            },
            { botToken: token, chatId: chatId, text: text }
        );
    }

    // 2) Otherwise always use Firebase Cloud Function / backend as a proxy
    // Token expiry hardening:
    // - Always force refresh token before the request (getIdToken(true))
    // - If backend responds with unauthenticated/401, refresh again and retry once.
    return (async function () {
        function sendOnce(idToken) {
            return doJsonProxy(
                TELEGRAM_FIREBASE_FN,
                { 'Content-Type': 'application/json', Authorization: 'Bearer ' + idToken },
                { botToken: token, chatId: chatId, text: text }
            );
        }

        const idToken1 = await getFreshFirebaseIdToken();
        if (!idToken1) return Promise.resolve({ ok: false, description: 'auth_unavailable' });

        const res1 = await sendOnce(idToken1);
        if (isUnauthenticatedLikeResult(res1)) {
            const idToken2 = await getFreshFirebaseIdToken();
            if (!idToken2) return res1;
            const res2 = await sendOnce(idToken2);
            return res2;
        }
        return res1;
    })();
}

// ===== Telegram Queue: async background delivery with safe retry =====

const TELEGRAM_QUEUE_KEY = 'telegramQueueV1';
let __telegramQueue = null;
let __telegramFlushTimer = null;
let __telegramFlushInFlight = false;

function loadTelegramQueue() {
    if (__telegramQueue) return __telegramQueue;
    try {
        const raw = localStorage.getItem(TELEGRAM_QUEUE_KEY);
        const parsed = raw ? JSON.parse(raw) : [];
        __telegramQueue = Array.isArray(parsed) ? parsed : [];
    } catch (_) {
        __telegramQueue = [];
    }
    return __telegramQueue;
}

function saveTelegramQueue() {
    try {
        localStorage.setItem(TELEGRAM_QUEUE_KEY, JSON.stringify(__telegramQueue || []));
    } catch (_) {}
}

function scheduleTelegramFlush(delayMs) {
    try {
        if (__telegramFlushTimer) clearTimeout(__telegramFlushTimer);
        __telegramFlushTimer = setTimeout(flushTelegramQueue, delayMs || 0);
    } catch (_) {}
}

function enqueueTelegramMessage(type, payload) {
    if (!settings.telegramEnabled || !settings.telegramBotToken || !settings.telegramChatId) return;
    const events = settings.telegramEvents || {};
    if (events[type] === false) return;

    const text = getTelegramMessageText(type, payload);
    const token = (settings.telegramBotToken || '').trim();
    const chatId = (settings.telegramChatId || '').trim();
    if (!token || !chatId || !text) return;

    const q = loadTelegramQueue();
    q.push({
        id: Date.now() + '-' + Math.random().toString(16).slice(2),
        token,
        chatId,
        text,
        createdAt: Date.now(),
        attempts: 0,
        nextAttemptAt: Date.now(),
        type
    });
    saveTelegramQueue();
    scheduleTelegramFlush(1000);
}

async function flushTelegramQueue() {
    if (__telegramFlushInFlight) return;
    __telegramFlushInFlight = true;
    __telegramFlushTimer = null;
    try {
        const q = loadTelegramQueue();
        if (!q.length) return;

        // Do not attempt if the browser is offline or the network is temporarily blocked
        try {
            if ((typeof navigator !== 'undefined' && navigator && navigator.onLine === false) || (window && window.__posNetOffline === true)) return;
        } catch (_) {}
        try {
            const blockedUntil = window.__telegramNetworkBlockedUntil || 0;
            if (blockedUntil && Date.now() < blockedUntil) return;
        } catch (_) {}

        let anyNetworkFail = false;
        const maxBatch = 5;
        const now = Date.now();

        for (let i = 0; i < Math.min(maxBatch, q.length); i++) {
            const msg = q[0];
            if (!msg) break;

            // Backoff: do not hammer the proxy/bot when previous attempts failed
            const nextAt = msg.nextAttemptAt || 0;
            if (nextAt && now < nextAt) {
                // Avoid head-of-line blocking: move not-due message to the end.
                q.push(q.shift());
                continue;
            }

            try {
                appendTelegramLog({ kind: 'attempt', msgId: msg.id, type: msg.type, attempts: msg.attempts || 0 });
                const res = await sendTelegramMessageRequest(msg.token, msg.chatId, msg.text);

                if (res && res.ok) {
                    appendTelegramLog({ kind: 'success', msgId: msg.id, type: msg.type });
                    q.shift();
                    continue;
                }

                const desc = (res && res.description) || 'unknown';
                msg.attempts = (msg.attempts || 0) + 1;
                msg.lastError = desc;
                msg.lastErrorAt = Date.now();

                const base = 2000;
                const cap = (desc === 'telegram_api' || desc === 'bad_response' || desc === 'function_not_deployed')
                    ? (24 * 60 * 60 * 1000) // 24 hours
                    : (60 * 60 * 1000); // 1 hour
                const delay = Math.min(cap, base * Math.pow(2, Math.max(0, msg.attempts - 1)));
                msg.nextAttemptAt = Date.now() + delay;

                if (desc === 'network_blocked' || desc === 'proxy_unreachable' || desc === 'proxy_failed' || desc === 'timeout') {
                    anyNetworkFail = true;
                }

                appendTelegramLog({ kind: 'fail', msgId: msg.id, type: msg.type, desc: desc, attempts: msg.attempts });

            // Surface configuration / proxy deployment issues once (do not block POS)
            if (!window.__telegramConfigErrorToastShown && (desc === 'telegram_api' || desc === 'function_not_deployed' || desc === 'bad_response')) {
                window.__telegramConfigErrorToastShown = true;
                try {
                    const msg = (document.documentElement.lang === 'en')
                        ? 'Telegram notification failed (check bot token / chat ID / proxy). Notifications will retry automatically.'
                        : 'فشل إرسال إشعار Telegram (تحقق من التوكن/Chat ID أو الـ proxy). سيتم إعادة المحاولة تلقائياً.';
                    if (typeof showNotification === 'function') showNotification(msg, 'error', 8000);
                } catch (_) {}
            }

                // Retry later by rotating the queue
                q.push(q.shift());
            } catch (err) {
                msg.attempts = (msg.attempts || 0) + 1;
                msg.lastError = (err && err.message) ? err.message : 'unknown_error';
                msg.lastErrorAt = Date.now();
                msg.nextAttemptAt = Date.now() + Math.min(30 * 60 * 1000, 2000 * Math.pow(2, Math.max(0, msg.attempts - 1)));
                anyNetworkFail = true;
                appendTelegramLog({ kind: 'exception', msgId: msg.id, type: msg.type, err: msg.lastError, attempts: msg.attempts });

                q.push(q.shift());
            }
        }

        saveTelegramQueue();

        if (anyNetworkFail) {
            try {
                // keep short throttle only; queue is preserved and will retry
                window.__telegramNetworkBlockedUntil = Date.now() + 60 * 1000; // 1 minute
            } catch (_) {}

            // Optional short toast: messages delayed but the system is working normally
            try {
                const isEn = (document.documentElement.lang || 'ar') === 'en';
                let infoMsg = isEn
                    ? 'Telegram messages are delayed. The system is still working normally.'
                    : 'تم تأخير رسائل تيليجرام. النظام يعمل بشكل طبيعي.';
                if (typeof getText === 'function') {
                    const raw = String(getText('telegram-delayed') || '').trim();
                    // Some i18n setups return the key itself when missing; never show raw keys to end users.
                    if (raw && raw.toLowerCase() !== 'telegram-delayed' && raw.toLowerCase() !== 'telegram_delayed') {
                        infoMsg = raw;
                    }
                }
                if (!window.__telegramDelayToastShown && typeof showNotification === 'function') {
                    window.__telegramDelayToastShown = true;
                    showNotification(infoMsg, 'info', 4000);
                    setTimeout(() => { window.__telegramDelayToastShown = false; }, 10 * 60 * 1000);
                }
            } catch (_) {}
        } else if (q.length) {
            // Messages still pending; retry quietly later
            scheduleTelegramFlush(5000);
        }
    } finally {
        __telegramFlushInFlight = false;
    }
}

// Auto-flush the queue when connectivity returns
try {
    window.addEventListener('online', () => scheduleTelegramFlush(2000));
    window.addEventListener('offline', () => {
        try { window.__telegramNetworkBlockedUntil = Date.now() + 30 * 1000; } catch(_) {}
    });
    document.addEventListener('visibilitychange', () => {
        if (document.visibilityState === 'visible') scheduleTelegramFlush(2000);
    });
    // Periodic safety flush: prevents "stops sending" if 'online' event is missed.
    setInterval(() => {
        try {
            if (window && window.__posNetOffline === true) return;
            if (typeof navigator !== 'undefined' && navigator.onLine === false) return;
            scheduleTelegramFlush(2000);
        } catch (_) {}
    }, 20000);
} catch (_) {}

// Simple interface used by the rest of the system: enqueue only, no waiting / no impact on core operations
function sendTelegramNotification(type, payload) {
    try {
        enqueueTelegramMessage(type, payload);
    } catch (_) {
        // Any failure here is fully ignored so it never impacts core operations
        try { appendTelegramLog({ kind: 'enqueue_exception', type: type, err: (typeof _?.message === 'string' ? _.message : 'unknown') }); } catch(_) {}
        if (typeof console !== 'undefined') console.warn('Telegram enqueue failed:', _);
    }
}

/** Send a document (backup) to Telegram via Cloud Function */
function sendTelegramDocumentRequest(token, chatId, documentBase64, filename) {
    token = String(token || '').trim();
    chatId = String(chatId || '').trim();
    if (!token || !chatId || !documentBase64) return Promise.resolve({ ok: false, description: 'missing' });
    // Token expiry hardening: always force refresh token; retry once on unauthenticated.
    return (async function () {
        async function sendOnce(idToken) {
            const r = await fetch(TELEGRAM_SEND_DOCUMENT_FN, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'Authorization': 'Bearer ' + idToken
                },
                body: JSON.stringify({
                    botToken: token,
                    chatId: chatId,
                    documentBase64: documentBase64,
                    filename: filename
                })
            });
            const data = await r.json().catch(function () { return { ok: false }; });
            // Normalize response shape for queue logic.
            if (data && data.ok === true) return { ok: true, httpStatus: r.status };
            return {
                ok: false,
                httpStatus: r.status,
                description: (data && (data.description || data.error)) || 'telegram_sendDocument_error',
                error: data && data.error ? data.error : null
            };
        }

        const idToken1 = await getFreshFirebaseIdToken();
        if (!idToken1) return Promise.resolve({ ok: false, description: 'auth_unavailable' });

        const res1 = await sendOnce(idToken1);
        if (isUnauthenticatedLikeResult(res1)) {
            const idToken2 = await getFreshFirebaseIdToken();
            if (!idToken2) return res1;
            const res2 = await sendOnce(idToken2);
            return res2;
        }
        return res1;
    })().catch(function () { return { ok: false, description: 'auth_failed' }; });
}

/** بناء نسخة احتياطية كاملة (منتجات، مبيعات، زباين، إعدادات، صور المنتجات، إلخ) */
function buildDailyBackupPayload() {
    var products = loadFromStorage('products', []);
    var customers = loadFromStorage('customers', []);
    var sales = loadFromStorage('sales', []);
    var suppliers = loadFromStorage('suppliers', []);
    var purchases = loadFromStorage('purchases', []);
    var supplierPayments = loadFromStorage('supplierPayments', []);
    var purchaseReturns = loadFromStorage('purchaseReturns', []);
    var supplierLedger = loadFromStorage('supplierLedger', []);
    var cashDrawer = loadFromStorage('cashDrawer', null);
    var cashDrawerTx = loadFromStorage('cashDrawerTx', []);
    var appSettings = loadFromStorage('settings', null);
    var stockMovements = loadFromStorage('stockMovements', []);
    var salesLogs = loadFromStorage('salesLogs', []);
    var customerLogs = loadFromStorage('customerLogs', {});
    if (!cashDrawer || typeof cashDrawer !== 'object') cashDrawer = { cashUSD: 0, cashLBP: 0, transactions: [] };
    var payload = {
        backupVersion: 1,
        createdAt: new Date().toISOString(),
        storeName: (appSettings && appSettings.storeName) || 'CATCH POS',
        products: products,
        customers: customers,
        sales: sales,
        suppliers: suppliers,
        purchases: purchases,
        supplierPayments: supplierPayments,
        purchaseReturns: purchaseReturns,
        supplierLedger: supplierLedger,
        cashDrawer: cashDrawer,
        cashDrawerTx: cashDrawerTx,
        settings: appSettings,
        stockMovements: stockMovements,
        salesLogs: salesLogs,
        customerLogs: customerLogs
    };
    var jsonStr = JSON.stringify(payload);
    var maxBytes = 48 * 1024 * 1024;
    if (new Blob([jsonStr]).size > maxBytes && Array.isArray(products) && products.length) {
        var productsNoImages = products.map(function (p) {
            var q = { ...p };
            if (q.imageUrl && typeof q.imageUrl === 'string') q.imageUrl = '(omitted - backup size limit)';
            return q;
        });
        payload.products = productsNoImages;
        payload._note = 'Product images omitted to stay under Telegram 50MB limit.';
        jsonStr = JSON.stringify(payload);
    }
    return jsonStr;
}

/** تشغيل النسخة الاحتياطية اليومية وإرسالها إلى Telegram */
function runDailyBackup() {
    if (!settings.telegramEnabled || !settings.telegramBotToken || !settings.telegramChatId) return;
    var token = settings.telegramBotToken.trim();
    var chatId = settings.telegramChatId.trim();
    if (!token || !chatId) return;
    try {
        var jsonStr = buildDailyBackupPayload();
        var bytes = new TextEncoder().encode(jsonStr);
        var binary = '';
        for (var i = 0; i < bytes.length; i++) binary += String.fromCharCode(bytes[i]);
        var base64 = typeof btoa !== 'undefined' ? btoa(binary) : (typeof Buffer !== 'undefined' ? Buffer.from(jsonStr, 'utf8').toString('base64') : '');
        if (!base64) return;
        var dateStr = new Date().toISOString().slice(0, 10);
        var filename = 'catch-pos-backup-' + dateStr + '.json';
        sendTelegramDocumentRequest(token, chatId, base64, filename).then(function (r) {
            if (r.ok) {
                try { showNotification('✅ تم إرسال النسخة الاحتياطية اليومية إلى Telegram', 'success', 4000); } catch (_) {}
            } else if (r.description && typeof console !== 'undefined') {
                console.warn('Daily backup Telegram send failed:', r.description);
            }
        });
    } catch (e) {
        if (typeof console !== 'undefined') console.warn('Daily backup error:', e);
    }
}

function getLocalDayKey(date) {
    if (!(date instanceof Date) || isNaN(date.getTime())) return '';
    return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`;
}

function parseTelegramReportSaleDate(sale) {
    const raw = sale && (sale.timestamp || sale.date || sale.returnDate);
    if (!raw) return null;
    try {
        if (typeof raw === 'string' && raw.includes('T')) {
            const parsed = new Date(raw);
            if (!isNaN(parsed.getTime())) return parsed;
            const parts = raw.split('T');
            if (parts.length === 2) {
                const [datePart, timePart] = parts;
                const [year, month, day] = datePart.split('-').map(Number);
                const cleanTime = String(timePart || '').replace('Z', '').split('+')[0];
                const [hours, minutes, seconds = '0'] = cleanTime.split(':');
                return new Date(
                    year,
                    (month || 1) - 1,
                    day || 1,
                    Number(hours || 0),
                    Number(minutes || 0),
                    Number(String(seconds).split('.')[0] || 0),
                    0
                );
            }
        }
        const parsed = new Date(raw);
        if (!isNaN(parsed.getTime())) return parsed;
    } catch (_) {}
    return null;
}

function isRefundSaleForTelegramReport(sale) {
    const pm = String((sale && sale.paymentMethod) || '').toLowerCase();
    const inv = String((sale && sale.invoiceNumber) || '').toUpperCase();
    return pm === 'refund' || /refund|مرتج|مرجعة|استرجاع|ارجاع/.test(pm) || inv.startsWith('RF-');
}

function isCompletedPaymentForTelegramReport(sale) {
    const pm = String((sale && sale.paymentMethod) || '').toLowerCase();
    if (!pm) return true;
    if (isRefundSaleForTelegramReport(sale)) return false;
    if (pm === 'credit' || /credit|دين|ائتمان/.test(pm)) return false;
    if (pm === 'partial' || /partial|جزئي/.test(pm)) return false;
    return true;
}

function getTelegramReportItemPriceUSD(item) {
    const price = item && (
        item.finalPriceUSD != null ? item.finalPriceUSD :
        item.priceUSD != null ? item.priceUSD :
        item.price != null ? item.price :
        item.finalPrice != null ? item.finalPrice :
        0
    );
    return Number(price) || 0;
}

function getTelegramReportItemCostUSD(item, productCostById) {
    if (item && item.costUSD != null && Number.isFinite(Number(item.costUSD))) {
        return Number(item.costUSD) || 0;
    }
    const productId = item && item.id != null ? String(item.id) : '';
    if (productId && productCostById.has(productId)) {
        return Number(productCostById.get(productId)) || 0;
    }
    return 0;
}

async function collectTelegramDailyReportSummary(dayOffset) {
    const normalizedOffset = Number.isFinite(Number(dayOffset)) ? Number(dayOffset) : 0;
    let salesRows = [];
    let retries = 0;

    while (retries < 6) {
        try {
            salesRows = typeof getCurrentSales === 'function' ? (getCurrentSales() || []) : [];
        } catch (_) {
            salesRows = [];
        }
        if (Array.isArray(salesRows) && salesRows.length > 0) break;
        retries += 1;
        if (retries < 6) await sleep(1000);
    }

    let productRows = [];
    try {
        productRows = typeof getCurrentProducts === 'function' ? (getCurrentProducts() || []) : (Array.isArray(products) ? products : []);
    } catch (_) {
        productRows = Array.isArray(products) ? products : [];
    }
    const productCostById = new Map(
        (Array.isArray(productRows) ? productRows : []).map(function (product) {
            return [String(product && product.id != null ? product.id : ''), Number(product && product.costUSD) || 0];
        })
    );

    const targetDate = new Date();
    targetDate.setHours(0, 0, 0, 0);
    targetDate.setDate(targetDate.getDate() + normalizedOffset);
    const rangeStart = new Date(targetDate.getFullYear(), targetDate.getMonth(), targetDate.getDate(), 0, 0, 0, 0);
    const rangeEnd = new Date(targetDate.getFullYear(), targetDate.getMonth(), targetDate.getDate(), 23, 59, 59, 999);
    const targetDayKey = getLocalDayKey(rangeStart);

    let totalSales = 0;
    let totalProfit = 0;
    let completedPayments = 0;

    (Array.isArray(salesRows) ? salesRows : []).forEach(function (sale) {
        if (!sale || !isCompletedPaymentForTelegramReport(sale)) return;

        const saleDate = parseTelegramReportSaleDate(sale);
        if (!saleDate || saleDate < rangeStart || saleDate > rangeEnd) return;

        let saleGross = 0;
        let saleCost = 0;
        let hasItems = false;
        const items = Array.isArray(sale.items) ? sale.items : [];

        items.forEach(function (item) {
            const quantity = Number(item && item.quantity) || 0;
            if (quantity <= 0) return;
            const itemPrice = getTelegramReportItemPriceUSD(item);
            const itemCost = getTelegramReportItemCostUSD(item, productCostById);
            saleGross += itemPrice * quantity;
            saleCost += itemCost * quantity;
            hasItems = true;
        });

        if (!hasItems) {
            saleGross = Number(sale.amount) || 0;
        }

        totalSales += saleGross;
        totalProfit += (saleGross - saleCost);
        completedPayments += 1;
    });

    return {
        targetDate: rangeStart,
        targetDayKey: targetDayKey,
        totalSales: Number(totalSales.toFixed(2)),
        totalProfit: Number(totalProfit.toFixed(2)),
        completedPayments: completedPayments,
        loadedSalesCount: Array.isArray(salesRows) ? salesRows.length : 0,
        dataReady: Array.isArray(salesRows) && salesRows.length > 0
    };
}

function calculateCompletedSalesSummaryForRange(range, salesRows) {
    const safeRange = range || {};
    const rangeStart = safeRange.from instanceof Date ? safeRange.from : new Date(0);
    const rangeEnd = safeRange.to instanceof Date ? safeRange.to : new Date();
    const sourceRows = Array.isArray(salesRows) ? salesRows : [];

    let totalSales = 0;
    let totalProfit = 0;
    let totalTransactions = 0;
    const filteredSales = [];

    let productRows = [];
    try {
        productRows = typeof getCurrentProducts === 'function' ? (getCurrentProducts() || []) : (Array.isArray(products) ? products : []);
    } catch (_) {
        productRows = Array.isArray(products) ? products : [];
    }
    const productCostById = new Map(
        (Array.isArray(productRows) ? productRows : []).map(function (product) {
            return [String(product && product.id != null ? product.id : ''), Number(product && product.costUSD) || 0];
        })
    );

    sourceRows.forEach(function (sale) {
        if (!sale || !isCompletedPaymentForTelegramReport(sale)) return;
        const saleDate = parseTelegramReportSaleDate(sale);
        if (!saleDate || saleDate < rangeStart || saleDate > rangeEnd) return;

        let saleGross = 0;
        let saleCost = 0;
        let hasItems = false;
        const items = Array.isArray(sale.items) ? sale.items : [];

        items.forEach(function (item) {
            const quantity = Number(item && item.quantity) || 0;
            if (quantity <= 0) return;
            saleGross += getTelegramReportItemPriceUSD(item) * quantity;
            saleCost += getTelegramReportItemCostUSD(item, productCostById) * quantity;
            hasItems = true;
        });

        if (!hasItems) {
            saleGross = Number(sale.amount) || 0;
        }

        totalSales += saleGross;
        totalProfit += (saleGross - saleCost);
        totalTransactions += 1;
        filteredSales.push(sale);
    });

    return {
        filteredSales: filteredSales,
        totalSales: Number(totalSales.toFixed(2)),
        totalProfit: Number(totalProfit.toFixed(2)),
        totalTransactions: totalTransactions
    };
}

function buildTelegramDailyReportText(summary) {
    const dateLabel = summary && summary.targetDate ? summary.targetDate.toLocaleDateString() : new Date().toLocaleDateString();
    const salesValue = Number(summary && summary.totalSales) || 0;
    const profitValue = Number(summary && summary.totalProfit) || 0;
    const countValue = Number(summary && summary.completedPayments) || 0;
    return [
        '📊 Daily Sales Report',
        '📅 ' + dateLabel,
        '🧾 Completed Payments: ' + countValue,
        '💰 Total Sales: ' + salesValue.toFixed(2) + ' USD',
        '📈 Total Profit: ' + profitValue.toFixed(2) + ' USD'
    ].join('\n');
}

async function runDailyTelegramReport(dayOffset) {
    if (!settings.telegramEnabled || !settings.telegramBotToken || !settings.telegramChatId) return false;
    const token = String(settings.telegramBotToken || '').trim();
    const chatId = String(settings.telegramChatId || '').trim();
    if (!token || !chatId) return false;

    const summary = await collectTelegramDailyReportSummary(dayOffset);
    console.log(summary.totalSales, summary.totalProfit);

    if (!summary.dataReady && summary.loadedSalesCount === 0) {
        console.warn('Daily Telegram report skipped: sales data not loaded yet', {
            targetDay: summary.targetDayKey
        });
        return false;
    }

    const text = buildTelegramDailyReportText(summary);
    try {
        const response = await sendTelegramMessageRequest(token, chatId, text);
        if (!response || !response.ok) {
            console.warn('Daily Telegram report send failed:', response && response.description ? response.description : response);
            return false;
        }
        console.log('Daily Telegram report sent successfully', {
            targetDay: summary.targetDayKey,
            totalSales: summary.totalSales,
            totalProfit: summary.totalProfit,
            completedPayments: summary.completedPayments
        });
        return true;
    } catch (error) {
        console.warn('Daily Telegram report error:', error);
        return false;
    }
}

/** جدولة النسخة الاحتياطية يومياً عند الساعة ١٢ ليلاً (00:00) — مفتاح التخزين حسب المستخدم لضمان نسخة احتياطية لكل حساب */
var dailyBackupIntervalId = null;
function startDailyBackupScheduler() {
    if (dailyBackupIntervalId) return;
    dailyBackupIntervalId = setInterval(function () {
        var uid = typeof getCurrentUserId === 'function' ? getCurrentUserId() : null;
        if (!uid) return;
        var now = new Date();
        if (now.getHours() !== 0 || now.getMinutes() >= 2) return;
        var today = now.getFullYear() + '-' + String(now.getMonth() + 1).padStart(2, '0') + '-' + String(now.getDate()).padStart(2, '0');
        var lastKey = 'pos_' + uid + '_lastDailyBackupDate';
        try {
            var last = localStorage.getItem(lastKey);
            if (last === today) return;
            runDailyBackup();
            localStorage.setItem(lastKey, today);
        } catch (_) {}
    }, 60 * 1000);
}

var dailyTelegramReportIntervalId = null;
function startDailyTelegramReportScheduler() {
    if (dailyTelegramReportIntervalId) return;
    dailyTelegramReportIntervalId = setInterval(async function () {
        var uid = typeof getCurrentUserId === 'function' ? getCurrentUserId() : null;
        if (!uid) return;
        var now = new Date();
        if (now.getHours() !== 0 || now.getMinutes() >= 10) return;

        var reportDate = new Date(now.getFullYear(), now.getMonth(), now.getDate() - 1, 0, 0, 0, 0);
        var reportDayKey = getLocalDayKey(reportDate);
        var lastKey = 'pos_' + uid + '_lastDailyTelegramReportDate';

        try {
            var last = localStorage.getItem(lastKey);
            if (last === reportDayKey) return;
            var sent = await runDailyTelegramReport(-1);
            if (sent) localStorage.setItem(lastKey, reportDayKey);
        } catch (_) {}
    }, 60 * 1000);
}

// Client-side fallback for AI daily insights.
// Keeps auto-send working even if cloud scheduler is delayed/unavailable.
var aiInsightsClientFallbackIntervalId = null;
var aiInsightsClientFallbackRunning = false;
function startAiInsightsClientFallbackScheduler() {
    if (aiInsightsClientFallbackIntervalId) return;
    aiInsightsClientFallbackIntervalId = setInterval(async function () {
        try {
            if (aiInsightsClientFallbackRunning) return;
            var uid = typeof getCurrentUserId === 'function' ? getCurrentUserId() : null;
            if (!uid) return;
            if (!settings || settings.aiInsightsEnabled !== true) return;
            if (!settings.telegramEnabled) return;
            var token = String((settings.telegramBotToken || '')).trim();
            var chatId = String((settings.telegramChatId || '')).trim();
            if (!token || !chatId) return;
            if (!window.firebaseDbInstance || typeof window.firebaseDbInstance.runAiInsightsNowSecure !== 'function') return;

            var hm = String(settings.aiInsightsReportTime || '09:00').trim();
            var m = hm.match(/^(\d{1,2}):(\d{2})$/);
            var targetH = m ? Math.max(0, Math.min(23, Number(m[1]) || 0)) : 9;
            var targetM = m ? Math.max(0, Math.min(59, Number(m[2]) || 0)) : 0;
            var targetMinute = (targetH * 60) + targetM;
            var tzOffset = Number(settings.aiTimezoneOffsetMinutes);
            if (!Number.isFinite(tzOffset)) tzOffset = -new Date().getTimezoneOffset();

            var nowMs = Date.now();
            var shiftedNow = new Date(nowMs + (tzOffset * 60000));
            var nowMinuteLocal = (shiftedNow.getUTCHours() * 60) + shiftedNow.getUTCMinutes();
            var minutesSinceTarget = nowMinuteLocal - targetMinute;
            if (minutesSinceTarget < 0 || minutesSinceTarget >= 95) return;

            var dayKey = shiftedNow.toISOString().slice(0, 10);
            var lastKey = 'pos_' + uid + '_lastClientAiInsightsDay';
            var lastDay = '';
            try { lastDay = String(localStorage.getItem(lastKey) || ''); } catch (_) {}
            if (lastDay === dayKey) return;

            aiInsightsClientFallbackRunning = true;
            var res = await window.firebaseDbInstance.runAiInsightsNowSecure();
            var ok = !!(res && res.ok);
            var skippedAlreadySent = !!(res && res.skipped && String(res.reason || '') === 'already_sent');
            if (ok || skippedAlreadySent) {
                try { localStorage.setItem(lastKey, dayKey); } catch (_) {}
                if (ok) {
                    console.log('AI insights sent by client fallback scheduler for day:', dayKey);
                }
            }
        } catch (e) {
            console.warn('startAiInsightsClientFallbackScheduler tick failed:', e && (e.message || e));
        } finally {
            aiInsightsClientFallbackRunning = false;
        }
    }, 60 * 1000);
}

let purchases = [];
let supplierPayments = [];
let purchaseReturns = [];
let supplierLedger = [];

function convertAmountUsingRate(amount, fromCurrency, toCurrency, rate) {
    if (!isFinite(Number(amount))) return 0;
    if (fromCurrency === toCurrency) return Number(amount);
    if (fromCurrency === 'USD' && toCurrency === 'LBP') return Number(amount) * rate;
    if (fromCurrency === 'LBP' && toCurrency === 'USD') return Number(amount) / rate;
    return Number(amount);
}

function toUSD(amount, currency, rate) {
    return convertAmountUsingRate(amount, currency, 'USD', rate);
}

function recalcPurchaseStatus(p) {
    const remaining = Math.max(0, (p.totalUSD || 0) - (p.paidUSD || 0));
    p.remainingUSD = remaining;
    if (remaining <= 0.0001) p.status = 'paid';
    else if (p.paidUSD > 0) p.status = 'partial';
    else p.status = 'unpaid';
    return p;
}

function getSupplierBalanceUSD(supplierId) {
    const sumBills = purchases.filter(b => b.supplierId === supplierId)
        .reduce((s, b) => s + Math.max(0, (b.totalUSD || 0) - (b.paidUSD || 0)), 0);
    return sumBills;
}

function recordSupplierPaymentCash(amount, currency, method, note) {
    const amt = Number(amount) || 0;
    if (amt <= 0) return;
    if (currency === 'USD') {
        cashDrawer.cashUSD = (cashDrawer.cashUSD || 0) - amt;
    } else {
        cashDrawer.cashLBP = (cashDrawer.cashLBP || 0) - Math.round(amt);
    }
    addCashDrawerTransaction({
        timestamp: new Date().toISOString(),
        type: 'supplier_payment',
        amount: amt,
        currency: currency,
        description: note || 'Supplier payment',
        user: (currentUser && currentUser.name) || 'user'
    });
    cashDrawer.lastUpdate = new Date().toISOString();
    saveToStorage('cashDrawer', cashDrawer);
    pushCashDrawerSummaryToCloud();
}

function updateSupplierPaymentBalanceDisplay(supplierId) {
    const supplier = supplierId ? suppliers.find((s) => s.id === supplierId) : null;
    const nameEl = document.getElementById('spSupplierDisplay');
    const balanceEl = document.getElementById('spBalanceDisplay');
    if (!nameEl || !balanceEl) return;
    const isEn = (document.documentElement.lang || 'ar') === 'en';
    if (!supplier) {
        nameEl.textContent = getText('supplier-select-prompt') || (isEn ? 'Select supplier' : 'اختر مورّداً');
        nameEl.classList.add('supplier-payment-balance-name--placeholder');
        balanceEl.textContent = '—';
        balanceEl.classList.add('supplier-payment-balance-value--empty');
        return;
    }
    nameEl.textContent = supplier.name || '—';
    nameEl.classList.remove('supplier-payment-balance-name--placeholder');
    balanceEl.textContent = formatCurrency(getSupplierBalanceUSD(supplier.id), 'USD');
    balanceEl.classList.remove('supplier-payment-balance-value--empty');
}

function validateSupplierPaymentForm() {
    const supplierId = parseInt(document.getElementById('spSupplier')?.value || '0', 10);
    const amount = Number(document.getElementById('spAmount')?.value) || 0;
    const confirmBtn = document.getElementById('confirmSupplierPayment');
    const amountError = document.getElementById('spAmountError');
    const isEn = (document.documentElement.lang || 'ar') === 'en';
    let valid = !!supplierId && amount > 0;
    if (amountError) {
        if (amount <= 0 && document.getElementById('spAmount')?.value) {
            amountError.textContent = getText('payment-amount-invalid') || (isEn ? 'Enter a valid payment amount.' : 'أدخل مبلغ دفع صالحاً.');
            amountError.hidden = false;
        } else {
            amountError.hidden = true;
        }
    }
    if (confirmBtn) confirmBtn.disabled = !valid;
    return valid;
}

function updateSupplierPaymentRateHint() {
    const currency = document.getElementById('spCurrency')?.value || 'USD';
    const hint = document.getElementById('spRateHint');
    if (!hint) return;
    const rate = settings?.exchangeRate || 89500;
    const isEn = (document.documentElement.lang || 'ar') === 'en';
    if (currency === 'LBP') {
        hint.textContent = (isEn ? 'Rate: ' : 'السعر: ') + `${Math.round(rate).toLocaleString()} LBP`;
        hint.hidden = false;
    } else {
        hint.hidden = true;
    }
}

function openSupplierPayment(supplierId) {
    closeAllActionMenus();
    const sel = document.getElementById('spSupplier');
    const list = document.getElementById('spSupplierList');
    const search = document.getElementById('spSupplierSearch');
    if (sel) sel.innerHTML = suppliers.map(s => `<option value="${escapeAttr(s.id)}">${escapeHtml(s.name || '')}</option>`).join('');
    translateSupplierPaymentModal();
    const renderList = (term = '') => {
        if (!list) return;
        const t = (term || '').trim().toLowerCase();
        const filtered = suppliers.filter((s) => {
            const name = (s.name || '').toLowerCase();
            const phone = (s.phone || '').toLowerCase();
            const contact = (s.contactPerson || '').toLowerCase();
            return !t || name.includes(t) || phone.includes(t) || contact.includes(t);
        });
        if (!filtered.length) {
            list.innerHTML = `<div class="sp-supplier-item">${getText('no-results') || ((document.documentElement.lang || 'en') === 'en' ? 'No results' : 'لا نتائج')}</div>`;
        } else {
            list.innerHTML = filtered.map(s => `<div class="sp-supplier-item" data-id="${escapeAttr(s.id)}"><span>${escapeHtml(s.name || '')}</span><span class="phone">${escapeHtml(s.phone || '')}</span></div>`).join('');
        }
        list.style.display = 'block';
        list.querySelectorAll('.sp-supplier-item[data-id]').forEach((item) => {
            item.onclick = function () {
                const id = parseInt(this.dataset.id, 10);
                if (sel) sel.value = String(id);
                if (search) search.value = suppliers.find(s => s.id === id)?.name || '';
                list.style.display = 'none';
                updateSupplierPaymentBalanceDisplay(id);
                validateSupplierPaymentForm();
            };
        });
    };
    if (search) {
        search.onfocus = () => renderList(search.value);
        search.oninput = () => renderList(search.value);
        search.onclick = () => renderList(search.value);
    }
    document.addEventListener('click', function (e) {
        if (!document.getElementById('spSupplierCombo')?.contains(e.target)) {
            if (list) list.style.display = 'none';
        }
    }, { once: false });
    if (sel) {
        sel.onchange = function () {
            const id = parseInt(this.value, 10);
            const selName = suppliers.find(s => s.id === id)?.name || '';
            if (search) search.value = selName;
            updateSupplierPaymentBalanceDisplay(id);
            validateSupplierPaymentForm();
        };
    }
    document.getElementById('spAmount').value = '';
    document.getElementById('spCurrency').value = 'USD';
    document.getElementById('spMethod').value = 'cash';
    const noteEl = document.getElementById('spNote');
    if (noteEl) noteEl.value = '';
    if (supplierId) {
        if (sel) sel.value = String(supplierId);
        if (search) search.value = suppliers.find(s => s.id === supplierId)?.name || '';
        updateSupplierPaymentBalanceDisplay(supplierId);
    } else {
        if (sel) sel.value = '';
        if (search) search.value = '';
        updateSupplierPaymentBalanceDisplay(null);
    }
    updateSupplierPaymentRateHint();
    const amountEl = document.getElementById('spAmount');
    const currencyEl = document.getElementById('spCurrency');
    if (amountEl && amountEl.dataset.paymentBound !== '1') {
        amountEl.dataset.paymentBound = '1';
        amountEl.addEventListener('input', validateSupplierPaymentForm);
    }
    if (currencyEl && currencyEl.dataset.paymentBound !== '1') {
        currencyEl.dataset.paymentBound = '1';
        currencyEl.addEventListener('change', () => {
            updateSupplierPaymentRateHint();
            validateSupplierPaymentForm();
        });
    }
    const confirmBtn = document.getElementById('confirmSupplierPayment');
    if (confirmBtn) {
        confirmBtn.onclick = () => confirmSupplierPayment();
    }
    const cancelBtn = document.getElementById('spCancelBtn');
    if (cancelBtn) cancelBtn.onclick = () => hideModal('supplierPaymentModal');
    validateSupplierPaymentForm();
    showModal('supplierPaymentModal');
}
window.openSupplierPayment = openSupplierPayment;

function renderOpenBillsForSupplier(supplierId) {
    const rate = settings.exchangeRate;
    const container = document.getElementById('spOpenBills');
    if (!container) return;
    const openBills = purchases.filter(p => p.supplierId === supplierId && (p.status === 'unpaid' || p.status === 'partial'));
    container.innerHTML = openBills.map(p => {
        const remainUSD = Math.max(0, (p.totalUSD||0) - (p.paidUSD||0));
        const remainDisp = p.currency === 'USD' ? `$${remainUSD.toFixed(2)}` : `${Math.round(remainUSD * (p.rate||rate)).toLocaleString()} L`;
        return `<label style="display:flex;align-items:center;gap:8px;margin:4px 0;">
            <input type="checkbox" class="sp-bill-check" value="${p.id}">
            <span>فاتورة #${p.id} - ${p.date} - متبقي: ${remainDisp}</span>
        </label>`;
    }).join('');
}

async function confirmSupplierPayment() {
    const btn = document.getElementById('confirmSupplierPayment');
    if (!validateSupplierPaymentForm()) {
        showMessage(getText('msg-choose-supplier-amount'), 'error');
        return;
    }
    const supplierId = parseInt(document.getElementById('spSupplier').value, 10);
    const amount = Number(document.getElementById('spAmount').value) || 0;
    const currency = document.getElementById('spCurrency').value || 'USD';
    const method = document.getElementById('spMethod').value || 'cash';
    const note = (document.getElementById('spNote')?.value || '').trim();
    const supplier = suppliers.find((s) => s.id === supplierId);
    const supName = supplier?.name || '';
    const balance = getSupplierBalanceUSD(supplierId);
    const isEn = (document.documentElement.lang || 'ar') === 'en';
    if (balance <= 0.001) {
        showMessage(getText('supplier-no-balance-due') || (isEn ? 'This supplier has no balance due.' : 'لا يوجد رصيد مستحق لهذا المورد.'), 'warning');
        return;
    }
    const amountLabel = currency === 'USD' ? formatCurrency(amount, 'USD') : `${Math.round(amount).toLocaleString()} LBP`;
    const confirmMsg = (getText('confirm-supplier-payment') || (isEn ? 'Confirm payment of {amount} to supplier {supplier}?' : 'تأكيد دفع {amount} للمورد {supplier}؟'))
        .replace('{amount}', amountLabel)
        .replace('{supplier}', supName);
    if (!(await uiConfirm(confirmMsg, { title: getText('confirm') || (isEn ? 'Confirm' : 'تأكيد') }))) return;

    if (btn) btn.disabled = true;
    const originalText = btn?.textContent;
    if (btn) btn.textContent = getText('processing') || (isEn ? 'Processing...' : 'جارٍ المعالجة...');
    let done = false;
    const finish = () => {
        if (btn) {
            btn.disabled = false;
            btn.textContent = originalText || (isEn ? 'Confirm Payment' : 'تأكيد الدفع');
        }
    };
    try {
    const rate = settings.exchangeRate;
    let remainingUSD = toUSD(amount, currency, rate);
    const alloc = [];
    // لم يعد هناك اختيار فواتير؛ سنوزع FIFO على جميع الفواتير المفتوحة
    let bills = purchases.filter(p => p.supplierId === supplierId && (p.status === 'unpaid' || p.status === 'partial'))
        .sort((a,b)=> new Date(a.date) - new Date(b.date));

    // إجمالي المتبقي المفتوح للتحقق من تجاوز المبلغ
    const totalRemainingUSD = purchases.filter(p => p.supplierId === supplierId && (p.status === 'unpaid' || p.status === 'partial'))
        .reduce((s,p)=> s + Math.max(0,(p.totalUSD||0)-(p.paidUSD||0)), 0);
    if (remainingUSD > totalRemainingUSD + 1e-6) {
        showMessage(getText('msg-paid-exceeds-remaining'), 'error');
        return finish();
    }
    for (const bill of bills) {
        if (remainingUSD <= 0) break;
        const need = Math.max(0, (bill.totalUSD||0) - (bill.paidUSD||0));
        const applied = Math.min(need, remainingUSD);
        if (applied > 0) {
            bill.paidUSD = (bill.paidUSD||0) + applied;
            recalcPurchaseStatus(bill);
            alloc.push({ billId: bill.id, amountUSD: applied });
            remainingUSD -= applied;
        }
    }
    if (alloc.length === 0) {
        showMessage(getText('msg-no-open-invoices-supplier'), 'warning');
        return finish();
    }
    const paymentRow = {
        id: createRecordId('sp'),
        supplierId,
        date: new Date().toISOString(),
        currency,
        amount,
        rate,
        method,
        note,
        user: (currentUser && currentUser.name) || (isEn ? 'System' : 'نظام'),
        appliedTo: alloc
    };
    supplierPayments.push(paymentRow);
    recordSupplierPaymentCash(amount, currency, method, getText('supplier-payment-cashbox-desc', { id: supplierId }));
    // قيد دفتر الأستاذ PAYMENT
    const paidUsd = toUSD(amount, currency, rate);
    const supName = (suppliers.find(s => s.id === supplierId) || {}).name || '';
    addSupplierLedgerEntry({
        supplier_id: supplierId,
        type: 'PAYMENT',
        ref_no: alloc.length ? alloc.map(a=>a.billId).join('|') : null,
        product_name: '',
        total_cost: 0,
        paid_now: paidUsd,
        remaining: 0,
        note: note || ('Bills: ' + alloc.map(a => '#' + a.billId).join(', ')),
        currency,
        rate
    });
    const ledgerLast = supplierLedger[supplierLedger.length - 1];
    saveAllData();
    /* رفع دائم للسحابة: فواتير محدثة + الدفعة + السجل (وإلا الدمج عند التحديث يعيد paidUSD القديم) */
    try {
        const billIds = new Set(alloc.map(a => a.billId));
        billIds.forEach(function (bid) {
            const bill = purchases.find(p => p.id === bid);
            if (bill) try { enqueueSyncOp('purchases', 'upsert', bill.id, bill); } catch (_) {}
        });
        try { enqueueSyncOp('supplierPayments', 'upsert', paymentRow.id, paymentRow); } catch (_) {}
        if (ledgerLast && ledgerLast.id != null) try { enqueueSyncOp('supplierLedger', 'upsert', ledgerLast.id, ledgerLast); } catch (_) {}
        saveToStorage('purchases', purchases);
        saveToStorage('supplierPayments', supplierPayments);
        saveToStorage('supplierLedger', supplierLedger);
        await flushSyncQueue();
    } catch (syncErr) {
        console.warn('Supplier payment cloud sync:', syncErr);
    }
    loadPurchases();
    try { loadSuppliers(); } catch(_) {}
    hideModal('supplierPaymentModal');
    showMessage(getText('supplier-payment-success') || (isEn ? 'Supplier payment recorded successfully.' : 'تم تسجيل دفع المورد بنجاح.'));
    const balAfter = getSupplierBalanceUSD(supplierId);
    sendTelegramNotification('supplier_payment', {
        operationLabel: 'Supplier payment',
        dateTime: new Date(),
        sellerName: typeof getCurrentUserName === 'function' ? getCurrentUserName() : undefined,
        supplierName: supName,
        amountPaid: paidUsd,
        remaining: balAfter,
        note: note || ''
    });
    done = true;
    } catch (err) {
        console.error('confirmSupplierPayment error', err);
        showMessage(getText('msg-payment-record-error'), 'error');
    } finally {
        finish();
    }
}

// إدارة الصندوق والنقدية - يملأها loadUserDataFromFirestore بعد تسجيل الدخول
let cashDrawer = {
    cashUSD: 0,
    cashLBP: 0,
    lastUpdate: new Date().toISOString(),
    transactions: []
};

// نظام versioning للمنتجات (معزول حسب المستخدم)
let productsCatalogVersion = 1;

// دالة لفحص وتحديث catalog version
function checkAndUpdateProductsCatalog() {
    const uid = getCurrentUserId();
    const cvKey = uid ? `pos_${uid}_productsCatalogVersion` : 'productsCatalogVersion';
    const luKey = uid ? `pos_${uid}_productsLastUpdated` : 'productsLastUpdated';
    const storedVersion = parseInt(localStorage.getItem(cvKey)) || 1;
    const storedLastUpdated = parseInt(localStorage.getItem(luKey)) || 0;
    
    console.log(`🔍 Catalog version check: local=${productsCatalogVersion}, stored=${storedVersion}`);
    
    if (storedVersion > productsCatalogVersion) {
        console.log(`🔄 New products update detected (version ${storedVersion}); reloading data...`);
        productsCatalogVersion = storedVersion;
        
        // إعادة تحميل المنتجات من localStorage
        products = getCurrentProducts();
        
        // إبطال أي cache للمنتجات
        if (window.productsCache) {
            delete window.productsCache;
        }
        
        console.log(`✅ Products updated to version ${productsCatalogVersion}`);
        return true; // تم التحديث
    }
    
    return false; // لا يوجد تحديث
}

// Notify other windows/tabs that products were updated
function notifyProductsUpdated() {
    console.log('📢 Broadcasting products update to all open windows');
    
    // PostMessage to other windows (multi-window support)
    if (window.postMessage) {
        window.postMessage({
            type: 'PRODUCTS_UPDATED',
            version: productsCatalogVersion,
            timestamp: Date.now()
        }, '*');
    }
    
    // Immediate refresh in the current window if POS is open
    if (window.location.hash === '#pos' || document.querySelector('.pos-section')) {
        console.log('🔄 Immediate POS refresh in current window');
        checkAndUpdateProductsCatalog();
    }
}

function refreshProductConsumersAfterAsyncLoad(data) {
    try {
        if (Array.isArray(data)) {
            const mem = Array.isArray(products) ? products : [];
            products = _mergeProductsById(data, mem);
            assignLargeKeyInMemory('products', products);
        }
    } catch (_) {}

    try {
        const productsPage = document.getElementById('products');
        if (productsPage && productsPage.classList.contains('active') && typeof renderProductsTable === 'function') {
            renderProductsTable();
        }
    } catch (error) {
        console.warn('[products async load] renderProductsTable failed:', error);
    }

    try {
        const posPage = document.getElementById('pos');
        if (posPage && posPage.classList.contains('active')) {
            if (typeof updatePOSIfActive === 'function') {
                updatePOSIfActive();
            } else if (typeof displayProducts === 'function') {
                const searchInput = document.getElementById('productSearch');
                displayProducts(searchInput && searchInput.value ? searchInput.value.trim() : '');
            }
        }
    } catch (error) {
        console.warn('[products async load] POS refresh failed:', error);
    }
}

// Listener for update messages
window.addEventListener('message', function(event) {
    if (event.data && event.data.type === 'PRODUCTS_UPDATED') {
        console.log('📨 Received PRODUCTS_UPDATED message:', event.data);
        checkAndUpdateProductsCatalog();
    }
});

// وظائف إدارة البيانات المحلية (معزولة حسب userId)
function saveToStorage(key, data) {
    try {
        const actualKey = getScopedStorageKey(key);
        if (USER_SPECIFIC_KEYS.includes(key) && !actualKey) {
            if (key === 'products' && Array.isArray(data) && data.length)
                console.warn('[storage] Refusing to save products without login — please log in and retry');
            return true;
        }
        const storageKey = actualKey || key;
        if (key === 'products') {
            if (!Array.isArray(data)) data = [];
            else if (window.__deletedProductIds && window.__deletedProductIds.size)
                data = filterOutDeletedProducts(data, window.__deletedProductIds);
        }
        // محاولة الحفظ في OPFS أولاً (قد يستوعب أحجاماً كبيرة)
        try {
            if (window.opfsKV) {
                window.opfsKV.put(storageKey, data);
            }
        } catch(_) {}
        // إن وُجد SQLite، خزّن أيضاً في قاعدة بيانات kv
        try {
            if (window.sqliteDb) {
                sqliteKVSetSync(storageKey, data);
            }
        } catch(_) {}
        // استخدام IndexedDB للمفاتيح الكبيرة
        if (key === 'products') {
            productsCatalogVersion++;
            const uid = getCurrentUserId();
            const cvKey = uid ? `pos_${uid}_productsCatalogVersion` : 'productsCatalogVersion';
            const luKey = uid ? `pos_${uid}_productsLastUpdated` : 'productsLastUpdated';
            const now = Date.now();
            localStorage.setItem(cvKey, productsCatalogVersion.toString());
            localStorage.setItem(luKey, now.toString());
            if (!window._lastCatalogLog || now - window._lastCatalogLog > 3000) {
                window._lastCatalogLog = now;
                console.log(`📦 Catalog version updated to: ${productsCatalogVersion}`);
            }
            products = data;
            try {
                if (typeof __largeCache !== 'undefined' && __largeCache && Object.prototype.hasOwnProperty.call(__largeCache, 'products')) {
                    delete __largeCache.products;
                }
            } catch (_) {}
            try {
                const bkKey = uid ? `pos_${uid}_products_autobackup` : 'products_autobackup';
                if (!window._productsBackupTimer) {
                    window._productsBackupTimer = setTimeout(function() {
                        window._productsBackupTimer = null;
                        idbSet(bkKey, Array.isArray(data) ? data : []).catch(function() {});
                    }, 400);
                }
            } catch (_) {}
        }
        const isLargeKey = Array.isArray(window.LARGE_STORAGE_KEYS) && window.LARGE_STORAGE_KEYS.includes(key);
        if (isLargeKey) {
            assignLargeKeyInMemory(key, data);
            // حفظ في IDB وإزالة النسخة الثقيلة من localStorage
            idbSet(storageKey, data).then(() => {
                try { localStorage.removeItem(storageKey); } catch(_) {}
                try { localStorage.setItem(`${storageKey}.meta`, 'idb'); } catch(_) {}
            }).catch(e => console.warn('idbSet async error:', e));
            return true;
        }
        // ضغط تلقائي للقيم الكبيرة في localStorage لتقليل الحجم
        const json = JSON.stringify(data);
        const MIN_COMPRESS = 4096; // 4KB
        // توفّر LZString صغير مدمج أدناه
        if (typeof LZString !== 'undefined' && json.length >= MIN_COMPRESS) {
            try {
                const compressed = LZString.compressToBase64(json);
                localStorage.setItem(storageKey, `__lz__:${compressed}`);
                localStorage.setItem(`${storageKey}.meta`, 'lz');
            } catch (e) {
                console.warn('lz compress failed, falling back to plain json', e);
                localStorage.setItem(storageKey, json);
                try { localStorage.removeItem(`${storageKey}.meta`); } catch(_) {}
            }
        } else {
            localStorage.setItem(storageKey, json);
            try { localStorage.removeItem(`${storageKey}.meta`); } catch(_) {}
        }
        return true;
    } catch (error) {
        console.error('Error saving data:', error);
        // Auto-handle storage quota being full
        try {
            if (error && (error.name === 'QuotaExceededError' || error.code === 22 || error.code === 1014)) {
                console.warn('⚠️ Storage quota exceeded — starting data compaction...');
                const compactOnce = () => {
                    // Remove non-critical keys
                    const optionalKeys = [
                        'sales_backup','productsLastUpdated','productsCatalogVersion',
                        'ui.scale','inventoryPaginationState','productsPaginationState','salesPaginationState',
                        'profit.pageSize','capital.pageSize','lastCartFocusIndex'
                    ];
                    optionalKeys.forEach(k => { try { localStorage.removeItem(k); } catch(_) {} });
                    
                    // Compact cash drawer transactions
                    try {
                        const cd = loadFromStorage('cashDrawer', null);
                        if (cd && Array.isArray(cd.transactions) && cd.transactions.length > 500) {
                            cd.transactions = cd.transactions.slice(-500);
                            saveToStorage('cashDrawer', cd);
                        }
                    } catch(_) {}
                    
                    // Compact stock movements
                    try {
                        const sm = loadFromStorage('stockMovements', []);
                        if (Array.isArray(sm) && sm.length > 1000) {
                            saveToStorage('stockMovements', sm.slice(-1000));
                        }
                    } catch(_) {}
                    
                    // Compact sales logs
                    try {
                        const sl = loadFromStorage('salesLogs', []);
                        if (Array.isArray(sl) && sl.length > 2000) {
                            saveToStorage('salesLogs', sl.slice(-2000));
                        }
                    } catch(_) {}
                    
                    // Compact customer logs
                    try {
                        const cl = loadFromStorage('customerLogs', {});
                        if (cl && typeof cl === 'object') {
                            Object.keys(cl).forEach(k => {
                                const arr = cl[k];
                                if (Array.isArray(arr) && arr.length > 300) {
                                    cl[k] = arr.slice(-300);
                                }
                            });
                            saveToStorage('customerLogs', cl);
                        }
                    } catch(_) {}
                };
                
                const compactAggressive = () => {
                    try {
                        const cd = loadFromStorage('cashDrawer', null);
                        if (cd && Array.isArray(cd.transactions) && cd.transactions.length > 200) {
                            cd.transactions = cd.transactions.slice(-200);
                            saveToStorage('cashDrawer', cd);
                        }
                    } catch(_) {}
                    try {
                        const sm = loadFromStorage('stockMovements', []);
                        if (Array.isArray(sm) && sm.length > 400) {
                            saveToStorage('stockMovements', sm.slice(-400));
                        }
                    } catch(_) {}
                    try {
                        const sl = loadFromStorage('salesLogs', []);
                        if (Array.isArray(sl) && sl.length > 500) {
                            saveToStorage('salesLogs', sl.slice(-500));
                        }
                    } catch(_) {}
                };
                
                // Attempt 1: standard compaction
                compactOnce();
                try {
                    localStorage.setItem(storageKey, JSON.stringify(data));
                    console.warn('✅ Saved after data compaction (phase 1).');
                    return true;
                } catch (e2) {
                    console.warn('Phase 1 was not enough; applying additional compaction...', e2);
                }
                
                // Attempt 2: more aggressive compaction
                compactAggressive();
                try {
                    localStorage.setItem(storageKey, JSON.stringify(data));
                    console.warn('✅ Saved after data compaction (phase 2).');
                    return true;
                } catch (e3) {
                    console.error('❌ Save failed after compaction attempts:', e3);
                    try { showMessage(getText('msg-storage-full'), 'error'); } catch(_) {}
                    return false;
                }
            }
        } catch(_) {}
        return false;
    }
}

// Minimal LZString-compatible shim: keeps API but doesn't truly compress (avoid compatibility issues)
var LZString = {
    compressToBase64: function (str) {
        try { return btoa(unescape(encodeURIComponent(str))); } catch (e) { 
            console.warn('LZString compress error:', e);
            return str; 
        }
    },
    decompressFromBase64: function (b64) {
        try { 
            if (!b64 || b64.length === 0) {
                console.warn('LZString: Empty base64 string');
                return null;
            }
            const decoded = decodeURIComponent(escape(atob(b64)));
            if (!decoded || decoded.length === 0) {
                console.warn('LZString: Empty decoded string');
                return null;
            }
            return decoded;
        } catch (e) { 
            console.warn('LZString decompress error:', e, 'for base64:', b64.substring(0, 50) + '...');
            return null; 
        }
    }
};

// وظيفة لتنظيف البيانات التالفة في localStorage
function cleanupCorruptedStorage() {
    const keysToCheck = ['products', 'customers', 'sales', 'suppliers', 'purchases'];
    let cleanedCount = 0;
    
    keysToCheck.forEach(key => {
        try {
            const data = localStorage.getItem(key);
            if (data) {
                // محاولة تحليل البيانات للتحقق من صحتها
                try {
                    if (data.startsWith('__lz__:')) {
                        // محاولة فك الضغط
                        if (typeof LZString !== 'undefined') {
                            const json = LZString.decompressFromBase64(data.slice(7));
                            if (json) {
                                JSON.parse(json); // التحقق من صحة JSON
                            } else {
                                throw new Error('Failed to decompress');
                            }
                        } else {
                            throw new Error('LZString not available');
                        }
                    } else {
                        JSON.parse(data); // التحقق من صحة JSON العادي
                    }
                } catch (parseError) {
                    console.warn(`⚠️ Found corrupted data for key "${key}", cleaning up...`, parseError);
                    try {
                        localStorage.removeItem(key);
                        cleanedCount++;
                        console.log(`✅ Cleaned corrupted data for key: ${key}`);
                    } catch (removeError) {
                        console.error(`❌ Failed to remove corrupted data for key ${key}:`, removeError);
                    }
                }
            }
        } catch (error) {
            console.error(`Error checking key "${key}":`, error);
        }
    });
    
    if (cleanedCount > 0) {
        console.log(`🧹 Cleaned ${cleanedCount} corrupted storage key(s)`);
        console.log('⚠️ Some corrupted data was found and cleaned. Please refresh the page.');
    }
    
    return cleanedCount;
}

// Clean corrupted storage on page load
if (typeof window !== 'undefined' && window.addEventListener) {
    window.addEventListener('DOMContentLoaded', function() {
        setTimeout(cleanupCorruptedStorage, 100);
    });
    
    // أيضاً تنظيف عند تحميل الصفحة مباشرة (إذا كانت DOMContentLoaded قد حدثت بالفعل)
    if (document.readyState === 'complete' || document.readyState === 'interactive') {
        setTimeout(cleanupCorruptedStorage, 100);
    }
}
