// ===== تخزين دائم عبر IndexedDB لحل مشكلة امتلاء localStorage =====
let __posDbPromise = null;
// تعريف المفاتيح الكبيرة بشكل آمن ومبكر
// ملاحظة: cashDrawer مستبعد من LARGE_STORAGE_KEYS لضمان حفظ/تحميل متزامن من localStorage
// (الحفظ في IDB غير متزامن ويسبب فقدان القيم عند تحديث الصفحة)
window.LARGE_STORAGE_KEYS = window.LARGE_STORAGE_KEYS || ['sales', 'salesLogs', 'stockMovements'];
const LARGE_STORAGE_KEYS = window.LARGE_STORAGE_KEYS;
const __largeCache = {};

// ===== SQLite (sql.js) KV store للعمل أوفلاين بالكامل =====
let __sqlInitPromise = null;
window.sqliteDb = window.sqliteDb || null;
window.sqliteReady = false;

function initSqlite() {
    if (__sqlInitPromise) return __sqlInitPromise;
    __sqlInitPromise = (async () => {
        try {
            if (typeof initSqlJs !== 'function') {
                console.warn('sql.js not loaded yet.');
                return null;
            }
            var sqlBase = (typeof window !== 'undefined' && window.__sqlJsBase) || '/vendor/sqljs';
            const SQL = await initSqlJs({
                locateFile: file => (sqlBase.endsWith('/') ? sqlBase : sqlBase + '/') + file
            });
            // تحميل بايتات قاعدة البيانات من IndexedDB إن وجدت
            let bytes = await idbGet('__sqlite_bytes__');
            if (bytes && !(bytes instanceof Uint8Array)) {
                try { bytes = new Uint8Array(bytes); } catch(_) {}
            }
            const db = bytes ? new SQL.Database(bytes) : new SQL.Database();
            db.run('CREATE TABLE IF NOT EXISTS kv (key TEXT PRIMARY KEY, value TEXT)');
            window.sqliteDb = db;
            window.sqliteReady = true;
            // هجرة أولية من localStorage (لا تؤثر إذا كانت المفاتيح موجودة مسبقاً)
            try { migrateLocalStorageToSqlite(); } catch(_) {}
            return db;
        } catch (e) {
            console.warn('SQLite init failed:', e);
            return null;
        }
    })();
    return __sqlInitPromise;
}

async function persistSqlite() {
    try {
        if (!window.sqliteDb) return false;
        const data = window.sqliteDb.export();
        await idbSet('__sqlite_bytes__', data);
        return true;
    } catch (e) {
        console.warn('persistSqlite error:', e);
        return false;
    }
}

function sqliteKVGetSync(key) {
    try {
        const db = window.sqliteDb;
        if (!db) return undefined;
        const stmt = db.prepare('SELECT value FROM kv WHERE key = ?');
        stmt.bind([key]);
        let out;
        if (stmt.step()) {
            const row = stmt.getAsObject();
            out = row && row.value;
        }
        stmt.free();
        if (out == null) return undefined;
        try { return JSON.parse(out); } catch { return undefined; }
    } catch (_) {
        return undefined;
    }
}

function sqliteKVSetSync(key, value) {
    try {
        const db = window.sqliteDb;
        if (!db) return false;
        const json = JSON.stringify(value);
        const stmt = db.prepare('INSERT INTO kv(key,value) VALUES (?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value');
        stmt.bind([key, json]);
        stmt.step();
        stmt.free();
        // حفظ إلى IndexedDB لضمان الاستمرارية
        persistSqlite();
        return true;
    } catch (e) {
        console.warn('sqliteKVSetSync error:', e);
        return false;
    }
}

function sqliteKVDeleteSync(key) {
    try {
        const db = window.sqliteDb;
        if (!db) return false;
        const stmt = db.prepare('DELETE FROM kv WHERE key = ?');
        stmt.bind([key]);
        stmt.step();
        stmt.free();
        persistSqlite();
        return true;
    } catch (e) {
        console.warn('sqliteKVDeleteSync error:', e);
        return false;
    }
}

function migrateLocalStorageToSqlite() {
    try {
        if (!window.sqliteDb) return;
        for (let i = 0; i < localStorage.length; i++) {
            const k = localStorage.key(i);
            if (!k) continue;
            try {
                const v = localStorage.getItem(k);
                if (v == null) continue;
                let parsed;
                try { 
                    if (typeof v === 'string' && v.startsWith('__lz__:') && typeof LZString !== 'undefined') {
                        const json = LZString.decompressFromBase64(v.slice(7));
                        parsed = json ? JSON.parse(json) : undefined;
                    } else {
                        parsed = JSON.parse(v);
                    }
                } catch { parsed = v; }
                sqliteKVSetSync(k, parsed);
            } catch(_) {}
        }
        // هجرة مفاتيح IDB الكبيرة إن وُجدت في الكاش بالذاكرة
        try {
            for (const key of (window.LARGE_STORAGE_KEYS || [])) {
                if (__largeCache.hasOwnProperty(key)) {
                    sqliteKVSetSync(key, __largeCache[key]);
                }
            }
        } catch(_) {}
        persistSqlite();
        console.log('✅ SQLite migration completed.');
    } catch (e) {
        console.warn('SQLite migration failed:', e);
    }
}

// تهيئة SQLite عند تحميل الصفحة
document.addEventListener('DOMContentLoaded', function() {
    initSqlite();
});

function initIndexedDB() {
    if (__posDbPromise) return __posDbPromise;
    __posDbPromise = new Promise((resolve, reject) => {
        try {
            const req = indexedDB.open('catch_pos_db', 1);
            req.onupgradeneeded = function() {
                const db = req.result;
                if (!db.objectStoreNames.contains('kv')) {
                    db.createObjectStore('kv');
                }
            };
            req.onsuccess = () => resolve(req.result);
            req.onerror = () => reject(req.error);
        } catch (e) {
            console.warn('IndexedDB init failed, fallback to localStorage only:', e);
            resolve(null);
        }
    });
    return __posDbPromise;
}

async function idbSet(key, value) {
    try {
        const db = await initIndexedDB();
        if (!db) return false;
        return await new Promise((resolve, reject) => {
            const tx = db.transaction('kv', 'readwrite');
            tx.objectStore('kv').put(value, key);
            tx.oncomplete = () => resolve(true);
            tx.onerror = () => reject(tx.error);
        });
    } catch (e) {
        console.warn('idbSet error:', e);
        return false;
    }
}

async function idbGet(key) {
    try {
        const db = await initIndexedDB();
        if (!db) return undefined;
        return await new Promise((resolve, reject) => {
            const tx = db.transaction('kv', 'readonly');
            const req = tx.objectStore('kv').get(key);
            req.onsuccess = () => resolve(req.result);
            req.onerror = () => reject(req.error);
        });
    } catch (e) {
        console.warn('idbGet error:', e);
        return undefined;
    }
}

async function idbDelete(key) {
    try {
        const db = await initIndexedDB();
        if (!db) return false;
        return await new Promise((resolve, reject) => {
            const tx = db.transaction('kv', 'readwrite');
            const req = tx.objectStore('kv').delete(key);
            tx.oncomplete = () => resolve(true);
            tx.onerror = () => reject(tx.error);
        });
    } catch (e) {
        console.warn('idbDelete error:', e);
        return false;
    }
}

function assignLargeKeyInMemory(key, data) {
    if (data == null) return;
    __largeCache[key] = data;
    try {
        switch (key) {
            case 'sales':
                sales = Array.isArray(data) ? data : [];
                break;
            case 'salesLogs':
                // لا تستخدم مباشرة في كل مكان، يكفي الكاش
                break;
            case 'stockMovements':
                // لا شيء مطلوب الآن
                break;
            case 'cashDrawer':
                cashDrawer = (data && typeof data === 'object') ? data : cashDrawer;
                break;
        }
    } catch (_) {}
}

async function migrateLargeKeysToIDB() {
    try {
        await initIndexedDB();
        for (const key of (window.LARGE_STORAGE_KEYS || [])) {
            try {
                const dataStr = localStorage.getItem(key);
                if (dataStr) {
                    const data = JSON.parse(dataStr);
                    await idbSet(key, data);
                    // اترك فقط ميتا صغيرة للدلالة على أن البيانات موجودة في الـ DB
                    localStorage.removeItem(key);
                    localStorage.setItem(`${key}.meta`, 'idb');
                    assignLargeKeyInMemory(key, data);
                } else {
                    // حاول التحميل من IDB إلى الذاكرة عند عدم وجود نسخة محلية
                    const data = await idbGet(key);
                    if (data) {
                        assignLargeKeyInMemory(key, data);
                        localStorage.setItem(`${key}.meta`, 'idb');
                    }
                }
            } catch (e) {
                console.warn('migrate key failed:', key, e);
            }
        }
        // ترحيل cashDrawer من IDB إلى localStorage (للمستخدمين الذين كانت بياناتهم في IDB سابقاً)
        try {
            const storageKey = getScopedStorageKey && getScopedStorageKey('cashDrawer');
            const keysToTry = storageKey ? [storageKey, 'cashDrawer'] : ['cashDrawer'];
            for (const k of keysToTry) {
                const fromIdb = await idbGet(k);
                if (fromIdb && typeof fromIdb === 'object') {
                    cashDrawer.cashUSD = Number(fromIdb.cashUSD) ?? 0;
                    cashDrawer.cashLBP = Number(fromIdb.cashLBP) ?? 0;
                    cashDrawer.transactions = Array.isArray(fromIdb.transactions) ? fromIdb.transactions : [];
                    cashDrawer.lastUpdate = fromIdb.lastUpdate || new Date().toISOString();
                    if (typeof saveToStorage === 'function') saveToStorage('cashDrawer', cashDrawer);
                    break;
                }
            }
        } catch (_) {}
        // تحميل cashDrawer من التخزين المحلي إذا لم تُحمّل بعد من Firestore (ضمان استمرارية البيانات بعد التحديث)
        if (!window.__dataLoadedForUserId && typeof loadFromStorage === 'function') {
            try {
                const cd = loadFromStorage('cashDrawer', null);
                if (cd && typeof cd === 'object') {
                    cashDrawer.cashUSD = Number(cd.cashUSD) ?? 0;
                    cashDrawer.cashLBP = Number(cd.cashLBP) ?? 0;
                    cashDrawer.transactions = Array.isArray(cd.transactions) ? cd.transactions : [];
                    cashDrawer.lastUpdate = cd.lastUpdate || new Date().toISOString();
                }
            } catch (_) {}
        }
        // تحديث واجهات حرجة بعد التحميل
        try { updateCashDrawerDisplay(); } catch(_) {}
        try { if (document.getElementById('sales')?.classList.contains('active')) loadSales(); } catch(_) {}
    } catch (e) {
        console.warn('migrateLargeKeysToIDB error:', e);
    }
}

// تشغيل التمهيد عند التحميل
document.addEventListener('DOMContentLoaded', function() {
    migrateLargeKeysToIDB();
});

// تم إلغاء طلب التخزين الدائم بناءً على متطلبات العمل (وضع أوفلاين بالكامل)

// ====== (اختياري) طبقة SQLite (sql.js) للتخزين كبنية قاعدة بيانات ======
let __sqlite = null;
let __sqliteReady = false;
const SQL_JS_VERSION = '1.10.2';

function getSqliteOwnerScopeId() {
    try {
        const ownerId = (typeof getEffectiveDataOwnerId === 'function' ? getEffectiveDataOwnerId() : null)
            || (typeof getCurrentUserId === 'function' ? getCurrentUserId() : null);
        if (!ownerId) return null;
        return String(ownerId).trim() || null;
    } catch (_) {
        return null;
    }
}

function loadScript(url) {
    return new Promise((resolve, reject) => {
        const s = document.createElement('script');
        s.src = url;
        s.async = true;
        s.onload = resolve;
        s.onerror = reject;
        document.head.appendChild(s);
    });
}

async function initSqliteBackend() {
    try {
        var sqlBase = (typeof window !== 'undefined' && window.__sqlJsBase) || '/vendor/sqljs';
        if (!window.initSqlJs) {
            var sqlSrc = (sqlBase === '.' || sqlBase === '') ? './sql-wasm.js' : sqlBase + '/sql-wasm.js';
            try {
                await loadScript(sqlSrc);
            } catch (e) {
                if (sqlBase === '.' || sqlBase === '') {
                    sqlBase = 'https://cdnjs.cloudflare.com/ajax/libs/sql.js/1.9.0';
                    await loadScript(sqlBase + '/sql-wasm.js');
                } else { throw e; }
            }
        }
        if (!window.initSqlJs) {
            console.warn('sql.js not available; skipping SQLite backend.');
            return;
        }
        const SQL = await window.initSqlJs({
            locateFile: (file) => (sqlBase.endsWith('/') ? sqlBase : sqlBase + '/') + file
        });
        // محاولة تحميل قاعدة موجودة من IndexedDB
        const existing = await idbGet('sqlite_db');
        __sqlite = existing ? new SQL.Database(existing) : new SQL.Database();
        // إنشاء الجداول الأساسية
        __sqlite.run(`
            CREATE TABLE IF NOT EXISTS sales (
                id TEXT PRIMARY KEY,
                invoiceNumber TEXT,
                timestamp TEXT,
                date TEXT,
                customer TEXT,
                amount REAL,
                paymentMethod TEXT,
                json TEXT,
                ownerId TEXT
            );
            CREATE INDEX IF NOT EXISTS idx_sales_time ON sales(timestamp);
            CREATE TABLE IF NOT EXISTS meta (key TEXT PRIMARY KEY, value TEXT);
        `);
        // Legacy DB upgrade path: old installs may have sales table without ownerId.
        try { __sqlite.run(`ALTER TABLE sales ADD COLUMN ownerId TEXT`); } catch (_) {}
        // Create owner scope index only after ensuring ownerId column exists.
        try { __sqlite.run(`CREATE INDEX IF NOT EXISTS idx_sales_owner_time ON sales(ownerId, timestamp);`); } catch (_) {}
        __sqliteReady = true;
        // ترحيل أولي من IDB إذا لم يُنفّذ سابقاً
        try {
            const ownerScopeId = getSqliteOwnerScopeId();
            const migratedKey = ownerScopeId ? `sqlite.migrated.sales.${ownerScopeId}` : 'sqlite.migrated.sales.anon';
            const migrated = localStorage.getItem(migratedKey);
            if (migrated !== '1') {
                const existingSales = loadFromStorage('sales', []);
                if (Array.isArray(existingSales) && existingSales.length > 0) {
                    // Never import sales into shared sqlite without a resolved owner scope.
                    if (!ownerScopeId) {
                        localStorage.setItem(migratedKey, '1');
                        return;
                    }
                    const stmt = __sqlite.prepare(`INSERT OR REPLACE INTO sales 
                        (id, invoiceNumber, timestamp, date, customer, amount, paymentMethod, json, ownerId) 
                        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?);`);
                    existingSales.forEach(sale => {
                        const rid = String(sale.id || sale.invoiceNumber || cryptoRandomId());
                        const inv = String(sale.invoiceNumber || `INV-${rid}`);
                        const ts = String(sale.timestamp || getLocalDateTimeISO());
                        const d = String(sale.date || (ts.split('T')[0]));
                        const cust = String(sale.customer || sale.customerName || 'عميل عادي');
                        const amt = Number(sale.amount) || 0;
                        const pm = String(sale.paymentMethod || 'نقدي');
                        const json = JSON.stringify(sale.items || []);
                        stmt.run([rid, inv, ts, d, cust, amt, pm, json, ownerScopeId]);
                    });
                    stmt.free();
                    await persistSqliteDb();
                }
                localStorage.setItem(migratedKey, '1');
            }
        } catch (e) { console.warn('SQLite migrate sales error:', e); }
        console.log('SQLite backend ready.');
    } catch (e) {
        console.warn('initSqliteBackend failed:', e);
    }
}

function cryptoRandomId() {
    try {
        const arr = new Uint32Array(3);
        crypto.getRandomValues(arr);
        return Array.from(arr).map(n => n.toString(36)).join('-');
    } catch (_) {
        return String(Date.now()) + '-' + Math.floor(Math.random()*1e9);
    }
}

async function persistSqliteDb() {
    try {
        if (!__sqlite) return;
        const binary = __sqlite.export();
        await idbSet('sqlite_db', binary);
        try { await writeBackupIfConfigured(binary); } catch(_) {}
    } catch (e) {
        console.warn('persistSqliteDb error:', e);
    }
}

function sqliteSaveSale(sale) {
    if (!__sqliteReady || !__sqlite) return;
    try {
        const ownerScopeId = getSqliteOwnerScopeId();
        if (!ownerScopeId) return;
        const rid = String(sale.id || sale.invoiceNumber || cryptoRandomId());
        const inv = String(sale.invoiceNumber || `INV-${rid}`);
        const ts = String(sale.timestamp || getLocalDateTimeISO());
        const d = String(sale.date || (ts.split('T')[0]));
        const cust = String(sale.customer || sale.customerName || 'عميل عادي');
        const amt = Number(sale.amount) || 0;
        const pm = String(sale.paymentMethod || 'نقدي');
        const json = JSON.stringify(sale.items || []);
        const stmt = __sqlite.prepare(`INSERT OR REPLACE INTO sales 
            (id, invoiceNumber, timestamp, date, customer, amount, paymentMethod, json, ownerId) 
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?);`);
        stmt.run([rid, inv, ts, d, cust, amt, pm, json, ownerScopeId]);
        stmt.free();
        // حفظ إلى IDB
        persistSqliteDb();
    } catch (e) {
        console.warn('sqliteSaveSale error:', e);
    }
}

// ===== File System Access backup (يُفضّل اختيار ملف داخل OneDrive) =====
async function backupPickDestination() {
    if (!('showSaveFilePicker' in window)) {
        showMessage(getText('msg-browser-no-save'), 'error');
        return null;
    }
    try {
        const handle = await window.showSaveFilePicker({
            suggestedName: 'catch_pos.sqlite',
            types: [{ description: 'SQLite DB', accept: { 'application/octet-stream': ['.sqlite'] } }]
        });
        await idbSet('backupHandle', handle);
        showMessage(getText('msg-backup-file-chosen'), 'success');
        return handle;
    } catch (_) { return null; }
}

async function writeBackupIfConfigured(optionalBytes) {
    try {
        const handle = await idbGet('backupHandle');
        if (!handle) return false;
        const bytes = optionalBytes || await idbGet('sqlite_db');
        if (!bytes) return false;
        const writable = await handle.createWritable();
        await writable.write(new Blob([bytes], { type: 'application/octet-stream' }));
        await writable.close();
        return true;
    } catch (e) {
        console.warn('writeBackupIfConfigured error:', e);
        return false;
    }
}

// واجهة عامة للاستخدام من الإعدادات/الكونسول
window.backupPickDestination = backupPickDestination;
window.backupSaveNow = () => writeBackupIfConfigured();

function loadSalesFromSqlite(limit = null) {
    if (!__sqliteReady || !__sqlite) return null;
    try {
        const ownerScopeId = getSqliteOwnerScopeId();
        if (!ownerScopeId) return [];
        const q = limit 
            ? `SELECT * FROM sales WHERE ownerId = ? ORDER BY timestamp DESC LIMIT ${Number(limit)}`
            : `SELECT * FROM sales WHERE ownerId = ? ORDER BY timestamp DESC`;
        const stmt = __sqlite.prepare(q);
        stmt.bind([ownerScopeId]);
        const rows = [];
        while (stmt.step()) {
            const o = stmt.getAsObject();
            try { o.items = JSON.parse(o.json || '[]'); } catch(_) { o.items = []; }
            delete o.json;
            rows.push(o);
        }
        stmt.free();
        return rows;
    } catch (e) {
        console.warn('loadSalesFromSqlite error:', e);
        return [];
    }
}

// بدء محرك SQLite بعد الإقلاع
document.addEventListener('DOMContentLoaded', function() {
    initSqliteBackend();
});

// تم إلغاء دعم Supabase نهائياً للعمل أوفلاين بالكامل
function cloudEnabled() { return false; }
async function cloudSaveSale() { return false; }
async function cloudLoadSales() { return []; }

/** وضع المزامنة الأوفلاين: لا نستدعي Firestore لأرقام الفواتير — كل شيء يُحفظ محلياً ثم يُزامن عبر الطابور */
function isPosOfflineSyncMode() {
    try {
        if (typeof navigator !== 'undefined' && navigator.onLine === false) return true;
        if (typeof window !== 'undefined' && window.__posNetOffline === true) return true;
    } catch (_) {}
    return false;
}

/**
 * رقم بيع محلي متزايد (IndexedDB) لتفادي تكرار/تعارض id عند عدة مبيعات أوفلاين أو فشل السيرفر.
 */
async function allocateMonotonicLocalSaleId(salesArr) {
    const uid = typeof getCurrentUserId === 'function' ? getCurrentUserId() : null;
    const key = uid ? `pos_${uid}_offlineSaleIdCounter` : 'offlineSaleIdCounter';
    let maxFromSales = 0;
    try {
        (Array.isArray(salesArr) ? salesArr : []).forEach((s) => {
            if (!s || s.id == null) return;
            const n = Number(s.id);
            if (!isNaN(n) && n > maxFromSales) maxFromSales = n;
        });
    } catch (_) {}
    let stored = 0;
    try {
        const v = await idbGet(key);
        stored = typeof v === 'number' && !isNaN(v) ? v : (parseInt(v, 10) || 0);
    } catch (_) {}
    const next = Math.max(maxFromSales, stored) + 1;
    try {
        await idbSet(key, next);
    } catch (_) {}
    return next;
}

async function updateOfflineSyncStatusUI() {
    const el = document.getElementById('offlineSyncBadge');
    if (!el) return;
    try { if (typeof navigator !== 'undefined' && navigator.onLine === true) { window.__posNetOffline = false; } } catch (_) {}
    const isEn = (document.documentElement.lang || 'ar') === 'en';
    const uid = typeof getEffectiveDataOwnerId === 'function' ? getEffectiveDataOwnerId() : (typeof getCurrentUserId === 'function' ? getCurrentUserId() : null);
    if (!uid) {
        el.hidden = true;
        el.className = 'status-dot offline';
        el.textContent = '';
        return;
    }
    const off = isPosOfflineSyncMode();
    let pending = 0;
    try {
        const q = (await idbGet(_syncQueueKey())) || [];
        pending = Array.isArray(q) ? q.length : 0;
    } catch (_) {}
    const syncing = (typeof _syncFlushInFlight !== 'undefined') ? !!_syncFlushInFlight : false;
    const lastErrAt = (typeof _syncLastErrorAt !== 'undefined') ? Number(_syncLastErrorAt || 0) : 0;
    const recentErr = lastErrAt > 0 && (Date.now() - lastErrAt) < 180000;
    const lastOkAt = (typeof _syncLastSuccessAt !== 'undefined') ? Number(_syncLastSuccessAt || 0) : 0;

    const isSynced = !off && !_syncPermissionPaused && pending === 0 && !recentErr;
    el.hidden = false;
    el.textContent = '';

    if (isSynced) {
        el.className = 'status-dot online';
        const syncTime = lastOkAt
            ? new Date(lastOkAt).toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' })
            : '';
        const baseTip = isEn ? 'Online / Synced' : 'متصل / متزامن';
        el.title = syncing
            ? (isEn ? 'Online / Syncing…' : 'متصل / جاري المزامنة…')
            : (syncTime
                ? (isEn ? `${baseTip} · Last sync ${syncTime}` : `${baseTip} · آخر مزامنة ${syncTime}`)
                : baseTip);
        el.setAttribute('aria-label', el.title);
    } else {
        el.className = 'status-dot offline';
        let detail = isEn ? 'Offline / Not synced' : 'غير متصل / غير متزامن';
        if (off) {
            detail = isEn
                ? 'Offline / Not synced — changes saved locally'
                : 'غير متصل / غير متزامن — التغييرات محفوظة محلياً';
        } else if (_syncPermissionPaused) {
            detail = isEn ? 'Offline / Not synced — sync paused' : 'غير متصل / غير متزامن — المزامنة متوقفة';
        } else if (pending > 0) {
            detail = isEn
                ? `Offline / Not synced — ${pending} pending`
                : `غير متصل / غير متزامن — ${pending} معلّق`;
        } else if (recentErr) {
            const msg = (typeof _syncLastErrorMsg !== 'undefined' ? String(_syncLastErrorMsg || '') : '').trim();
            detail = isEn
                ? (`Offline / Not synced${msg ? ': ' + msg : ''}`)
                : (`غير متصل / غير متزامن${msg ? ': ' + msg : ''}`);
        }
        el.title = detail;
        el.setAttribute('aria-label', detail);
    }
}

let __usageStatsTimer = null;

function estimateCurrentStoreUsageBytes() {
    let total = 0;
    try {
        // localStorage footprint (UTF-16 approximation)
        for (let i = 0; i < localStorage.length; i += 1) {
            const k = localStorage.key(i) || '';
            const v = localStorage.getItem(k) || '';
            total += (k.length + v.length) * 2;
        }
    } catch (_) {}
    try {
        // Main in-memory datasets (JSON payload approximation)
        const payload = {
            products: Array.isArray(products) ? products : [],
            customers: Array.isArray(customers) ? customers : [],
            suppliers: Array.isArray(suppliers) ? suppliers : [],
            sales: Array.isArray(sales) ? sales : [],
            purchases: Array.isArray(purchases) ? purchases : [],
            expenses: Array.isArray(expenses) ? expenses : [],
            settings: (typeof settings === 'object' && settings) ? settings : {}
        };
        total += JSON.stringify(payload).length * 2;
    } catch (_) {}
    return Math.max(0, Math.floor(total));
}

async function publishCurrentStoreUsageStats() {
    try {
        const db = window.firebaseDbInstance;
        if (!db || typeof db.upsertUsageStats !== 'function') return;
        const ownerId = (typeof getEffectiveDataOwnerId === 'function')
            ? getEffectiveDataOwnerId()
            : ((typeof currentUser !== 'undefined' && currentUser && currentUser.uid) ? currentUser.uid : null);
        if (!ownerId) return;
        const bytes = estimateCurrentStoreUsageBytes();
        await db.upsertUsageStats(ownerId, { bytes });
    } catch (error) {
        // Best-effort telemetry only.
        console.warn('publishCurrentStoreUsageStats skipped:', error && (error.message || error.code || error));
    }
}

function startUsageStatsHeartbeat() {
    if (__usageStatsTimer) clearInterval(__usageStatsTimer);
    // Publish once immediately and then periodically.
    publishCurrentStoreUsageStats();
    __usageStatsTimer = setInterval(() => {
        publishCurrentStoreUsageStats();
    }, 3 * 60 * 1000);
}

// حفظ آمن وموحّد لأي عملية بيع (نقدي/جزئي/دين/مرتجع)
async function secureSaveSale(sale, opts = {}) {
    try {
        const options = opts || {};
        const idempotencyKey = options && options.idempotencyKey ? String(options.idempotencyKey) : null;
        const uid = getEffectiveDataOwnerId ? getEffectiveDataOwnerId() : ((typeof currentUser !== 'undefined' && currentUser && currentUser.uid) ? currentUser.uid : null);
        const idempotencyStorageKey = idempotencyKey ? `pos.idempotency.sales.${uid || 'anon'}` : null;
        let idempotencyRecord = null;
        let alreadyProcessed = false;
        // Stable transaction ID for idempotent sync retries.
        if (idempotencyKey && sale && !sale.txId) sale.txId = idempotencyKey;

        // Idempotency: if this exact payment attempt was already saved, reuse ids and skip re-enqueue.
        if (idempotencyKey && idempotencyStorageKey) {
            try {
                const raw = localStorage.getItem(idempotencyStorageKey);
                const map = raw ? JSON.parse(raw) : {};
                idempotencyRecord = map && map[idempotencyKey] ? map[idempotencyKey] : null;
                if (idempotencyRecord && (idempotencyRecord.saleId != null)) {
                    alreadyProcessed = true;
                    sale.id = idempotencyRecord.saleId;
                    if (idempotencyRecord.invoiceNumber) sale.invoiceNumber = idempotencyRecord.invoiceNumber;
                }
            } catch (_) {}
        }
        // تأكيد وجود مصفوفة المبيعات (عزل: استخدام مصدر البيانات الصحيح للمستخدم الحالي)
        if (!Array.isArray(sales)) sales = getCurrentSales() || [];
        // F2: رقم فاتورة — أونلاين: Firestore transaction | أوفلاين/فشل: رقم محلي متزايد + طابور مزامنة
        if (!sale.id || !sale.invoiceNumber) {
            const uid = getEffectiveDataOwnerId ? getEffectiveDataOwnerId() : ((typeof currentUser !== 'undefined' && currentUser && currentUser.uid) ? currentUser.uid : null);
            const inv = String(sale.invoiceNumber || '');
            const pm = String(sale.paymentMethod || '').toLowerCase();
            let prefix = 'INV';
            if (inv.startsWith('RF') || pm === 'refund') prefix = 'RF';
            else if (inv.startsWith('CR') || pm === 'credit') prefix = 'CR';

            let gotServerIds = false;
            if (!isPosOfflineSyncMode() && !window.__firestoreRestricted && uid && window.firebaseDbInstance && typeof window.firebaseDbInstance.getNextSaleId === 'function') {
                try {
                    const next = await window.firebaseDbInstance.getNextSaleId(uid, prefix);
                    sale.id = next.id;
                    sale.invoiceNumber = next.invoiceNumber;
                    gotServerIds = true;
                } catch (e) {
                    console.warn('getNextSaleId failed, using local fallback', e);
                }
            }
            if (!gotServerIds) {
                if (!sale.id) {
                    sale.id = await allocateMonotonicLocalSaleId(sales);
                }
                if (!sale.invoiceNumber) {
                    sale.invoiceNumber = `${prefix}-${String(sale.id).padStart(3, '0')}`;
                }
            }
            if (isPosOfflineSyncMode()) {
                try {
                    sale.offlineCreated = true;
                    sale.clientSeqTs = Date.now();
                } catch (_) {}
            }
        }
        // ضمان التاريخ والوقت المحليين
        const ts = sale.timestamp && String(sale.timestamp).includes('T') ? sale.timestamp : getLocalDateTimeISO();
        sale.timestamp = ts;
        if (!sale.date) {
            const dateOnly = ts.split('T')[0];
            sale.date = dateOnly;
        }
        // توحيد العميل وطريقة الدفع
        sale.customer = sale.customer || sale.customerName || (getText && getText('regular-customer')) || 'عميل عادي';
        sale.paymentMethod = sale.paymentMethod || 'نقدي';
        sale.parentAdminId = sale.parentAdminId || uid || null;
        sale.soldByUserId = sale.soldByUserId || (typeof getCurrentUserId === 'function' ? getCurrentUserId() : null);
        if (!sale.soldByUserId && typeof currentUser !== 'undefined' && currentUser && currentUser.uid) sale.soldByUserId = currentUser.uid;
        // ضمان بنود الفاتورة
        if (!Array.isArray(sale.items)) sale.items = [];
        // ضمان المبلغ
        sale.amount = Number(sale.amount) || 0;
        const existingIdx = Array.isArray(sales)
            ? sales.findIndex(s => s && sale && String(s.id) === String(sale.id))
            : -1;

        // If already processed and the sale exists locally, return immediately.
        if (alreadyProcessed && existingIdx >= 0) return sales[existingIdx];

        // دفع إلى المصفوفة (بدون تكرار نفس sale.id)
        if (existingIdx >= 0) {
            sales[existingIdx] = { ...sales[existingIdx], ...sale, id: sale.id };
        } else {
            sales.push(sale);
        }
        // حفظ إلى التخزين
        saveToStorage('sales', sales);

        // Store idempotency record after we've successfully persisted the sale locally.
        if (!alreadyProcessed && idempotencyKey && idempotencyStorageKey) {
            try {
                const raw = localStorage.getItem(idempotencyStorageKey);
                const map = raw ? JSON.parse(raw) : {};
                map[idempotencyKey] = { saleId: sale.id, invoiceNumber: sale.invoiceNumber, createdAt: Date.now() };
                localStorage.setItem(idempotencyStorageKey, JSON.stringify(map));
            } catch (_) {}
        }

        // حفظ نسخة احتياطية خفيفة (آخر 100 فقط)
        if (!alreadyProcessed) try { 
            const backup = loadFromStorage('sales_backup', []);
            const slim = { id: sale.id, invoiceNumber: sale.invoiceNumber, timestamp: sale.timestamp, amount: sale.amount };
            const next = Array.isArray(backup) ? [...backup, slim].slice(-100) : [slim];
            localStorage.setItem('sales_backup', JSON.stringify(next)); 
        } catch(_) {}
        // تسجيل في سجل المبيعات العام
        if (!alreadyProcessed) try {
            const salesLogs = loadFromStorage('salesLogs', []);
            salesLogs.push({
                timestamp: sale.timestamp,
                invoiceNumber: sale.invoiceNumber,
                amount: sale.amount,
                currency: 'USD',
                method: sale.paymentMethod,
                customer: sale.customer || '-',
                user: currentUser || 'المستخدم'
            });
            saveToStorage('salesLogs', salesLogs);
        } catch(_) {}
        // حفظ أيضاً في SQLite إن كانت جاهزة
        if (!alreadyProcessed) try { if (__sqliteReady && __sqlite) sqliteSaveSale(sale); } catch(_) {}
        // حفظ إلى السحابة إن مفعّل
        if (!alreadyProcessed) try { if (cloudEnabled()) cloudSaveSale(sale); } catch(_) {}
        // V2 Firestore sync (incremental): queue this sale doc
        if (!alreadyProcessed) try {
            await enqueueSyncOp('sales', 'upsert', sale.id, { ...sale, id: sale.id });
        } catch(_) {}
        return sale;
    } catch (e) {
        console.error('secureSaveSale error:', e, sale);
        // محاولة إنقاذ: حفظ الحد الأدنى في التخزين المباشر
        try {
            const minimal = sales || [];
            minimal.push(sale);
            localStorage.setItem('sales', JSON.stringify(minimal));
        } catch(_) {}
        return sale;
    }
}

// helper: الحصول على أحدث بيانات المبيعات من التخزين بشكل آمن
function getCurrentSales() {
    try {
        // عزل المستخدم: إذا تم تحميل البيانات لهذا المستخدم، نفضّل النسخة في الذاكرة،
        // لكن لا نجبر تحميل كل المبيعات إذا كانت ضخمة (نستخدم SQLite/Local fallback للأداء).
        if (typeof window !== 'undefined' && window.__dataLoadedForUserId) {
            if (Array.isArray(sales) && sales.length) return sales;
            // إذا لم تكن المبيعات محمّلة في الذاكرة، استخدم SQLite (إن كانت جاهزة) أو التخزين المحلي
            if (__sqliteReady && __sqlite) {
                const rows = loadSalesFromSqlite(2000);
                if (rows && rows.length) return rows;
            }
            const data = loadFromStorage('sales', []);
            if (Array.isArray(data) && data.length) return data;
            return [];
        }
        // Cloud أولاً إن توفر
        if (cloudEnabled()) {
            // ملاحظة: الاستدعاء غير متزامن، لذا نُعيد آخر نسخة محلية فوراً ونحدّث لاحقاً
            cloudLoadSales().then(rows => {
                if (Array.isArray(rows) && rows.length) {
                    assignLargeKeyInMemory('sales', rows);
                    try { saveToStorage('sales', rows); } catch(_) {}
                    try { if (document.getElementById('sales')?.classList.contains('active')) loadSales(); } catch(_) {}
                }
            });
        }
        // إذا كانت SQLite جاهزة، اجلب مباشرةً منها
        if (__sqliteReady && __sqlite) {
            const rows = loadSalesFromSqlite();
            if (rows && rows.length) return rows;
        }
        const data = loadFromStorage('sales', []);
        if (Array.isArray(data)) return data;
    } catch(_) {}
    // fallback: محاولة إعادة بناء بيانات مبيعات من السجل إن لم تتوفر
    try {
        const logs = loadFromStorage('salesLogs', []);
        if (Array.isArray(logs) && logs.length > 0) {
            const reconstructed = logs
                .filter(l => l && l.invoiceNumber && l.invoiceNumber !== '-' && typeof l.amount !== 'undefined')
                .map((l, idx) => {
                    const ts = l.timestamp || getLocalDateTimeISO();
                    // تحليل تاريخ محلي من timestamp
                    let dateOnly;
                    try {
                        if (typeof ts === 'string' && ts.includes('T')) {
                            dateOnly = ts.split('T')[0];
                        } else {
                            const d = new Date(ts);
                            dateOnly = `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
                        }
                    } catch(_) {
                        const d = new Date();
                        dateOnly = `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
                    }
                    return {
                        id: idx + 1,
                        invoiceNumber: l.invoiceNumber,
                        timestamp: ts,
                        date: dateOnly,
                        customer: l.customer || getText('regular-customer') || 'عميل عادي',
                        customerId: null,
                        amount: Number(l.amount) || 0,
                        paymentMethod: l.method || 'نقدي',
                        items: []
                    };
                });
            if (reconstructed.length > 0) return reconstructed;
        }
    } catch(_) {}
    return Array.isArray(sales) ? sales : [];
}

function loadFromStorage(key, defaultValue = null) {
    try {
        const actualKey = getScopedStorageKey(key);
        if (USER_SPECIFIC_KEYS.includes(key) && !actualKey) return defaultValue; // لا مستخدم - لا نقرأ بيانات مستخدم آخر
        const storageKey = actualKey || key;
        // قراءة من OPFS أولاً إن توفّر (بدون await؛ نُحدّث الخلفيات لاحقاً)
        try {
            if (window.opfsKV && typeof window.opfsKV.get === 'function') {
                window.opfsKV.get(storageKey).then((data) => {
                    if (data === undefined) return;
                    try { assignLargeKeyInMemory && assignLargeKeyInMemory(key, data); } catch(_) {}
                    try { localStorage.setItem(storageKey, JSON.stringify(data)); } catch(_) {}
                    if (key === 'products') {
                        try {
                            refreshProductConsumersAfterAsyncLoad(data);
                        } catch (error) {
                            console.warn('[products async load] OPFS refresh failed:', error);
                        }
                    }
                    try {
                        if (key === 'cashDrawer') updateCashDrawerDisplay();
                        if (key === 'sales' && document.getElementById('sales')?.classList.contains('active')) loadSales();
                    } catch(_) {}
                }).catch(()=>{});
            }
        } catch(_) {}
        // في حال تفعيل SQLite نفضّل القراءة منه أولاً (متزامنة)
        try {
            if (window.sqliteDb) {
                const v = sqliteKVGetSync(storageKey);
                if (v !== undefined) return v;
            }
        } catch(_) {}
        // للمفاتيح الكبيرة: حاول أولاً من الكاش ثم من localStorage كتراث، ثم حمّل من IDB في الخلفية
        const isLargeKey = Array.isArray(window.LARGE_STORAGE_KEYS) && window.LARGE_STORAGE_KEYS.includes(key);
        if (isLargeKey) {
            if (!window.__largeKeyHydrationState) window.__largeKeyHydrationState = {};
            if (__largeCache.hasOwnProperty(key)) {
                window.__largeKeyHydrationState[key] = true;
                return __largeCache[key];
            }
            const legacy = localStorage.getItem(storageKey);
            if (legacy) {
                try {
                    const parsed = legacy.startsWith('__lz__:') && typeof LZString !== 'undefined'
                        ? JSON.parse(LZString.decompressFromBase64(legacy.slice(7)) || 'null')
                        : JSON.parse(legacy);
                    idbSet(storageKey, parsed).then(()=> {
                        assignLargeKeyInMemory(key, parsed);
                        window.__largeKeyHydrationState[key] = true;
                        try { localStorage.removeItem(storageKey); localStorage.setItem(`${storageKey}.meta`, 'idb'); } catch(_) {}
                    });
                    window.__largeKeyHydrationState[key] = true;
                    return parsed ?? defaultValue;
                } catch(_) {}
            }
            // تحميل غير متزامن من IDB وتحديث الذاكرة
            if (typeof window.__largeKeyHydrationState[key] !== 'boolean') {
                window.__largeKeyHydrationState[key] = false;
            }
            idbGet(storageKey).then(data => {
                if (data != null) {
                    assignLargeKeyInMemory(key, data);
                    try { localStorage.setItem(`${storageKey}.meta`, 'idb'); } catch(_) {}
                    if (key === 'products') {
                        try {
                            refreshProductConsumersAfterAsyncLoad(data);
                        } catch (error) {
                            console.warn('[products async load] IDB refresh failed:', error);
                        }
                    }
                    // تحديث الواجهات عند الحاجة
                    try {
                        if (key === 'cashDrawer') updateCashDrawerDisplay();
                        if (key === 'sales' && document.getElementById('sales')?.classList.contains('active')) loadSales();
                    } catch(_) {}
                }
                window.__largeKeyHydrationState[key] = true;
            }).catch(() => {
                window.__largeKeyHydrationState[key] = true;
            });
            return defaultValue;
        }
        const data = localStorage.getItem(storageKey);
        if (!data) return defaultValue;
        try {
            // Check if data is compressed
            if (data.startsWith('__lz__:')) {
                if (typeof LZString !== 'undefined') {
                    try {
                        const json = LZString.decompressFromBase64(data.slice(7));
                        if (json) {
                            return JSON.parse(json);
                        } else {
                            console.warn('Failed to decompress data for key', key, '- returning default value');
                            return defaultValue;
                        }
                    } catch (decompressError) {
                        console.warn('Decompression error for key', key, decompressError);
                        // Try to clear corrupted data
                        try {
                            localStorage.removeItem(storageKey);
                            console.log('Cleared corrupted data for key:', key);
                        } catch (clearError) {
                            console.error('Failed to clear corrupted data:', clearError);
                        }
                        return defaultValue;
                    }
                } else {
                    console.warn('LZString library not available - cannot decompress data for key', key);
                    // Try to clear compressed data if library is missing
                    try {
                        localStorage.removeItem(storageKey);
                        console.log('Cleared compressed data (LZString not available) for key:', key);
                    } catch (clearError) {
                        console.error('Failed to clear compressed data:', clearError);
                    }
                    return defaultValue;
                }
            }
            // Try to parse as regular JSON
            return JSON.parse(data);
        } catch (e) {
            console.warn('parse/decompress error for key', key, e);
            // If parsing fails, try to clear corrupted data
            try {
                const data = localStorage.getItem(storageKey);
                if (data && (data.startsWith('__lz__:') || data.startsWith('{'))) {
                    console.log('Attempting to clear corrupted data for key:', key);
                    localStorage.removeItem(storageKey);
                    console.log('Cleared corrupted data for key:', key);
                }
            } catch (clearError) {
                console.error('Failed to clear corrupted data:', clearError);
            }
            return defaultValue;
        }
    } catch (error) {
        console.error('Error loading data:', error);
        return defaultValue;
    }
}

function isLargeStorageHydrated(key) {
    try {
        const isLargeKey = Array.isArray(window.LARGE_STORAGE_KEYS) && window.LARGE_STORAGE_KEYS.includes(key);
        if (!isLargeKey) return true;
        if (__largeCache && __largeCache.hasOwnProperty(key)) return true;
        if (!window.__largeKeyHydrationState || typeof window.__largeKeyHydrationState[key] !== 'boolean') return false;
        return window.__largeKeyHydrationState[key] === true;
    } catch (_) {
        return false;
    }
}

/** يحوّل حقل سعر (رقم أو نص من JSON/النماذج) إلى رقم. بدون هذا، getProductPrice يتجاهل "7.1" كنص ويسقط لـ priceUSD قديم (مثلاً 7) فيظهر المجموع $21 بدل $22. */
function _numericPriceField(v) {
    if (v == null || v === '') return NaN;
    if (typeof v === 'number') return isFinite(v) ? v : NaN;
    if (typeof v === 'string') {
        const t = String(v).trim().replace(/,/g, '');
        if (t === '') return NaN;
        const n = Number(t);
        return isFinite(n) ? n : NaN;
    }
    return NaN;
}

let __recordIdCounter = 0;
function createRecordId() {
    __recordIdCounter = (__recordIdCounter + 1) % 1000;
    const base = Date.now() * 1000;
    const rand = Math.floor(Math.random() * 1000);
    return base + rand + __recordIdCounter;
}

// دالة للحصول على السعر حسب النوع والعملة — نوع السعر له الأولوية ليتغير السعر عند تغيير القائمة
// ملاحظة مهمة: إذا كان هناك سعر LBP مخزَّن يدوياً، فهو دائماً صاحب الأولوية في مبيعات الليرة.
function getProductPrice(product, priceType = currentPriceType, currency = 'USD') {
    const rate = settings.exchangeRate || 1;
    
    const typePrices = product && product.prices && product.prices[priceType];
    if (typePrices) {
        const usdN = _numericPriceField(typePrices.USD);
        const lbpN = _numericPriceField(typePrices.LBP);
        
        if (currency === 'LBP') {
            if (isFinite(lbpN)) return lbpN;
            if (isFinite(usdN)) return Math.round(usdN * rate);
        } else {
            if (isFinite(usdN)) return usdN;
            if (isFinite(lbpN)) return lbpN / rate;
        }
    }
    
    const fallbackUSD = isFinite(_numericPriceField(product && product.priceUSD))
        ? _numericPriceField(product.priceUSD)
        : 0;
    const fallbackLBP = isFinite(_numericPriceField(product && product.priceLBP))
        ? _numericPriceField(product.priceLBP)
        : Math.round(fallbackUSD * rate);
    
    return currency === 'USD' ? fallbackUSD : fallbackLBP;
}

/** سعر الوحدة بالدولار لسطر السلة: يطابق منطق إتمام الدفع (custom → جاري التحرير → كتالوج). بدون هذا، updateCart يتجاهل _workingPriceUSD فيعيد المجموع خطأ بعد تغيير الكمية أو المزامنة. */
function getCartLineEffectivePriceUSD(item) {
    if (!item || item.type === 'previous_account') return 0;
    const pt = item.selectedPriceType || currentPriceType;
    const baseUSD = typeof getProductPrice === 'function'
        ? getProductPrice(item, pt, 'USD')
        : (_numericPriceField(item && item.priceUSD) || 0);
    const customN = _numericPriceField(item.customPriceUSD);
    if (isFinite(customN)) return customN;
    const workN = _numericPriceField(item._workingPriceUSD);
    if (isFinite(workN)) return workN;
    return Number(baseUSD) || 0;
}

function getCartLineUnitPriceInCurrency(item, currency) {
    if (!item || item.type === 'previous_account') return 0;
    const pt = item.selectedPriceType || currentPriceType;
    const baseUSD = typeof getProductPrice === 'function'
        ? getProductPrice(item, pt, 'USD')
        : (_numericPriceField(item && item.priceUSD) || 0);
    const baseLBP = typeof getProductPrice === 'function'
        ? getProductPrice(item, pt, 'LBP')
        : Math.round(Number(baseUSD) * (settings.exchangeRate || 1));
    const effUSD = getCartLineEffectivePriceUSD(item);
    if (currency === 'USD') return effUSD;
    const rate = settings.exchangeRate || 1;
    const bu = Number(baseUSD);
    const eu = Number(effUSD);
    const bl = Math.round(Number(baseLBP) || 0);
    if (!isFinite(bu) || bu <= 0) {
        if (!isFinite(eu) || eu <= 0) return bl;
        return Math.round(eu * rate);
    }
    if (!isFinite(eu)) return bl;
    if (Math.abs(eu - bu) < 1e-6) return bl;
    return Math.round(bl * (eu / bu));
}

/** كمية سطر العربة كعدد صحيح ≥ 0 — يمنع أخطاء JS مثل "1" + 1 => "11" وسلاسل غير رقمية. */
function posCartLineQuantity(item) {
    if (!item || item.type === 'previous_account') return 0;
    const n = Number(item.quantity);
    if (!isFinite(n) || n < 0) return 0;
    return Math.min(Math.floor(n), 999999);
}

function ensureCartLineUid(item) {
    if (!item || item.type === 'previous_account') return;
    if (item.cartLineUid) return;
    item.cartLineUid = (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function')
        ? crypto.randomUUID()
        : ('cl_' + Date.now() + '_' + Math.random().toString(36).slice(2, 10));
}

/** مجموع POS من الصفر: Σ (سعر الوحدة × الكمية) لكل سطر — مصدر واحد للعرض والدفع. */
function sumPosCartTotalsFromScratch(currency) {
    let subtotal = 0;
    let totalItems = 0;
    const cartArr = Array.isArray(cart) ? cart : [];
    for (let i = 0; i < cartArr.length; i++) {
        const item = cartArr[i];
        if (!item) continue;
        if (item.type === 'previous_account') {
            const priceUSD = Number(item.customPriceUSD ?? item.priceUSD ?? item.price ?? 0) || 0;
            const price = currency === 'USD' ? priceUSD : Math.round(priceUSD * (settings.exchangeRate || 1));
            subtotal += price;
            totalItems += 1;
            continue;
        }
        const lineQty = posCartLineQuantity(item);
        if (lineQty <= 0) continue;
        const unit = getCartLineUnitPriceInCurrency(item, currency);
        subtotal += unit * lineQty;
        totalItems += lineQty;
    }
    const finalTotal = Math.round((subtotal + Number.EPSILON) * 100) / 100;
    return { subtotal, totalItems, finalTotal };
}

function getCartLineLineTotalInCurrency(item, currency) {
    const qty = posCartLineQuantity(item);
    return getCartLineUnitPriceInCurrency(item, currency) * qty;
}

// Update cart products from local storage
function updateCartProductsFromStorage() {
    console.log('🔄 Updating cart products...');
    const updatedProducts = loadFromStorage('products', []);
    let updatedCount = 0;
    
    // Update each item in the cart
    cart.forEach((cartItem, index) => {
        const updatedProduct = updatedProducts.find(p => p.id === cartItem.id);
        if (updatedProduct) {
            // Preserve important fields before update
            const oldPriceUSD = cartItem.priceUSD;
            const oldPrices = cartItem.prices;
            
            // Update core fields
            cartItem.name = updatedProduct.name;
            cartItem.stock = updatedProduct.stock;
            cartItem.prices = updatedProduct.prices;
            cartItem.priceUSD = updatedProduct.priceUSD;
            cartItem.priceLBP = updatedProduct.priceLBP;
            cartItem.barcode = updatedProduct.barcode;
            cartItem.category = updatedProduct.category;
            cartItem.costUSD = updatedProduct.costUSD;
            cartItem.supplier = updatedProduct.supplier;
            cartItem.imageUrl = updatedProduct.imageUrl || null;
            
            // احتفظ بـ customPriceUSD: مزامنة المخزون (مثل فتح كرتون) لا يجب أن تمسح سعر الكاشير اليدوي وإلا يختلف المجموع عن المعروض.
            
            // Log price changes
            if (oldPriceUSD !== updatedProduct.priceUSD) {
                console.log(`💰 Updated price for ${cartItem.name}: $${oldPriceUSD} -> $${updatedProduct.priceUSD}`);
            }
            
            updatedCount++;
            console.log(`✅ Cart item updated: ${cartItem.name}`);
        } else {
            console.log(`⚠️ Updated product not found for cart item: ${cartItem.name} (ID: ${cartItem.id})`);
        }
    });
    
    console.log(`✅ Updated ${updatedCount} out of ${cart.length} cart item(s)`);
}

// Update POS page if it is currently active
