// Convert data URL to Blob for ZIP export
function dataURLtoBlob(dataUrl) {
    const arr = dataUrl.split(',');
    const mimeMatch = arr[0].match(/:(.*?);/);
    const mime = mimeMatch ? mimeMatch[1] : 'image/png';
    const bstr = atob(arr[1]);
    let n = bstr.length;
    const u8arr = new Uint8Array(n);
    while (n--) u8arr[n] = bstr.charCodeAt(n);
    return new Blob([u8arr], { type: mime });
}
function getImageExtensionFromMime(mime) {
    if (!mime) return 'png';
    if (mime.includes('jpeg') || mime.includes('jpg')) return 'jpg';
    if (mime.includes('webp')) return 'webp';
    return 'png';
}

/** تصدير صور المنتجات فقط إلى ZIP (لنقلها بين الأجهزة) */
function exportProductImagesOnly() {
    if (!hasProductPermission('canExportProducts')) {
        showPermissionDeniedMessage('تصدير المنتجات', 'export products');
        return;
    }
    const list = typeof getCurrentProducts === 'function' ? getCurrentProducts() : (Array.isArray(products) ? products : []);
    const withImages = list.filter(p => p.imageUrl && typeof p.imageUrl === 'string' && p.imageUrl.startsWith('data:image'));
    if (withImages.length === 0) {
        showMessage(typeof getText === 'function' ? getText('no-product-images') : 'لا توجد صور لمنتجات لتصديرها.', 'info');
        return;
    }
    if (typeof JSZip === 'undefined') {
        showMessage(typeof getText === 'function' ? getText('msg-import-file-error') : 'ZIP غير متاح.', 'error');
        return;
    }
    const manifest = withImages.map(p => ({ id: p.id, name: (p.name || '').trim() || String(p.id) }));
    const zip = new JSZip();
    zip.file('manifest.json', JSON.stringify({ productIds: manifest, exportDate: new Date().toISOString() }, null, 2));
    const imagesFolder = zip.folder('images');
    withImages.forEach(p => {
        const mimeMatch = p.imageUrl.match(/data:(image\/[^;]+);/);
        const mime = mimeMatch ? mimeMatch[1] : 'image/png';
        const ext = getImageExtensionFromMime(mime);
        const blob = dataURLtoBlob(p.imageUrl);
        imagesFolder.file(String(p.id) + '.' + ext, blob);
    });
    zip.generateAsync({ type: 'blob' }).then(blob => {
        const link = document.createElement('a');
        link.href = URL.createObjectURL(blob);
        link.download = 'product-images-' + new Date().toISOString().split('T')[0] + '.zip';
        link.click();
        setTimeout(() => URL.revokeObjectURL(link.href), 2000);
        showMessage((typeof getText === 'function' ? getText('data-exported') : 'تم التصدير') + ' — ' + withImages.length + ' صورة');
    }).catch(err => {
        console.error('Export product images failed:', err);
        showMessage(typeof getText === 'function' ? getText('msg-import-file-error') : 'فشل التصدير', 'error');
    });
}

/** استيراد صور المنتجات من ZIP وربطها بالمنتجات حسب الـ ID */
async function importProductImagesOnly(event) {
    if (!hasProductPermission('canImportProducts')) {
        showPermissionDeniedMessage('استيراد المنتجات', 'import products');
        event.target.value = '';
        return;
    }
    const file = event.target.files[0];
    event.target.value = '';
    if (!file || !file.name.toLowerCase().endsWith('.zip')) return;
    if (typeof JSZip === 'undefined') {
        showMessage(typeof getText === 'function' ? getText('msg-import-file-error') : 'ZIP غير متاح.', 'error');
        return;
    }
    const list = Array.isArray(products) ? products : [];
    const productById = {};
    list.forEach(p => { if (p.id != null) productById[String(p.id)] = p; });
    try {
        const zip = await JSZip.loadAsync(file);
        const imagesFolder = zip.folder('images');
        if (!imagesFolder) {
            showMessage(typeof getText === 'function' ? getText('msg-import-file-error') : 'ملف ZIP غير صالح (لا يوجد مجلد images).', 'error');
            return;
        }
        let applied = 0;
        const names = Object.keys(zip.files).filter(n => n.startsWith('images/') && !n.endsWith('/'));
        for (const path of names) {
            const name = path.replace(/^images\//, '');
            const idMatch = name.match(/^([^.]+)\.(png|jpg|jpeg|webp)$/i);
            if (!idMatch) continue;
            const productId = idMatch[1];
            const product = productById[productId];
            if (!product) continue;
            const imgFile = zip.file(path);
            if (!imgFile) continue;
            const base64 = await imgFile.async('base64');
            const ext = (idMatch[2] || '').toLowerCase();
            const mime = ext === 'png' ? 'image/png' : ext === 'webp' ? 'image/webp' : 'image/jpeg';
            product.imageUrl = 'data:' + mime + ';base64,' + base64;
            applied++;
        }
        if (applied === 0) {
            showMessage(typeof getText === 'function' ? getText('msg-import-file-error') : 'لم يتم العثور على صور تطابق منتجات حالية. تأكد من أن المنتجات على هذا الجهاز لها نفس الـ ID.', 'warning');
            return;
        }
        saveToStorage('products', products);
        if (typeof displayProducts === 'function') displayProducts();
        if (typeof loadPOS === 'function') try { loadPOS(); } catch(_) {}
        showMessage((typeof getText === 'function' ? getText('data-imported') : 'تم الاستيراد') + ' — ' + applied + ' صورة مرتبطة بالمنتجات');
    } catch (err) {
        console.error('Import product images failed:', err);
        showMessage(typeof getText === 'function' ? getText('msg-import-file-error') : 'فشل استيراد الصور.', 'error');
    }
}

// Export data with optional type filters. selectedTypes is an array like ['products','sales','customers','suppliers','reports','settings','images'].
function exportData(selectedTypes) {
    if (!hasProductPermission('canExportProducts')) {
        showPermissionDeniedMessage('تصدير المنتجات', 'export products');
        return;
    }
    const allTypes = ['products', 'sales', 'customers', 'suppliers', 'reports', 'settings', 'images'];
    const types = Array.isArray(selectedTypes) && selectedTypes.length ? selectedTypes.slice() : allTypes.slice();
    const typeSet = new Set(types);
    const now = new Date();
    const iso = now.toISOString();
    const datePart = iso.split('T')[0];
    
    const baseData = {};
    if (typeSet.has('products') || typeSet.has('images')) {
        baseData.products = products;
    }
    if (typeSet.has('customers')) {
        baseData.customers = customers;
        baseData.customerLogs = loadFromStorage('customerLogs', {});
    }
    if (typeSet.has('sales')) {
        baseData.sales = sales;
        baseData.purchases = typeof purchases !== 'undefined' ? purchases : [];
        baseData.supplierPayments = typeof supplierPayments !== 'undefined' ? supplierPayments : [];
        baseData.purchaseReturns = typeof purchaseReturns !== 'undefined' ? purchaseReturns : [];
        baseData.supplierLedger = typeof supplierLedger !== 'undefined' ? supplierLedger : [];
    }
    if (typeSet.has('suppliers')) {
        baseData.suppliers = suppliers;
        if (!baseData.purchases && typeof purchases !== 'undefined') baseData.purchases = purchases;
        if (!baseData.supplierPayments && typeof supplierPayments !== 'undefined') baseData.supplierPayments = supplierPayments;
        if (!baseData.purchaseReturns && typeof purchaseReturns !== 'undefined') baseData.purchaseReturns = purchaseReturns;
        if (!baseData.supplierLedger && typeof supplierLedger !== 'undefined') baseData.supplierLedger = supplierLedger;
    }
    if (typeSet.has('reports')) {
        baseData.stockMovements = loadFromStorage('stockMovements', []);
        baseData.salesLogs = loadFromStorage('salesLogs', []);
        baseData.cashDrawer = loadFromStorage('cashDrawer', {});
    }
    if (typeSet.has('settings')) {
        baseData.settings = settings;
        baseData.license_state = loadLicenseState();
    }
    baseData.exportDate = iso;

    if (typeof JSZip !== 'undefined') {
        const zip = new JSZip();

        // Products (with optional imageRef mapping)
        if (baseData.products && typeSet.has('products')) {
            const includeImagesRefs = typeSet.has('images');
            const productsForJson = baseData.products.map(p => {
                if (includeImagesRefs && p.imageUrl && typeof p.imageUrl === 'string' && p.imageUrl.startsWith('data:image')) {
                    const mimeMatch = p.imageUrl.match(/data:(image\/[^;]+);/);
                    const mime = mimeMatch ? mimeMatch[1] : 'image/png';
                    const ext = getImageExtensionFromMime(mime);
                    return { ...p, imageRef: `images/${p.id}.${ext}`, imageUrl: null };
                }
                return { ...p, imageUrl: p.imageUrl || null };
            });
            zip.file(`products_${datePart}.json`, JSON.stringify(productsForJson, null, 2));
            baseData.products = productsForJson;
        }

        // Other JSON files per type
        if (baseData.sales) {
            zip.file(`sales_${datePart}.json`, JSON.stringify(baseData.sales, null, 2));
        }
        if (baseData.customers) {
            zip.file(`customers_${datePart}.json`, JSON.stringify(baseData.customers, null, 2));
        }
        if (baseData.suppliers) {
            zip.file(`suppliers_${datePart}.json`, JSON.stringify(baseData.suppliers, null, 2));
        }
        if (baseData.purchases || baseData.supplierPayments || baseData.purchaseReturns || baseData.supplierLedger) {
            const suppliersBundle = {
                purchases: baseData.purchases || [],
                supplierPayments: baseData.supplierPayments || [],
                purchaseReturns: baseData.purchaseReturns || [],
                supplierLedger: baseData.supplierLedger || []
            };
            zip.file(`suppliers_details_${datePart}.json`, JSON.stringify(suppliersBundle, null, 2));
        }
        if (baseData.stockMovements || baseData.salesLogs || baseData.cashDrawer) {
            const reportsBundle = {
                stockMovements: baseData.stockMovements || [],
                salesLogs: baseData.salesLogs || [],
                cashDrawer: baseData.cashDrawer || {}
            };
            zip.file(`reports_${datePart}.json`, JSON.stringify(reportsBundle, null, 2));
        }
        if (baseData.settings || baseData.license_state) {
            const settingsBundle = {
                settings: baseData.settings || {},
                license_state: baseData.license_state || null
            };
            zip.file(`settings_${datePart}.json`, JSON.stringify(settingsBundle, null, 2));
        }
        if (baseData.customerLogs && typeSet.has('customers')) {
            zip.file(`customer_logs_${datePart}.json`, JSON.stringify(baseData.customerLogs, null, 2));
        }

        // Master combined JSON for backward compatibility
        zip.file(`data_${datePart}.json`, JSON.stringify(baseData, null, 2));

        // Images (if requested)
        if (typeSet.has('images') && baseData.products) {
            const imagesFolder = zip.folder('images');
            baseData.products.forEach(p => {
                if (p.imageUrl && typeof p.imageUrl === 'string' && p.imageUrl.startsWith('data:image')) {
                    const blob = dataURLtoBlob(p.imageUrl);
                    const mimeMatch = p.imageUrl.match(/data:(image\/[^;]+);/);
                    const mime = mimeMatch ? mimeMatch[1] : 'image/png';
                    const ext = getImageExtensionFromMime(mime);
                    imagesFolder.file(`${p.id}.${ext}`, blob);
                }
            });
        }

        zip.generateAsync({ type: 'blob' }).then(blob => {
            const link = document.createElement('a');
            link.href = URL.createObjectURL(blob);
            const typesLabel = types.includes('images') && types.length === 1 ? 'images' : (types.join('-') || 'all');
            link.download = `export_${typesLabel}_${datePart}.zip`;
            link.click();
            setTimeout(() => URL.revokeObjectURL(link.href), 2000);
            showMessage(getText('data-exported'));
        }).catch(err => {
            console.error('ZIP export failed:', err);
            exportDataJsonOnly(baseData);
        });
    } else {
        exportDataJsonOnly(baseData);
    }
}
function exportDataJsonOnly(data) {
    const dataStr = JSON.stringify(data, null, 2);
    const dataBlob = new Blob([dataStr], { type: 'application/json' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(dataBlob);
    link.download = `sales-system-backup-${new Date().toISOString().split('T')[0]}.json`;
    link.click();
    setTimeout(() => URL.revokeObjectURL(link.href), 2000);
    showMessage(getText('data-exported'));
}

// ===== Export Data Modal helpers =====
function showExportDataModal() {
    if (!canManageGlobalSettings()) {
        showMessage(getText('msg-permission-denied') || 'You do not have permission for this action.', 'error');
        return;
    }
    if (!hasProductPermission('canExportProducts')) {
        showPermissionDeniedMessage('تصدير المنتجات', 'export products');
        return;
    }
    const modal = document.getElementById('exportDataModal');
    if (!modal) {
        // fallback: export everything if modal missing
        exportData();
        return;
    }
    const checkboxes = modal.querySelectorAll('.export-data-cb');
    checkboxes.forEach(cb => { cb.checked = true; });
    const selectAll = document.getElementById('exportDataSelectAll');
    if (selectAll) selectAll.checked = true;
    modal.style.display = 'block';
}

function hideExportDataModal() {
    const modal = document.getElementById('exportDataModal');
    if (modal) modal.style.display = 'none';
}

const exportDataModalEl = document.getElementById('exportDataModal');
if (exportDataModalEl) {
    const selectAllCb = document.getElementById('exportDataSelectAll');
    if (selectAllCb) {
        selectAllCb.addEventListener('change', function() {
            const checkboxes = exportDataModalEl.querySelectorAll('.export-data-cb');
            checkboxes.forEach(cb => { cb.checked = selectAllCb.checked; });
        });
    }
    const confirmBtn = document.getElementById('exportDataConfirmBtn');
    if (confirmBtn) {
        confirmBtn.addEventListener('click', function() {
            const selected = [];
            const checkboxes = exportDataModalEl.querySelectorAll('.export-data-cb');
            checkboxes.forEach(cb => {
                if (cb.checked) selected.push(cb.value);
            });
            if (selected.length === 0) {
                showMessage(typeof getText === 'function' ? (getText('msg-choose-export-data') || 'Please select at least one data type to export.') : 'Please select at least one data type to export.', 'warning');
                return;
            }
            hideExportDataModal();
            exportData(selected);
        });
    }
}

