function importData(event) {
    if (!canManageGlobalSettings()) {
        showMessage(getText('msg-permission-denied') || 'You do not have permission for this action.', 'error');
        event.target.value = '';
        return;
    }
    if (!hasProductPermission('canImportProducts')) {
        showPermissionDeniedMessage('استيراد المنتجات', 'import products');
        event.target.value = '';
        return;
    }
    const file = event.target.files[0];
    if (!file) return;
    
    const fileName = String(file.name || '').toLowerCase();
    const isZip = fileName.endsWith('.zip');
    const isJson = fileName.endsWith('.json');
    if (!isZip && !isJson) {
        showMessage(getText('msg-import-file-error') || 'Please choose a JSON or ZIP backup file.', 'error');
        event.target.value = '';
        return;
    }
    
    if (isZip && typeof JSZip !== 'undefined') {
        const reader = new FileReader();
        reader.onload = async function(e) {
            try {
                const zip = await JSZip.loadAsync(e.target.result);
                const dataFile = zip.file('data.json');
                if (!dataFile) {
                    showMessage(getText('msg-import-file-error') || 'Invalid backup ZIP: data.json not found', 'error');
                    return;
                }
                const dataStr = await dataFile.async('string');
                const data = JSON.parse(dataStr);
                if (data.products && data.products.length) {
                    for (const p of data.products) {
                        const ref = p.imageRef;
                        if (ref && ref.startsWith('images/')) {
                            const name = ref.replace('images/', '');
                            const imgFile = zip.file(ref) || zip.file('images/' + name);
                            if (imgFile) {
                                const base64 = await imgFile.async('base64');
                                const mime = name.endsWith('.png') ? 'image/png' : name.endsWith('.webp') ? 'image/webp' : 'image/jpeg';
                                p.imageUrl = 'data:' + mime + ';base64,' + base64;
                            }
                            delete p.imageRef;
                        }
                    }
                }
                if (!(await uiConfirm(getText('msg-confirm-import'), { title: (getText('confirm') || 'Confirm') }))) return;
                applyImportedData(data);
            } catch (err) {
                console.error('Import ZIP failed:', err);
                showMessage(getText('msg-import-file-error'), 'error');
            } finally {
                event.target.value = '';
            }
        };
        reader.readAsArrayBuffer(file);
    } else {
        const reader = new FileReader();
        reader.onload = async function(e) {
            try {
                const data = JSON.parse(e.target.result);
                if (!(await uiConfirm(getText('msg-confirm-import'), { title: (getText('confirm') || 'Confirm') }))) return;
                applyImportedData(data);
            } catch (error) {
                showMessage(getText('msg-import-file-error'), 'error');
            } finally {
                event.target.value = '';
            }
        };
        reader.readAsText(file);
    }
}
function applyImportedData(data) {
    if (data.products) products = data.products;
    if (data.customers) customers = data.customers;
    if (data.sales) sales = data.sales;
    if (data.suppliers) suppliers = data.suppliers;
            if (data.settings) settings = getSanitizedSettingsForCurrentUser(data.settings);
    if (data.purchases) purchases = data.purchases;
    if (data.supplierPayments) supplierPayments = data.supplierPayments;
    if (data.purchaseReturns) purchaseReturns = data.purchaseReturns;
    if (data.supplierLedger) supplierLedger = data.supplierLedger;
    if (data.stockMovements) saveToStorage('stockMovements', data.stockMovements);
    if (data.salesLogs) saveToStorage('salesLogs', data.salesLogs);
    if (data.customerLogs) saveToStorage('customerLogs', data.customerLogs);
    if (data.cashDrawer) {
        cashDrawer = data.cashDrawer;
        saveToStorage('cashDrawer', cashDrawer);
    }
    saveAllData();
    location.reload();
}

// Debounce timer for Firestore: avoid hammering the API when saveAllData is called repeatedly
let _firestoreSaveTimer = null;
const FIRESTORE_DEBOUNCE_MS = 2000;

async function saveAllData() {
    // Always persist the latest product snapshot to avoid stale-memory overwrites.
    try { products = getCurrentProducts(); } catch (_) {}
    // Save to localStorage (for offline support) — always immediate
    saveToStorage('products', products);
    saveToStorage('customers', customers);
    saveToStorage('sales', sales);
    saveToStorage('suppliers', suppliers);
    const settingsForCurrentUser = getSanitizedSettingsForCurrentUser(settings);
    saveToStorage('settings', settingsForCurrentUser);
    saveToStorage('cashDrawer', cashDrawer);
    saveToStorage('purchases', purchases);
    saveToStorage('supplierPayments', supplierPayments);
    saveToStorage('purchaseReturns', purchaseReturns);
    saveToStorage('supplierLedger', supplierLedger);

    // Firestore: debounced + retry on transient errors (QUIC/400)
    const effUid = typeof getEffectiveDataOwnerId === 'function' ? getEffectiveDataOwnerId() : (currentUser && currentUser.uid);
    if (window.firebaseDbInstance && currentUser && effUid) {
        if (_firestoreSaveTimer) clearTimeout(_firestoreSaveTimer);
        _firestoreSaveTimer = setTimeout(() => {
            _firestoreSaveTimer = null;
            runFirestoreSaveWithRetry();
        }, FIRESTORE_DEBOUNCE_MS);
    }
}

function _cleanForFirestore(obj) {
    if (obj === null || obj === undefined) return null;
    if (Array.isArray(obj)) return obj.map(item => _cleanForFirestore(item));
    if (typeof obj === 'object' && obj.constructor === Object) {
        const cleaned = {};
        for (const key in obj) {
            if (obj.hasOwnProperty(key)) {
                const value = obj[key];
                if (value !== undefined) {
                    if (key === 'imageUrl' && typeof value === 'string' && value.startsWith('data:image')) {
                        cleaned[key] = null;
                    } else {
                        cleaned[key] = _cleanForFirestore(value);
                    }
                }
            }
        }
        return cleaned;
    }
    return obj;
}

function _isOfflineLikeFirestoreError(error) {
    const code = error && error.code;
    const msg = (error && (error.message || '')).toString();
    if (code === 'unavailable' || code === 'deadline-exceeded') return true;
    if (/failed to get document because the client is offline|client is offline|network request failed/i.test(msg)) return true;
    return false;
}

function _isPermissionDeniedFirestoreError(error) {
    const code = error && error.code;
    const msg = (error && (error.message || error.code || '')).toString();
    if (code === 'permission-denied') return true;
    return /missing or insufficient permissions|permission-denied/i.test(msg);
}

function _isRetryableFirestoreError(error) {
    if (_isOfflineLikeFirestoreError(error)) return true;
    const msg = (error && (error.message || error.code || '')).toString();
    return /QUIC|network|400|transport|unavailable|failed|offline/i.test(msg);
}

async function runFirestoreSaveWithRetry(retryCount = 0) {
    const maxRetries = 2;
    const delays = [2000, 5000];
    const effUid = typeof getEffectiveDataOwnerId === 'function' ? getEffectiveDataOwnerId() : (currentUser && currentUser.uid);
    if (!window.firebaseDbInstance || !currentUser || !effUid) return;
    // If the browser is offline, do not attempt saving now — it will be saved when online via flushSyncQueue
    if (typeof navigator !== 'undefined' && navigator.onLine === false) {
        console.log('ℹ️ Skipping Firestore sync because the device is currently offline');
        return;
    }
    try {
        // Flush queued incremental ops first (V2 scalable sync)
        try { await flushSyncQueue(); } catch (_) {}

        // Save only small docs in Firestore (settings + cash drawer summary).
        // Large entities (products/sales/...) are synced via the V2 queue to subcollections.
        const cleanedData = {
            cashDrawer: _cleanForFirestore(cashDrawer)
        };
        if (!(typeof isSubUser === 'function' && isSubUser()) || canCurrentUserEditSettings()) {
            cleanedData.settings = _cleanForFirestore(getSanitizedSettingsForCurrentUser(settings));
        }
        const saveUid = typeof getEffectiveDataOwnerId === 'function' ? getEffectiveDataOwnerId() : currentUser.uid;
        await window.firebaseDbInstance.saveAllUserData(saveUid, cleanedData);
        console.log('✅ Firestore sync OK (meta/settings/cashdrawer)');
    } catch (error) {
        if (_isOfflineLikeFirestoreError(error)) {
            console.warn('Firestore sync deferred (offline/unavailable):', error && error.code);
        } else {
            console.error('❌ Error saving data to Firestore:', error);
        }
        if (retryCount < maxRetries && _isRetryableFirestoreError(error)) {
            const delay = delays[retryCount] || 5000;
            console.warn(`🔄 Retry Firestore save in ${delay / 1000}s (attempt ${retryCount + 2}/${maxRetries + 1})`);
            setTimeout(() => runFirestoreSaveWithRetry(retryCount + 1), delay);
        }
    }
}

// ============================================================
// V2 Sync Queue (IndexedDB) - prevents full data re-upload
// ============================================================
const SYNC_QUEUE_MAX = 5000;
let _syncFlushTimer = null;
let _syncFlushInFlight = false;
let _syncBackoffMs = 0;
let _syncLastSuccessAt = 0;
let _syncLastErrorAt = 0;
let _syncLastErrorMsg = '';
let _syncQueueBlocked = false;
let _syncQueueOverflowAt = 0;
let _syncDroppedOpsCount = 0;
let _syncPermissionPaused = false;
let _syncPermissionPauseLoggedAt = 0;
let _deletedProductsMergePermissionBlocked = false;
let _restrictedFirestoreAccessLogged = false;

function _notifySyncQueueCapacityReached() {
    const now = Date.now();
    if (_syncQueueOverflowAt && (now - _syncQueueOverflowAt) < 15000) return;
    _syncQueueOverflowAt = now;
    const isEn = (document.documentElement.lang || 'ar') === 'en';
    showNotification(
        isEn
            ? 'Sync queue is full. New operations are paused until pending sync is uploaded.'
            : 'طابور المزامنة ممتلئ. تم إيقاف العمليات الجديدة مؤقتاً حتى رفع العمليات المعلقة.',
        'warning',
        6000
    );
}

function _syncQueueKey() {
    const uid = typeof getEffectiveDataOwnerId === 'function' ? getEffectiveDataOwnerId() : getCurrentUserId();
    return uid ? `pos_${uid}_syncQueueV2` : 'syncQueueV2';
}

/** معرّفات منتجات حُذفت محلياً — لا تُعاد من السحابة عند الدمج حتى يُحذف المستند فعلياً */
function _deletedProductIdsKey() {
    const uid = typeof getEffectiveDataOwnerId === 'function' ? getEffectiveDataOwnerId() : getCurrentUserId();
    return uid ? `pos_${uid}_deletedProductIds` : 'deletedProductIds';
}
function _ensureDeletedProductsSyncCache() {
    if (!window.__deletedProductIds) window.__deletedProductIds = new Set();
    return window.__deletedProductIds;
}
async function addDeletedProductId(id) {
    const s = String(id);
    _ensureDeletedProductsSyncCache().add(s);
    try {
        const key = _deletedProductIdsKey();
        const arr = (await idbGet(key)) || [];
        if (!arr.includes(s)) {
            arr.push(s);
            if (arr.length > 8000) arr.splice(0, arr.length - 8000);
            await idbSet(key, arr);
        }
    } catch (e) {
        console.warn('addDeletedProductId:', e);
    }
}
async function removeDeletedProductId(id) {
    const s = String(id);
    _ensureDeletedProductsSyncCache().delete(s);
    try {
        const key = _deletedProductIdsKey();
        const arr = (await idbGet(key)) || [];
        const next = arr.filter(x => String(x) !== s);
        if (next.length !== arr.length) await idbSet(key, next);
    } catch (_) {}
}
async function getDeletedProductIdSet() {
    try {
        const arr = (await idbGet(_deletedProductIdsKey())) || [];
        return new Set(arr.map(String));
    } catch (_) {
        return new Set();
    }
}

/** يدمج معرفات المنتجات المحذوفة من السحابة (V2) مع IndexedDB — بدونها يبقى المنتج ظاهراً على أجهزة أخرى لأن الدمج محلي+سحابة اتحاد وليس استبدالاً. */
async function mergeCloudDeletedProductIdsIntoLocal(ownerUserId) {
    if (!ownerUserId || typeof navigator !== 'undefined' && navigator.onLine === false) return;
    if (_deletedProductsMergePermissionBlocked) return;
    if (!window.firebaseDbInstance || typeof window.firebaseDbInstance.v2FetchDeletedProductIds !== 'function') return;
    try {
        const cloudIds = await window.firebaseDbInstance.v2FetchDeletedProductIds(ownerUserId);
        if (!cloudIds || cloudIds.size === 0) return;
        const key = _deletedProductIdsKey();
        const arr = (await idbGet(key)) || [];
        const set = new Set(arr.map(String));
        let added = false;
        cloudIds.forEach(id => {
            const s = String(id);
            if (!set.has(s)) {
                set.add(s);
                added = true;
            }
        });
        if (!added) return;
        let next = Array.from(set);
        if (next.length > 8000) next = next.slice(next.length - 8000);
        await idbSet(key, next);
        window.__deletedProductIds = new Set(next.map(String));
        _deletedProductsMergePermissionBlocked = false;
    } catch (e) {
        if (_isPermissionDeniedFirestoreError(e)) {
            _deletedProductsMergePermissionBlocked = true;
            console.warn('🔐 Deleted-products cloud merge paused: missing permission');
            return;
        }
        console.warn('mergeCloudDeletedProductIdsIntoLocal:', e && (e.message || e.code || e));
    }
}
function filterOutDeletedProducts(list, deletedSet) {
    if (!Array.isArray(list) || !deletedSet || !deletedSet.size) return Array.isArray(list) ? list : [];
    return list.filter(p => p && p.id != null && !deletedSet.has(String(p.id)));
}

(function () {
    _ensureDeletedProductsSyncCache();
    if (typeof getDeletedProductIdSet === 'function')
        getDeletedProductIdSet().then(function (s) { window.__deletedProductIds = s; }).catch(function () {});
})();

async function enqueueSyncOp(entity, op, docId, data) {
    try {
        const uid = typeof getEffectiveDataOwnerId === 'function' ? getEffectiveDataOwnerId() : getCurrentUserId();
        if (!uid) return false;
        const key = _syncQueueKey();
        const q = (await idbGet(key)) || [];
        const cleanedData = op === 'delete' ? null : _cleanForFirestore(data);
        const docIdStr = String(docId);

        // Dedupe: avoid enqueuing the exact same intent twice.
        // For sales we prefer a stable txId (idempotencyKey) when available.
        let dedupeIndex = -1;
        if (op !== 'delete' && entity === 'sales' && cleanedData && cleanedData.txId) {
            const txId = String(cleanedData.txId);
            dedupeIndex = q.findIndex(x =>
                x && x.entity === 'sales' && x.op === 'upsert' &&
                x.data && x.data.txId != null && String(x.data.txId) === txId
            );
        }
        if (dedupeIndex < 0) {
            dedupeIndex = q.findIndex(x => x && x.entity === entity && x.op === op && String(x.docId) === docIdStr);
        }

        if (dedupeIndex >= 0) {
            q[dedupeIndex] = {
                ...(q[dedupeIndex] || {}),
                entity,
                op,
                docId: docIdStr,
                data: cleanedData,
                ts: Date.now()
            };
        } else {
            if (q.length >= SYNC_QUEUE_MAX) {
                _syncQueueBlocked = true;
                _notifySyncQueueCapacityReached();
                scheduleSyncFlush();
                try { void updateOfflineSyncStatusUI(); } catch (_) {}
                return false;
            }
            q.push({
                entity,
                op,
                docId: docIdStr,
                data: cleanedData,
                ts: Date.now()
            });
        }
        await idbSet(key, q);
        if (_syncQueueBlocked && q.length < Math.max(1000, Math.floor(SYNC_QUEUE_MAX * 0.8))) {
            _syncQueueBlocked = false;
        }
        scheduleSyncFlush();
        try { void updateOfflineSyncStatusUI(); } catch (_) {}
        return true;
    } catch (e) {
        console.warn('enqueueSyncOp failed:', e);
        return false;
    }
}

function scheduleSyncFlush() {
    if (_syncPermissionPaused) return;
    if (_syncFlushTimer) return;
    const delay = _syncBackoffMs > 0 ? _syncBackoffMs : 1500;
    _syncFlushTimer = setTimeout(() => {
        _syncFlushTimer = null;
        flushSyncQueue();
    }, delay);
}

async function flushSyncQueue(options = {}) {
    const strict = !!(options && options.strict);
    if (_syncFlushInFlight) return;
    if (_syncPermissionPaused && !strict) return;
    const effUid = typeof getEffectiveDataOwnerId === 'function' ? getEffectiveDataOwnerId() : (currentUser && currentUser.uid);
    if (!window.firebaseDbInstance || !currentUser || !effUid) return;
    if (typeof navigator !== 'undefined' && navigator.onLine === false) return;
    if (typeof window !== 'undefined' && window.__posNetOffline === true) return;
    _syncFlushInFlight = true;
    try { void updateOfflineSyncStatusUI(); } catch (_) {}
    let _debugKey = '';
    let _debugWriteUid = '';
    let _debugChunk = [];
    try {
        const key = _syncQueueKey();
        _debugKey = key;
        let q = (await idbGet(key)) || [];
        if (!Array.isArray(q) || q.length === 0) return;

        // Preserve operation order (sales / stock) — oldest first, then dedupe keeps latest per key
        try {
            q.sort((a, b) => (Number(a && a.ts) || 0) - (Number(b && b.ts) || 0));
        } catch (_) {}

        // Safety dedupe for pre-existing queue duplicates:
        // keep only the last operation per (sales.txId) or per (entity/op/docId).
        try {
            const idxByKey = new Map();
            const deduped = [];
            for (const op of q) {
                if (!op || !op.entity || !op.op) continue;
                const entity = op.entity;
                const opKind = op.op;
                const docIdStr = op.docId != null ? String(op.docId) : '';
                let k;
                if (entity === 'sales' && opKind === 'upsert' && op.data && op.data.txId) {
                    k = `sales_tx:${String(op.data.txId)}`;
                } else {
                    k = `${entity}|${opKind}|${docIdStr}`;
                }
                if (idxByKey.has(k)) {
                    deduped[idxByKey.get(k)] = op;
                } else {
                    idxByKey.set(k, deduped.length);
                    deduped.push(op);
                }
            }
            q = deduped;
            await idbSet(key, q);
        } catch (_) {}

        // Firestore batch limit is 500 operations; keep a buffer
        const chunk = q.slice(0, 450);
        const writeUid = typeof getEffectiveDataOwnerId === 'function' ? getEffectiveDataOwnerId() : currentUser.uid;
        _debugWriteUid = String(writeUid || '');
        _debugChunk = Array.isArray(chunk) ? chunk.slice(0, 8) : [];
        await window.firebaseDbInstance.v2BatchWrite(writeUid, chunk);
        // Keep deleted product tombstones permanently.
        // Do not remove IDs after cloud delete success; this prevents resurrection
        // from stale sync snapshots/other devices.
        q = q.slice(chunk.length);
        await idbSet(key, q);
        if (_syncQueueBlocked && q.length < Math.max(1000, Math.floor(SYNC_QUEUE_MAX * 0.8))) {
            _syncQueueBlocked = false;
        }
        _syncBackoffMs = 0;
        _syncPermissionPaused = false;
        _syncPermissionPauseLoggedAt = 0;
        _syncLastSuccessAt = Date.now();
        _syncLastErrorAt = 0;
        _syncLastErrorMsg = '';
        if (q.length) scheduleSyncFlush();
    } catch (e) {
        if (_isPermissionDeniedFirestoreError(e)) {
            _syncLastErrorAt = Date.now();
            _syncLastErrorMsg = 'permission-denied';
            _syncBackoffMs = 0;
            _syncPermissionPaused = true;
            const now = Date.now();
            if (!_syncPermissionPauseLoggedAt || (now - _syncPermissionPauseLoggedAt) > 60000) {
                _syncPermissionPauseLoggedAt = now;
                console.warn('🔐 Firestore sync paused: missing permission for current user scope');
            }
            try {
                const sample = (_debugChunk || []).map(op => ({
                    entity: op && op.entity,
                    op: op && op.op,
                    docId: op && op.docId
                }));
                try {
                    console.warn('[sync-debug] permission-denied', JSON.stringify({
                        queueKey: _debugKey,
                        actorUid: (typeof getCurrentUserId === 'function' ? getCurrentUserId() : (currentUser && currentUser.uid) || null),
                        writeUid: _debugWriteUid,
                        sampleOps: sample
                    }));
                } catch (_) {
                    console.warn('[sync-debug] permission-denied', { queueKey: _debugKey, writeUid: _debugWriteUid, sampleOps: sample });
                }
            } catch (_) {}
            if (strict) throw e;
            return;
        }
        console.warn('flushSyncQueue failed:', e);
        try {
            const sample = (_debugChunk || []).map(op => ({
                entity: op && op.entity,
                op: op && op.op,
                docId: op && op.docId
            }));
            console.warn('[sync-debug] context', {
                queueKey: _debugKey,
                actorUid: (typeof getCurrentUserId === 'function' ? getCurrentUserId() : (currentUser && currentUser.uid) || null),
                writeUid: _debugWriteUid,
                actorLinkFields: currentUser ? {
                    parentAdminId: currentUser.parentAdminId || null,
                    parentAdminID: currentUser.parentAdminID || null,
                    parentId: currentUser.parentId || null,
                    parent: currentUser.parent || null,
                    parentUid: currentUser.parentUid || null,
                    parentUserId: currentUser.parentUserId || null,
                    mainAdminId: currentUser.mainAdminId || null,
                    adminId: currentUser.adminId || null,
                    ownerId: currentUser.ownerId || null,
                    ownerUid: currentUser.ownerUid || null,
                    storeOwnerId: currentUser.storeOwnerId || null,
                    storeId: currentUser.storeId || null,
                    createdBy: currentUser.createdBy || null,
                    createdByUid: currentUser.createdByUid || null
                } : null,
                sampleOps: sample
            });
        } catch (_) {}
        _syncLastErrorAt = Date.now();
        _syncLastErrorMsg = String((e && (e.code || e.message)) || e || 'sync_failed');
        _syncBackoffMs = Math.min(30000, (_syncBackoffMs || 2000) * 2);
        scheduleSyncFlush();
        if (strict) throw e;
    } finally {
        _syncFlushInFlight = false;
        try { void updateOfflineSyncStatusUI(); } catch (_) {}
    }
}

// Auto flush on connectivity / visibility changes
try {
    // More reliable offline detection than navigator.onLine
    try { window.__posNetOffline = false; } catch(_) {}
    window.addEventListener('offline', () => { try { window.__posNetOffline = true; } catch(_) {} try { void updateOfflineSyncStatusUI(); } catch (_) {} });
    window.addEventListener('online', () => {
        try { window.__posNetOffline = false; } catch(_) {}
        _syncBackoffMs = 0;
        if (_syncPermissionPaused) {
            try { flushSyncQueue({ strict: true }); } catch (_) {}
        } else {
            scheduleSyncFlush();
        }
        try { void updateOfflineSyncStatusUI(); } catch (_) {}
    });
    document.addEventListener('visibilitychange', () => {
        if (document.visibilityState === 'visible') {
            scheduleSyncFlush();
            if (_syncPermissionPaused) {
                setTimeout(function () {
                    try { void flushSyncQueue({ strict: true }); } catch (_) {}
                }, 800);
            }
            try {
                const oid = typeof getEffectiveDataOwnerId === 'function' ? getEffectiveDataOwnerId() : null;
                if (oid && window.firebaseDbInstance && typeof mergeCloudDeletedProductIdsIntoLocal === 'function') {
                    mergeCloudDeletedProductIdsIntoLocal(oid).then(function () {
                        try {
                            products = getCurrentProducts();
                            if (typeof loadProducts === 'function') loadProducts();
                            if (typeof updatePOSIfActive === 'function') updatePOSIfActive();
                        } catch (_) {}
                    }).catch(function () {});
                }
            } catch (_) {}
        }
        try { void updateOfflineSyncStatusUI(); } catch (_) {}
    });
    // periodic flush (safe, debounced internally)
    setInterval(() => scheduleSyncFlush(), 8000);
    if (typeof document !== 'undefined') {
        document.addEventListener('DOMContentLoaded', function () {
            setTimeout(function () { try { void updateOfflineSyncStatusUI(); } catch (_) {} }, 800);
        });
    }
} catch(_) {}

// آخر رصيد سحابي مؤكد (minor units) لاستخدامه كـ base في تحديثات delta الذرّية.
let __cashboxSyncedUSDCents = null;
let __cashboxSyncedLBPUnits = null;

function toUSDCents(value) {
    return Math.round((Number(value) || 0) * 100);
}

function toLBPUnits(value) {
    return Math.round(Number(value) || 0);
}

function readCashSummaryUSD(summaryLike) {
    if (!summaryLike || typeof summaryLike !== 'object') return 0;
    if (Number.isFinite(Number(summaryLike.cashUSDCents))) {
        return Number(summaryLike.cashUSDCents) / 100;
    }
    return Number(summaryLike.cashUSD || 0) || 0;
}

function readCashSummaryLBP(summaryLike) {
    if (!summaryLike || typeof summaryLike !== 'object') return 0;
    if (Number.isFinite(Number(summaryLike.cashLBPUnits))) {
        return Number(summaryLike.cashLBPUnits);
    }
    return Math.round(Number(summaryLike.cashLBP || 0) || 0);
}

// دفع ملخص الصندوق (USD/LBP) إلى السحابة فوراً بعد كل تغيير — عبر delta transaction-safe.
function pushCashDrawerSummaryToCloud(retryCount, opMeta) {
    retryCount = retryCount || 0;
    const tenantId = getSharedCashboxDocId();
    if (!tenantId || !window.firebaseDbInstance || typeof window.firebaseDbInstance.saveTenantCashboxSummary !== 'function') return;
    const nowIso = cashDrawer && cashDrawer.lastUpdate ? cashDrawer.lastUpdate : new Date().toISOString();
    const targetUSDCents = opMeta && Number.isFinite(Number(opMeta.targetUSDCents))
        ? Number(opMeta.targetUSDCents)
        : toUSDCents(cashDrawer && cashDrawer.cashUSD);
    const targetLBPUnits = opMeta && Number.isFinite(Number(opMeta.targetLBPUnits))
        ? Number(opMeta.targetLBPUnits)
        : toLBPUnits(cashDrawer && cashDrawer.cashLBP);

    // Bootstrap base from current local state if sync baseline isn't known yet.
    if (!Number.isFinite(__cashboxSyncedUSDCents) || !Number.isFinite(__cashboxSyncedLBPUnits)) {
        __cashboxSyncedUSDCents = targetUSDCents;
        __cashboxSyncedLBPUnits = targetLBPUnits;
    }

    // No-op guard: avoid duplicate cloud writes when nothing changed.
    if (retryCount === 0 && targetUSDCents === __cashboxSyncedUSDCents && targetLBPUnits === __cashboxSyncedLBPUnits) {
        return;
    }

    const operationId = (opMeta && opMeta.operationId)
        ? String(opMeta.operationId)
        : ('cashop_' + Date.now() + '_' + Math.random().toString(36).slice(2, 10));

    const baseUSDCents = opMeta && Number.isFinite(Number(opMeta.baseUSDCents))
        ? Number(opMeta.baseUSDCents)
        : __cashboxSyncedUSDCents;
    const baseLBPUnits = opMeta && Number.isFinite(Number(opMeta.baseLBPUnits))
        ? Number(opMeta.baseLBPUnits)
        : __cashboxSyncedLBPUnits;

    const summary = {
        cashUSD: targetUSDCents / 100,
        cashLBP: targetLBPUnits,
        baseCashUSDCents: baseUSDCents,
        baseCashLBPUnits: baseLBPUnits,
        operationId,
        lastUpdate: nowIso
    };

    // Offline: queue the summary write so it syncs once when connection returns.
    if (typeof navigator !== 'undefined' && navigator.onLine === false) {
        try { enqueueSyncOp('cashDrawer', 'upsert', 'summary', summary); } catch (_) {}
        return;
    }
    window.firebaseDbInstance.saveTenantCashboxSummary(tenantId, summary).then(function() {
        __cashboxSyncedUSDCents = targetUSDCents;
        __cashboxSyncedLBPUnits = targetLBPUnits;
        if (retryCount > 0) console.log('✅ Cash drawer summary synced to cloud (after retry)');
        try {
            if (typeof _syncPermissionPaused !== 'undefined' && _syncPermissionPaused) {
                _syncPermissionPaused = false;
                if (typeof scheduleSyncFlush === 'function') scheduleSyncFlush();
            }
        } catch (_) {}
    }).catch(function(err) {
        console.warn('pushCashDrawerSummaryToCloud failed:', err);
        if (retryCount < 2) {
            const delay = retryCount === 0 ? 2000 : 5000;
            setTimeout(function() {
                pushCashDrawerSummaryToCloud(retryCount + 1, {
                    operationId,
                    targetUSDCents,
                    targetLBPUnits,
                    baseUSDCents,
                    baseLBPUnits
                });
            }, delay);
        }
    });
}

let __tenantCashboxUnsub = null;
function stopTenantCashboxRealtimeSync() {
    try { if (typeof __tenantCashboxUnsub === 'function') __tenantCashboxUnsub(); } catch (_) {}
    __tenantCashboxUnsub = null;
}

function startTenantCashboxRealtimeSync() {
    try {
        stopTenantCashboxRealtimeSync();
        const tenantId = getSharedCashboxDocId();
        if (!tenantId || !window.firebaseDbInstance || typeof window.firebaseDbInstance.subscribeTenantCashboxSummary !== 'function') return;
        __tenantCashboxUnsub = window.firebaseDbInstance.subscribeTenantCashboxSummary(tenantId, function(summary) {
            if (!summary || typeof cashDrawer === 'undefined') return;
            const localLast = cashDrawer && cashDrawer.lastUpdate ? new Date(cashDrawer.lastUpdate).getTime() : 0;
            const cloudIso = typeof getCashDrawerDocLastUpdateIso === 'function' ? getCashDrawerDocLastUpdateIso(summary) : (summary.lastUpdate || null);
            const cloudLast = cloudIso ? new Date(cloudIso).getTime() : 0;
            if (isFinite(localLast) && isFinite(cloudLast) && cloudLast < localLast) return;
            const usdFromCloud = Number.isFinite(Number(summary.cashUSDCents))
                ? (Number(summary.cashUSDCents) / 100)
                : Number(summary.cashUSD || 0);
            const lbpFromCloud = Number.isFinite(Number(summary.cashLBPUnits))
                ? Number(summary.cashLBPUnits)
                : Number(summary.cashLBP || 0);
            cashDrawer.cashUSD = Number(usdFromCloud) || 0;
            cashDrawer.cashLBP = Math.round(Number(lbpFromCloud) || 0);
            __cashboxSyncedUSDCents = toUSDCents(cashDrawer.cashUSD);
            __cashboxSyncedLBPUnits = toLBPUnits(cashDrawer.cashLBP);
            const appliedIso = typeof getCashDrawerDocLastUpdateIso === 'function' ? getCashDrawerDocLastUpdateIso(summary) : null;
            if (appliedIso) cashDrawer.lastUpdate = appliedIso;
            else if (summary.lastUpdate) cashDrawer.lastUpdate = summary.lastUpdate;
            try { saveToStorage('cashDrawer', cashDrawer); } catch (_) {}
            try { updateCashDrawerDisplay(); } catch (_) {}
        });
    } catch (e) {
        console.warn('startTenantCashboxRealtimeSync failed:', e && (e.message || e.code || e));
    }
}

// Script: fix timestamps for old sales records
function fixOldSalesTimestamps() {
    console.log('🔧 Starting timestamp fix for old sales records...');
    
    let fixedCount = 0;
    let skippedCount = 0;
    
    sales.forEach(sale => {
        // Check if it already has a valid timestamp
        if (sale.timestamp && sale.timestamp.includes('T')) {
            // Validate timestamp
            const testDate = new Date(sale.timestamp);
            if (!isNaN(testDate.getTime())) {
                skippedCount++;
                return; // Valid timestamp, no changes needed
            }
        }
        
        // This sale needs fixing
        if (sale.date) {
            try {
                // Attempt to create a local timestamp based on the existing date
                const dateStr = sale.date;
                
                // If date only (YYYY-MM-DD)
                if (/^\d{4}-\d{2}-\d{2}$/.test(dateStr)) {
                    // Create a local timestamp with a default time (12:00:00)
                    // This is better than midnight to avoid timezone edge cases
                    const [year, month, day] = dateStr.split('-').map(Number);
                    const localDate = new Date(year, month - 1, day, 12, 0, 0, 0);
                    
                    // Create a local timestamp using the same format as getLocalDateTimeISO
                    const localYear = localDate.getFullYear();
                    const localMonth = String(localDate.getMonth() + 1).padStart(2, '0');
                    const localDay = String(localDate.getDate()).padStart(2, '0');
                    const localHours = String(localDate.getHours()).padStart(2, '0');
                    const localMinutes = String(localDate.getMinutes()).padStart(2, '0');
                    const localSeconds = String(localDate.getSeconds()).padStart(2, '0');
                    const localMs = String(localDate.getMilliseconds()).padStart(3, '0');
                    
                    sale.timestamp = `${localYear}-${localMonth}-${localDay}T${localHours}:${localMinutes}:${localSeconds}.${localMs}`;
                    fixedCount++;
                    
                    console.log(`✅ Fixed sale ${sale.invoiceNumber || sale.id}: ${sale.timestamp}`);
                } else {
                    // If date uses another format, try standard parsing
                    const parsedDate = new Date(dateStr);
                    if (!isNaN(parsedDate.getTime())) {
                        // Convert to local-time components
                        const localYear = parsedDate.getFullYear();
                        const localMonth = String(parsedDate.getMonth() + 1).padStart(2, '0');
                        const localDay = String(parsedDate.getDate()).padStart(2, '0');
                        const localHours = String(parsedDate.getHours()).padStart(2, '0');
                        const localMinutes = String(parsedDate.getMinutes()).padStart(2, '0');
                        const localSeconds = String(parsedDate.getSeconds()).padStart(2, '0');
                        const localMs = String(parsedDate.getMilliseconds()).padStart(3, '0');
                        
                        sale.timestamp = `${localYear}-${localMonth}-${localDay}T${localHours}:${localMinutes}:${localSeconds}.${localMs}`;
                        fixedCount++;
                        
                        console.log(`✅ Fixed sale ${sale.invoiceNumber || sale.id}: ${sale.timestamp}`);
                    } else {
                        console.warn(`❌ Cannot parse date for sale ${sale.invoiceNumber || sale.id}: ${sale.date}`);
                    }
                }
            } catch (error) {
                console.error(`❌ Error fixing sale ${sale.invoiceNumber || sale.id}:`, error);
            }
        } else {
            console.warn(`❌ Missing date for sale ${sale.invoiceNumber || sale.id}`);
        }
    });
    
    if (fixedCount > 0) {
        // Save changes
        saveToStorage('sales', sales);
        console.log(`🎉 Fixed ${fixedCount} sale record(s) successfully!`);
        
        // Show a user notification
        const lang = document.documentElement.lang || 'en';
        const message = lang === 'en' 
            ? `Fixed timestamps for ${fixedCount} old sales records`
            : `تم إصلاح توقيت ${fixedCount} من المبيعات القديمة`;
        showMessage(message, 'success');
        
        // Reload sales lists
        if (typeof loadSales === 'function') {
            loadSales();
        }
        if (typeof loadInvoices === 'function') {
            loadInvoices();
        }
    }
    
    console.log(`📊 Total processed: ${fixedCount} fixed, ${skippedCount} already valid`);
    return { fixed: fixedCount, skipped: skippedCount };
}

// Check sales timestamps status
function checkSalesTimestampsStatus() {
    let totalSales = sales.length;
    let hasTimestamp = 0;
    let hasValidTimestamp = 0;
    let needsFix = 0;
    
    sales.forEach(sale => {
        if (sale.timestamp) {
            hasTimestamp++;
            // Validate timestamp
            const testDate = new Date(sale.timestamp);
            if (!isNaN(testDate.getTime())) {
                hasValidTimestamp++;
            } else {
                needsFix++;
            }
        } else {
            needsFix++;
        }
    });
    
    console.log(`📊 Sales timestamps status report:`);
    console.log(`   • Total sales: ${totalSales}`);
    console.log(`   • Has timestamp: ${hasTimestamp}`);
    console.log(`   • Valid timestamp: ${hasValidTimestamp}`);
    console.log(`   • Needs fix: ${needsFix}`);
    
    return {
        total: totalSales,
        hasTimestamp: hasTimestamp,
        hasValidTimestamp: hasValidTimestamp,
        needsFix: needsFix
    };
}

// Validate reports time accuracy
function validateReportsAccuracy() {
    console.log('🔍 Validating report timing accuracy...');
    
    let issues = [];
    
    // Check sales missing timestamps
    const salesWithoutTimestamp = sales.filter(sale => !sale.timestamp);
    if (salesWithoutTimestamp.length > 0) {
        issues.push(`${salesWithoutTimestamp.length} sale(s) do not have a timestamp`);
    }
    
    // Check invalid timestamps
    const invalidTimestamps = sales.filter(sale => {
        if (sale.timestamp) {
            const testDate = new Date(sale.timestamp);
            return isNaN(testDate.getTime());
        }
        return false;
    });
    
    if (invalidTimestamps.length > 0) {
        issues.push(`${invalidTimestamps.length} sale(s) have invalid timestamps`);
    }
    
    // Check timestamp format usage in reports
    const reportsUsingCorrectFormat = sales.filter(sale => {
        // Check if timestamp is used in a consistent format
        return sale.timestamp && sale.timestamp.includes('T');
    });
    
    console.log(`✅ ${reportsUsingCorrectFormat.length} sale(s) use a valid timestamp format`);
    
    if (issues.length === 0) {
        console.log('🎉 Reports timing looks accurate — no timestamp issues detected');
        return { status: 'success', issues: [] };
    } else {
        console.warn('⚠️ Report timing issues detected:');
        issues.forEach(issue => console.warn(`   • ${issue}`));
        return { status: 'warning', issues: issues };
    }
}

// Generate a comprehensive timestamp report
function generateTimestampReport() {
    const timestampStatus = checkSalesTimestampsStatus();
    const accuracyStatus = validateReportsAccuracy();
    
    const report = {
        timestamp: timestampStatus,
        accuracy: accuracyStatus,
        recommendations: []
    };
    
    if (timestampStatus.needsFix > 0) {
        report.recommendations.push('Run fixOldSalesTimestamps() to fix old sales records');
    }
    
    if (accuracyStatus.status === 'warning') {
        report.recommendations.push('Review reports to ensure correct timestamp usage');
    }
    
    console.log('📋 Comprehensive timestamp report:', report);
    return report;
}

// Manual testing/fix helpers — callable from the console
window.fixOldSalesTimestamps = fixOldSalesTimestamps;
window.checkSalesTimestampsStatus = checkSalesTimestampsStatus;
window.validateReportsAccuracy = validateReportsAccuracy;
window.generateTimestampReport = generateTimestampReport;

// Quick check+fix helper (console)
window.quickTimestampFix = function() {
    console.log('🔧 Starting quick sales timestamp check+fix...');
    const status = checkSalesTimestampsStatus();
    
    if (status.needsFix > 0) {
        console.log(`Detected ${status.needsFix} sale(s) that need fixing. Starting fix...`);
        const result = fixOldSalesTimestamps();
        
        // Verify results
        setTimeout(() => {
            const newStatus = checkSalesTimestampsStatus();
            console.log(`✅ Fix completed: ${result.fixed} fixed, ${result.skipped} already valid`);
            console.log(`📊 Current status: ${newStatus.needsFix} still need fixing`);
        }, 500);
        
        return result;
    } else {
        console.log('✅ All sales have valid timestamps — no fix needed');
        return { fixed: 0, skipped: status.total };
    }
};

// تحديث إجمالي مشتريات جميع العملاء
function updateAllCustomersTotalPurchases() {
    customers.forEach(customer => {
        const customerSales = sales.filter(sale => {
            return sale.customerId === customer.id ||
                   sale.customerName === customer.name ||
                   (sale.partialDetails && sale.partialDetails.customerId === customer.id) ||
                   (sale.partialDetails && sale.partialDetails.customerName === customer.name);
        });
        
        // حساب إجمالي المشتريات (شامل جميع أنواع البيع)
        const totalPurchases = customerSales.reduce((sum, sale) => {
            let purchaseAmount = 0;
            
            // للبيع النقدي - المبلغ كاملاً (يشمل الدين السابق إذا تم تسويته)
            if (sale.cashDetails) {
                // إذا كان هناك دين سابق تم تسويته
                if (sale.previousAccountAmount && sale.previousAccountAmount > 0) {
                    // sale.amount هو مبيعات المنتجات فقط؛ تسوية الدين تُسجل منفصلة
                    purchaseAmount = Math.max(0, sale.amount || 0);
                } else {
                    // بيع عادي بدون دين سابق
                    purchaseAmount = sale.amount || 0;
                }
            }
            // للبيع الجزئي - المبلغ المدفوع فقط
            else if (sale.partialDetails) {
                const paidInUSD = sale.partialDetails.paymentCurrency === 'USD' 
                    ? sale.partialDetails.amountPaid 
                    : sale.partialDetails.amountPaid / (settings.exchangeRate || 1);
                purchaseAmount = paidInUSD;
            }
            // للبيع بالدين - المبلغ كاملاً (حتى لو لم يتم الدفع بعد)
            else if (sale.paymentMethod === 'credit' || sale.invoiceNumber?.startsWith('CR-')) {
                purchaseAmount = sale.amount || 0;
            }
            // للبيع العادي (بدون تفاصيل دفع) - المبلغ كاملاً
            else {
                purchaseAmount = sale.amount || 0;
            }
            
            return sum + purchaseAmount;
        }, 0);
        
        const oldTotal = customer.totalPurchases || 0;
        customer.totalPurchases = totalPurchases;
    });
    saveToStorage('customers', customers);
}

// تحديث إجمالي مشتريات عميل محدد بعد دفع الدين
function updateCustomerTotalPurchasesAfterPayment(customerId, paymentAmount) {
    const customer = customers.find(c => c.id === customerId);
    if (!customer) return;
    
    console.log(`🔄 [Customer] Recalculating total purchases for ${customer.name} after payment of ${paymentAmount}`);
    
    // إعادة حساب إجمالي المشتريات بدلاً من إضافة المبلغ المدفوع
    // لأن إجمالي المشتريات يجب أن يكون ثابتاً (المبلغ الأصلي للمشتريات)
    updateAllCustomersTotalPurchases();
    
    console.log(`📊 [Customer] Recalculated total purchases for ${customer.name} after payment`);
}

// إعادة حساب إجمالي مشتريات عميل محدد
function recalculateCustomerTotalPurchases(customerId) {
    const customer = customers.find(c => c.id === customerId);
    if (!customer) return;
    
    console.log(`🔄 [Customer] Recalculating total purchases for ${customer.name}...`);
    
    // إعادة حساب إجمالي المشتريات
    updateAllCustomersTotalPurchases();
    
    console.log(`📊 [Customer] Recalculated total purchases for ${customer.name}: ${customer.totalPurchases}`);
}

// أنواع قيود الموردين: PURCHASE | PAYMENT | ADJUSTMENT
function addSupplierLedgerEntry(entry) {
    const e = {
        id: createRecordId('sl'),
        supplier_id: entry.supplier_id,
        type: entry.type,
        ref_no: entry.ref_no || null,
        product_name: entry.product_name || '',
        total_cost: Number(entry.total_cost) || 0,
        paid_now: Number(entry.paid_now) || 0,
        remaining: Number(entry.remaining) || 0,
        note: entry.note || '',
        currency: entry.currency || 'USD',
        rate: entry.rate || settings.exchangeRate,
        created_at: new Date().toISOString()
    };
    supplierLedger.push(e);
    saveToStorage('supplierLedger', supplierLedger);
    return e;
}

// وظائف إدارة الصندوق والنقدية
function calculateOptimalChange(totalDue, amountPaid, paymentCurrency, preferredChangeCurrency = null) {
    const changeNeeded = amountPaid - totalDue;
    
    if (changeNeeded <= 0) {
        return { change: 0, currency: paymentCurrency, canGiveChange: true, breakdown: null };
    }
    
    // إذا لم يحدد العميل عملة الباقي، نحاول إعطاؤه بنفس عملة الدفع
    if (!preferredChangeCurrency) {
        preferredChangeCurrency = paymentCurrency;
    }
    
    // التحقق من توفر النقدية
    const availableCash = {
        USD: cashDrawer.cashUSD,
        LBP: cashDrawer.cashLBP
    };
    
    // حساب الباقي بالعملة المفضلة
    let changeAmount = changeNeeded;
    let changeCurrency = preferredChangeCurrency;
    
    // إذا كانت العملة مختلفة، نحتاج للتحويل
    if (paymentCurrency !== preferredChangeCurrency) {
        if (paymentCurrency === 'USD' && preferredChangeCurrency === 'LBP') {
            changeAmount = changeNeeded * settings.exchangeRate;
        } else if (paymentCurrency === 'LBP' && preferredChangeCurrency === 'USD') {
            changeAmount = changeNeeded / settings.exchangeRate;
        }
    }
    
    // التحقق من توفر النقدية المطلوبة
    const canGiveChange = availableCash[changeCurrency] >= changeAmount;
    
    // إذا لم تتوفر النقدية بالعملة المطلوبة، نجرب العملة الأخرى
    if (!canGiveChange) {
        const alternateCurrency = changeCurrency === 'USD' ? 'LBP' : 'USD';
        let alternateAmount;
        
        if (changeCurrency === 'USD') {
            alternateAmount = changeAmount * settings.exchangeRate;
        } else {
            alternateAmount = changeAmount / settings.exchangeRate;
        }
        
        if (availableCash[alternateCurrency] >= alternateAmount) {
            return {
                change: alternateAmount,
                currency: alternateCurrency,
                canGiveChange: true,
                breakdown: null,
                note: `تم إعطاء الباقي بعملة ${alternateCurrency === 'USD' ? 'الدولار' : 'الليرة'} لعدم توفر النقدية بالعملة المطلوبة`
            };
        }
    }
    
    // إذا لم تكف النقدية، نحاول التوزيع بين العملتين
    if (!canGiveChange && changeNeeded > 0) {
        const breakdown = calculateMixedCurrencyChange(changeNeeded, paymentCurrency);
        return {
            change: changeNeeded,
            currency: paymentCurrency,
            canGiveChange: breakdown.possible,
            breakdown: breakdown,
            note: breakdown.possible ? 'سيتم إعطاء الباقي بعملات مختلطة' : 'لا توجد نقدية كافية لإعطاء الباقي'
        };
    }
    
    return {
        change: changeAmount,
        currency: changeCurrency,
        canGiveChange: canGiveChange,
        breakdown: null
    };
}

function calculateMixedCurrencyChange(changeNeeded, originalCurrency) {
    let remainingChange = changeNeeded;
    const breakdown = { USD: 0, LBP: 0, possible: false };
    
    // إذا كان الدفع بالدولار، نعطي أولاً من الدولار ثم الليرة
    if (originalCurrency === 'USD') {
        const usdAvailable = Math.min(cashDrawer.cashUSD, remainingChange);
        breakdown.USD = usdAvailable;
        remainingChange -= usdAvailable;
        
        if (remainingChange > 0) {
            const lbpNeeded = remainingChange * settings.exchangeRate;
            if (cashDrawer.cashLBP >= lbpNeeded) {
                breakdown.LBP = lbpNeeded;
                remainingChange = 0;
            }
        }
    } else {
        // إذا كان الدفع بالليرة، نعطي أولاً من الليرة ثم الدولار
        const lbpAvailable = Math.min(cashDrawer.cashLBP, remainingChange);
        breakdown.LBP = lbpAvailable;
        remainingChange -= lbpAvailable;
        
        if (remainingChange > 0) {
            const usdNeeded = remainingChange / settings.exchangeRate;
            if (cashDrawer.cashUSD >= usdNeeded) {
                breakdown.USD = usdNeeded;
                remainingChange = 0;
            }
        }
    }
    
    breakdown.possible = remainingChange <= 0.01; // نسامح فلوس قليلة جداً
    return breakdown;
}

function updateCashDrawer(amountReceived, currency, changeGiven, changeCurrency) {
    // إضافة المبلغ المستلم
    if (currency === 'USD') {
        cashDrawer.cashUSD += amountReceived;
    } else {
        cashDrawer.cashLBP += amountReceived;
    }
    
    // خصم الباقي المُعطى
    if (changeGiven > 0) {
        if (changeCurrency === 'USD') {
            cashDrawer.cashUSD -= changeGiven;
        } else {
            cashDrawer.cashLBP -= changeGiven;
        }
    }
    
    // تسجيل المعاملة
    addCashDrawerTransaction({
        timestamp: new Date().toISOString(),
        type: 'sale',
        amountReceived: amountReceived,
        receivedCurrency: currency,
        changeGiven: changeGiven,
        changeCurrency: changeCurrency,
        balanceAfter: {
            USD: cashDrawer.cashUSD,
            LBP: cashDrawer.cashLBP
        }
    });
    
    cashDrawer.lastUpdate = new Date().toISOString();
    saveToStorage('cashDrawer', cashDrawer);
}

