function savePurchase(payNow) {
    const supplierId = parseInt(document.getElementById('purchaseSupplier').value);
    const date = document.getElementById('purchaseDate').value || new Date().toISOString().split('T')[0];
    const dueDate = document.getElementById('purchaseDueDate').value || '';
    const currency = document.getElementById('purchaseCurrency').value || 'USD';
    const rate = Number(document.getElementById('purchaseRate').value) || settings.exchangeRate;
    const items = Array.from(document.querySelectorAll('.purchase-item-product')).map((sel, i)=>{
        return {
            productId: parseInt(sel.value),
            quantity: Math.max(1, parseInt(document.querySelectorAll('.purchase-item-qty')[i].value)||1),
            price: Number(document.querySelectorAll('.purchase-item-price')[i].value)||0
        };
    });

    if (!supplierId || items.length === 0) {
        showMessage(getText('msg-choose-supplier-add-items'), 'error');
        return;
    }

    // حساب الإجمالي
    const { total, totalUSD } = calcPurchaseTotals(items, currency, rate);

    // إنشاء الفاتورة
    const bill = {
        id: createRecordId('pu'),
        supplierId, date, dueDate,
        currency, rate,
        items,
        total,
        totalUSD,
        paidUSD: 0,
        status: 'unpaid'
    };
    recalcPurchaseStatus(bill);

    // تحديث المخزون
    items.forEach(it => {
        const pr = products.find(p => p.id === it.productId);
        if (pr) {
            addPackStockToProduct(pr, it.quantity || 0);
            try { enqueueSyncOp('products', 'upsert', pr.id, pr); } catch(_) {}
        }
    });

    // حفظ الفاتورة
    purchases.push(bill);
    try { enqueueSyncOp('purchases', 'upsert', bill.id, bill); } catch(_) {}
    saveAllData();

    // الدفع الآن (اختياري)
    if (payNow) {
        const payCurrency = currency; // تبسيط: الدفع بنفس عملة الفاتورة الآن
        const amount = total;
        const payUSD = toUSD(amount, payCurrency, rate);
        bill.paidUSD += payUSD;
        recalcPurchaseStatus(bill);
        supplierPayments.push({
            id: createRecordId('sp'),
            supplierId,
            date: new Date().toISOString(),
            currency: payCurrency,
            amount,
            rate,
            appliedTo: [{ billId: bill.id, amountUSD: payUSD }],
            method: 'cash'
        });
        try { enqueueSyncOp('supplierPayments', 'upsert', supplierPayments[supplierPayments.length - 1].id, supplierPayments[supplierPayments.length - 1]); } catch(_) {}
        recordSupplierPaymentCash(amount, payCurrency, 'cash', `دفعة للمورد Bill#${bill.id}`);
        saveAllData();
    }

    loadProducts();
    loadPurchases();
    hideModal('purchaseModal');
    showMessage(getText('purchase-invoice-saved'));
}

function showMessage(message, type = 'success') {
    const messageDiv = document.createElement('div');
    messageDiv.className = `${type}-message`;
    
    let iconClass = 'exclamation';
    if (type === 'success') iconClass = 'check';
    else if (type === 'error') iconClass = 'times';
    else if (type === 'warning') iconClass = 'exclamation-triangle';
    else if (type === 'info') iconClass = 'info';
    
    const icon = document.createElement('i');
    icon.className = `fas fa-${iconClass}-circle`;
    messageDiv.textContent = '';
    messageDiv.appendChild(icon);
    messageDiv.appendChild(document.createTextNode(' ' + String(message == null ? '' : message)));
    
    document.body.appendChild(messageDiv);
    
    setTimeout(() => {
        messageDiv.remove();
    }, 3000);
}

// When import succeeds we may want to allow login immediately even if
// the renderer's license-status check is slightly delayed or hits
// filesystem timing issues. Use this flag to bypass the live check once
// an import has succeeded in this session.
let __licenseForcedActive = false;

// ============================================================
// Load all user data from Firestore
// ============================================================
async function migrateUserDataV1ToV2IfNeeded(userId) {
    try {
        if (!window.firebaseDbInstance || !userId) return false;
        const meta = await window.firebaseDbInstance.getUserDataMeta(userId);
        if (meta && Number(meta.schemaVersion || 1) >= 2 && meta.migrationComplete) return false;

        // Read legacy doc once (V1 arrays)
        const legacySnap = await window.firebaseDb.collection('userData').doc(userId).get();
        if (!legacySnap.exists) {
            // Initialize V2 empty meta if nothing exists
            await window.firebaseDbInstance.v2InitEmptyUserData(userId);
            return true;
        }
        const legacy = legacySnap.data() || {};

        // If legacy doc is already small (no arrays) just mark V2
        const hasAnyArray = Array.isArray(legacy.products) || Array.isArray(legacy.customers) || Array.isArray(legacy.sales) ||
            Array.isArray(legacy.suppliers) || Array.isArray(legacy.purchases) || Array.isArray(legacy.supplierPayments) ||
            Array.isArray(legacy.purchaseReturns) || Array.isArray(legacy.supplierLedger);
        if (!hasAnyArray) {
            await window.firebaseDbInstance.v2InitEmptyUserData(userId);
            return true;
        }

        console.log('🧭 Migrating legacy userData -> V2 subcollections...');
        const makeOps = (entity, arr) => (Array.isArray(arr) ? arr.map(obj => ({
            entity,
            op: 'upsert',
            docId: (obj && (obj.id != null ? obj.id : (obj.invoiceNumber || obj.date || Math.random().toString(36).slice(2)))) ,
            data: (obj && typeof obj === 'object') ? { ...obj, id: (obj.id != null ? obj.id : undefined) } : obj
        })) : []);

        const opsAll = []
            .concat(makeOps('products', legacy.products))
            .concat(makeOps('customers', legacy.customers))
            .concat(makeOps('sales', legacy.sales))
            .concat(makeOps('suppliers', legacy.suppliers))
            .concat(makeOps('purchases', legacy.purchases))
            .concat(makeOps('supplierPayments', legacy.supplierPayments))
            .concat(makeOps('purchaseReturns', legacy.purchaseReturns))
            .concat(makeOps('supplierLedger', legacy.supplierLedger));

        // Write in chunks (Firestore batch limit)
        let idx = 0;
        while (idx < opsAll.length) {
            const chunk = opsAll.slice(idx, idx + 450).map(op => ({
                ...op,
                data: _cleanForFirestore(op.data)
            }));
            await window.firebaseDbInstance.v2BatchWrite(userId, chunk);
            idx += chunk.length;
            // Yield to UI thread
            await new Promise(r => setTimeout(r, 10));
        }

        // Save small docs
        try {
            const settingsClean = _cleanForFirestore(legacy.settings || {});
            const cd = legacy.cashDrawer || {};
            await window.firebaseDbInstance.saveAllUserData(userId, {
                settings: settingsClean,
                cashDrawer: _cleanForFirestore({ cashUSD: cd.cashUSD || 0, cashLBP: cd.cashLBP || 0 })
            });
        } catch (_) {}

        // Remove heavy arrays from legacy root doc (keeps only meta + lastUpdated)
        try {
            const del = firebase.firestore.FieldValue.delete();
            await window.firebaseDb.collection('userData').doc(userId).set({
                products: del,
                customers: del,
                sales: del,
                suppliers: del,
                purchases: del,
                supplierPayments: del,
                purchaseReturns: del,
                supplierLedger: del,
                cashDrawer: del,
                settings: del,
                schemaVersion: 2,
                migrationComplete: true,
                lastUpdated: firebase.firestore.FieldValue.serverTimestamp()
            }, { merge: true });
        } catch (e) {
            console.warn('Legacy root cleanup failed:', e);
        }

        console.log('✅ Migration to V2 complete.');
        return true;
    } catch (e) {
        console.warn('migrateUserDataV1ToV2IfNeeded failed:', e);
        return false;
    }
}

async function v2DownloadCollectionToLocal(userId, entity, storageKey, pageSize = 500, maxDocs = 5000, orderField = 'updatedAt', orderDir = 'asc') {
    try {
        if (!window.firebaseDb || !userId) return false;
        const col = window.firebaseDb.collection('userData').doc(userId).collection(entity);
        let docs = [];
        let last = null;
        while (docs.length < maxDocs) {
            let q = col.orderBy(orderField, orderDir).limit(pageSize);
            if (last) q = q.startAfter(last);
            const snap = await q.get();
            if (snap.empty) break;
            snap.docs.forEach(d => {
                const data = d.data() || {};
                if (data && data.id == null) data.id = isNaN(Number(d.id)) ? d.id : Number(d.id);
                docs.push(data);
            });
            last = snap.docs[snap.docs.length - 1];
            await new Promise(r => setTimeout(r, 10));
        }
        if (Array.isArray(docs)) {
            if (storageKey === 'products') {
                let deletedSet = await getDeletedProductIdSet();
                if (!deletedSet || !deletedSet.size) deletedSet = window.__deletedProductIds || new Set();
                window.__deletedProductIds = deletedSet;
                const prev = filterOutDeletedProducts(loadFromStorage('products', []) || [], deletedSet);
                const docsFiltered = filterOutDeletedProducts(docs, deletedSet);
                let merged = _mergeProductsById(prev, docsFiltered);
                merged = repairProductsFromPurchases(merged, typeof purchases !== 'undefined' ? purchases : loadFromStorage('purchases', []), typeof suppliers !== 'undefined' ? suppliers : loadFromStorage('suppliers', []));
                saveToStorage(storageKey, merged);
            } else {
                const localExisting = loadFromStorage(storageKey, []);
                const merged = _mergeEntitiesById(localExisting, docs);
                saveToStorage(storageKey, merged);
            }
        }
        return true;
    } catch (e) {
        console.warn('v2DownloadCollectionToLocal failed:', entity, e);
        // Fallback: simple one-shot fetch (no order/pagination)
        try {
            if (!window.firebaseDb || !userId) return false;
            const col = window.firebaseDb.collection('userData').doc(userId).collection(entity);
            const snap = await col.limit(maxDocs).get();
            const docs = snap.docs.map(d => {
                const data = d.data() || {};
                if (data && data.id == null) data.id = isNaN(Number(d.id)) ? d.id : Number(d.id);
                return data;
            });
            if (storageKey === 'products') {
                let deletedSet = await getDeletedProductIdSet();
                if (!deletedSet || !deletedSet.size) deletedSet = window.__deletedProductIds || new Set();
                window.__deletedProductIds = deletedSet;
                const prev = filterOutDeletedProducts(loadFromStorage('products', []) || [], deletedSet);
                const docsFiltered = filterOutDeletedProducts(docs, deletedSet);
                let merged = _mergeProductsById(prev, docsFiltered);
                merged = repairProductsFromPurchases(merged, loadFromStorage('purchases', []), loadFromStorage('suppliers', []));
                saveToStorage(storageKey, merged);
            } else {
                const localExisting = loadFromStorage(storageKey, []);
                const merged = _mergeEntitiesById(localExisting, docs);
                saveToStorage(storageKey, merged);
            }
            return true;
        } catch (e2) {
            console.warn('v2DownloadCollectionToLocal fallback failed:', entity, e2);
            return false;
        }
    }
}

function _entityUpdatedMs(entity) {
    if (!entity || typeof entity !== 'object') return 0;
    if (typeof entity.clientUpdatedAt === 'number' && isFinite(entity.clientUpdatedAt)) return entity.clientUpdatedAt;
    try {
        const u = entity.updatedAt;
        if (u == null) return 0;
        if (typeof u === 'number' && isFinite(u)) return u < 1e12 ? u * 1000 : u;
        if (typeof u.toMillis === 'function') return u.toMillis();
        if (typeof u.seconds === 'number') return u.seconds * 1000 + Math.floor((u.nanoseconds || 0) / 1e6);
    } catch (_) {}
    return 0;
}

function _mergeEntitiesById(existing, incoming) {
    const base = Array.isArray(existing) ? existing.slice() : [];
    const byId = new Map();
    base.forEach(x => { if (x && x.id != null) byId.set(String(x.id), x); });
    (Array.isArray(incoming) ? incoming : []).forEach(x => {
        if (!x || x.id == null) return;
        const id = String(x.id);
        const local = byId.get(id);
        if (!local) {
            byId.set(id, x);
            return;
        }
        const localMs = _entityUpdatedMs(local);
        const incomingMs = _entityUpdatedMs(x);
        if (incomingMs > localMs) byId.set(id, x);
        else if (incomingMs === localMs && incomingMs === 0) byId.set(id, { ...local, ...x });
        else byId.set(id, local);
    });
    return Array.from(byId.values());
}

/** حقول لا تُستبدل بقيمة فارغة من السحابة أبداً */
function _pickNonEmpty(locVal, incVal) {
    const L = String(locVal || '').trim();
    const I = String(incVal || '').trim();
    if (L) return locVal;
    if (I) return incVal;
    return locVal != null ? locVal : incVal;
}

/** آخر وقت تعديل معروف للمنتج (محلي clientUpdatedAt أو updatedAt من السحابة) — للدمج بدون استبدال مخزون أحدث بقديم */
function _productUpdatedMs(p) {
    if (!p || typeof p !== 'object') return 0;
    if (typeof p.clientUpdatedAt === 'number' && isFinite(p.clientUpdatedAt)) return p.clientUpdatedAt;
    try {
        const u = p.updatedAt;
        if (u == null) return 0;
        if (typeof u === 'number' && isFinite(u)) return u < 1e12 ? u * 1000 : u;
        if (typeof u.toMillis === 'function') return u.toMillis();
        if (typeof u.seconds === 'number') return u.seconds * 1000 + Math.floor((u.nanoseconds || 0) / 1e6);
    } catch (_) {}
    return 0;
}

/** يُستدعى بعد أي تغيير كمية/IMEI محلي حتى يفوز الدمج على بيانات سحابة قديمة بعد Refresh */
function touchProductClientTimestamp(product) {
    try {
        if (!product || typeof product !== 'object') return;
        product.clientUpdatedAt = Date.now();
    } catch (_) {}
}

/** دمج منتجات: لا يمسح الحقول الكاملة بمستند سحابة ناقص (بعد أخطاء مزامنة قديمة) */
function _mergeProductsById(existing, incoming) {
    const byId = new Map();
    (Array.isArray(existing) ? existing : []).forEach(p => {
        if (p && p.id != null) byId.set(String(p.id), { ...p });
    });
    (Array.isArray(incoming) ? incoming : []).forEach(inc => {
        if (!inc || inc.id == null) return;
        const id = String(inc.id);
        const loc = byId.get(id);
        if (!loc) {
            byId.set(id, { ...inc });
            return;
        }
        const locMs = _productUpdatedMs(loc);
        const incMs = _productUpdatedMs(inc);
        const merged = { ...loc, ...inc };
        merged.name = _pickNonEmpty(loc.name, inc.name);
        merged.category = _pickNonEmpty(loc.category, inc.category);
        merged.expiryDate = _pickNonEmpty(loc.expiryDate, inc.expiryDate);
        merged.barcode = _pickNonEmpty(loc.barcode, inc.barcode);
        merged.supplierName = _pickNonEmpty(loc.supplierName, inc.supplierName);
        if (String(loc.name || '').trim() && !String(inc.name || '').trim()) merged.name = loc.name;
        // المخزون وـ IMEI: لا تُستبدل نسخة أحدث (بعد بيع أوفلاين) بنسخة سحابة لم تُزامن بعد
        if (locMs > incMs) {
            merged.stock = loc.stock;
            if (loc.imeiList) merged.imeiList = loc.imeiList;
            if (loc.imeiTracking != null) merged.imeiTracking = loc.imeiTracking;
            if (typeof loc.clientUpdatedAt === 'number') merged.clientUpdatedAt = loc.clientUpdatedAt;
        } else if (incMs > locMs) {
            merged.stock = inc.stock;
            if (inc.imeiList) merged.imeiList = inc.imeiList;
            if (inc.imeiTracking != null) merged.imeiTracking = inc.imeiTracking;
        } else {
            // نفس الطابع الزمني: لا نستخدم Math.min — كان يُسقط تعديل المخزون اليدوي (زيادة الكمية)
            if (typeof inc.clientUpdatedAt === 'number' && isFinite(inc.clientUpdatedAt)) {
                merged.stock = inc.stock;
            } else if (typeof loc.clientUpdatedAt === 'number' && isFinite(loc.clientUpdatedAt)) {
                merged.stock = loc.stock;
            } else {
                const ls = Number(loc.stock), isn = Number(inc.stock);
                if (!isNaN(ls) && !isNaN(isn)) merged.stock = Math.max(ls, isn);
                else merged.stock = loc.stock != null ? loc.stock : (inc.stock != null ? inc.stock : 0);
            }
        }
        if (merged.stock === undefined || merged.stock === null) merged.stock = loc.stock != null ? loc.stock : 0;
        const puL = Number(loc.priceUSD) || 0;
        const puI = Number(inc.priceUSD) || 0;
        merged.priceUSD = puI > 0 ? puI : (puL > 0 ? puL : (loc.priceUSD != null ? loc.priceUSD : inc.priceUSD));
        if (merged.priceLBP === undefined || merged.priceLBP === null) merged.priceLBP = loc.priceLBP != null ? loc.priceLBP : 0;
        if (merged.costUSD === undefined || merged.costUSD === null) merged.costUSD = loc.costUSD != null ? loc.costUSD : 0;
        if (!merged.prices && loc.prices) merged.prices = loc.prices;
        if (!String(merged.supplier || '').trim() && String(loc.supplier || '').trim()) merged.supplier = loc.supplier;
        if (!merged.imageUrl && loc.imageUrl) merged.imageUrl = loc.imageUrl;
        if (!merged.createdAt && loc.createdAt) merged.createdAt = loc.createdAt;
        const uL = _productUpdatedMs(loc);
        const uI = _productUpdatedMs(inc);
        merged.updatedAt = Math.max(uL, uI);
        byId.set(id, merged);
    });
    return Array.from(byId.values());
}

/**
 * فهرس استعادة: من كل فواتير البيع (المحلية + النسخ الاحتياطي) نسترجع الاسم والسعر كما بيع فعلياً
 */
function _buildProductRecoveryFromSales() {
    const byPid = new Map();
    const add = (pid, name, priceUSD, priceLBP, ts) => {
        if (pid == null || pid === '') return;
        const id = String(pid);
        const n = String(name || '').trim();
        if (!n || n.length < 2) return;
        const prev = byPid.get(id) || { name: '', priceUSD: 0, priceLBP: 0, ts: 0 };
        const t = ts ? new Date(ts).getTime() : 0;
        const longer = n.length > String(prev.name || '').length;
        const newer = t >= prev.ts;
        byPid.set(id, {
            name: (longer || newer) ? n : prev.name,
            priceUSD: priceUSD > 0 ? priceUSD : prev.priceUSD,
            priceLBP: priceLBP > 0 ? priceLBP : prev.priceLBP,
            ts: Math.max(t, prev.ts)
        });
    };
    const scanSales = arr => {
        if (!Array.isArray(arr)) return;
        arr.forEach(sale => {
            const items = sale && sale.items;
            if (!Array.isArray(items)) return;
            items.forEach(it => {
                const pid = it && (it.id != null ? it.id : it.productId);
                const name = it && (it.name || it.productName);
                const usd = Number(it.finalPriceUSD != null ? it.finalPriceUSD : it.originalPriceUSD) || 0;
                const rate = (typeof settings !== 'undefined' && settings.exchangeRate) ? Number(settings.exchangeRate) : 89500;
                const lbp = usd > 0 ? Math.round(usd * rate) : 0;
                add(pid, name, usd, lbp, sale.timestamp || sale.date);
            });
        });
    };
    try { scanSales(typeof sales !== 'undefined' ? sales : []); } catch (_) {}
    try { scanSales(loadFromStorage('sales', [])); } catch (_) {}
    try { scanSales(loadFromStorage('sales_backup', [])); } catch (_) {}
    return byPid;
}

function _isPlaceholderProductName(name) {
    const s = String(name || '').trim();
    if (s.length < 2) return true;
    if (/ناقص|Incomplete|فاتورة شراء\s*#|Item \(see supplier\)/i.test(s)) return true;
    return false;
}

/** استعادة كاملة: مبيعات → مشتريات (كل الأسطر) — لا تستبدل اسماً صالحاً أبداً */
function recoverProductsFromHistory(productsArr, purchasesArr, suppliersArr) {
    const fromSales = _buildProductRecoveryFromSales();
    const bills = Array.isArray(purchasesArr) ? purchasesArr : [];
    const sups = Array.isArray(suppliersArr) ? suppliersArr : [];
    const purchaseNameByPid = new Map();
    bills.forEach(bill => {
        if (!bill || !Array.isArray(bill.items)) return;
        bill.items.forEach(it => {
            if (!it || it.productId == null) return;
            const id = String(it.productId);
            const n = String(it.name || '').trim();
            if (n.length >= 2) {
                const prev = purchaseNameByPid.get(id) || '';
                if (n.length > prev.length) purchaseNameByPid.set(id, n);
            }
        });
    });
    return (Array.isArray(productsArr) ? productsArr : []).map(p => {
        if (!p || p.id == null) return p;
        const q = { ...p };
        const pid = String(p.id);
        const rec = fromSales.get(pid);
        if (rec && rec.name) {
            if (_isPlaceholderProductName(q.name)) q.name = rec.name;
            if ((!q.priceUSD || q.priceUSD === 0) && rec.priceUSD > 0) {
                q.priceUSD = rec.priceUSD;
                q.priceLBP = rec.priceLBP || Math.round(rec.priceUSD * ((settings && settings.exchangeRate) || 89500));
                if (!q.prices) {
                    const r = (settings && settings.exchangeRate) || 89500;
                    q.prices = {
                        retail: { USD: q.priceUSD, LBP: Math.round(q.priceUSD * r) },
                        wholesale: { USD: q.priceUSD, LBP: Math.round(q.priceUSD * r) },
                        vip: { USD: q.priceUSD, LBP: Math.round(q.priceUSD * r) }
                    };
                }
            }
        }
        const pName = purchaseNameByPid.get(pid);
        if (pName && _isPlaceholderProductName(q.name)) q.name = pName;
        if (!String(q.category || '').trim()) q.category = q.category || 'عام';
        if (q.stock === undefined || q.stock === null) q.stock = 0;
        return q;
    });
}

/** استعادة اسم/كمية/مورد من فواتير الشراء للمنتجات التالفة */
function repairProductsFromPurchases(productsArr, purchasesArr, suppliersArr) {
    if (!Array.isArray(productsArr)) return productsArr || [];
    const bills = Array.isArray(purchasesArr) ? purchasesArr : [];
    const sups = Array.isArray(suppliersArr) ? suppliersArr : [];
    const langEn = (typeof document !== 'undefined' && document.documentElement.lang === 'en');
    return productsArr.map(p => {
        if (!p || p.id == null) return p;
        const q = { ...p };
        const needName = !String(q.name || '').trim();
        const needStock = q.stock === undefined || q.stock === null;
        let matchedBill = false;
        if (needName || needStock || !String(q.supplier || '').trim()) {
            for (let j = bills.length - 1; j >= 0; j--) {
                const bill = bills[j];
                if (!bill || !Array.isArray(bill.items)) continue;
                const it = bill.items.find(x => x && String(x.productId) === String(p.id));
                if (!it) continue;
                matchedBill = true;
                if (needName && String(it.name || '').trim()) q.name = String(it.name).trim();
                if (needStock && it.quantity != null && !isNaN(Number(it.quantity))) q.stock = Number(it.quantity);
                if (needName && !String(q.name || '').trim() && (it.price != null || it.priceUSD != null)) {
                    const pr = Number(it.price != null ? it.price : it.priceUSD);
                    if (!isNaN(pr) && pr > 0) {
                        q.priceUSD = q.priceUSD != null ? q.priceUSD : pr;
                        if (!q.prices && q.priceUSD) {
                            const rate = (typeof settings !== 'undefined' && settings.exchangeRate) ? Number(settings.exchangeRate) : 89500;
                            q.prices = {
                                retail: { USD: q.priceUSD, LBP: Math.round(q.priceUSD * rate) },
                                wholesale: { USD: q.priceUSD, LBP: Math.round(q.priceUSD * rate) },
                                vip: { USD: q.priceUSD, LBP: Math.round(q.priceUSD * rate) }
                            };
                            q.priceLBP = q.prices.retail.LBP;
                        }
                    }
                }
                if (bill.supplierId != null) {
                    if (!String(q.supplier || '').trim()) q.supplier = String(bill.supplierId);
                    const sup = sups.find(s => String(s.id) === String(bill.supplierId));
                    if (sup && String(sup.name || '').trim() && !String(q.supplierName || '').trim()) q.supplierName = String(sup.name).trim();
                }
                break;
            }
        }
        if (!String(q.name || '').trim()) {
            const bc = String(q.barcode || '').trim();
            if (bc && bc.length >= 2 && bc !== 'Not specified') q.name = bc;
        }
        if (!String(q.category || '').trim()) q.category = q.category || (langEn ? 'general' : 'عام');
        if (q.stock === undefined || q.stock === null) q.stock = 0;
        return q;
    });
}

/** دمج فواتير الشراء: لا نرجع paidUSD للخلف (السحابة قد تكون قديمة قبل رفع الدفعة) */
function _mergePurchasesPreservingPayments(existing, incoming) {
    const base = Array.isArray(existing) ? existing.slice() : [];
    const byId = new Map();
    base.forEach(p => { if (p && p.id != null) byId.set(String(p.id), { ...p }); });
    (Array.isArray(incoming) ? incoming : []).forEach(inc => {
        if (!inc || inc.id == null) return;
        const id = String(inc.id);
        const loc = byId.get(id);
        if (loc) {
            const paidLoc = Number(loc.paidUSD) || 0;
            const paidInc = Number(inc.paidUSD) || 0;
            const merged = { ...loc, ...inc };
            merged.paidUSD = Math.max(paidLoc, paidInc);
            if (typeof recalcPurchaseStatus === 'function') recalcPurchaseStatus(merged);
            byId.set(id, merged);
        } else {
            const copy = { ...inc };
            if (typeof recalcPurchaseStatus === 'function') recalcPurchaseStatus(copy);
            byId.set(id, copy);
        }
    });
    return Array.from(byId.values());
}

async function v2DownloadRecentMergeToLocal(userId, entity, storageKey, limit = 2000) {
    try {
        if (!window.firebaseDb || !userId) return false;
        const col = window.firebaseDb.collection('userData').doc(userId).collection(entity);
        const snap = await col.orderBy('updatedAt', 'desc').limit(limit).get();
        if (snap.empty) return true;
        const incoming = snap.docs.map(d => {
            const data = d.data() || {};
            if (data && data.id == null) data.id = isNaN(Number(d.id)) ? d.id : Number(d.id);
            return data;
        });
        const existing = loadFromStorage(storageKey, []);
        if (storageKey === 'purchases') {
            const merged = _mergePurchasesPreservingPayments(existing, incoming);
            saveToStorage(storageKey, merged);
            return true;
        }
        if (storageKey === 'products') {
            let deletedSet = await getDeletedProductIdSet();
            if (!deletedSet || !deletedSet.size) deletedSet = window.__deletedProductIds || new Set();
            window.__deletedProductIds = deletedSet;
            const inMemory = (typeof products !== 'undefined' && Array.isArray(products)) ? products : [];
            const existingUnion = _mergeProductsById(existing, inMemory);
            const existingFiltered = filterOutDeletedProducts(existingUnion, deletedSet);
            const incomingFiltered = filterOutDeletedProducts(incoming, deletedSet);
            const idsBefore = new Set();
            existingFiltered.forEach(p => { if (p && p.id != null) idsBefore.add(String(p.id)); });
            try {
                const uid = getCurrentUserId();
                const bkKey = uid ? `pos_${uid}_products_autobackup` : 'products_autobackup';
                idbSet(bkKey, existingFiltered).catch(() => {});
            } catch (_) {}
            let merged = _mergeProductsById(existingFiltered, incomingFiltered);
            merged = recoverProductsFromHistory(merged, typeof purchases !== 'undefined' ? purchases : loadFromStorage('purchases', []), typeof suppliers !== 'undefined' ? suppliers : loadFromStorage('suppliers', []));
            merged = repairProductsFromPurchases(merged, typeof purchases !== 'undefined' ? purchases : loadFromStorage('purchases', []), typeof suppliers !== 'undefined' ? suppliers : loadFromStorage('suppliers', []));
            const idsAfter = new Set();
            merged.forEach(p => { if (p && p.id != null) idsAfter.add(String(p.id)); });
            if (idsBefore.size > 0 && idsAfter.size < idsBefore.size) {
                console.warn('[products] Prevented ID loss after sync — reverting to pre-merge union');
                merged = _mergeProductsById(existingFiltered, merged);
                saveToStorage(storageKey, merged);
            } else {
                saveToStorage(storageKey, merged);
            }
            try {
                window.__posCatalogLog = window.__posCatalogLog || [];
                window.__posCatalogLog.push({ t: Date.now(), action: 'merge_products', localCount: existing.length, memCount: inMemory.length, cloudIncoming: incoming.length, mergedCount: merged.length });
                if (window.__posCatalogLog.length > 80) window.__posCatalogLog.shift();
            } catch (_) {}
            return true;
        }
        const merged = _mergeEntitiesById(existing, incoming);
        saveToStorage(storageKey, merged);
        if (storageKey === 'customers') {
            try {
                const localDebt = _customersDebtTotal(existing);
                const incomingDebt = _customersDebtTotal(incoming);
                const mergedDebt = _customersDebtTotal(merged);
                console.log(`[customers][merge] local=${localDebt.toFixed(2)} incoming=${incomingDebt.toFixed(2)} merged=${mergedDebt.toFixed(2)} rows=${merged.length}`);
            } catch (_) {}
        }
        return true;
    } catch (e) {
        if (typeof _isFirestoreLimitError === 'function' && _isFirestoreLimitError(e)) {
            try { window.__firestoreLimitExceeded = true; } catch (_) {}
        }
        console.warn('v2DownloadRecentMergeToLocal failed:', entity, e && (e.message || e.code));
        return false;
    }
}

function stopPeriodicSyncFromCloud() {
    if (typeof window !== 'undefined' && window._periodicSyncInterval) {
        clearInterval(window._periodicSyncInterval);
        window._periodicSyncInterval = null;
    }
}

// فترة المزامنة الدورية من السحابة — زيادة الفترة لتقليل قراءات Firestore بدون التأثير على الاستخدام اليومي
// كانت 120000ms (كل دقيقتين)، الآن نجعلها كل 5 دقائق لتقليل عدد الـ reads إلى أقل من النصف تقريباً.
const PERIODIC_SYNC_INTERVAL_MS = 300000;

// آخر نشاط للمستخدم (حركة في الواجهة) لتقليل المزامنة عندما لا يكون هناك استخدام فعلي
window.__lastUserActivityAt = window.__lastUserActivityAt || Date.now();
['click','keydown','mousemove','touchstart'].forEach(evt => {
    window.addEventListener(evt, () => { window.__lastUserActivityAt = Date.now(); }, { passive: true });
});

function _isFirestoreLimitError(e) {
    if (!e || typeof e !== 'object') return false;
    const code = (e.code || e.message || '').toString().toLowerCase();
    const msg = (e.message || '').toString().toLowerCase();
    return /resource-exhausted|quota|limit exceeded|too many|read.?limit/i.test(code) || /resource-exhausted|quota|limit exceeded|too many|read.?limit/i.test(msg);
}

function startPeriodicSyncFromCloud(userId) {
    stopPeriodicSyncFromCloud();
    if (!userId || !window.firebaseDbInstance) return;
    window._periodicSyncInterval = setInterval(async function runPeriodicSync() {
        if (document.visibilityState !== 'visible') return;
        // لا تعمل مزامنة دورية إذا كان الجهاز Offline لتجنّب أخطاء غير ضرورية
        if (typeof navigator !== 'undefined' && navigator.onLine === false) return;
        // إذا لم يكن هناك أي نشاط للمستخدم منذ أكثر من 10 دقائق، نخفّف المزامنة تلقائياً
        try {
            const lastAct = window.__lastUserActivityAt || 0;
            if (lastAct && Date.now() - lastAct > 10 * 60 * 1000) {
                return;
            }
        } catch (_) {}
        // userId = data owner (admin); sub-user uid differs — still run sync for this loaded store
        const effOwner = (typeof getEffectiveDataOwnerId === 'function' ? getEffectiveDataOwnerId() : null) || userId;
        if (!effOwner || String(userId) !== String(effOwner)) return;
        const uid = (typeof currentUser !== 'undefined' && currentUser && currentUser.uid) ? currentUser.uid : null;
        if (!uid) return;
        if (window.__firestoreLimitExceeded) {
            const limitTime = window.__firestoreLimitExceededTime || 0;
            if (Date.now() - limitTime < 15 * 60 * 1000) return;
            window.__firestoreLimitExceeded = false;
            window.__firestoreLimitExceededTime = 0;
        }
        try {
            // Push pending local writes first to avoid stale cloud snapshots overwriting fresh local balances.
            try { await flushSyncQueue({ strict: true }); } catch (e) { console.warn('[periodic-sync] flush before merge failed:', e && (e.message || e.code || e)); }
            try { await mergeCloudDeletedProductIdsIntoLocal(userId); } catch (e) { console.warn('[periodic-sync] tombstones:', e && (e.message || e.code || e)); }
            await v2DownloadRecentMergeToLocal(userId, 'sales', 'sales', 2000);
            await v2DownloadRecentMergeToLocal(userId, 'products', 'products', 3000);
            try {
                products = getCurrentProducts();
                if (document.getElementById('pos') && document.getElementById('pos').classList.contains('active') && typeof displayProducts === 'function') {
                    const si = document.getElementById('productSearch');
                    displayProducts(si && si.value ? si.value.trim() : '');
                }
            } catch (_) {}
            await v2DownloadRecentMergeToLocal(userId, 'customers', 'customers', 3000);
            try { logCustomerBalanceSnapshot('periodic_sync_after_customers_merge', loadFromStorage('customers', []) || []); } catch (_) {}
            if (window.__firestoreLimitExceeded) return;
            const tenantId = getSharedCashboxDocId();
            const summary = tenantId && window.firebaseDbInstance.getTenantCashboxSummary
                ? await window.firebaseDbInstance.getTenantCashboxSummary(tenantId)
                : null;
            if (summary && typeof cashDrawer !== 'undefined') {
                // لا تقم أبداً بكتابة رصيد الصندوق المحلي بقيم أقدم من التغييرات الحالية (مبيعات/مرتجعات/حركات يدوية)
                // افترض أن السحابة ترسل lastUpdate عند توفره، وإلا فاعتمد على الرصيد المحلي للحفاظ على دقة الصندوق
                let canApplyCloudSummary = true;
                try {
                    const localFromStorage = (typeof loadFromStorage === 'function')
                        ? loadFromStorage('cashDrawer', null)
                        : null;
                    const localLast = (localFromStorage && localFromStorage.lastUpdate) || cashDrawer.lastUpdate;
                    const cloudLast = (typeof getCashDrawerDocLastUpdateIso === 'function' ? getCashDrawerDocLastUpdateIso(summary) : null) || summary.lastUpdate;
                    if (localLast && cloudLast) {
                        const localTime = new Date(localLast).getTime();
                        const cloudTime = new Date(cloudLast).getTime();
                        if (isFinite(localTime) && isFinite(cloudTime) && cloudTime <= localTime) {
                            // ملخص السحابة أقدم أو يساوي المحلي – تجاهله حتى لا نرجع إلى رصيد قديم (مثلاً رصيد إقفال اليوم السابق)
                            canApplyCloudSummary = false;
                        }
                    }
                } catch (_) {
                    // في حال حدوث أي خطأ في المقارنة، افترض أن المحلي هو الأصح ولا تطبق السحابة بشكل أعمى
                }
                
                if (canApplyCloudSummary) {
                    cashDrawer.cashUSD = readCashSummaryUSD(summary);
                    cashDrawer.cashLBP = readCashSummaryLBP(summary);
                    __cashboxSyncedUSDCents = toUSDCents(cashDrawer.cashUSD);
                    __cashboxSyncedLBPUnits = toLBPUnits(cashDrawer.cashLBP);
                    if (summary.lastUpdate) {
                        cashDrawer.lastUpdate = summary.lastUpdate;
                    }
                    if (typeof saveToStorage === 'function') saveToStorage('cashDrawer', cashDrawer);
                    if (typeof updateCashDrawerDisplay === 'function') updateCashDrawerDisplay();
                } else {
                    // احتفظ بالرصيد المحلي لأنه أحدث من السحابة
                    if (typeof updateCashDrawerDisplay === 'function') updateCashDrawerDisplay();
                }
            }
            window.__firestoreLimitExceeded = false;
        } catch (e) {
            if (_isFirestoreLimitError(e)) {
                window.__firestoreLimitExceeded = true;
                window.__firestoreLimitExceededTime = Date.now();
                if (!window.__firestoreLimitToastShown) {
                    window.__firestoreLimitToastShown = true;
                    try { showNotification(typeof getText === 'function' ? (getText('msg-using-local-data') || 'البيانات المعروضة من النسخة المحلية (تجاوز حد القراءة مؤقتاً)') : 'البيانات المعروضة من النسخة المحلية (تجاوز حد القراءة مؤقتاً)', 'info', 5000); } catch (_) {}
                }
            }
            console.warn('Periodic sync from cloud failed:', e && (e.message || e.code));
        }
    }, PERIODIC_SYNC_INTERVAL_MS);
}

async function v2IsCloudCollectionEmpty(userId, entity) {
    try {
        if (!window.firebaseDb || !userId) return true;
        const snap = await window.firebaseDb.collection('userData').doc(userId).collection(entity).limit(1).get();
        return snap.empty;
    } catch (e) {
        // If we can't read, treat as empty for seeding decision? safer to NOT seed.
        console.warn('v2IsCloudCollectionEmpty failed:', entity, e);
        return false;
    }
}

async function v2SeedCloudFromLocalIfEmpty(userId, entity, localItems, getDocId) {
    try {
        if (!window.firebaseDbInstance || !userId) return false;
        if (!Array.isArray(localItems) || localItems.length === 0) return false;
        const isEmpty = await v2IsCloudCollectionEmpty(userId, entity);
        if (!isEmpty) return false;

        console.log(`☁️ Seeding cloud '${entity}' from local (${localItems.length})...`);
        let idx = 0;
        while (idx < localItems.length) {
            const slice = localItems.slice(idx, idx + 450);
            const ops = slice.map(obj => {
                const docId = getDocId(obj);
                return { entity, op: 'upsert', docId: String(docId), data: obj };
            }).filter(op => op.docId && op.docId !== 'undefined');
            if (ops.length) {
                await window.firebaseDbInstance.v2BatchWrite(userId, ops);
            }
            idx += slice.length;
            await new Promise(r => setTimeout(r, 20));
        }
        console.log(`✅ Cloud seed complete for '${entity}'.`);
        return true;
    } catch (e) {
        console.warn('v2SeedCloudFromLocalIfEmpty failed:', entity, e);
        return false;
    }
}

async function loadUserDataFromFirestore(userId) {
    if (!userId) {
        console.warn('⚠️ Cannot load user data: userId missing');
        return;
    }
    
    // Wait for Firebase DB to be ready
    if (!window.firebaseDbInstance) {
        console.log('⏳ Waiting for Firebase DB initialization...');
        let attempts = 0;
        while (!window.firebaseDbInstance && attempts < 10) {
            await new Promise(resolve => setTimeout(resolve, 500));
            attempts++;
        }
        if (!window.firebaseDbInstance) {
            console.warn('⚠️ Cannot load user data: Firebase DB not initialized after waiting');
            return;
        }
    }

    // Verify user is authenticated
    if (!window.firebaseAuthInstance || !window.firebaseAuthInstance.isAuthenticated()) {
        console.warn('⚠️ Cannot load user data: User not authenticated');
        return;
    }

    // Verify userId matches data owner (current user loads own; sub-user loads parent's)
    const currentUser = window.firebaseAuthInstance.getCurrentUser();
    if (!currentUser) {
        console.warn('⚠️ Cannot load user data: no current user');
        return;
    }
    const parentAdminId = getParentAdminId(currentUser);
    const allowed = (userId === currentUser.uid) || (parentAdminId && userId === parentAdminId);
    if (!allowed) {
        console.warn('⚠️ Cannot load user data: userId mismatch');
        return;
    }

    try {
        try { window.__productsInitialSyncInFlight = true; } catch (_) {}
        window.__deletedProductIds = await getDeletedProductIdSet();
        if (!window.__deletedProductIds || !window.__deletedProductIds.size) window.__deletedProductIds = new Set();
        try {
            if (navigator.onLine !== false) {
                await mergeCloudDeletedProductIdsIntoLocal(userId);
                window.__deletedProductIds = await getDeletedProductIdSet();
                if (!window.__deletedProductIds || !window.__deletedProductIds.size) window.__deletedProductIds = new Set();
            }
        } catch (e) {
            console.warn('[loadUserDataFromFirestore] cloud tombstones merge:', e && (e.message || e.code || e));
        }
        console.log('📥 Loading user data from Firestore...');
        // One-time migration: V1 -> V2
        try { await migrateUserDataV1ToV2IfNeeded(userId); } catch(_) {}
        const firestoreData = await window.firebaseDbInstance.loadAllUserData(userId);
        const isRestricted = !!(firestoreData && firestoreData.__restricted);
        if (isRestricted) {
            try { window.__firestoreRestricted = true; } catch (_) {}
            _syncPermissionPaused = true;
            _deletedProductsMergePermissionBlocked = true;
            _restrictedFirestoreAccessLogged = true;
        } else {
            try { window.__firestoreRestricted = false; } catch (_) {}
        }
        
        const isV2 = firestoreData && firestoreData.__schemaVersion === 2;
        // Data isolation: if V2, do NOT overwrite large arrays with empty Firestore payload.
        if (!isV2) {
            products = firestoreData?.products || [];
            // Restore product images from local storage (Firestore strips base64; images stay local)
            const localProducts = loadFromStorage('products', []);
            if (Array.isArray(localProducts)) {
                const imageById = {};
                localProducts.forEach(p => { if (p.id != null && p.imageUrl) imageById[p.id] = p.imageUrl; });
                products.forEach(p => { if (imageById[p.id]) p.imageUrl = imageById[p.id]; });
            }
            customers = firestoreData?.customers || [];
            sales = firestoreData?.sales || [];
            suppliers = firestoreData?.suppliers || [];
            purchases = firestoreData?.purchases || [];
        } else {
            // Use local device data as primary offline store
            products = loadFromStorage('products', []) || [];
            customers = loadFromStorage('customers', []) || [];
            logCustomerBalanceSnapshot('load_local_v2_primary', customers);
            sales = loadFromStorage('sales', []) || [];
            suppliers = loadFromStorage('suppliers', []) || [];
            purchases = loadFromStorage('purchases', []) || [];
            supplierPayments = loadFromStorage('supplierPayments', []) || [];
            purchaseReturns = loadFromStorage('purchaseReturns', []) || [];
            supplierLedger = loadFromStorage('supplierLedger', []) || [];
            const cashTxLocal = loadFromStorage('cashDrawerTx', []) || [];
            if (Array.isArray(cashTxLocal) && cashTxLocal.length) {
                cashDrawer.transactions = cashTxLocal;
            }

            // If local has data but cloud is empty (common when upgrading), seed once to cloud
            if (navigator.onLine !== false && !isRestricted) {
                // Critical: flush pending queued writes first, so old cloud data cannot override fresh local debt after refresh.
                try { await flushSyncQueue({ strict: true }); } catch (e) { console.warn('[customers] pre-sync flush failed before cloud merge:', e && (e.message || e.code || e)); }
                try {
                    await v2SeedCloudFromLocalIfEmpty(userId, 'products', products, (x) => (x && x.id != null ? x.id : ''));
                    await v2SeedCloudFromLocalIfEmpty(userId, 'customers', customers, (x) => (x && x.id != null ? x.id : ''));
                    await v2SeedCloudFromLocalIfEmpty(userId, 'suppliers', suppliers, (x) => (x && x.id != null ? x.id : ''));
                    await v2SeedCloudFromLocalIfEmpty(userId, 'purchases', purchases, (x) => (x && x.id != null ? x.id : ''));
                    await v2SeedCloudFromLocalIfEmpty(userId, 'supplierPayments', supplierPayments, (x) => (x && x.id != null ? x.id : ''));
                    await v2SeedCloudFromLocalIfEmpty(userId, 'purchaseReturns', purchaseReturns, (x) => (x && x.id != null ? x.id : ''));
                    await v2SeedCloudFromLocalIfEmpty(userId, 'supplierLedger', supplierLedger, (x) => (x && x.id != null ? x.id : ''));
                    // Sales could be large; seed only if there is *no* cloud sales at all
                    await v2SeedCloudFromLocalIfEmpty(userId, 'sales', sales.slice(0, 5000), (x) => (x && (x.id != null ? x.id : (x.invoiceNumber || ''))));

                    // Seed cashbox manual tx (skip sale/refund)
                    const txSeed = (Array.isArray(cashDrawer.transactions) ? cashDrawer.transactions : [])
                        .filter(t => {
                            const tt = String(t.type || '').toLowerCase();
                            return tt && tt !== 'sale' && tt !== 'refund';
                        })
                        .map(t => ensureCashTxId({ ...(t || {}) }));
                    await v2SeedCloudFromLocalIfEmpty(userId, 'cashDrawerTx', txSeed.slice(0, 5000), (x) => (x && x.id != null ? x.id : ''));
                } catch (_) {}
            }

            // If device is empty (new device), download core collections from Firestore
            if (navigator.onLine !== false && !isRestricted) {
                const shouldDownloadIfHydratedAndEmpty = (storageKey, arr) => {
                    const hydrated = isLargeStorageHydrated(storageKey);
                    if (!hydrated) return false;
                    return !Array.isArray(arr) || arr.length === 0;
                };
                const needsProducts = shouldDownloadIfHydratedAndEmpty('products', products);
                const needsCustomers = shouldDownloadIfHydratedAndEmpty('customers', customers);
                const needsSuppliers = shouldDownloadIfHydratedAndEmpty('suppliers', suppliers);
                const needsPurchases = shouldDownloadIfHydratedAndEmpty('purchases', purchases);
                const needsSales = shouldDownloadIfHydratedAndEmpty('sales', sales);
                const needsSupplierPayments = shouldDownloadIfHydratedAndEmpty('supplierPayments', supplierPayments);
                const needsPurchaseReturns = shouldDownloadIfHydratedAndEmpty('purchaseReturns', purchaseReturns);
                const needsSupplierLedger = shouldDownloadIfHydratedAndEmpty('supplierLedger', supplierLedger);
                const needsCashTx = shouldDownloadIfHydratedAndEmpty('cashDrawerTx', cashTxLocal);

                if (needsProducts || needsCustomers || needsSuppliers || needsPurchases || needsSales || needsCashTx) {
                    console.log('⬇️ V2 initial sync: downloading cloud data for this account...');
                }

                if (needsProducts) await v2DownloadCollectionToLocal(userId, 'products', 'products', 500, 20000);
                if (needsCustomers) await v2DownloadCollectionToLocal(userId, 'customers', 'customers', 500, 20000);
                if (needsSuppliers) await v2DownloadCollectionToLocal(userId, 'suppliers', 'suppliers', 500, 20000);
                if (needsPurchases) await v2DownloadCollectionToLocal(userId, 'purchases', 'purchases', 500, 20000);
                if (needsSupplierPayments) await v2DownloadCollectionToLocal(userId, 'supplierPayments', 'supplierPayments', 500, 20000);
                if (needsPurchaseReturns) await v2DownloadCollectionToLocal(userId, 'purchaseReturns', 'purchaseReturns', 500, 20000);
                if (needsSupplierLedger) await v2DownloadCollectionToLocal(userId, 'supplierLedger', 'supplierLedger', 500, 20000);
                // Sales can be large: download the most recent window first
                if (needsSales) await v2DownloadCollectionToLocal(userId, 'sales', 'sales', 500, 2000, 'updatedAt', 'desc');
                // Cashbox transactions (manual operations): recent window
                if (needsCashTx) await v2DownloadCollectionToLocal(userId, 'cashDrawerTx', 'cashDrawerTx', 500, 5000, 'updatedAt', 'desc');

                // Reload locals after download
                products = filterOutDeletedProducts(loadFromStorage('products', []) || [], window.__deletedProductIds || new Set());
                customers = loadFromStorage('customers', []) || [];
                logCustomerBalanceSnapshot('load_after_v2_download', customers);
                sales = loadFromStorage('sales', []) || [];
                suppliers = loadFromStorage('suppliers', []) || [];
                purchases = loadFromStorage('purchases', []) || [];
                supplierPayments = loadFromStorage('supplierPayments', []) || [];
                purchaseReturns = loadFromStorage('purchaseReturns', []) || [];
                supplierLedger = loadFromStorage('supplierLedger', []) || [];
                const cashTxAfter = loadFromStorage('cashDrawerTx', []) || [];
                if (Array.isArray(cashTxAfter) && cashTxAfter.length) {
                    cashDrawer.transactions = cashTxAfter;
                }
                try {
                    products = recoverProductsFromHistory(products, purchases, suppliers);
                    products = repairProductsFromPurchases(products, purchases, suppliers);
                    saveToStorage('products', products);
                } catch (_) {}
            }

            // Always do a lightweight "recent updates" refresh (merge) so data stays consistent across devices.
            if (navigator.onLine !== false && !isRestricted) {
                try { await v2DownloadRecentMergeToLocal(userId, 'products', 'products', 3000); } catch(_) {}
                try { await v2DownloadRecentMergeToLocal(userId, 'customers', 'customers', 3000); } catch(_) {}
                try { await v2DownloadRecentMergeToLocal(userId, 'suppliers', 'suppliers', 2000); } catch(_) {}
                try { await v2DownloadRecentMergeToLocal(userId, 'purchases', 'purchases', 2000); } catch(_) {}
                try { await v2DownloadRecentMergeToLocal(userId, 'supplierPayments', 'supplierPayments', 2000); } catch(_) {}
                try { await v2DownloadRecentMergeToLocal(userId, 'purchaseReturns', 'purchaseReturns', 2000); } catch(_) {}
                try { await v2DownloadRecentMergeToLocal(userId, 'supplierLedger', 'supplierLedger', 2000); } catch(_) {}
                try { await v2DownloadRecentMergeToLocal(userId, 'sales', 'sales', 2000); } catch(_) {}
                try { await v2DownloadRecentMergeToLocal(userId, 'cashDrawerTx', 'cashDrawerTx', 3000); } catch(_) {}

                // Reload locals after merge refresh
                products = filterOutDeletedProducts(loadFromStorage('products', []) || [], window.__deletedProductIds || new Set());
                customers = loadFromStorage('customers', []) || [];
                logCustomerBalanceSnapshot('load_after_v2_recent_merge', customers);
                sales = loadFromStorage('sales', []) || [];
                suppliers = loadFromStorage('suppliers', []) || [];
                purchases = loadFromStorage('purchases', []) || [];
                try {
                    products = recoverProductsFromHistory(products, purchases, suppliers);
                    products = repairProductsFromPurchases(products, purchases, suppliers);
                    saveToStorage('products', products);
                } catch (_) {}
                supplierPayments = loadFromStorage('supplierPayments', []) || [];
                purchaseReturns = loadFromStorage('purchaseReturns', []) || [];
                supplierLedger = loadFromStorage('supplierLedger', []) || [];
                const cashTxMerge = loadFromStorage('cashDrawerTx', []) || [];
                if (Array.isArray(cashTxMerge) && cashTxMerge.length) cashDrawer.transactions = cashTxMerge;
            }
            // always try to flush any queued ops after login
            if (!isRestricted) {
                try { scheduleSyncFlush(); } catch(_) {}
            }
        }
        // للحسابات الجديدة: الصندوق يبدأ من 0. للحسابات الموجودة: نستخدم القيم المخزنة
        const firestoreCashDrawer = firestoreData?.cashDrawer || {};
        const hasStoredCash = firestoreCashDrawer.cashUSD !== undefined || firestoreCashDrawer.cashLBP !== undefined;
        const txV2 = isV2 ? (loadFromStorage('cashDrawerTx', []) || []) : null;
        const cloudDrawerIso = typeof getCashDrawerDocLastUpdateIso === 'function'
            ? getCashDrawerDocLastUpdateIso(firestoreCashDrawer)
            : (firestoreCashDrawer.lastUpdate || null);
        cashDrawer = {
            cashUSD: hasStoredCash ? readCashSummaryUSD(firestoreCashDrawer) : 0,
            cashLBP: hasStoredCash ? readCashSummaryLBP(firestoreCashDrawer) : 0,
            transactions: (isV2 && Array.isArray(txV2)) ? txV2 : (firestoreCashDrawer.transactions || []),
            lastUpdate: cloudDrawerIso || null
        };
        __cashboxSyncedUSDCents = toUSDCents(cashDrawer.cashUSD);
        __cashboxSyncedLBPUnits = toLBPUnits(cashDrawer.cashLBP);
        // إذا كان التخزين المحلي يحتوي على بيانات أحدث (تعديل قبل انتهاء المزامنة) نفضّلها
        try {
            const localCd = loadFromStorage('cashDrawer', null);
            if (localCd && typeof localCd === 'object') {
                const localTs = localCd.lastUpdate;
                const localTime = localTs ? new Date(localTs).getTime() : NaN;
                const cloudTs = cloudDrawerIso;
                const cloudTime = cloudTs ? new Date(cloudTs).getTime() : NaN;
                let preferLocal = false;
                if (localTs && cloudTs && !isNaN(localTime) && !isNaN(cloudTime)) {
                    preferLocal = localTime > cloudTime;
                } else if (localTs && !cloudTs) {
                    // وثيقة السحابة بلا lastUpdate — لا نستخدم وقتًا مزيفًا فيفوز المحلي عند وجوده
                    preferLocal = true;
                }
                if (preferLocal) {
                    cashDrawer.cashUSD = Number(localCd.cashUSD) ?? cashDrawer.cashUSD;
                    cashDrawer.cashLBP = Number(localCd.cashLBP) ?? cashDrawer.cashLBP;
                    cashDrawer.lastUpdate = localCd.lastUpdate;
                    if (Array.isArray(localCd.transactions)) cashDrawer.transactions = localCd.transactions;
                }
            }
        } catch (_) {}
        try {
            if (isV2 && !isRestricted && navigator.onLine !== false) {
                const tid = typeof getSharedCashboxDocId === 'function' ? getSharedCashboxDocId() : null;
                if (tid && window.firebaseDbInstance && typeof window.firebaseDbInstance.getTenantCashboxSummary === 'function') {
                    const tsum = await window.firebaseDbInstance.getTenantCashboxSummary(tid);
                    if (tsum && typeof tsum === 'object') {
                        const tenantIso = typeof getCashDrawerDocLastUpdateIso === 'function' ? getCashDrawerDocLastUpdateIso(tsum) : (tsum.lastUpdate || null);
                        const curIso = cashDrawer.lastUpdate || null;
                        const tT = tenantIso ? new Date(tenantIso).getTime() : NaN;
                        const cT = curIso ? new Date(curIso).getTime() : NaN;
                        const tenantNewer = tenantIso && curIso && !isNaN(tT) && !isNaN(cT) && tT > cT;
                        const useTenantNoLocalTime = tenantIso && !curIso;
                        if (tenantNewer || useTenantNoLocalTime) {
                            cashDrawer.cashUSD = readCashSummaryUSD(tsum);
                            cashDrawer.cashLBP = readCashSummaryLBP(tsum);
                            __cashboxSyncedUSDCents = toUSDCents(cashDrawer.cashUSD);
                            __cashboxSyncedLBPUnits = toLBPUnits(cashDrawer.cashLBP);
                            cashDrawer.lastUpdate = tenantIso;
                        }
                    }
                }
            }
        } catch (_) {}
        if (!cashDrawer.lastUpdate) {
            try { cashDrawer.lastUpdate = new Date().toISOString(); } catch (_) {}
        }
        supplierPayments = isV2 ? (loadFromStorage('supplierPayments', []) || []) : (firestoreData?.supplierPayments || []);
        purchaseReturns = isV2 ? (loadFromStorage('purchaseReturns', []) || []) : (firestoreData?.purchaseReturns || []);
        supplierLedger = isV2 ? (loadFromStorage('supplierLedger', []) || []) : (firestoreData?.supplierLedger || []);
        
        // Update settings (merge with existing)
        if (firestoreData?.settings) {
                settings = { ...settings, ...getSanitizedSettingsForCurrentUser(firestoreData.settings) };
        }
        
        // Final reconciliation: do not let a late Firestore load overwrite a product added during login/sync.
        try {
            const deletedSet = await getDeletedProductIdSet();
            window.__deletedProductIds = deletedSet;
            const latestLocalProducts = filterOutDeletedProducts(loadFromStorage('products', []) || [], deletedSet);
            const latestMemoryProducts = filterOutDeletedProducts((typeof products !== 'undefined' && Array.isArray(products)) ? products : [], deletedSet);
            let mergedProducts = _mergeProductsById(latestLocalProducts, latestMemoryProducts);
            try {
                const uid = getCurrentUserId();
                const bkKey = uid ? `pos_${uid}_products_autobackup` : 'products_autobackup';
                const backup = await idbGet(bkKey);
                if (Array.isArray(backup) && backup.length)
                    mergedProducts = _mergeProductsById(filterOutDeletedProducts(backup, deletedSet), mergedProducts);
            } catch (_) {}
            mergedProducts = filterOutDeletedProducts(mergedProducts, deletedSet);
            mergedProducts = recoverProductsFromHistory(mergedProducts, purchases, suppliers);
            mergedProducts = repairProductsFromPurchases(mergedProducts, purchases, suppliers);
            products = mergedProducts;
            try {
                window.__posCatalogLog = window.__posCatalogLog || [];
                window.__posCatalogLog.push({
                    t: Date.now(),
                    action: 'firestore_load_reconcile_products',
                    localCount: latestLocalProducts.length,
                    memoryCount: latestMemoryProducts.length,
                    finalCount: mergedProducts.length
                });
                if (window.__posCatalogLog.length > 80) window.__posCatalogLog.shift();
            } catch (_) {}
        } catch (e) {
            console.warn('[loadUserDataFromFirestore] products reconcile failed:', e);
        }

        // Save to localStorage (avoid overwriting large sets in V2 with empties)
        saveToStorage('products', products);
        saveToStorage('customers', customers);
        logCustomerBalanceSnapshot('load_final_saved_local', customers);
        saveToStorage('sales', sales);
        saveToStorage('suppliers', suppliers);
        saveToStorage('purchases', purchases);
        saveToStorage('cashDrawer', cashDrawer);
        saveToStorage('supplierPayments', supplierPayments);
        saveToStorage('purchaseReturns', purchaseReturns);
        saveToStorage('supplierLedger', supplierLedger);
        if (firestoreData?.settings) {
            saveToStorage('settings', settings);
        }
        
        // تحديث عرض سعر الصرف في الهيدر ونموذج الإعدادات بعد تحميل Firestore
        const rate = Number(settings.exchangeRate) || 89500;
        const rateSuffix = (document.documentElement.lang || 'ar') === 'en' ? 'LBP' : 'L';
        const exchangeRateEl = document.getElementById('exchangeRate');
        if (exchangeRateEl && typeof getText === 'function') exchangeRateEl.textContent = getText('exchange-rate') + ': ' + rate.toLocaleString() + ' ' + rateSuffix;
        const currentRateEl = document.getElementById('currentExchangeRate');
        if (currentRateEl) currentRateEl.textContent = rate.toLocaleString();
        const exchangeRateInput = document.getElementById('exchangeRateInput');
        if (exchangeRateInput) exchangeRateInput.value = rate;
        
        window.__dataLoadedForUserId = userId;
        console.log(`✅ Loaded user data from Firestore: ${products.length} products, ${customers.length} customers, ${sales.length} sales`);
        try { refreshProductConsumersAfterAsyncLoad(products); } catch (_) {}
        startPeriodicSyncFromCloud(userId);
    } catch (error) {
        const isLimitError = typeof _isFirestoreLimitError === 'function' && _isFirestoreLimitError(error);
        const errorMsg = String((error && (error.message || error.code)) || '');
        const isPermissionDenied = _isPermissionDeniedFirestoreError(error) ||
            /missing or insufficient permissions|permission-denied/i.test(errorMsg);
        if (isLimitError) try { window.__firestoreLimitExceeded = true; } catch (_) {}
        if (isPermissionDenied) {
            console.warn('⚠️ Firestore restricted for current user scope — using local data + backup');
        } else {
            console.error('❌ Error loading user data from Firestore:', error && (error.message || error.code));
        }
        /* لا نمسح البيانات المحلية عند فشل الشبكة أو تجاوز حد القراءة — الاعتماد على النسخة المحلية */
        try {
            const locP = loadFromStorage('products', []) || [];
            const locC = loadFromStorage('customers', []) || [];
            const locS = loadFromStorage('sales', []) || [];
            const locSup = loadFromStorage('suppliers', []) || [];
            const locPur = loadFromStorage('purchases', []) || [];
            let mergedP = Array.isArray(locP) ? locP.slice() : [];
            try {
                const uid = userId;
                const bkKey = uid ? `pos_${uid}_products_autobackup` : 'products_autobackup';
                const bk = await idbGet(bkKey);
                if (Array.isArray(bk) && bk.length) mergedP = _mergeProductsById(bk, mergedP);
            } catch (_) {}
            if (mergedP.length || (Array.isArray(locC) && locC.length) || (Array.isArray(locS) && locS.length)) {
                products = mergedP;
                customers = Array.isArray(locC) ? locC : [];
                logCustomerBalanceSnapshot('load_fallback_local', customers);
                sales = Array.isArray(locS) ? locS : [];
                suppliers = Array.isArray(locSup) ? locSup : [];
                purchases = Array.isArray(locPur) ? locPur : [];
                supplierPayments = loadFromStorage('supplierPayments', []) || [];
                purchaseReturns = loadFromStorage('purchaseReturns', []) || [];
                supplierLedger = loadFromStorage('supplierLedger', []) || [];
                cashDrawer = loadFromStorage('cashDrawer', null) || {
                    cashUSD: 0, cashLBP: 0, transactions: [], lastUpdate: new Date().toISOString()
                };
                saveToStorage('products', products);
                window.__dataLoadedForUserId = userId;
                if (isLimitError) {
                    try { showNotification(typeof getText === 'function' ? (getText('msg-using-local-data') || 'البيانات المعروضة من النسخة المحلية (تجاوز حد القراءة مؤقتاً)') : 'البيانات المعروضة من النسخة المحلية (تجاوز حد القراءة مؤقتاً)', 'info', 6000); } catch (_) {}
                }
                console.warn('⚠️ Firestore unavailable — using local data + backup');
                try { scheduleSyncFlush(); } catch (_) {}
                try { refreshProductConsumersAfterAsyncLoad(products); } catch (_) {}
                startPeriodicSyncFromCloud(userId);
            } else {
                products = [];
                customers = [];
                sales = [];
                suppliers = [];
                purchases = [];
                cashDrawer = { cashUSD: 0, cashLBP: 0, transactions: [], lastUpdate: new Date().toISOString() };
                supplierPayments = [];
                purchaseReturns = [];
                supplierLedger = [];
                saveToStorage('products', products);
                saveToStorage('customers', customers);
                saveToStorage('sales', sales);
                saveToStorage('suppliers', suppliers);
                saveToStorage('purchases', purchases);
                saveToStorage('cashDrawer', cashDrawer);
                saveToStorage('supplierPayments', supplierPayments);
                saveToStorage('purchaseReturns', purchaseReturns);
                saveToStorage('supplierLedger', supplierLedger);
                console.log('⚠️ No local data — initializing empty state');
            }
        } catch (e2) {
            console.error(e2);
        }
    } finally {
        try { window.__productsInitialSyncInFlight = false; } catch (_) {}
    }
}

// ============================================================
// نظام Subdomain Routing - روابط خاصة لكل مستخدم
// ============================================================

// توجيه المستخدم لرابطه الخاص بعد تسجيل الدخول
window.redirectToUserSubdomain = function(subdomain) {
    if (!subdomain) return;
    
    const currentPath = window.location.pathname;
    const expectedPath = `/${subdomain}`;
    
    // إذا لم يكن المستخدم في رابط subdomain الخاص به، قم بتوجيهه
    if (currentPath !== expectedPath && !currentPath.startsWith(expectedPath + '/')) {
        const newUrl = `${window.location.origin}${expectedPath}`;
        console.log(`🔄 Redirecting to user subdomain: ${newUrl}`);
        window.history.replaceState({}, '', newUrl);
    }
};

// Also define as regular function for hoisting
function redirectToUserSubdomain(subdomain) {
    window.redirectToUserSubdomain(subdomain);
}

// Hide auth-checking overlay once we know auth state (keeps session on reload without showing login first)
function hideAuthChecking() {
    const el = document.getElementById('authChecking');
    if (el) el.classList.add('hidden');
}

// تأخير عرض شاشة الدخول عند null لتفادي وميض الـ login عند Reload (Firebase يعيد null ثم المستخدم بعد استعادة الجلسة)
const AUTH_SHOW_LOGIN_DELAY_MS = 700;

// Best-effort heartbeat for online presence; avoids noisy permission-denied loops.
async function safeUpdateLastSeen(firebaseUser) {
    try {
        if (!window.firebaseDb || !firebaseUser || !firebaseUser.uid) return;
        const authUid = window.firebaseAuthInstance?.auth?.currentUser?.uid || '';
        if (!authUid || authUid !== firebaseUser.uid) return;
        if (window.__lastSeenBlockedForUid && window.__lastSeenBlockedForUid === firebaseUser.uid) return;

        await window.firebaseDb.collection('users').doc(firebaseUser.uid).update({
            lastSeen: firebase.firestore.FieldValue.serverTimestamp()
        });
    } catch (e) {
        const code = String(e && e.code || '');
        if (code.includes('permission-denied')) {
            window.__lastSeenBlockedForUid = firebaseUser && firebaseUser.uid ? firebaseUser.uid : null;
            return; // avoid noisy console output for expected rule blocks
        }
        console.warn('Error updating lastSeen:', e);
    }
}

function showLoginScreenAfterAuthResolved() {
    hideAuthChecking();
    document.getElementById('mainScreen')?.classList.remove('active');
    document.getElementById('loginScreen')?.classList.add('active');
}

function cancelPendingShowLoginTimeout() {
    if (window._authShowLoginTimeoutId) {
        clearTimeout(window._authShowLoginTimeoutId);
        window._authShowLoginTimeoutId = null;
    }
}

