            totalPurchases: 'إجمالي المشتريات',
            totalSettlements: 'إجمالي التسويات',
            transactions: 'المعاملات',
            date: 'التاريخ',
            type: 'النوع',
            amount: 'المبلغ',
            desc: 'الوصف',
            purchase: 'شراء',
            pay: 'دفع',
