// عرض سجل المعاملات (دخول/خروج) للعميل
function openCustomerTransactions(customerId) {
    const customer = customers.find(c => c.id === customerId);
    if (!customer) return;
    const logs = loadFromStorage('customerLogs', {});
    const key = String(customerId);
    let list = Array.isArray(logs[key]) ? logs[key] : [];
    // ترتيب تنازلي بحسب التاريخ والوقت
    list = list.sort((a, b) => new Date(b.timestamp || 0) - new Date(a.timestamp || 0));
    const lang = document.documentElement.lang || 'ar';
    const tHead = lang === 'en'
        ? { title: 'Customer Log', datetime: 'Date & Time', type: 'Type', user: 'User', notes: 'Notes', empty: 'No logs' }
        : { title: 'سجل العميل', datetime: 'التاريخ والوقت', type: 'النوع', user: 'المستخدم', notes: 'ملاحظات', empty: 'لا يوجد سجلات' };
    function actionLabel(action) {
        if (!action) return '-';
        if (lang !== 'en') return action;
        var s = String(action).trim();
        if (s === 'دين') return 'Debt';
        if (s === 'تسديد') return 'Payment';
        if (/استرجاع.*دين/i.test(s)) return 'Refund (Credit)';
        if (s === 'تسوية دين سابق') return 'Debt settlement';
        return action;
    }
    function userLabel(u) {
        if (u == null) return '-';
        if (typeof u === 'object') return (u && u.name) ? String(u.name) : '-';
        return String(u);
    }
    function noteLabel(note) {
        if (!note || lang !== 'en') return note || '-';
        var n = String(note);
        var m = n.match(/فاتورة\s+([^\s]+)\s+بقيمة\s+([^\s]+)/);
        if (m) return 'Invoice ' + m[1] + ' for ' + m[2];
        if (/^تسديد\s+/i.test(n)) return n.replace(/^تسديد\s+/i, 'Payment ');
        if (/تم استرجاع/i.test(n)) return n.replace(/تم استرجاع بقيمة\s*/i, 'Refund ').replace(/من الفاتورة\s*/i, 'from invoice ');
        if (/تم تسوية/i.test(n)) return n.replace(/تم تسوية\s*/i, 'Settled ').replace(/\s*عبر بيع نقدي/i, ' via cash sale');
        return n;
    }
    let html = `
        <div class="report-stats">
            <div class="stat-item">
                <h4>${tHead.title}</h4>
                <p class="stat-value">${escapeHtml(customer.name || '')}</p>
            </div>
        </div>
        <table class="report-table">
            <thead>
                <tr>
                    <th>${tHead.datetime}</th>
                    <th>${tHead.type}</th>
                    <th>${tHead.user}</th>
                    <th>${tHead.notes}</th>
                </tr>
            </thead>
            <tbody>
                ${list.length ? list.map((r, index) => `
                    <tr ${index === 0 ? 'style="background-color:#e3f2fd;font-weight:700;"' : ''}>
                        <td>${escapeHtml(r.timestamp || '-')}</td>
                        <td>${escapeHtml(actionLabel(r.action) || '')}</td>
                        <td>${escapeHtml(userLabel(r.user) || '')}</td>
                        <td>${escapeHtml(noteLabel(r.note) || '')}</td>
                    </tr>
                `).join('') : `<tr><td colspan="4">${escapeHtml(tHead.empty)}</td></tr>`}
            </tbody>
        </table>
    `;
    const reportContent = document.getElementById('reportContent');
    const reportTitle = document.getElementById('reportTitle');
    setReportModalCreditHistoryMode(false);
    if (reportTitle) reportTitle.textContent = tHead.title;
    if (reportContent) reportContent.innerHTML = html;
    showModal('reportModal');
}

function appendCustomerLogEntry(customerId, actionAr, actionEn, noteAr, noteEn) {
    try {
        if (customerId == null) return;
        const logs = loadFromStorage('customerLogs', {});
        const key = String(customerId);
        if (!Array.isArray(logs[key])) logs[key] = [];
        const isEn = (document.documentElement.lang || 'ar') === 'en';
        logs[key].push({
            timestamp: new Date().toLocaleString(),
            action: isEn ? actionEn : actionAr,
            user: (typeof getCurrentUserName === 'function'
                ? getCurrentUserName()
                : (currentUser && currentUser.name) || (typeof currentUser === 'string' ? currentUser : (isEn ? 'User' : 'المستخدم'))),
            note: isEn ? noteEn : noteAr
        });
        saveToStorage('customerLogs', logs);
    } catch (e) {
        console.warn('appendCustomerLogEntry failed:', e);
    }
}

