// وظائف صفحة الفواتير
function loadInvoices() {
    // حمل أحدث بيانات المبيعات من التخزين قبل رسم الفواتير
    sales = getCurrentSales();
    const invoicesTable = document.getElementById('invoicesTable');
    // ترتيب تنازلي بحسب التاريخ والوقت (الأحدث أولاً)
    const sorted = [...sales].sort((a, b) => {
        // استخدام timestamp إذا كان متوفراً، وإلا fallback إلى date
        const timestampA = a.timestamp || a.date || 0;
        const timestampB = b.timestamp || b.date || 0;
        
        const da = new Date(timestampA);
        const db = new Date(timestampB);
        return db - da;
    });
    
    invoicesTable.innerHTML = sorted.map(sale => {
        let status = 'نشطة';
        let statusClass = 'active';
        
        if (sale.cancelled) {
            status = 'ملغاة';
            statusClass = 'cancelled';
        } else if (sale.returned) {
            status = 'مرجعة';
            statusClass = 'returned';
        }
        
        return `
        <tr class="${sale.cancelled ? 'cancelled-row' : ''}">
            <td>${escapeHtml(sale.invoiceNumber || '')}</td>
            <td>${formatDateTime(sale.timestamp || sale.date, sale.paymentMethod)}</td>
            <td>${escapeHtml(sale.customer || '')}</td>
            <td>${formatCurrency(sale.amount)}</td>
            <td>${escapeHtml(sale.paymentMethod || '')}</td>
            <td><span class="status-badge ${statusClass}">${status}</span></td>
            <td>
                <button class="action-btn view-btn" onclick="viewInvoice('${escapeAttr(sale.invoiceNumber || '')}')">عرض</button>
                ${!sale.cancelled && !sale.returned && !isRefundInvoiceNumber(sale.invoiceNumber) ? `
                <button class="action-btn return-btn" onclick="returnInvoice('${escapeAttr(sale.invoiceNumber || '')}')">إرجاع</button>
                ` : ''}
            </td>
        </tr>
        `;
    }).join('');
}

async function returnInvoice(invoiceNumber) {
    products = getCurrentProducts();
    const sale = sales.find(s => s.invoiceNumber === invoiceNumber);
    if (!sale) {
        showNotification('❌ الفاتورة غير موجودة', 'error');
        return;
    }
    
    if (sale.returned) {
        showNotification('❌ الفاتورة مرجعة مسبقاً', 'error');
        return;
    }
    
    if (sale.cancelled) {
        showNotification('❌ لا يمكن إرجاع فاتورة ملغاة', 'error');
        return;
    }
    
    // التحقق من أن الفاتورة ليست من نوع مرتجع (RF-)
    // منع إنشاء "Refund Loop" - لا يمكن عمل مرتجع على فاتورة مرتجع
    if (isRefundInvoiceNumber(sale.invoiceNumber)) {
        showNotification('⚠ لا يمكن عمل مرتجع لفاتورة مرتجع سابق.', 'error');
        return;
    }
    
    const canProceed = await requirePrivilegedActionAuth({
        requiredPermission: 'canViewSales',
        accessDeniedMessage: getText('msg-no-permission-sales') || 'لا تملك صلاحية تنفيذ الاسترجاع.',
        promptMessage: '🔒 ' + (getText('msg-enter-password-return-invoice') || 'أدخل كلمة مرور الحساب لإرجاع الفاتورة:')
    });
    if (!canProceed) {
        return;
    }
    
    if (!(await uiConfirm(getText('confirm-return-invoice').replace('{invoiceNumber}', invoiceNumber), { title: (getText('confirm') || 'Confirm') }))) {
        return;
    }
    
    // إرجاع الفاتورة
    sale.returned = true;
    sale.returnedDate = new Date().toISOString().split('T')[0];
    
    // إرجاع المنتجات للمخزون (ومنها IMEI: إعادة الحالة إلى available — حتى بدون imei على سطر قديم)
    sale.items.forEach(item => {
        const pid = item.productId != null ? item.productId : item.id;
        const product = products.find(p => p.id === pid || String(p.id) === String(pid));
        if (!product) return;
        const qty = Math.max(1, Number(item.quantity) || 1);
        if (product.imeiTracking && Array.isArray(product.imeiList)) {
            if (item.imei) {
                const entry = product.imeiList.find(e => String(e.imei || '').replace(/\s/g, '') === String(item.imei || '').replace(/\s/g, ''));
                if (entry) entry.status = 'available';
            } else {
                restoreImeisAfterReturnByQuantity(product, qty);
            }
            recalcImeiProductStock(product);
        } else {
            addPackStockToProduct(product, qty);
        }
        touchProductClientTimestamp(product);
    });
    
    // إرجاع المبالغ المدفوعة للصندوق (عكس عملية البيع: طرح من الصندوق)
    if (sale.cashDetails) {
        const currency = sale.cashDetails.paymentCurrency;
        const amount = sale.cashDetails.amountPaid;
        
        // عند المرتجع النقدي يجب أن يخرج المبلغ من الصندوق
        if (currency === 'USD') {
            cashDrawer.cashUSD -= amount;
        } else {
            cashDrawer.cashLBP -= amount;
        }
        
        // تسجيل عملية سحب مطابقة لحركة المرتجع
        addCashDrawerTransaction({
            date: new Date().toISOString(),
            type: 'refund',
            amountUSD: currency === 'USD' ? amount : 0,
            amountLBP: currency === 'LBP' ? amount : 0,
            description: `إرجاع مبلغ فاتورة ملغاة ${invoiceNumber}`
        });
    }
    
    // إذا كان دفع جزئي، تقليل الدين من العميل
    if (sale.partialDetails) {
        const customer = customers.find(c => c.id === sale.customerId);
        if (customer) {
            const debtAmount = sale.partialDetails.debtAmount;
            customer.creditBalance = Math.max(0, customer.creditBalance - debtAmount);
            customer.currentDebt = customer.creditBalance;
            touchCustomerClientTimestamp(customer);
            
            // إضافة سجل في تاريخ العميل
            if (!customer.creditHistory) customer.creditHistory = [];
            customer.creditHistory.push({
                date: new Date().toISOString().split('T')[0],
                type: 'cancellation',
                amount: -debtAmount,
                description: creditHistoryDescriptionText('cancel_invoice', { invoice: invoiceNumber })
            });
            await persistCustomerRecord(customer, { requireCloudConfirm: true, context: 'invoice_cancellation_partial' });
            
            // إرجاع المبلغ المدفوع للصندوق (طرح من الصندوق)
            const currency = sale.partialDetails.paymentCurrency;
            const paidAmount = sale.partialDetails.amountPaid;
            
            // عند إلغاء دفع جزئي، يتم رد المدفوع للعميل وبالتالي ينقص الصندوق
            if (currency === 'USD') {
                cashDrawer.cashUSD -= paidAmount;
            } else {
                cashDrawer.cashLBP -= paidAmount;
            }
            
            addCashDrawerTransaction({
                date: new Date().toISOString(),
                type: 'refund',
                amountUSD: currency === 'USD' ? paidAmount : 0,
                amountLBP: currency === 'LBP' ? paidAmount : 0,
                description: `إرجاع مبلغ مدفوع - فاتورة ملغاة ${invoiceNumber}`
            });
        }
    }
    
    // حفظ البيانات
    saveAllData();
    
    // تحديث الواجهات
    loadInvoices();
    updateCashDrawerDisplay();
    displayProducts();
    
    if (document.getElementById('customers').classList.contains('active')) {
        loadCustomers();
    }
    
    // إظهار إشعار مفصل
    let message = `✅ تم إرجاع الفاتورة ${invoiceNumber} بنجاح!

📦 المنتجات أُرجعت للمخزون`;
    
    if (sale.cashDetails) {
        const currency = sale.cashDetails.paymentCurrency;
        const amount = sale.cashDetails.amountPaid;
        message += `
💰 ${formatCurrency(amount, currency)} أُرجع للصندوق`;
    }
    
    if (sale.partialDetails) {
        const customer = customers.find(c => c.id === sale.customerId);
        const debtAmount = sale.partialDetails.debtAmount;
        const paidAmount = sale.partialDetails.amountPaid;
        const currency = sale.partialDetails.paymentCurrency;
        message += `
👤 ${customer?.name}: تم تقليل الدين ${formatCurrency(debtAmount)}
💰 ${formatCurrency(paidAmount, currency)} أُرجع للصندوق`;
    }
    
    showNotification(message, 'success', 6000);
}

function viewInvoice(invoiceNumber) {
    const sale = sales.find(s => s.invoiceNumber === invoiceNumber);
    if (sale) {
        showInvoice(sale);
    }
}

function filterInvoices() {
    const fromDate = document.getElementById('invoicesFromDate').value;
    const toDate = document.getElementById('invoicesToDate').value;
    
    // تأكد من استخدام أحدث بيانات المبيعات
    sales = getCurrentSales();
    let filteredSales = sales;
    
    if (fromDate) {
        filteredSales = filteredSales.filter(sale => {
            try {
                const dateValue = sale.timestamp || sale.date;
                const saleDate = new Date(dateValue);
                return !isNaN(saleDate.getTime()) && saleDate >= new Date(fromDate);
            } catch (error) {
                return false;
            }
        });
    }
    
    if (toDate) {
        filteredSales = filteredSales.filter(sale => {
            try {
                const dateValue = sale.timestamp || sale.date;
                const saleDate = new Date(dateValue);
                return !isNaN(saleDate.getTime()) && saleDate <= new Date(toDate);
            } catch (error) {
                return false;
            }
        });
    }
    
    displayFilteredInvoices(filteredSales);
}

function displayFilteredInvoices(filteredSales) {
    const invoicesTable = document.getElementById('invoicesTable');
    
    // دالة محسنة لتحليل timestamp
    function parseSaleTimestamp(sale) {
        const timestamp = sale.timestamp || sale.date || 0;
        if (!timestamp) return new Date(0);
        
        try {
            // إذا كان timestamp محلي بصيغة ISO
            if (typeof timestamp === 'string' && timestamp.includes('T')) {
                if (!timestamp.includes('Z') && !timestamp.includes('+') && !timestamp.includes('-', 10)) {
                    // timestamp محلي بدون timezone - parse يدوياً
                    const parts = timestamp.split('T');
                    if (parts.length === 2) {
                        const [datePart, timePart] = parts;
                        const [year, month, day] = datePart.split('-').map(Number);
                        const timeWithMs = timePart.includes('.') ? timePart : timePart + '.000';
                        const [timeOnly, ms] = timeWithMs.split('.');
                        const [hours, minutes, seconds] = timeOnly.split(':').map(Number);
                        return new Date(year, month - 1, day, hours, minutes, seconds, Number(ms.padEnd(3, '0')));
                    }
                }
                return new Date(timestamp);
            }
            
            return new Date(timestamp);
        } catch (error) {
            console.warn('Error parsing timestamp:', timestamp, error);
            return new Date(0);
        }
    }
    
    // ترتيب تنازلي بحسب التاريخ والوقت ورقم الفاتورة
    const sorted = [...filteredSales].sort((a, b) => {
        const da = parseSaleTimestamp(a);
        const db = parseSaleTimestamp(b);
        
        // أولاً حسب الوقت
        const timeDiff = db.getTime() - da.getTime();
        if (timeDiff !== 0) return timeDiff;
        
        // ثم حسب رقم الفاتورة (الأحدث أولاً)
        const invoiceA = a.invoiceNumber || '';
        const invoiceB = b.invoiceNumber || '';
        return invoiceB.localeCompare(invoiceA, undefined, { numeric: true });
    });
    
    invoicesTable.innerHTML = sorted.map(sale => {
        const status = sale.cancelled ? 'ملغاة' : 'نشطة';
        const statusClass = sale.cancelled ? 'cancelled' : 'active';
        
        return `
        <tr class="${sale.cancelled ? 'cancelled-row' : ''}">
            <td>${escapeHtml(sale.invoiceNumber || '')}</td>
            <td>${sale.date}</td>
            <td>${escapeHtml(sale.customer || '')}</td>
            <td>${formatCurrency(sale.amount)}</td>
            <td>${escapeHtml(sale.paymentMethod || '')}</td>
            <td><span class="status-badge ${statusClass}">${status}</span></td>
            <td>
                <button class="action-btn view-btn" onclick="viewInvoice('${escapeAttr(sale.invoiceNumber || '')}')">عرض</button>
                ${!sale.cancelled && !sale.returned && !isRefundInvoiceNumber(sale.invoiceNumber) ? `
                <button class="action-btn return-btn" onclick="returnInvoice('${escapeAttr(sale.invoiceNumber || '')}')">إرجاع</button>
                ` : ''}
            </td>
        </tr>
        `;
    }).join('');
}

// ===== نظام Pagination للمنتجات =====

// متغيرات pagination للمنتجات
let productsCurrentPage = 1;
let productsPageSize = 20;
let productsSearchTerm = '';

// تحميل المنتجات مع pagination
function loadProducts() {
    try {
        products = getCurrentProducts();
        if (window.__deletedProductIds && window.__deletedProductIds.size)
            products = filterOutDeletedProducts(products || [], window.__deletedProductIds);
        const before = JSON.stringify(products);
        products = recoverProductsFromHistory(products || [], purchases || [], suppliers || []);
        products = repairProductsFromPurchases(products || [], purchases || [], suppliers || []);
        if (window.__deletedProductIds && window.__deletedProductIds.size)
            products = filterOutDeletedProducts(products || [], window.__deletedProductIds);
        if (JSON.stringify(products) !== before) {
            saveToStorage('products', products);
            products.forEach(p => {
                if (!p || p.id == null) return;
                try { enqueueSyncOp('products', 'upsert', p.id, p); } catch (_) {}
            });
            try { scheduleSyncFlush(); } catch (_) {}
        }
    } catch (_) {}
    setupProductsPagination();
    renderProductsTable();
    applyProductPermissionsUI();
    updateExpiryDashboardAlert();
    try {
        const expiryPage = document.getElementById('expiryManagement');
        if (expiryPage && expiryPage.classList.contains('active')) loadExpiryManagement();
    } catch (_) {}
}

// إعداد pagination للمنتجات
function setupProductsPagination() {
    // تحميل حالة pagination من sessionStorage
    loadProductsPaginationState();
    
    // إعداد event listeners
    setupProductsPaginationEvents();
}

// تحميل حالة pagination من sessionStorage
function loadProductsPaginationState() {
    try {
        const saved = sessionStorage.getItem('productsPaginationState');
        if (saved) {
            const state = JSON.parse(saved);
            productsCurrentPage = state.page || 1;
            productsPageSize = state.pageSize || 20;
            productsSearchTerm = state.searchTerm || '';
        }
    } catch (e) {
        console.warn('Error loading products pagination state:', e);
    }
}

// حفظ حالة pagination في sessionStorage
function saveProductsPaginationState() {
    try {
        const state = {
            page: productsCurrentPage,
            pageSize: productsPageSize,
            searchTerm: productsSearchTerm
        };
        sessionStorage.setItem('productsPaginationState', JSON.stringify(state));
    } catch (e) {
        console.warn('Error saving products pagination state:', e);
    }
}

// إعداد event listeners للـ pagination
function setupProductsPaginationEvents() {
    const bindOnce = (id, handler, key = 'productsPagerBound') => {
        const el = document.getElementById(id);
        if (!el || el.dataset[key] === '1') return;
        el.dataset[key] = '1';
        el.addEventListener('click', handler);
    };
    bindOnce('productsPrevPage', () => goToProductsPage(productsCurrentPage - 1));
    bindOnce('productsNextPage', () => goToProductsPage(productsCurrentPage + 1));
    
    // تعيين القيمة المحفوظة لحجم الصفحة
    const pageSizeSelect = document.getElementById('productsPageSize');
    if (pageSizeSelect && productsPageSize) {
        if (productsPageSize >= 999999) {
            pageSizeSelect.value = 'all';
        } else {
            pageSizeSelect.value = String(productsPageSize);
        }
    }
    
    // تغيير حجم الصفحة
    if (pageSizeSelect && pageSizeSelect.dataset.productsPageSizeBound !== '1') {
        pageSizeSelect.dataset.productsPageSizeBound = '1';
        pageSizeSelect.addEventListener('change', function() {
            if (this.value === 'all') {
                productsPageSize = 999999;
            } else {
                productsPageSize = parseInt(this.value, 10) || 20;
            }
            productsCurrentPage = 1;
            saveProductsPaginationState();
            renderProductsTable();
        });
    }
    
    // البحث في المنتجات
    const productsSearch = document.getElementById('productsSearch');
    if (productsSearch) {
        productsSearch.value = productsSearchTerm;
        updateProductsSearchClearButton();
        if (productsSearch.dataset.productsSearchBound !== '1') {
            productsSearch.dataset.productsSearchBound = '1';
            productsSearch.addEventListener('input', function() {
                productsSearchTerm = this.value.trim().toLowerCase();
                productsCurrentPage = 1;
                updateProductsSearchClearButton();
                saveProductsPaginationState();
                renderProductsTable();
            });
        }
    }
    const productsSearchClear = document.getElementById('productsSearchClear');
    if (productsSearchClear && productsSearchClear.dataset.productsSearchClearBound !== '1') {
        productsSearchClear.dataset.productsSearchClearBound = '1';
        productsSearchClear.addEventListener('click', function() {
            productsSearchTerm = '';
            if (productsSearch) productsSearch.value = '';
            productsCurrentPage = 1;
            updateProductsSearchClearButton();
            saveProductsPaginationState();
            renderProductsTable();
            if (productsSearch) productsSearch.focus();
        });
    }
    
    // إضافة دعم لوحة المفاتيح للتنقل بين الصفحات (عند التركيز على جدول المنتجات)
    const productsTable = document.getElementById('productsTable');
    if (productsTable) {
        const tableContainer = productsTable.parentElement;
        if (tableContainer && tableContainer.dataset.productsKeyboardPagerBound !== '1') {
            tableContainer.dataset.productsKeyboardPagerBound = '1';
            tableContainer.addEventListener('keydown', function(e) {
            const totalPages = getProductsTotalPages();
            
            // السهم الأيمن = الصفحة السابقة (RTL)
            if (e.key === 'ArrowRight' && productsCurrentPage > 1) {
                e.preventDefault();
                goToProductsPage(productsCurrentPage - 1);
            }
            // السهم الأيسر = الصفحة التالية (RTL)
            else if (e.key === 'ArrowLeft' && productsCurrentPage < totalPages) {
                e.preventDefault();
                goToProductsPage(productsCurrentPage + 1);
            }
            // Home = الصفحة الأولى
            else if (e.key === 'Home') {
                e.preventDefault();
                goToProductsPage(1);
            }
            // End = الصفحة الأخيرة
            else if (e.key === 'End') {
                e.preventDefault();
                goToProductsPage(totalPages);
            }
            });
        }
    }
}

function formatProductCategoryLabel(category) {
    const raw = String(category || '').trim();
    const isEn = (document.documentElement.lang || 'ar') === 'en';
    if (!raw || raw === '.' || raw === '-') {
        return getText('uncategorized') || (isEn ? 'Uncategorized' : 'غير مصنّف');
    }
    return raw;
}

function formatProductCategoryCell(category) {
    const label = formatProductCategoryLabel(category);
    const raw = String(category || '').trim();
    if (!raw || raw === '.' || raw === '-') {
        return `<span class="table-empty-value table-category-empty">${escapeHtml(label)}</span>`;
    }
    return escapeHtml(label);
}

function formatProductEmptyCell(value) {
    const raw = String(value || '').trim();
    const notSpec = String(getText('not_specified') || 'Not specified').trim().toLowerCase();
    if (!raw || raw === '.' || raw.toLowerCase() === notSpec) {
        return '<span class="table-empty-value">—</span>';
    }
    return escapeHtml(raw);
}

function buildProductStockCellHtml(product, stockNum, minS) {
    const isEn = (document.documentElement.lang || 'ar') === 'en';
    const stockDisp = escapeHtml(getProductStockDisplay(product));
    if (stockNum <= 0) {
        return `<span class="stock-status-badge stock-status-badge--out">${isEn ? 'Out of stock' : 'نفد المخزون'}</span>`;
    }
    if (stockNum <= minS) {
        return `<span class="stock-status-badge stock-status-badge--low">${isEn ? 'Low stock' : 'مخزون منخفض'}</span><span class="stock-qty-num">${stockDisp}</span>`;
    }
    return `<span class="stock-qty-num">${stockDisp}</span>`;
}

function updateProductsSearchClearButton() {
    const input = document.getElementById('productsSearch');
    const clearBtn = document.getElementById('productsSearchClear');
    if (!input || !clearBtn) return;
    const hasValue = String(input.value || '').trim().length > 0;
    clearBtn.hidden = !hasValue;
}

// الحصول على المنتجات المفلترة (مع ترتيب بحسب أحدث المنتجات أولاً)
function getFilteredProducts() {
    let base = Array.isArray(products) ? products : [];
    if (window.__deletedProductIds && window.__deletedProductIds.size)
        base = filterOutDeletedProducts(base, window.__deletedProductIds);
    
    if (productsSearchTerm) {
        // Avoid calling getProductSupplierLabel() for every product during search filtering,
        // because it performs a .find() over suppliers (O(products * suppliers)).
        // Instead, build an ID->name map once per call and use product.supplierName / supplierId.
        let supplierNameMap = null;
        try {
            if (Array.isArray(suppliers)) {
                supplierNameMap = new Map();
                suppliers.forEach(s => {
                    if (s && s.id != null) supplierNameMap.set(String(s.id), String(s.name || '').trim());
                });
            }
        } catch (_) {}

        base = base.filter(product => {
            const supplierId = product && product.supplier != null ? String(product.supplier) : '';
            const supplierName = product && product.supplierName ? String(product.supplierName) : (supplierNameMap ? (supplierNameMap.get(supplierId) || '') : '');
            const searchableText =
                String(product && product.name ? product.name : '') + ' ' +
                String(product && product.category ? product.category : '') + ' ' +
                String(product && product.barcode ? product.barcode : '') + ' ' +
                String(supplierId || '') + ' ' +
                String(supplierName || '') + ' ' +
                String(product && product.priceUSD != null ? product.priceUSD : '') + ' ' +
                String(product && product.priceLBP != null ? product.priceLBP : '') + ' ' +
                String(product ? getProductStockDisplay(product) : '');

            return searchableText.toLowerCase().includes(productsSearchTerm);
        });
    }
    
    // ترتيب المنتجات بحيث يظهر آخر منتج تمت إضافته في أعلى الجدول
    const sorted = [...base].sort((a, b) => {
        const aTime = a && a.createdAt ? Date.parse(a.createdAt) || 0 : 0;
        const bTime = b && b.createdAt ? Date.parse(b.createdAt) || 0 : 0;
        if (aTime !== bTime) return bTime - aTime;
        const aId = typeof a.id === 'number' ? a.id : 0;
        const bId = typeof b.id === 'number' ? b.id : 0;
        return bId - aId;
    });
    
    return sorted;
}

// الحصول على عدد الصفحات الإجمالي
function getProductsTotalPages() {
    const filteredProducts = getFilteredProducts();
    return Math.max(1, Math.ceil(filteredProducts.length / productsPageSize));
}

// الانتقال إلى صفحة معينة
function goToProductsPage(page) {
    const totalPages = getProductsTotalPages();
    if (page < 1 || page > totalPages) return;
    
    productsCurrentPage = page;
    saveProductsPaginationState();
    renderProductsTable();
    
    // التمرير السلس إلى أعلى الجدول
    const productsTable = document.getElementById('productsTable');
    if (productsTable) {
        productsTable.parentElement?.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }
}

/** اسم المورد في الجدول: supplierName من Firebase، أو البحث بالـ id — لا نعرض الرقم فقط */
function getProductSupplierLabel(product) {
    if (!product) return getText('not_specified') || '—';
    const n = String(product.supplierName || '').trim();
    if (n) return n;
    const idRaw = String(product.supplier || '').trim();
    if (!idRaw) return getText('not_specified') || '—';
    try {
        const list = typeof suppliers !== 'undefined' && Array.isArray(suppliers) ? suppliers : [];
        const sup = list.find(s => String(s.id) === idRaw);
        if (sup && String(sup.name || '').trim()) return String(sup.name).trim();
    } catch (_) {}
    return getText('not_specified') || '—';
}

function patchTableRowsIncremental(tbody, rowModels) {
    if (!tbody) return;
    const existingRows = new Map();
    Array.from(tbody.children).forEach((row) => {
        const k = row && row.dataset ? row.dataset.rowKey : '';
        if (k) existingRows.set(k, row);
    });

    const usedKeys = new Set();
    const frag = document.createDocumentFragment();
    rowModels.forEach((model) => {
        const key = String(model.key);
        usedKeys.add(key);
        const existing = existingRows.get(key);
        if (existing) {
            if (existing.dataset.rowSig !== String(model.sig)) {
                existing.innerHTML = model.html;
                existing.dataset.rowSig = String(model.sig);
            }
            frag.appendChild(existing);
            return;
        }
        const row = document.createElement('tr');
        row.dataset.rowKey = key;
        row.dataset.rowSig = String(model.sig);
        row.innerHTML = model.html;
        frag.appendChild(row);
    });

    existingRows.forEach((row, key) => {
        if (!usedKeys.has(key) && row && row.parentNode === tbody) {
            row.remove();
        }
    });

    tbody.textContent = '';
    tbody.appendChild(frag);
}

// عرض المنتجات في الجدول
function renderProductsTable() {
    const t0 = (typeof performance !== 'undefined' && performance.now) ? performance.now() : Date.now();
    const tbody = document.getElementById('productsTable');
    if (!tbody) return;
    if (!hasProductPermission('canViewProducts')) {
        tbody.innerHTML = '';
        updateProductsPaginationUI(0);
        return;
    }
    tbody.textContent = '';
    
    const filteredProducts = getFilteredProducts();
    const totalPages = Math.max(1, Math.ceil(filteredProducts.length / productsPageSize));
    
    // التأكد من أن الصفحة الحالية صحيحة
    if (productsCurrentPage > totalPages) {
        productsCurrentPage = Math.max(1, totalPages);
    }
    
    // حساب الفهارس
    const start = (productsCurrentPage - 1) * productsPageSize;
    const end = Math.min(start + productsPageSize, filteredProducts.length);
    const pageProducts = filteredProducts.slice(start, end);
    
    // عرض المنتجات
    const rowModels = [];
    const costUnlocked = canCurrentUserViewCosts() && isCostUnlocked();
    const canEditProducts = hasProductPermission('canEditProducts');
    const canDeleteProducts = hasProductPermission('canDeleteProducts');
    let supplierNameMap = null;
    try {
        if (Array.isArray(suppliers)) {
            supplierNameMap = new Map();
            suppliers.forEach(s => {
                if (s && s.id != null) supplierNameMap.set(String(s.id), String(s.name || '').trim());
            });
        }
    } catch (_) {}

    const notSpecified = getText('not_specified') || '—';
    const isEn = (document.documentElement.lang || 'ar') === 'en';
    const canViewProducts = hasProductPermission('canViewProducts');

    resetPortalizedProductActionMenus();
    closeAllProductActionsDropdowns();

    pageProducts.forEach(product => {
        const stockNum = getProductStockNumericForThreshold(product);
        const minS = (product.minStock !== undefined && product.minStock !== null) ? Number(product.minStock) : 5;
        const isLowStock = stockNum <= minS;
        const stockCellHtml = buildProductStockCellHtml(product, stockNum, minS);

        const supplierId = product && product.supplier != null ? String(product.supplier) : '';
        const supplierLabel = product && product.supplierName
            ? String(product.supplierName).trim()
            : (supplierNameMap ? (supplierId ? (supplierNameMap.get(supplierId) || '') : '') : '');
        const viewActionHtml = canViewProducts ? `
                        <button type="button" class="dropdown-action-btn view-btn" onclick="viewProduct(${product.id})">
                            <i class="fas fa-eye"></i> ${getText('view')}
                        </button>` : '';
        const editActionHtml = canEditProducts ? `
                        <button type="button" class="dropdown-action-btn edit-btn" onclick="editProduct(${product.id})">
                            <i class="fas fa-edit"></i> ${getText('edit')}
                        </button>` : '';
        const adjustStockHtml = canEditProducts ? `
                        <button type="button" class="dropdown-action-btn product-log-btn" onclick="adjustProductStock(${product.id})">
                            <i class="fas fa-boxes-stacked"></i> ${getText('adjust-stock') || (isEn ? 'Adjust Stock' : 'تعديل المخزون')}
                        </button>` : '';
        const deleteActionHtml = canDeleteProducts ? `
                        <button type="button" class="dropdown-action-btn delete-btn" onclick="deleteProduct(${product.id})">
                            <i class="fas fa-trash"></i> ${getText('delete')}
                        </button>` : '';
        
        const rowHtml = `
            <td class="product-name-cell">${escapeHtml(product.name || '')}</td>
            <td class="product-category-cell">${formatProductCategoryCell(product.category)}</td>
            <td>${formatProductEmptyCell(product.barcode)}</td>
            <td>${supplierLabel ? escapeHtml(supplierLabel) : formatProductEmptyCell('')}</td>
            <td class="col-price col-price-usd">${formatCurrency(product.priceUSD != null ? product.priceUSD : 0)}</td>
            <td class="cost-col col-price col-cost-usd" style="${costUnlocked ? '' : 'display:none'}">${formatCurrency(product.costUSD || 0)}</td>
            <td class="col-price col-price-lbp">${formatCurrency(product.priceLBP != null ? product.priceLBP : 0, 'LBP')}</td>
            <td class="col-stock">${stockCellHtml}</td>
            <td class="actions-cell">
                <div class="actions-dropdown">
                    <button type="button" class="actions-toggle-btn actions-toggle-btn--icon-only" data-product-actions-id="${product.id}" aria-label="${escapeHtml(getText('actions') || (isEn ? 'Actions' : 'الإجراءات'))}" onclick="toggleProductActionsDropdown(${product.id})">
                        <i class="fas fa-ellipsis-v" aria-hidden="true"></i>
                    </button>
                    <div class="actions-dropdown-menu" id="product-actions-menu-${product.id}">
                        ${viewActionHtml}
                        ${editActionHtml}
                        ${adjustStockHtml}
                        ${deleteActionHtml}
                    </div>
                </div>
            </td>
        `;
        const rowKey = String(product.id != null ? product.id : (`p_${start}_${rowModels.length}`));
        const rowSig = [
            product.name || '',
            product.category || '',
            product.barcode || '',
            supplierLabel,
            product.priceUSD,
            product.costUSD,
            product.priceLBP,
            stockNum,
            isLowStock ? 1 : 0,
            costUnlocked ? 1 : 0
        ].join('|');
        rowModels.push({ key: rowKey, sig: rowSig, html: rowHtml });
    });
    patchTableRowsIncremental(tbody, rowModels);
    
    // تحديث واجهة pagination
    updateProductsPaginationUI(filteredProducts.length);

    const t1 = (typeof performance !== 'undefined' && performance.now) ? performance.now() : Date.now();
    if (t1 - t0 > 120 && typeof console !== 'undefined' && console.warn) {
        console.warn('[PERF] renderProductsTable slow:', Math.round(t1 - t0) + 'ms', {
            totalProducts: Array.isArray(products) ? products.length : null,
            filtered: filteredProducts.length,
            page: productsCurrentPage,
            pageSize: productsPageSize
        });
    }
}

// تحديث واجهة pagination
function updateProductsPaginationUI(filteredLen) {
    const totalLen = typeof filteredLen === 'number' ? filteredLen : getFilteredProducts().length;
    const totalPages = Math.max(1, Math.ceil(totalLen / productsPageSize));
    const isEn = (document.documentElement.lang || 'ar') === 'en';
    
    const start = totalLen === 0 ? 0 : ((productsCurrentPage - 1) * productsPageSize + 1);
    const end = totalLen === 0 ? 0 : Math.min(start + productsPageSize - 1, totalLen);
    
    const pageInfo = document.getElementById('productsPageInfo');
    if (pageInfo) {
        const productsWord = getText('pagination-products') || (isEn ? 'products' : 'منتج');
        if (totalLen === 0) {
            pageInfo.textContent = isEn ? 'No products found' : 'لا توجد منتجات';
        } else {
            pageInfo.textContent = `${getText('pagination-showing')} ${start}–${end} ${getText('pagination-of')} ${totalLen} ${productsWord}`;
        }
    }

    const pageNumbersWrap = document.getElementById('productsPageNumbers');
    if (pageNumbersWrap) {
        pageNumbersWrap.textContent = '';
        if (totalLen > 0) {
            const windowSize = 5;
            const startPage = Math.max(1, productsCurrentPage - Math.floor(windowSize / 2));
            const endPage = Math.min(totalPages, startPage + windowSize - 1);
            for (let p = startPage; p <= endPage; p++) {
                const btn = document.createElement('button');
                btn.type = 'button';
                btn.className = 'pagination-btn pagination-number-btn';
                btn.textContent = String(p);
                btn.disabled = p === productsCurrentPage;
                if (p === productsCurrentPage) btn.classList.add('active');
                btn.addEventListener('click', () => goToProductsPage(p));
                pageNumbersWrap.appendChild(btn);
            }
        }
    }
    
    const prevBtn = document.getElementById('productsPrevPage');
    const nextBtn = document.getElementById('productsNextPage');
    
    if (prevBtn) {
        prevBtn.disabled = productsCurrentPage === 1 || totalLen === 0;
        prevBtn.title = getText('pagination-previous');
    }
    if (nextBtn) {
        nextBtn.disabled = productsCurrentPage === totalPages || totalLen === 0;
        nextBtn.title = getText('pagination-next');
    }
    
    [prevBtn, nextBtn].forEach(btn => {
        if (btn) {
            if (btn.disabled) {
                btn.style.opacity = '0.5';
                btn.style.cursor = 'not-allowed';
            } else {
                btn.style.opacity = '1';
                btn.style.cursor = 'pointer';
            }
        }
    });
    
    const pageSizeLabel = document.getElementById('productsPageSizeLabel');
    if (pageSizeLabel) {
        pageSizeLabel.textContent = getText('pagination-items-per-page');
    }
    
    const allOption = document.querySelector('#productsPageSize option[value="all"]');
    if (allOption) {
        allOption.textContent = getText('pagination-all');
    }
}

// قفل عرض التكلفة بكلمة سر بسيطة
function isCostUnlocked() {
    try {
        if (!canCurrentUserViewCosts()) return false;
        return localStorage.getItem('costUnlocked') === '1';
    } catch(_) { return false; }
}
function setCostUnlocked(unlocked) {
    try { localStorage.setItem('costUnlocked', unlocked ? '1' : '0'); } catch(_) {}
}
function updateCostToggleButton() {
    const btn = document.getElementById('toggleCostVisibility');
    if (!btn) return;
    if (!canCurrentUserViewCosts()) {
        btn.style.display = 'none';
        return;
    }
    btn.style.display = '';
    const lang = (typeof currentLanguage === 'string' && currentLanguage)
        ? currentLanguage
        : ((document.documentElement.lang || '').toLowerCase().startsWith('en') ? 'en' : 'ar');
    if (isCostUnlocked()) {
        btn.classList.add('is-active');
        btn.innerHTML = '<i class="fas fa-eye-slash"></i> <span data-i18n="hide-cost">' + (lang === 'en' ? 'Hide Cost' : 'إخفاء التكلفة') + '</span>';
    } else {
        btn.classList.remove('is-active');
        btn.innerHTML = '<i class="fas fa-lock"></i> <span data-i18n="show-cost">' + (lang === 'en' ? 'Show Cost' : 'إظهار التكلفة') + '</span>';
    }
}
function applyCostVisibility() {
    const canViewCosts = canCurrentUserViewCosts();
    const unlocked = canViewCosts && isCostUnlocked();
    const toggleBtn = document.getElementById('toggleCostVisibility');
    if (toggleBtn) toggleBtn.style.display = canViewCosts ? '' : 'none';
    // رأس عمود التكلفة
    const thCost = document.getElementById('thCostUSD');
    if (thCost) thCost.style.display = unlocked ? '' : 'none';
    // خلايا التكلفة في الصفوف
    document.querySelectorAll('#productsTable td.cost-col').forEach(td => {
        td.style.display = unlocked ? '' : 'none';
    });
    // حقول التكلفة في النماذج تعتمد على الصلاحية مباشرة (وليس قفل الجدول).
    ['productCostUSD', 'editProductCostUSD'].forEach((id) => {
        const input = document.getElementById(id);
        if (input) {
            if (!input.dataset.initialRequired) input.dataset.initialRequired = input.required ? '1' : '0';
            input.required = canViewCosts ? (input.dataset.initialRequired === '1') : false;
            if (!canViewCosts && (input.value == null || String(input.value).trim() === '')) input.value = '0';
            const costSection = input.closest('.add-product-section');
            if (costSection && costSection.querySelector('.add-product-cost-group')) {
                costSection.style.display = canViewCosts ? '' : 'none';
            }
        }
    });
    updateCostToggleButton();
}
document.addEventListener('DOMContentLoaded', function() {
    const btn = document.getElementById('toggleCostVisibility');
    if (btn) {
        btn.addEventListener('click', async function() {
            if (!isCostUnlocked()) {
                const lang = document.documentElement.lang || 'ar';
                const canUnlock = await requirePrivilegedActionAuth({
                    requiredPermission: 'canEditPrice',
                    accessDeniedMessage: getText('msg-no-permission-edit-price') || (lang === 'en' ? 'No permission to view costs.' : 'لا تملك صلاحية عرض التكلفة.'),
                    promptMessage: lang === 'en' ? 'Enter account password to show costs' : 'أدخل كلمة مرور الحساب لإظهار التكلفة'
                });
                if (canUnlock) {
                    setCostUnlocked(true);
                    try { renderProductsTable(); } catch(_) {}
                    applyCostVisibility();
                    showMessage(getText('cost-shown'), 'success');
                } else {
                    showMessage(getText('msg-no-permission-edit-price') || (lang === 'en' ? 'No permission to view costs.' : 'لا تملك صلاحية عرض التكلفة.'), 'error');
                }
            } else {
                setCostUnlocked(false);
                applyCostVisibility();
                const lang = document.documentElement.lang || 'ar';
                showMessage(getText('cost-hidden'), 'info');
            }
        });
    }
    // تطبيق حالة الإخفاء/الإظهار عند التحميل
    setTimeout(applyCostVisibility, 0);
});

// وظيفة البحث في المنتجات (للتوافق مع الكود القديم)
function handleProductsSearch() {
    const term = this.value.trim().toLowerCase();
    filterProductsTable(term);
}

// تصفية جدول المنتجات (تم تحديثها للعمل مع pagination)
function filterProductsTable(term) {
    productsSearchTerm = term;
    productsCurrentPage = 1;
    saveProductsPaginationState();
    renderProductsTable();
}

/** تطبيع الباركود للمقارنة (فريد 100% بعد الـ trim) */
function normalizeProductBarcode(barcode) {
    return String(barcode == null ? '' : barcode).trim();
}

/** يعيد منتجاً آخر يستخدم نفس الباركود، أو null */
function findProductWithBarcode(barcodeNorm, excludeProductId) {
    if (!barcodeNorm) return null;
    const ex = excludeProductId != null && excludeProductId !== '' ? String(excludeProductId) : null;
    for (let i = 0; i < products.length; i++) {
        const p = products[i];
        if (!p) continue;
        if (ex != null && String(p.id) === ex) continue;
        if (normalizeProductBarcode(p.barcode) === barcodeNorm) return p;
    }
    return null;
}

/** يعيد منتجاً آخر بنفس الاسم (مقارنة بدون حساسية لحالة الأحرف)، أو null */
function findProductWithNameSame(nameTrim, excludeProductId) {
    if (!nameTrim || nameTrim.length < 2) return null;
    const lower = nameTrim.toLowerCase();
    const ex = excludeProductId != null && excludeProductId !== '' ? String(excludeProductId) : null;
    for (let i = 0; i < products.length; i++) {
        const p = products[i];
        if (!p) continue;
        if (ex != null && String(p.id) === ex) continue;
        if (String(p.name || '').trim().toLowerCase() === lower) return p;
    }
    return null;
}

const PRODUCT_CATEGORIES_STORAGE_KEY = 'productCategories';

function normalizeCategoryName(name) {
    return String(name || '').trim().replace(/\s+/g, ' ');
}

function getSavedProductCategories() {
    try {
        const stored = loadFromStorage(PRODUCT_CATEGORIES_STORAGE_KEY, []);
        if (!Array.isArray(stored)) return [];
        const seen = new Set();
        const result = [];
        stored.forEach((c) => {
            const v = normalizeCategoryName(c);
            const key = v.toLowerCase();
            if (!v || seen.has(key)) return;
            seen.add(key);
            result.push(v);
        });
        return result;
    } catch (_) {
        return [];
    }
}

function getAllProductCategories() {
    const seen = new Set();
    const result = [];
    const addOne = (value) => {
        const v = normalizeCategoryName(value);
        const key = v.toLowerCase();
        if (!v || seen.has(key)) return;
        seen.add(key);
        result.push(v);
    };
    try {
        (products || []).forEach((p) => addOne(p && p.category));
    } catch (_) {}
    getSavedProductCategories().forEach(addOne);
    return result.sort((a, b) => a.localeCompare(b, undefined, { sensitivity: 'base' }));
}

function saveProductCategories(categories) {
    const clean = [];
    const seen = new Set();
    (Array.isArray(categories) ? categories : []).forEach((c) => {
        const v = normalizeCategoryName(c);
        const key = v.toLowerCase();
        if (!v || seen.has(key)) return;
        seen.add(key);
        clean.push(v);
    });
    saveToStorage(PRODUCT_CATEGORIES_STORAGE_KEY, clean);
}

function upsertProductCategory(categoryName) {
    const normalized = normalizeCategoryName(categoryName);
    if (!normalized) return '';
    const categories = getAllProductCategories();
    const existing = categories.find((c) => c.toLowerCase() === normalized.toLowerCase());
    if (existing) return existing;
    categories.push(normalized);
    saveProductCategories(categories);
    return normalized;
}

function getCategoryUiTexts() {
    const isEn = (document.documentElement.lang || 'ar') === 'en';
    return isEn
        ? {
            placeholder: 'Search or create category...',
            addNew: 'Add New Category',
            createNewPrefix: 'Create new category:',
            empty: 'No categories found'
        }
        : {
            placeholder: 'ابحث أو أنشئ تصنيف...',
            addNew: 'إضافة تصنيف جديد',
            createNewPrefix: 'إنشاء تصنيف جديد:',
            empty: 'لا توجد تصنيفات'
        };
}

function selectProductCategory(categoryName) {
    const value = normalizeCategoryName(categoryName);
    const hidden = document.getElementById('productCategory');
    const search = document.getElementById('productCategorySearch');
    if (hidden) hidden.value = value;
    if (search) search.value = value;
}

function selectEditProductCategory(categoryName) {
    const value = normalizeCategoryName(categoryName);
    const hidden = document.getElementById('editProductCategory');
    const search = document.getElementById('editProductCategorySearch');
    if (hidden) hidden.value = value;
    if (search) search.value = value;
}

function hideProductCategoryDropdown() {
    const dropdown = document.getElementById('productCategoryDropdown');
    if (dropdown) dropdown.style.display = 'none';
}

function renderProductCategoryDropdown(query = '') {
    const dropdown = document.getElementById('productCategoryDropdown');
    if (!dropdown) return;
    const texts = getCategoryUiTexts();
    const categories = getAllProductCategories();
    const q = normalizeCategoryName(query);
    const qLower = q.toLowerCase();
    const filtered = q
        ? categories.filter((c) => c.toLowerCase().includes(qLower))
        : categories;
    const exactExists = q && categories.some((c) => c.toLowerCase() === qLower);

    const rows = [];
    if (q && !exactExists) {
        rows.push(`<div class="category-dropdown-item create-new" data-create="${escapeHtml(q)}">${escapeHtml(texts.createNewPrefix)} ${escapeHtml(q)}</div>`);
    } else {
        rows.push(`<div class="category-dropdown-item create-new" data-create="">${escapeHtml(texts.addNew)}</div>`);
    }

    if (!filtered.length) {
        rows.push(`<div class="category-dropdown-item">${escapeHtml(texts.empty)}</div>`);
    } else {
        filtered.forEach((cat) => {
            rows.push(`<div class="category-dropdown-item" data-value="${escapeHtml(cat)}">${escapeHtml(cat)}</div>`);
        });
    }

    dropdown.innerHTML = rows.join('');
    dropdown.style.display = 'block';

    dropdown.querySelectorAll('.category-dropdown-item[data-value]').forEach((item) => {
        item.addEventListener('click', () => {
            selectProductCategory(item.getAttribute('data-value') || '');
            hideProductCategoryDropdown();
        });
    });
    dropdown.querySelectorAll('.category-dropdown-item[data-create]').forEach((item) => {
        item.addEventListener('click', () => {
            const prefill = normalizeCategoryName(item.getAttribute('data-create') || q || '');
            openAddCategoryModal(prefill);
        });
    });
}

