function openAddCategoryModal(prefill = '') {
    const input = document.getElementById('newCategoryName');
    const titleEl = document.querySelector('#addCategoryModal .modal-header h3');
    const labelEl = document.querySelector('#addCategoryModal label[for="newCategoryName"]');
    const saveBtn = document.getElementById('saveCategoryBtn');
    const texts = getCategoryUiTexts();
    const isEn = (document.documentElement.lang || 'ar') === 'en';
    if (titleEl) titleEl.textContent = isEn ? 'Add New Category' : 'إضافة تصنيف جديد';
    if (labelEl) labelEl.textContent = isEn ? 'Category Name' : 'اسم التصنيف';
    if (saveBtn) saveBtn.textContent = isEn ? 'Save' : 'حفظ';
    if (input) input.value = normalizeCategoryName(prefill);
    if (input) input.placeholder = isEn ? 'Enter category name' : 'أدخل اسم التصنيف';
    const modal = document.getElementById('addCategoryModal');
    if (modal) modal.classList.remove('closing');
    showModal('addCategoryModal');
    setTimeout(() => {
        if (input) {
            input.focus();
            input.select();
        }
    }, 30);
}

function hideAddCategoryModalAnimated() {
    const modal = document.getElementById('addCategoryModal');
    if (!modal || !modal.classList.contains('active')) return;
    if (modal.classList.contains('closing')) return;
    modal.classList.add('closing');
    setTimeout(() => {
        hideModal('addCategoryModal');
        modal.classList.remove('closing');
    }, 160);
}

function saveNewProductCategory() {
    const input = document.getElementById('newCategoryName');
    const raw = input ? input.value : '';
    const normalized = normalizeCategoryName(raw);
    if (!normalized) {
        showMessage((document.documentElement.lang || 'ar') === 'en' ? 'Category name is required.' : 'اسم التصنيف مطلوب.', 'error');
        return;
    }
    const saved = upsertProductCategory(normalized);
    if (!saved) return;
    if (document.getElementById('editProductModal')?.classList.contains('active')) {
        selectEditProductCategory(saved);
        hideEditProductCategoryDropdown();
    } else {
        selectProductCategory(saved);
        hideProductCategoryDropdown();
    }
    hideAddCategoryModalAnimated();
    showMessage((document.documentElement.lang || 'ar') === 'en' ? 'Category saved successfully.' : 'تم حفظ التصنيف بنجاح.', 'success');
}

function setupProductCategorySearchableSelect() {
    const searchInput = document.getElementById('productCategorySearch');
    const dropdown = document.getElementById('productCategoryDropdown');
    if (!searchInput || !dropdown || searchInput.dataset.boundCategorySelect === '1') return;
    searchInput.dataset.boundCategorySelect = '1';

    const applyLocaleText = () => {
        const texts = getCategoryUiTexts();
        searchInput.placeholder = texts.placeholder;
    };
    applyLocaleText();

    searchInput.addEventListener('focus', () => {
        renderProductCategoryDropdown(searchInput.value || '');
    });

    searchInput.addEventListener('input', () => {
        const hidden = document.getElementById('productCategory');
        if (hidden) hidden.value = '';
        renderProductCategoryDropdown(searchInput.value || '');
    });

    searchInput.addEventListener('keydown', (e) => {
        if (e.key === 'Escape') {
            hideProductCategoryDropdown();
            return;
        }
        if (e.key === 'Enter' && dropdown.style.display !== 'none') {
            const first = dropdown.querySelector('.category-dropdown-item[data-value], .category-dropdown-item[data-create]');
            if (first) {
                e.preventDefault();
                first.click();
            }
        }
    });

    document.addEventListener('click', (e) => {
        const wrap = document.getElementById('productCategorySelectWrap');
        if (!wrap) return;
        if (!wrap.contains(e.target) && !document.getElementById('addCategoryModal')?.contains(e.target)) {
            hideProductCategoryDropdown();
        }
    });

    const saveBtn = document.getElementById('saveCategoryBtn');
    if (saveBtn && !saveBtn.dataset.boundSaveCategory) {
        saveBtn.dataset.boundSaveCategory = '1';
        saveBtn.addEventListener('click', saveNewProductCategory);
    }

    const newCategoryInput = document.getElementById('newCategoryName');
    if (newCategoryInput && !newCategoryInput.dataset.boundSaveCategoryInput) {
        newCategoryInput.dataset.boundSaveCategoryInput = '1';
        newCategoryInput.addEventListener('keydown', (e) => {
            if (e.key === 'Enter') {
                e.preventDefault();
                saveNewProductCategory();
            }
        });
    }

    const modal = document.getElementById('addCategoryModal');
    const closeBtn = document.querySelector('#addCategoryModal .modal-header .close-btn');
    const cancelBtn = document.querySelector('#addCategoryModal .modal-actions .cancel-btn');
    if (closeBtn && !closeBtn.dataset.boundAddCategoryClose) {
        closeBtn.dataset.boundAddCategoryClose = '1';
        closeBtn.addEventListener('click', (e) => {
            e.preventDefault();
            hideAddCategoryModalAnimated();
        });
    }
    if (cancelBtn && !cancelBtn.dataset.boundAddCategoryCancel) {
        cancelBtn.dataset.boundAddCategoryCancel = '1';
        cancelBtn.addEventListener('click', (e) => {
            e.preventDefault();
            hideAddCategoryModalAnimated();
        });
    }
    if (modal && !modal.dataset.boundAddCategoryEscape) {
        modal.dataset.boundAddCategoryEscape = '1';
        modal.addEventListener('keydown', (e) => {
            if (e.key === 'Escape') {
                e.preventDefault();
                hideAddCategoryModalAnimated();
            }
        });
    }
}

