function parseExpiryDateOnly(value) {
    const raw = String(value || '').trim();
    if (!raw) return null;
    const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(raw);
    if (!m) return null;
    const y = Number(m[1]);
    const mm = Number(m[2]);
    const d = Number(m[3]);
    if (!y || !mm || !d) return null;
    return new Date(y, mm - 1, d);
}

function normalizeExpiryDate(value) {
    const d = parseExpiryDateOnly(value);
    if (!d) return '';
    const y = d.getFullYear();
    const m = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    return `${y}-${m}-${day}`;
}

function getExpiryStatus(expiryDateStr) {
    const isEn = (document.documentElement.lang || 'ar') === 'en';
    const labels = isEn
        ? { expired: 'Expired', soon: 'Expiring Soon', valid: 'Valid', none: 'No Expiry' }
        : { expired: 'منتهي', soon: 'قريب الانتهاء', valid: 'سليم', none: 'بدون تاريخ' };
    const dateObj = parseExpiryDateOnly(expiryDateStr);
    if (!dateObj) {
        return {
            status: 'none',
            statusLabel: labels.none,
            daysRemaining: null,
            orderDays: 999999,
            daysText: '—'
        };
    }
    const now = new Date();
    const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
    const diffMs = dateObj.getTime() - today.getTime();
    const days = Math.floor(diffMs / 86400000);
    if (days < 0) {
        return {
            status: 'expired',
            statusLabel: labels.expired,
            daysRemaining: days,
            orderDays: days,
            daysText: formatExpiryDaysRemaining(days, 'expired')
        };
    }
    if (days <= 30) {
        return {
            status: 'soon',
            statusLabel: labels.soon,
            daysRemaining: days,
            orderDays: days,
            daysText: formatExpiryDaysRemaining(days, 'soon')
        };
    }
    return {
        status: 'valid',
        statusLabel: labels.valid,
        daysRemaining: days,
        orderDays: days,
        daysText: formatExpiryDaysRemaining(days, 'valid')
    };
}

function formatExpiryDaysRemaining(days, status) {
    if (days == null || status === 'none') return '—';
    const isEn = (document.documentElement.lang || 'ar') === 'en';
    if (status === 'expired' || days < 0) {
        const abs = Math.abs(days);
        return getText('expiry_days_ago', { days: abs }) || (isEn ? `Expired ${abs} days ago` : `منتهي منذ ${abs} يوم`);
    }
    return getText('expiry_days_left', { days }) || (isEn ? `${days} days left` : `بقي ${days} يوم`);
}

function formatExpiryDisplayDate(expiryDateStr) {
    const d = parseExpiryDateOnly(expiryDateStr);
    if (!d) return null;
    const isEn = (document.documentElement.lang || 'ar') === 'en';
    const day = String(d.getDate()).padStart(2, '0');
    const month = String(d.getMonth() + 1).padStart(2, '0');
    const year = d.getFullYear();
    if (isEn) {
        const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
        return `${d.getDate()} ${months[d.getMonth()]} ${year}`;
    }
    return `${day}/${month}/${year}`;
}

function getExpiryStatusClass(status) {
    if (status === 'expired') return 'expired';
    if (status === 'soon') return 'soon';
    if (status === 'none') return 'none';
    return 'valid';
}

function getExpirySummaryCounts() {
    const list = Array.isArray(products) ? products : [];
    const counts = { expired: 0, soon: 0, valid: 0, none: 0 };
    list.forEach((p) => {
        const st = getExpiryStatus(p && p.expiryDate).status;
        if (counts[st] != null) counts[st] += 1;
    });
    return counts;
}

function updateExpirySummaryCards() {
    const counts = getExpirySummaryCounts();
    const map = {
        expired: document.getElementById('expirySummaryExpired'),
        soon: document.getElementById('expirySummarySoon'),
        valid: document.getElementById('expirySummaryValid'),
        none: document.getElementById('expirySummaryNone')
    };
    Object.keys(map).forEach((key) => {
        if (map[key]) map[key].textContent = String(counts[key] || 0);
    });
    document.querySelectorAll('#expirySummaryGrid .expiry-summary-card').forEach((card) => {
        const key = card.getAttribute('data-expiry-summary');
        card.classList.toggle('is-active', document.getElementById('expiryFilter')?.value === key);
    });
}

