function buildExpiryDateCellHtml(product) {
    const pid = String(product.id);
    const expiryValue = normalizeExpiryDate(product.expiryDate);
    const displayDate = formatExpiryDisplayDate(product.expiryDate);
    const noDateText = getText('expiry_no_date') || ((document.documentElement.lang || 'ar') === 'en' ? 'No expiry date' : 'بدون تاريخ انتهاء');
    const isEditing = expiryEditingProductId === pid;

    if (isEditing) {
        return `
            <div class="expiry-date-edit-panel">
                <input type="date" class="expiry-date-input expiry-date-input--edit" data-expiry-edit-input="${escapeAttr(pid)}" value="${escapeAttr(expiryValue)}">
                <div class="expiry-date-edit-actions">
                    <button type="button" class="expiry-date-save-btn" data-expiry-save="${escapeAttr(pid)}">${escapeHtml(getText('expiry_save') || 'Save')}</button>
                    <button type="button" class="expiry-date-cancel-btn" data-expiry-cancel="${escapeAttr(pid)}">${escapeHtml(getText('expiry_cancel') || 'Cancel')}</button>
                </div>
            </div>
        `;
    }

    const dateHtml = displayDate
        ? `<span class="expiry-date-text">${escapeHtml(displayDate)}</span>`
        : `<span class="expiry-date-text expiry-date-text--empty">${escapeHtml(noDateText)}</span>`;

    return `
        <div class="expiry-date-display">
            ${dateHtml}
            <button type="button" class="expiry-date-edit-btn" data-expiry-edit="${escapeAttr(pid)}" title="${escapeAttr(getText('expiry_action_edit_date') || 'Edit')}">
                <i class="fas fa-pen" aria-hidden="true"></i>
            </button>
        </div>
    `;
}

function buildExpiryActionsCellHtml(product) {
    const pid = product.id;
    const isEn = (document.documentElement.lang || 'ar') === 'en';
    const canView = hasProductPermission('canViewProducts');
    const canEdit = hasProductPermission('canEditProducts');
    const items = [];
    if (canEdit) {
        items.push(`<button type="button" class="dropdown-action-btn edit-btn" onclick="openExpiryDateEditor(${pid})"><i class="fas fa-calendar-day"></i> ${escapeHtml(getText('expiry_action_edit_date') || (isEn ? 'Edit Expiry Date' : 'تعديل تاريخ الانتهاء'))}</button>`);
    }
    if (canView) {
        items.push(`<button type="button" class="dropdown-action-btn view-btn" onclick="viewProduct(${pid})"><i class="fas fa-eye"></i> ${escapeHtml(getText('expiry_action_view') || (isEn ? 'View Product' : 'عرض المنتج'))}</button>`);
    }
    if (canEdit) {
        items.push(`<button type="button" class="dropdown-action-btn product-log-btn" onclick="markProductNoExpiry(${pid})"><i class="fas fa-ban"></i> ${escapeHtml(getText('expiry_action_no_expiry') || (isEn ? 'Mark as No Expiry' : 'بدون تاريخ انتهاء'))}</button>`);
        items.push(`<button type="button" class="dropdown-action-btn delete-btn" onclick="removeProductExpiryDate(${pid})"><i class="fas fa-eraser"></i> ${escapeHtml(getText('expiry_action_remove_date') || (isEn ? 'Remove Expiry Date' : 'إزالة تاريخ الانتهاء'))}</button>`);
    }
    if (!items.length) return '<span class="table-empty-value">—</span>';
    return buildActionMenuCellHtml({
        scope: 'expiry',
        id: pid,
        extraClass: 'expiry-actions-dropdown',
        toggleFn: 'toggleExpiryActionsDropdown',
        items
    });
}

