function updateExpiryDashboardAlert() {
    const alertEl = document.getElementById('expiryDashboardAlert');
    if (!alertEl) return;
    const list = Array.isArray(products) ? products : [];
    const soonCount = list.filter((p) => getExpiryStatus(p && p.expiryDate).status === 'soon').length;
    const expiredCount = list.filter((p) => getExpiryStatus(p && p.expiryDate).status === 'expired').length;
    if (soonCount === 0 && expiredCount === 0) {
        alertEl.style.display = 'none';
        alertEl.innerHTML = '';
        return;
    }
    const isEn = (document.documentElement.lang || 'ar') === 'en';
    let message = '';
    if (expiredCount > 0 && soonCount > 0) {
        message = isEn
            ? `Expiry Alert: ${expiredCount} expired product${expiredCount === 1 ? '' : 's'} · ${soonCount} expiring soon`
            : `تنبيه انتهاء: ${expiredCount} منتج منتهي · ${soonCount} ينتهي قريباً`;
    } else if (expiredCount > 0) {
        message = isEn
            ? `Expiry Alert: ${expiredCount} expired product${expiredCount === 1 ? '' : 's'}`
            : `تنبيه انتهاء: ${expiredCount} منتج منتهي`;
    } else {
        message = isEn
            ? `Expiry Alert: ${soonCount} product${soonCount === 1 ? '' : 's'} expiring soon`
            : `تنبيه انتهاء: ${soonCount} منتج ينتهي قريباً`;
    }
    alertEl.innerHTML = `<i class="fas fa-exclamation-triangle" aria-hidden="true"></i><span>${escapeHtml(message)}</span>`;
    alertEl.style.display = '';
    const goExpiry = () => {
        const nav = document.querySelector('.nav-item[data-screen="expiryManagement"]');
        if (nav) __navigateFromNavItem(nav);
    };
    alertEl.onclick = goExpiry;
    alertEl.onkeydown = (e) => {
        if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault();
            goExpiry();
        }
    };
}

function updateProductExpiryDate(productId, expiryDateValue) {
    const idx = products.findIndex((p) => String(p.id) === String(productId));
    if (idx < 0) return;
    const normalized = normalizeExpiryDate(expiryDateValue);
    if (normalized) products[idx].expiryDate = normalized;
    else delete products[idx].expiryDate;
    try { touchProductClientTimestamp(products[idx]); } catch (_) {}
    saveToStorage('products', products);
    try { enqueueSyncOp('products', 'upsert', products[idx].id, products[idx]); } catch (_) {}
    try { scheduleSyncFlush(); } catch (_) {}
    updateExpiryDashboardAlert();
    try {
        const expiryPage = document.getElementById('expiryManagement');
        if (expiryPage && expiryPage.classList.contains('active')) loadExpiryManagement();
    } catch (_) {}
}

let expiryCurrentPage = 1;
let expiryPageSize = 25;

function getFilteredExpiryRows() {
    products = getCurrentProducts();
    const search = (document.getElementById('expirySearch')?.value || '').trim().toLowerCase();
    const filter = document.getElementById('expiryFilter')?.value || 'all';
    return (Array.isArray(products) ? products : [])
        .map((p) => ({ product: p, ...getExpiryStatus(p && p.expiryDate) }))
        .filter((x) => {
            if (!x.product) return false;
            if (search) {
                const n = String(x.product.name || '').toLowerCase();
                const c = String(formatProductCategoryLabel(x.product.category) || '').toLowerCase();
                if (!n.includes(search) && !c.includes(search)) return false;
            }
            if (filter === 'expired') return x.status === 'expired';
            if (filter === 'soon') return x.status === 'soon';
            if (filter === 'valid') return x.status === 'valid';
            if (filter === 'none') return x.status === 'none';
            return true;
        })
        .sort((a, b) => (a.orderDays !== b.orderDays ? (a.orderDays - b.orderDays) : String(a.product.name || '').localeCompare(String(b.product.name || ''))));
}

function loadExpiryPaginationState() {
    try {
        const saved = sessionStorage.getItem('expiryPaginationState');
        if (!saved) return;
        const state = JSON.parse(saved);
        expiryCurrentPage = state.page || 1;
        expiryPageSize = state.pageSize || 25;
    } catch (e) {
        console.warn('Error loading expiry pagination state:', e);
    }
}

function saveExpiryPaginationState() {
    try {
        sessionStorage.setItem('expiryPaginationState', JSON.stringify({
            page: expiryCurrentPage,
            pageSize: expiryPageSize
        }));
    } catch (e) {
        console.warn('Error saving expiry pagination state:', e);
    }
}

function getExpiryTotalPages() {
    const rows = getFilteredExpiryRows();
    return Math.max(1, Math.ceil(rows.length / expiryPageSize));
}

function goToExpiryPage(page) {
    const totalPages = getExpiryTotalPages();
    expiryCurrentPage = Math.max(1, Math.min(page, totalPages));
    saveExpiryPaginationState();
    loadExpiryManagement();
}

function updateExpiryPaginationUI(totalLen) {
    const totalPages = Math.max(1, Math.ceil(totalLen / expiryPageSize));
    const currentPageSpan = document.getElementById('expiryCurrentPage');
    const pageInfo = document.getElementById('expiryPageInfo');
    const firstBtn = document.getElementById('expiryFirstPage');
    const prevBtn = document.getElementById('expiryPrevPage');
    const nextBtn = document.getElementById('expiryNextPage');
    const lastBtn = document.getElementById('expiryLastPage');
    const pageSizeLabel = document.getElementById('expiryPageSizeLabel');
    const allOption = document.querySelector('#expiryPageSize option[value="all"]');

    if (currentPageSpan) currentPageSpan.textContent = `${expiryCurrentPage} / ${totalPages}`;

    const start = totalLen === 0 ? 0 : ((expiryCurrentPage - 1) * expiryPageSize) + 1;
    const end = totalLen === 0 ? 0 : Math.min(start + expiryPageSize - 1, totalLen);
    if (pageInfo) {
        pageInfo.textContent = totalLen === 0
            ? getText('pagination-no-items')
            : `${getText('pagination-showing')} ${start}-${end} ${getText('pagination-of')} ${totalLen}`;
    }

    [firstBtn, prevBtn, nextBtn, lastBtn].forEach((btn) => {
        if (!btn) return;
        btn.disabled = totalLen === 0;
        btn.style.opacity = btn.disabled ? '0.5' : '1';
        btn.style.cursor = btn.disabled ? 'not-allowed' : 'pointer';
    });
    if (firstBtn) firstBtn.disabled = totalLen === 0 || expiryCurrentPage === 1;
    if (prevBtn) prevBtn.disabled = totalLen === 0 || expiryCurrentPage === 1;
    if (nextBtn) nextBtn.disabled = totalLen === 0 || expiryCurrentPage === totalPages;
    if (lastBtn) lastBtn.disabled = totalLen === 0 || expiryCurrentPage === totalPages;

    [firstBtn, prevBtn, nextBtn, lastBtn].forEach((btn) => {
        if (!btn) return;
        btn.style.opacity = btn.disabled ? '0.5' : '1';
        btn.style.cursor = btn.disabled ? 'not-allowed' : 'pointer';
    });
    if (pageSizeLabel) pageSizeLabel.textContent = getText('pagination-items-per-page');
    if (allOption) allOption.textContent = getText('pagination-all');
}

function setupExpiryManagementPagination() {
    loadExpiryPaginationState();
    const pageSizeSelect = document.getElementById('expiryPageSize');
    if (pageSizeSelect && expiryPageSize) {
        pageSizeSelect.value = expiryPageSize >= 999999 ? 'all' : String(expiryPageSize);
    }
    const bindOnce = (id, handler) => {
        const el = document.getElementById(id);
        if (!el || el.dataset.expiryPagerBound === '1') return;
        el.dataset.expiryPagerBound = '1';
        el.addEventListener('click', handler);
    };
    bindOnce('expiryFirstPage', () => goToExpiryPage(1));
    bindOnce('expiryPrevPage', () => goToExpiryPage(expiryCurrentPage - 1));
    bindOnce('expiryNextPage', () => goToExpiryPage(expiryCurrentPage + 1));
    bindOnce('expiryLastPage', () => goToExpiryPage(getExpiryTotalPages()));
    if (pageSizeSelect && pageSizeSelect.dataset.expiryPageSizeBound !== '1') {
        pageSizeSelect.dataset.expiryPageSizeBound = '1';
        pageSizeSelect.addEventListener('change', function () {
            expiryPageSize = this.value === 'all' ? 999999 : (parseInt(this.value, 10) || 25);
            expiryCurrentPage = 1;
            saveExpiryPaginationState();
            loadExpiryManagement();
        });
    }
}

function loadExpiryManagement(options) {
    const table = document.getElementById('expiryTable');
    if (!table) return;

    if (options && options.loading) {
        expiryTableLoading = true;
        renderExpiryTableSkeleton();
        updateExpirySummaryCards();
        updateExpiryPaginationUI(0);
        return;
    }

    expiryTableLoading = false;
    setupExpiryManagementPagination();
    updateExpirySummaryCards();
    closeAllExpiryActionsDropdowns();

    const rows = getFilteredExpiryRows();
    const totalPages = Math.max(1, Math.ceil(rows.length / expiryPageSize));
    if (expiryCurrentPage > totalPages) expiryCurrentPage = totalPages;

    if (!rows.length) {
        table.innerHTML = renderExpiryEmptyState();
        updateExpiryPaginationUI(0);
        saveExpiryPaginationState();
        return;
    }

    const start = (expiryCurrentPage - 1) * expiryPageSize;
    const end = Math.min(start + expiryPageSize, rows.length);
    const pageRows = rows.slice(start, end);

    table.innerHTML = pageRows.map((x) => {
        const p = x.product || {};
        const statusClass = getExpiryStatusClass(x.status);
        return `
            <tr>
                <td class="expiry-product-name">${escapeHtml(p.name || '')}</td>
                <td>${formatProductCategoryCell(p.category)}</td>
                <td class="expiry-col-qty">${escapeHtml(getProductStockDisplay(p))}</td>
                <td class="expiry-date-cell">${buildExpiryDateCellHtml(p)}</td>
                <td class="expiry-col-days">${escapeHtml(x.daysText || '—')}</td>
                <td class="expiry-col-status"><span class="expiry-status ${statusClass}">${escapeHtml(x.statusLabel)}</span></td>
                <td class="expiry-col-actions actions-cell">${buildExpiryActionsCellHtml(p)}</td>
            </tr>
        `;
    }).join('');

    table.querySelectorAll('[data-expiry-edit]').forEach((btn) => {
        btn.addEventListener('click', () => openExpiryDateEditor(btn.getAttribute('data-expiry-edit')));
    });
    table.querySelectorAll('[data-expiry-save]').forEach((btn) => {
        btn.addEventListener('click', () => saveExpiryDateFromEditor(btn.getAttribute('data-expiry-save')));
    });
    table.querySelectorAll('[data-expiry-cancel]').forEach((btn) => {
        btn.addEventListener('click', cancelExpiryDateEditor);
    });

    updateExpiryPaginationUI(rows.length);
    saveExpiryPaginationState();
}

function setupExpiryManagementEvents() {
    const search = document.getElementById('expirySearch');
    const filter = document.getElementById('expiryFilter');
    if (search && !search.dataset.expiryBound) {
        search.dataset.expiryBound = '1';
        search.addEventListener('input', () => {
            expiryCurrentPage = 1;
            expiryEditingProductId = null;
            saveExpiryPaginationState();
            loadExpiryManagement();
        });
    }
    if (filter && !filter.dataset.expiryBound) {
        filter.dataset.expiryBound = '1';
        filter.addEventListener('change', () => {
            expiryCurrentPage = 1;
            expiryEditingProductId = null;
            saveExpiryPaginationState();
            loadExpiryManagement();
        });
    }
    document.querySelectorAll('#expirySummaryGrid .expiry-summary-card').forEach((card) => {
        if (card.dataset.expirySummaryBound === '1') return;
        card.dataset.expirySummaryBound = '1';
        card.addEventListener('click', () => {
            const key = card.getAttribute('data-expiry-summary');
            const sel = document.getElementById('expiryFilter');
            if (!sel || !key) return;
            sel.value = key;
            expiryCurrentPage = 1;
            expiryEditingProductId = null;
            saveExpiryPaginationState();
            loadExpiryManagement();
        });
    });
}

