// وظيفة إنشاء باركود تلقائي
function generateBarcode() {
    let barcode = '';
    for (let attempt = 0; attempt < 80; attempt++) {
        const candidate = String(Math.floor(1000000000000 + Math.random() * 9000000000000));
        if (!findProductWithBarcode(candidate, null)) {
            barcode = candidate;
            break;
        }
    }
    if (!barcode) {
        showMessage((document.documentElement.lang === 'en' ? 'Could not generate a unique barcode. Try again.' : 'تعذر توليد باركود فريد. حاول مرة أخرى.'), 'error');
        return;
    }
    const barcodeInput = document.getElementById('productBarcode');
    if (barcodeInput) {
        barcodeInput.value = barcode;
        
        // إضافة تأثير بصري
        barcodeInput.style.backgroundColor = '#d4edda';
        barcodeInput.style.borderColor = '#28a745';
        
        // إزالة التأثير بعد ثانيتين
        setTimeout(() => {
            barcodeInput.style.backgroundColor = '';
            barcodeInput.style.borderColor = '';
        }, 2000);
        
        // إظهار رسالة نجاح
        showMessage(getText('barcode-generated'), 'success');
    }
}

function generateEditBarcode() {
    const editId = document.getElementById('editProductForm')?.dataset?.editId || null;
    let barcode = '';
    for (let attempt = 0; attempt < 80; attempt++) {
        const candidate = String(Math.floor(1000000000000 + Math.random() * 9000000000000));
        if (!findProductWithBarcode(candidate, editId)) {
            barcode = candidate;
            break;
        }
    }
    if (!barcode) {
        showMessage((document.documentElement.lang === 'en' ? 'Could not generate a unique barcode. Try again.' : 'تعذر توليد باركود فريد. حاول مرة أخرى.'), 'error');
        return;
    }
    const barcodeInput = document.getElementById('editProductBarcode');
    if (barcodeInput) {
        barcodeInput.value = barcode;
        barcodeInput.style.backgroundColor = '#d4edda';
        barcodeInput.style.borderColor = '#28a745';
        setTimeout(() => {
            barcodeInput.style.backgroundColor = '';
            barcodeInput.style.borderColor = '';
        }, 2000);
        showMessage(getText('barcode-generated'), 'success');
    }
}
window.generateEditBarcode = generateEditBarcode;

// فتح نافذة طباعة الباركود
function openPrintBarcode(productId) {
    const product = products.find(p => p.id === productId);
    if (!product) {
        showMessage(getText('msg-product-not-found'), 'error');
        return;
    }
    
    // إذا كان المنتج يتتبع IMEI ولدَيه قائمة، نستخدم IMEI (مثلاً لأول جهاز) ككود للطباعة
    let codeToPrint = product.barcode || '';
    if (!codeToPrint && product.imeiTracking && Array.isArray(product.imeiList) && product.imeiList.length > 0) {
        const firstImei = String(product.imeiList[0].imei || '').trim();
        if (firstImei) {
            codeToPrint = firstImei;
        }
    }
    
    // ملء معلومات المنتج
    document.getElementById('barcodeProductName').textContent = product.name;
    document.getElementById('barcodeNumber').textContent = codeToPrint || getText('not_specified');
    
    // تحديث ترجمة تسمية الباركود (تُظهر "IMEI" إذا كان الكود من قائمة IMEI)
    const barcodeLabel = document.querySelector('#barcodeProductCode [data-i18n="barcode"]');
    if (barcodeLabel) {
        if (product.imeiTracking && codeToPrint) {
            barcodeLabel.textContent = 'IMEI';
        } else {
            barcodeLabel.textContent = getText('barcode');
        }
    }
    
    // إنشاء معاينة الباركود
    updateBarcodePreview();
    
    // إضافة event listeners
    document.getElementById('barcodeSize').addEventListener('change', updateBarcodePreview);
    
    // إظهار النافذة
    showModal('printBarcodeModal');
}

// تحديث معاينة الباركود
function updateBarcodePreview() {
    const barcodeNumber = document.getElementById('barcodeNumber').textContent;
    const size = document.getElementById('barcodeSize').value;
    const preview = document.getElementById('barcodePreview');
    
    if (barcodeNumber && barcodeNumber !== getText('not_specified')) {
        // إنشاء عنصر SVG للباركود
        const svgId = 'barcode-svg-' + Date.now();
        preview.innerHTML = `
            <div class="barcode-container">
                <div style="font-size: 14px; margin-bottom: 10px; font-weight: bold;">${document.getElementById('barcodeProductName').textContent}</div>
                <svg id="${svgId}" class="barcode-svg"></svg>
                <div style="font-size: 12px; margin-top: 10px; color: #666;">${barcodeNumber}</div>
            </div>
        `;
        
        // إنشاء الباركود البصري — نستخدم CODE128 دائماً لتجنّب أخطاء EAN13 مع IMEI
        try {
            JsBarcode(`#${svgId}`, barcodeNumber, {
                format: "CODE128",
                width: size === 'small' ? 1.5 : size === 'large' ? 2.5 : 2,
                height: size === 'small' ? 40 : size === 'large' ? 60 : 50,
                displayValue: false,
                background: "#ffffff",
                lineColor: "#000000",
                margin: 10
            });
        } catch (error2) {
            console.error('Error generating CODE128 barcode:', error2);
            preview.innerHTML = `
                <div class="barcode-container">
                    <div style="font-size: 14px; margin-bottom: 10px; font-weight: bold;">${document.getElementById('barcodeProductName').textContent}</div>
                    <div style="font-family: 'Courier New', monospace; font-weight: bold; letter-spacing: 2px; font-size: 16px;">${barcodeNumber}</div>
                    <div style="font-size: 12px; margin-top: 10px; color: #666;">Barcode (Text Format)</div>
                </div>
            `;
        }
    } else {
        preview.innerHTML = `<p style="color: #999;">${getText('barcode')}: ${getText('not_specified')}</p>`;
    }
}

// Print barcode — robust flow
function printBarcode() {
    console.log('🖨️ Starting barcode print...');
    
    try {
        const productName = document.getElementById('barcodeProductName').textContent;
        const barcodeNumber = document.getElementById('barcodeNumber').textContent;
        const quantity = parseInt(document.getElementById('printQuantity').value);
        const size = document.getElementById('barcodeSize').value;
        
        if (barcodeNumber === getText('not_specified')) {
            showMessage(getText('barcode') + ' ' + getText('not_specified'), 'error');
            return;
        }
        
        if (!quantity || quantity < 1) {
            showMessage(getText('msg-enter-valid-print-qty'), 'error');
            return;
        }
        
        console.log(`📊 Print details: ${quantity} × ${productName} (${barcodeNumber})`);
        
        // إنشاء نافذة طباعة محسنة
        const printWindow = window.open('', '_blank', 'width=600,height=800');
        
        if (!printWindow) {
            console.error('❌ Failed to open print window');
            showMessage(getText('msg-print-popup-blocked'), 'error');
            return;
        }
        
        const printContent = `
        <!DOCTYPE html>
        <html>
        <head>
            <title>${((document.documentElement.lang || 'ar') === 'en' ? 'Print Barcode' : 'طباعة الباركود')} - ${productName}</title>
            <meta charset="UTF-8">
            <meta name="viewport" content="width=device-width, initial-scale=1.0">
            <script src="https://cdn.jsdelivr.net/npm/jsbarcode@3.11.5/dist/JsBarcode.all.min.js"></script>
            <style>
                body { 
                    font-family: Arial, sans-serif; 
                    margin: 0; 
                    padding: 10px; 
                    text-align: center;
                }
                .barcode-item {
                    border: 1px solid #000;
                    padding: 10px 8px;
                    margin: 6px;
                    display: inline-block;
                    min-width: 180px;
                    page-break-inside: avoid;
                }
                .product-name {
                    font-size: 14px;
                    font-weight: bold;
                    margin-bottom: 6px;
                }
                .barcode-svg {
                    margin: 4px 0 6px 0;
                }
                .barcode-number {
                    font-family: 'Courier New', monospace;
                    font-weight: 600;
                    font-size: 11px;
                    letter-spacing: 0.6px;
                    color: #333;
                    margin-top: 2px;
                    margin-bottom: 1px;
                    white-space: nowrap;
                }
                @media print {
                    body { 
                        margin: 0; 
                        padding: 4px;
                    }
                    .barcode-item { 
                        page-break-inside: avoid; 
                        margin: 4px;
                        border: 1px solid #000;
                    }
                }
            </style>
        </head>
        <body>
            ${Array(quantity).fill(0).map((_, index) => `
                <div class="barcode-item">
                    <div class="product-name">${productName}</div>
                    <div class="barcode-number">${barcodeNumber}</div>
                    <svg id="barcode-${index}" class="barcode-svg"></svg>
                </div>
            `).join('')}
            
            <script>
                console.log('🔄 Starting barcode generation...');
                
                // Create visual barcodes
                document.addEventListener('DOMContentLoaded', function() {
                    const barcodeWidth = ${size === 'small' ? 1.5 : size === 'large' ? 2.5 : 2};
                    const barcodeHeight = ${size === 'small' ? 40 : size === 'large' ? 60 : 50};
                    const fontSize = ${size === 'small' ? 10 : size === 'large' ? 14 : 12};
                    
                    console.log('📊 Barcode parameters:', { barcodeWidth, barcodeHeight, fontSize });
                    
                    let successCount = 0;
                    let errorCount = 0;
                    
                    for (let i = 0; i < ${quantity}; i++) {
                        try {
                            // Always use CODE128 (supports IMEI and any numeric/letter text without checksum restrictions)
                            JsBarcode('#barcode-' + i, '${barcodeNumber}', {
                                format: "CODE128",
                                width: barcodeWidth,
                                height: barcodeHeight,
                                displayValue: true,
                                fontSize: fontSize,
                                textMargin: 5,
                                background: "#ffffff",
                                lineColor: "#000000",
                                margin: 10,
                                textAlign: "center",
                                textPosition: "bottom"
                            });
                            successCount++;
                        } catch (error2) {
                            console.error('Error generating CODE128 barcode:', error2);
                            errorCount++;
                        }
                    }
                    
                    console.log('✅ Generated ' + successCount + ' barcode(s), ' + errorCount + ' error(s)');
                    
                    // Auto-print
                    setTimeout(() => {
                        try {
                            window.focus();
                            window.print();
                            
                            // Close window after printing
                            setTimeout(() => {
                                window.close();
                                console.log('✅ Print window closed');
                            }, 1000);
                        } catch (printError) {
                            console.error('❌ Print error:', printError);
                            window.close();
                        }
                    }, 1000);
                });
            </script>
        </body>
        </html>
        `;
        
        printWindow.document.write(printContent);
        printWindow.document.close();
        
        // Handle errors
        printWindow.onerror = function(error) {
            console.error('❌ Print window error:', error);
            showMessage(getText('msg-print-window-error'), 'error');
            printWindow.close();
        };
        
        showMessage(getText('barcode-printing', { quantity: quantity }), 'success');
        closePrintBarcode();
        
    } catch (error) {
        console.error('❌ General barcode print error:', error);
        showMessage(getText('msg-barcode-print-error', { message: error.message }), 'error');
    }
}

// Close barcode print modal
function closePrintBarcode() {
    hideModal('printBarcodeModal');
}

// The form handler was moved below to support auto-calculation

// T3: Security code stored as SHA-256 hash only (no plain text in source)
// This is the hash of the default code; change via settings.securityCodeHash if needed
const SECURITY_CODE_HASH_DEFAULT = 'f1534392279bddbf9d43dde8701cb5be14b82f76ec6607bf8d6ad557f60f304e'; // SHA-256 of default code (00)

async function hashStringForSecurityCode(str) {
    try {
        const data = new TextEncoder().encode(String(str || ''));
        const buf = await crypto.subtle.digest('SHA-256', data);
        return Array.from(new Uint8Array(buf)).map(b => b.toString(16).padStart(2, '0')).join('');
    } catch (e) {
        console.warn('hashStringForSecurityCode failed', e);
        return '';
    }
}

function getStoredSecurityCodeHash() {
    try {
        const s = typeof settings !== 'undefined' && settings && settings.securityCodeHash;
        if (s && typeof s === 'string' && s.length === 64 && /^[a-f0-9]+$/.test(s)) return s;
    } catch (_) {}
    return SECURITY_CODE_HASH_DEFAULT;
}

// Universal in-app dialog (NO browser alert/prompt/confirm)
function uiDialog(options = {}) {
    const {
        title = '',
        message = '',
        input = false,
        inputType = 'text', // 'text' | 'password' | 'number'
        placeholder = '',
        defaultValue = '',
        confirmText = getText('ok') || 'OK',
        cancelText = getText('cancel') || 'Cancel',
        showCancel = true
    } = options;

    return new Promise((resolve) => {
        const modalId = 'uiDialogModal';
        const modal = document.getElementById(modalId);
        const titleEl = document.getElementById('uiDialogTitle');
        const textEl = document.getElementById('uiDialogMessage');
        const labelEl = document.getElementById('uiDialogLabel');
        const inputEl = document.getElementById('uiDialogInput');
        const errorEl = document.getElementById('uiDialogError');
        const okBtn = document.getElementById('uiDialogOkBtn');
        const cancelBtn = document.getElementById('uiDialogCancelBtn');
        const closeBtn = document.getElementById('uiDialogCloseBtn');

        const formGroup = document.getElementById('uiDialogInputGroup');

        const cleanup = () => {
            if (okBtn) okBtn.onclick = null;
            if (cancelBtn) cancelBtn.onclick = null;
            if (closeBtn) closeBtn.onclick = null;
            if (inputEl) inputEl.onkeydown = null;
        };

        if (!modal || !okBtn) {
            // Safe fallback: do NOT auto-confirm.
            resolve({ confirmed: false, value: null });
            return;
        }

        if (titleEl) titleEl.innerHTML = `${title}`;
        if (textEl) textEl.textContent = message || '';
        if (errorEl) errorEl.style.display = 'none';

        if (formGroup) formGroup.style.display = input ? '' : 'none';
        if (labelEl) labelEl.textContent = input ? (getText('security-code-label') || 'Input') : '';
        if (inputEl) {
            inputEl.type = inputType;
            inputEl.value = input ? String(defaultValue || '') : '';
            inputEl.placeholder = input ? String(placeholder || '') : '';
        }

        okBtn.textContent = confirmText || (getText('ok') || 'OK');
        if (cancelBtn) {
            cancelBtn.textContent = cancelText || (getText('cancel') || 'Cancel');
            cancelBtn.style.display = showCancel ? '' : 'none';
        }

        const doCancel = () => {
            cleanup();
            try { hideModal(modalId); } catch(_) {}
            resolve({ confirmed: false, value: null });
        };

        const doOk = () => {
            const value = inputEl ? String(inputEl.value || '') : null;
            cleanup();
            try { hideModal(modalId); } catch(_) {}
            resolve({ confirmed: true, value });
        };

        okBtn.onclick = doOk;
        if (cancelBtn) cancelBtn.onclick = doCancel;
        if (closeBtn) closeBtn.onclick = doCancel;
        if (inputEl) {
            inputEl.onkeydown = (e) => {
                if (e.key === 'Enter') { e.preventDefault(); doOk(); }
                if (e.key === 'Escape') { e.preventDefault(); doCancel(); }
            };
        }

        showModal(modalId);
        if (input && inputEl) setTimeout(() => inputEl.focus(), 0);
    });
}

async function uiConfirm(message, opts = {}) {
    const r = await uiDialog({
        title: opts.title || (getText('confirm') || 'Confirm'),
        message,
        input: false,
        showCancel: true,
        confirmText: opts.confirmText || (getText('ok') || 'OK'),
        cancelText: opts.cancelText || (getText('cancel') || 'Cancel')
    });
    return !!r.confirmed;
}

async function uiPrompt(message, opts = {}) {
    const r = await uiDialog({
        title: opts.title || (getText('security-code-label') || 'Input'),
        message,
        input: true,
        inputType: opts.inputType || 'password',
        placeholder: opts.placeholder || '',
        defaultValue: opts.defaultValue || '',
        showCancel: true,
        confirmText: opts.confirmText || (getText('ok') || 'OK'),
        cancelText: opts.cancelText || (getText('cancel') || 'Cancel')
    });
    return r.confirmed ? (r.value || '') : null;
}

async function uiAlert(message, opts = {}) {
    await uiDialog({
        title: opts.title || (getText('error') || 'Message'),
        message,
        input: false,
        showCancel: false,
        confirmText: opts.confirmText || (getText('ok') || 'OK')
    });
}

// Expose for other modules
window.uiConfirm = uiConfirm;
window.uiPrompt = uiPrompt;
window.uiAlert = uiAlert;

function requestSecurityCodeModal({ titleKey }) {
    return new Promise((resolve) => {
        const modalId = 'securityCodeModal';
        const modal = document.getElementById(modalId);
        const title = document.getElementById('securityCodeTitle');
        const text = document.getElementById('securityCodeText');
        const label = document.getElementById('securityCodeLabel');
        const input = document.getElementById('securityCodeInput');
        const msg = document.getElementById('securityCodeMsg');
        const okBtn = document.getElementById('securityCodeApplyBtn');
        const cancelBtn = document.getElementById('securityCodeCancelBtn');
        const closeBtn = document.getElementById('closeSecurityCodeModal');

        const cleanup = () => {
            if (okBtn) okBtn.onclick = null;
            if (cancelBtn) cancelBtn.onclick = null;
            if (closeBtn) closeBtn.onclick = null;
            if (input) input.onkeydown = null;
        };

        if (!modal || !input || !okBtn || !cancelBtn) {
            // Fallback (should not happen): resolve false without exposing code
            resolve(false);
            return;
        }

        // Set localized text
        if (title) title.innerHTML = `<i class="fas fa-lock"></i> ${getText(titleKey) || getText('security-code-label') || 'Security code'}`;
        if (text) text.textContent = (document.documentElement.lang || 'en') === 'en'
            ? 'Please enter your admin code to continue.'
            : 'الرجاء إدخال رمز الأمان للمتابعة.';
        if (label) label.textContent = getText('security-code-label') || 'Security code';
        input.value = '';
        input.placeholder = getText('security-code-placeholder') || '';
        if (msg) msg.style.display = 'none';
        okBtn.textContent = getText('ok') || 'OK';
        cancelBtn.textContent = getText('cancel') || 'Cancel';

        const doCancel = () => {
            cleanup();
            try { hideModal(modalId); } catch(_) {}
            resolve(false);
        };

        const doOk = async () => {
            const entered = String(input.value || '').trim();
            const hashEntered = await hashStringForSecurityCode(entered);
            const storedHash = getStoredSecurityCodeHash();
            if (hashEntered !== storedHash) {
                if (msg) {
                    msg.textContent = getText('security-code-wrong') || 'Incorrect code';
                    msg.style.display = 'block';
                }
                input.focus();
                input.select();
                return;
            }
            cleanup();
            try { hideModal(modalId); } catch(_) {}
            resolve(true);
        };

        okBtn.onclick = doOk;
        cancelBtn.onclick = doCancel;
        if (closeBtn) closeBtn.onclick = doCancel;
        input.onkeydown = (e) => {
            if (e.key === 'Enter') { e.preventDefault(); doOk(); }
            if (e.key === 'Escape') { e.preventDefault(); doCancel(); }
        };

        showModal(modalId);
        setTimeout(() => input.focus(), 0);
    });
}

function editProduct(id) {
    closeAllProductActionsDropdowns();
    if (!hasProductPermission('canEditProducts')) {
        showPermissionDeniedMessage('تعديل المنتجات', 'edit products');
        return;
    }
    const product = products.find(p => p.id === id);
    if (!product) {
        showMessage(getText('msg-product-not-found'), 'error');
        return;
    }

    // Open edit flow directly without security code prompt.
    _continueEditProduct(id, product);
}

function _continueEditProduct(id, product) {
    const lang = document.documentElement.lang || 'ar';
    syncCartonConversionFormState();
    
    // ملء النموذج ببيانات المنتج الحالية
    const editProductName = document.getElementById('editProductName');
    const editProductCategory = document.getElementById('editProductCategory');
    const editProductExpiryDate = document.getElementById('editProductExpiryDate');
    const editProductCostUSD = document.getElementById('editProductCostUSD');
    const editProductQuantity = document.getElementById('editProductQuantity');
    const editProductBarcode = document.getElementById('editProductBarcode');
    const editProductSupplier = document.getElementById('editProductSupplier');

    const prices = product.prices && typeof product.prices === 'object' ? product.prices : {};
    const retailUSD = (prices.retail && typeof prices.retail.USD === 'number') ? prices.retail.USD : (product.priceUSD != null ? product.priceUSD : 0);
    const retailLBP = (prices.retail && typeof prices.retail.LBP === 'number') ? prices.retail.LBP : (product.priceLBP != null ? product.priceLBP : 0);
    const vipUSD = (prices.vip && typeof prices.vip.USD === 'number') ? prices.vip.USD : retailUSD;
    const vipLBP = (prices.vip && typeof prices.vip.LBP === 'number') ? prices.vip.LBP : retailLBP;
    const wholesaleUSD = (prices.wholesale && typeof prices.wholesale.USD === 'number') ? prices.wholesale.USD : retailUSD;
    const wholesaleLBP = (prices.wholesale && typeof prices.wholesale.LBP === 'number') ? prices.wholesale.LBP : retailLBP;

    if (editProductName) editProductName.value = product.name;
    selectEditProductCategory(product.category || '');
    if (editProductExpiryDate) editProductExpiryDate.value = normalizeExpiryDate(product.expiryDate);
    const editProductRetailUSD = document.getElementById('editProductRetailUSD');
    const editRetailLBPDisplay = document.getElementById('editRetailLBPDisplay');
    const editProductVipUSD = document.getElementById('editProductVipUSD');
    const editVipLBPDisplay = document.getElementById('editVipLBPDisplay');
    const editProductWholesaleUSD = document.getElementById('editProductWholesaleUSD');
    const editWholesaleLBPDisplay = document.getElementById('editWholesaleLBPDisplay');
    if (editProductRetailUSD) editProductRetailUSD.value = retailUSD;
    if (editRetailLBPDisplay) editRetailLBPDisplay.value = retailLBP > 0 ? retailLBP : '';
    if (editProductVipUSD) editProductVipUSD.value = vipUSD;
    if (editVipLBPDisplay) editVipLBPDisplay.value = vipLBP > 0 ? vipLBP : '';
    if (editProductWholesaleUSD) editProductWholesaleUSD.value = wholesaleUSD;
    if (editWholesaleLBPDisplay) editWholesaleLBPDisplay.value = wholesaleLBP > 0 ? wholesaleLBP : '';

    const editExchangeSpan = document.getElementById('editCurrentExchangeRate');
    if (editExchangeSpan && typeof settings !== 'undefined' && settings.exchangeRate) {
        editExchangeSpan.textContent = Number(settings.exchangeRate).toLocaleString();
    }

    const editImeiGroup = document.getElementById('editProductImeiGroup');
    const editImeiStatusSummary = document.getElementById('editImeiStatusSummary');
    const editNewImeis = document.getElementById('editProductNewImeis');
    if (product.imeiTracking && Array.isArray(product.imeiList)) {
        if (editImeiGroup) editImeiGroup.style.display = 'block';
        const list = product.imeiList;
        const available = list.filter(e => e.status === 'available').length;
        const sold = list.filter(e => e.status === 'sold').length;
        const returned = list.filter(e => e.status === 'returned').length;
        const lang = document.documentElement.lang || 'ar';
        if (editImeiStatusSummary) {
            editImeiStatusSummary.innerHTML = (lang === 'en' ? 'Available: ' : 'متوفر: ') + available + ' &nbsp;|&nbsp; ' +
                (lang === 'en' ? 'Sold: ' : 'مباع: ') + sold + ' &nbsp;|&nbsp; ' +
                (lang === 'en' ? 'Returned: ' : 'مرتجع: ') + returned;
        }
        if (editNewImeis) editNewImeis.value = '';
    } else {
        if (editImeiGroup) editImeiGroup.style.display = 'none';
    }
    if (editProductQuantity) {
        editProductQuantity.value = getProductSellableStock(product);
        editProductQuantity.readOnly = !!product.imeiTracking;
    }
    const editUnitType = document.getElementById('editProductUnitType');
    const editLinkedPackId = document.getElementById('editLinkedPackProductId');
    const editUnitsPerCarton = document.getElementById('editProductUnitsPerCarton');
    if (editUnitType) editUnitType.value = getProductUnitType(product);
    populateLinkedPackProductOptions('editLinkedPackProductId', getLinkedPackProductId(product), id);
    if (editLinkedPackId) editLinkedPackId.value = getLinkedPackProductId(product);
    if (editUnitsPerCarton) editUnitsPerCarton.value = isCartonLinkedProduct(product) ? getUnitsPerCarton(product) : '';
    updateLinkedProductFields('edit');

    if (editProductCostUSD) editProductCostUSD.value = product.costUSD || 0;
    if (editProductBarcode) editProductBarcode.value = product.barcode || '';
    
    // تحديث قائمة الموردين
    updateSuppliersDropdown('editProductSupplier');
    if (editProductSupplier) editProductSupplier.value = product.supplier || '';
    const editSupplierSearch = document.getElementById('editProductSupplierSearch');
    if (editSupplierSearch) {
        const sup = product.supplier && Array.isArray(suppliers)
            ? suppliers.find(s => String(s.id) === String(product.supplier))
            : null;
        editSupplierSearch.value = (sup && sup.name) ? sup.name : (product.supplierName || '');
    }
    
    // تخزين معرف المنتج الذي يتم تعديله
    document.getElementById('editProductForm').dataset.editId = id;
    
    // عرض الصورة الحالية إذا كانت موجودة
    const editImageInput = document.getElementById('editProductImage');
    const editPreviewImg = document.getElementById('editProductImagePreviewImg');
    const editPlaceholder = document.getElementById('editProductImagePlaceholder');
    const editRemoveBtn = document.getElementById('removeEditProductImageBtn');
    
    // إعادة تعيين حقل الصورة
    if (editImageInput) {
        editImageInput.value = '';
        editImageInput.dataset.removeImage = 'false';
    }
    
    if (product.imageUrl && (product.imageUrl.startsWith('data:image') || product.imageUrl.startsWith('http'))) {
        if (editPreviewImg) {
            editPreviewImg.src = product.imageUrl;
            editPreviewImg.style.display = 'block';
        }
        if (editPlaceholder) editPlaceholder.style.display = 'none';
        if (editRemoveBtn) editRemoveBtn.style.display = 'inline-flex';
    } else {
        if (editPreviewImg) {
            editPreviewImg.src = '';
            editPreviewImg.style.display = 'none';
        }
        if (editPlaceholder) editPlaceholder.style.display = 'flex';
        if (editRemoveBtn) editRemoveBtn.style.display = 'none';
    }

    markManualLbpFlagsForEditProduct();

    try { translateEditProductModal(); } catch(e) {}

    showModal('editProductModal');

    // التأكد من إعداد معالجات الأحداث للميزة الجديدة
    setTimeout(() => {
        initializeAddQuantityFeature();
        initializeAddQuantityInputHandlers();
        initializeAddQuantityFormHandler();
    }, 100);
}

// Adjust Stock modal
