// تحميل الإعدادات
function loadSettings() {
    const storeName = document.getElementById('storeName');
    const storeAddress = document.getElementById('storeAddress');
    const storePhone = document.getElementById('storePhone');
    const exchangeRateInput = document.getElementById('exchangeRateInput');
    const lowStockThreshold = document.getElementById('lowStockThreshold');
    const lowStockAlertCheckbox = document.getElementById('lowStockAlertCheckbox');
    
    if (storeName) storeName.value = settings.storeName;
    if (storeAddress) storeAddress.value = settings.storeAddress;
    if (storePhone) storePhone.value = settings.storePhone;
    const printFormatSelect = document.getElementById('printFormatSelect');
    if (printFormatSelect) printFormatSelect.value = settings.printFormat || 'thermal80';
    try { refreshStoreLogoPreview(); } catch (_) {}
    if (exchangeRateInput) {
        exchangeRateInput.value = settings.exchangeRate;
        formatSettingsExchangeRateInput();
    }
    // تم إزالة إعدادات الضريبة
    if (lowStockThreshold) lowStockThreshold.value = settings.lowStockThreshold || 10;
    if (lowStockAlertCheckbox) lowStockAlertCheckbox.checked = settings.lowStockAlert !== false;
    
    // إشعارات Telegram
    const telegramEnabled = document.getElementById('telegramEnabled');
    const telegramBotToken = document.getElementById('telegramBotToken');
    const telegramChatId = document.getElementById('telegramChatId');
    if (telegramEnabled) telegramEnabled.checked = settings.telegramEnabled === true;
    const canViewSensitive = !(typeof isSubUser === 'function' && isSubUser()) || hasPermission('canViewSensitiveData');
    const canEditSensitive = !(typeof isSubUser === 'function' && isSubUser()) || canCurrentUserEditSettings();
    if (telegramBotToken) {
        telegramBotToken.value = canViewSensitive ? (settings.telegramBotToken || '') : '';
        telegramBotToken.readOnly = !canEditSensitive;
    }
    if (telegramChatId) {
        telegramChatId.value = canViewSensitive ? (settings.telegramChatId || '') : '';
        telegramChatId.readOnly = !canEditSensitive;
    }
    var tgProxyUrl = document.getElementById('telegramProxyUrl');
    var tgProxySec = document.getElementById('telegramProxySecret');
    const aiInsightsEnabled = document.getElementById('aiInsightsEnabled');
    const aiInsightsReportTime = document.getElementById('aiInsightsReportTime');
    const aiAlertSales = document.getElementById('aiAlertSales');
    const aiAlertInventory = document.getElementById('aiAlertInventory');
    const aiAlertCustomers = document.getElementById('aiAlertCustomers');
    const aiAlertManagement = document.getElementById('aiAlertManagement');
    if (tgProxyUrl) {
        tgProxyUrl.value = canViewSensitive ? (settings.telegramProxyUrl || '') : '';
        tgProxyUrl.readOnly = !canEditSensitive;
    }
    if (tgProxySec) {
        tgProxySec.value = canViewSensitive ? (settings.telegramProxySecret || '') : '';
        tgProxySec.readOnly = !canEditSensitive;
    }
    const ev = settings.telegramEvents || {};
    ['tgEventSaleCreated', 'tgEventSaleReturned', 'tgEventPriceEdited', 'tgEventCashDrawer', 'tgEventCashMovement', 'tgEventSupplierPayment'].forEach(function(id, i) {
        const key = ['sale_created', 'sale_returned', 'price_edited', 'cash_drawer', 'cash_movement', 'supplier_payment'][i];
        const el = document.getElementById(id);
        if (el) el.checked = ev[key] !== false;
    });
    const aiCfg = (settings.aiInsightAlerts && typeof settings.aiInsightAlerts === 'object') ? settings.aiInsightAlerts : {};
    if (aiInsightsEnabled) aiInsightsEnabled.checked = settings.aiInsightsEnabled === true;
    if (aiInsightsReportTime) aiInsightsReportTime.value = String(settings.aiInsightsReportTime || '09:00');
    if (aiAlertSales) aiAlertSales.checked = aiCfg.sales !== false;
    if (aiAlertInventory) aiAlertInventory.checked = aiCfg.inventory !== false;
    if (aiAlertCustomers) aiAlertCustomers.checked = aiCfg.customers !== false;
    if (aiAlertManagement) aiAlertManagement.checked = aiCfg.management !== false;
    
    // إظهار/إخفاء مجموعة حد التحذير
    toggleStockThresholdGroup();
    
    // تحديث عرض الصندوق الحالي
    updateCashDrawerSettings();
    
    // إدارة اليوزرز الفرعيين (للأدمين فقط)
    initSubUsersSection();
    applySettingsGlobalControlsAccessUI();
    initSettingsTabs();
}

function applySettingsGlobalControlsAccessUI() {
    applySensitiveSettingsAccessUI();

    const isOwner = canManageGlobalSettings();
    const publishPanel = document.getElementById('testPublishControls');
    if (publishPanel) {
        publishPanel.style.display = 'none';
        publishPanel.setAttribute('hidden', 'hidden');
        publishPanel.setAttribute('aria-hidden', 'true');
    }

    const tabAccess = {
        store: true,
        currency: isOwner,
        notifications: isOwner || hasPermission('canViewSensitiveData'),
        ai: isOwner,
        backup: isOwner || hasPermission('canImportProducts') || hasPermission('canExportProducts'),
        security: isOwner
    };
    document.querySelectorAll('#settingsTabs .settings-tab').forEach((tab) => {
        const id = tab.getAttribute('data-settings-tab');
        tab.style.display = tabAccess[id] ? '' : 'none';
    });

    const resetZone = document.getElementById('resetLicenseZone');
    if (resetZone) resetZone.style.display = isOwner ? '' : 'none';

    const clearZone = document.getElementById('clearDataDangerZone');
    if (clearZone) clearZone.style.display = isOwner ? '' : 'none';

    const updateRateBtn = document.getElementById('updateExchangeRate');
    const exchangeInput = document.getElementById('exchangeRateInput');
    const primaryCurrency = document.getElementById('primaryCurrency');
    const openCashMove = document.getElementById('openCashMove');
    if (updateRateBtn) updateRateBtn.style.display = isOwner ? '' : 'none';
    if (exchangeInput) exchangeInput.readOnly = !isOwner;
    if (primaryCurrency) primaryCurrency.disabled = !isOwner;
    if (openCashMove) openCashMove.style.display = isOwner || hasPermission('canManageCashDrawer') ? '' : 'none';

    const autoBackupCheckbox = document.getElementById('autoBackupCheckbox');
    if (autoBackupCheckbox) autoBackupCheckbox.disabled = !isOwner;

    const productImagesSection = document.getElementById('productImagesExportSection');
    if (productImagesSection) {
        const canImportImages = isOwner || hasPermission('canImportProducts');
        productImagesSection.style.display = canImportImages ? '' : 'none';
    }

    try { applyProductPermissionsUI(); } catch (_) {}
    try { refreshAppUpdatePublishControls(window.__lastAppUpdateControlState || {}); } catch (_) {}
    try { renderAppBuildDebugPanel(window.__lastAppUpdateControlState || null); } catch (_) {}
    try { initSettingsTabs(); } catch (_) {}
}

function toggleStockThresholdGroup() {
    const checkbox = document.getElementById('lowStockAlertCheckbox');
    const group = document.getElementById('stockThresholdGroup');
    if (group) {
        group.style.display = checkbox && checkbox.checked ? 'block' : 'none';
    }
}

function getSanitizedSettingsForCurrentUser(sourceSettings) {
    const base = { ...(sourceSettings || {}) };
    if (typeof isSubUser === 'function' && isSubUser()) {
        if (!hasPermission('canViewSensitiveData')) {
            delete base.telegramBotToken;
            delete base.telegramChatId;
            delete base.telegramProxySecret;
            delete base.telegramProxyUrl;
        }
        if (!canCurrentUserEditSettings()) {
            delete base.securityCodeHash;
        }
    }
    return base;
}

function applySensitiveSettingsAccessUI() {
    const restricted = typeof isSubUser === 'function' && isSubUser();
    const canViewSensitive = !restricted || hasPermission('canViewSensitiveData');
    const canEditSettings = !restricted || canCurrentUserEditSettings();
    const sensitiveIds = ['telegramBotToken', 'telegramChatId', 'telegramProxyUrl', 'telegramProxySecret', 'telegramSaveBtn', 'telegramTestBtn', 'aiSaveBtn', 'aiRunNowBtn'];
    sensitiveIds.forEach((id) => {
        const el = document.getElementById(id);
        if (!el) return;
        if (!canViewSensitive) {
            if ('value' in el) el.value = '';
            el.setAttribute('disabled', 'disabled');
            const row = el.closest('.setting-group, .advanced-proxy-wrap, .settings-card, .settings-grid > div');
            if (row) row.style.display = 'none';
        } else if (!canEditSettings && (el.tagName === 'INPUT' || el.tagName === 'BUTTON' || el.tagName === 'TEXTAREA' || el.tagName === 'SELECT')) {
            el.setAttribute('disabled', 'disabled');
        } else {
            el.removeAttribute('disabled');
        }
    });

    const hintId = 'sensitiveSettingsHint';
    let hint = document.getElementById(hintId);
    if (!canViewSensitive) {
        if (!hint) {
            hint = document.createElement('div');
            hint.id = hintId;
            hint.className = 'settings-hint';
            const anchor = document.getElementById('telegramEnabled')?.closest('.settings-card') || document.getElementById('telegramEnabled')?.parentElement;
            if (anchor && anchor.parentElement) anchor.parentElement.insertBefore(hint, anchor.nextSibling);
        }
        hint.textContent = getText('msg-sensitive-settings-hidden') || 'Sensitive settings are hidden because your permissions do not allow viewing or editing them.';
    } else if (hint && hint.parentElement) {
        hint.parentElement.removeChild(hint);
    }
}

function getCreateSubUserFunctionUrl() {
    try {
        if (typeof firebase !== 'undefined' && firebase.app && firebase.app()) {
            const pid = firebase.app().options && firebase.app().options.projectId;
            if (pid) return 'https://us-central1-' + pid + '.cloudfunctions.net/createSubUser';
        }
    } catch (_) {}
    return 'https://us-central1-pos-catch.cloudfunctions.net/createSubUser';
}
function showAddSubUserModal() {
    document.getElementById('addSubUserModal').classList.add('active');
    if (document.getElementById('overlay')) document.getElementById('overlay').classList.add('active');
    document.getElementById('subUserEmail').value = '';
    document.getElementById('subUserPassword').value = '';
    document.getElementById('subUserName').value = '';
    document.getElementById('subUserCanSell').checked = true;
    document.getElementById('subUserCanEditPrice').checked = true;
    document.getElementById('subUserCanViewSales').checked = true;
    document.getElementById('subUserCanViewProducts').checked = true;
    const canAddProductsEl = document.getElementById('subUserCanAddProducts');
    const canEditProductsEl = document.getElementById('subUserCanEditProducts');
    const canDeleteProductsEl = document.getElementById('subUserCanDeleteProducts');
    const canImportProductsEl = document.getElementById('subUserCanImportProducts');
    const canExportProductsEl = document.getElementById('subUserCanExportProducts');
    document.getElementById('subUserCanViewCustomers').checked = true;
    document.getElementById('subUserCanViewReports').checked = true;
    document.getElementById('subUserCanViewSuppliers').checked = false;
    document.getElementById('subUserCanManageCashDrawer').checked = false;
    const canViewSettingsEl = document.getElementById('subUserCanViewSettings');
    const canViewCostsEl = document.getElementById('subUserCanViewCosts');
    const canViewSensitiveDataEl = document.getElementById('subUserCanViewSensitiveData');
    const canManageUsersEl = document.getElementById('subUserCanManageUsers');
    if (canAddProductsEl) canAddProductsEl.checked = false;
    if (canEditProductsEl) canEditProductsEl.checked = false;
    if (canDeleteProductsEl) canDeleteProductsEl.checked = false;
    if (canImportProductsEl) canImportProductsEl.checked = false;
    if (canExportProductsEl) canExportProductsEl.checked = false;
    if (canViewSettingsEl) canViewSettingsEl.checked = false;
    if (canViewCostsEl) canViewCostsEl.checked = false;
    if (canViewSensitiveDataEl) canViewSensitiveDataEl.checked = false;
    if (canManageUsersEl) canManageUsersEl.checked = false;
    try {
        if (typeof translateElements === 'function') translateElements();
    } catch (_) {}
}
function hideAddSubUserModal() {
    const m = document.getElementById('addSubUserModal');
    if (m) m.classList.remove('active');
    try {
        const anyOpen = document.querySelector('.modal.active');
        if (!anyOpen && document.getElementById('overlay')) document.getElementById('overlay').classList.remove('active');
    } catch (_) {
        if (document.getElementById('overlay')) document.getElementById('overlay').classList.remove('active');
    }
}
async function initSubUsersSection() {
    const section = document.getElementById('subUsersSection');
    const addBtn = document.getElementById('addSubUserBtn');
    if (!section) return;
    if (typeof isSubUser === 'function' && isSubUser()) {
        section.style.display = 'none';
        return;
    }
    section.style.display = 'block';
    if (addBtn && !addBtn._bound) {
        addBtn._bound = true;
        addBtn.addEventListener('click', showAddSubUserModal);
    }
    const confirmBtn = document.getElementById('addSubUserConfirmBtn');
    if (confirmBtn && !confirmBtn._bound) {
        confirmBtn._bound = true;
        confirmBtn.addEventListener('click', async function() {
            const email = (document.getElementById('subUserEmail')?.value || '').trim();
            const password = document.getElementById('subUserPassword')?.value || '';
            const name = (document.getElementById('subUserName')?.value || '').trim();
            if (!email) { showMessage(typeof getText === 'function' ? getText('sub-user-email-required') : 'Enter email', 'error'); return; }
            if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
                showMessage((document.documentElement.lang || 'ar') === 'en'
                    ? 'Please enter a valid email address (example: user@example.com)'
                    : 'يرجى إدخال بريد إلكتروني صحيح (مثال: user@example.com)', 'error');
                return;
            }
            if (password.length < 6) { showMessage(typeof getText === 'function' ? getText('sub-user-password-short') : 'Password too short', 'error'); return; }
            const permissions = {
                canSell: document.getElementById('subUserCanSell')?.checked ?? true,
                canEditPrice: document.getElementById('subUserCanEditPrice')?.checked ?? true,
                canViewSales: document.getElementById('subUserCanViewSales')?.checked ?? true,
                canViewProducts: document.getElementById('subUserCanViewProducts')?.checked ?? true,
                canAddProducts: document.getElementById('subUserCanAddProducts')?.checked ?? false,
                canEditProducts: document.getElementById('subUserCanEditProducts')?.checked ?? false,
                canDeleteProducts: document.getElementById('subUserCanDeleteProducts')?.checked ?? false,
                canImportProducts: document.getElementById('subUserCanImportProducts')?.checked ?? false,
                canExportProducts: document.getElementById('subUserCanExportProducts')?.checked ?? false,
                canViewCustomers: document.getElementById('subUserCanViewCustomers')?.checked ?? true,
                canViewReports: document.getElementById('subUserCanViewReports')?.checked ?? true,
                canViewSuppliers: document.getElementById('subUserCanViewSuppliers')?.checked ?? false,
                canManageCashDrawer: document.getElementById('subUserCanManageCashDrawer')?.checked ?? false,
                canViewSettings: document.getElementById('subUserCanViewSettings')?.checked ?? false,
                canEditSettings: false,
                canViewCosts: document.getElementById('subUserCanViewCosts')?.checked ?? false,
                canViewSensitiveData: document.getElementById('subUserCanViewSensitiveData')?.checked ?? false,
                canManageUsers: document.getElementById('subUserCanManageUsers')?.checked ?? false
            };
            if (!permissions.canViewProducts) {
                permissions.canAddProducts = false;
                permissions.canEditProducts = false;
                permissions.canDeleteProducts = false;
                permissions.canImportProducts = false;
                permissions.canExportProducts = false;
            }
            try {
                const token = await (window.firebaseAuthInstance?.auth?.currentUser?.getIdToken?.() || (async () => { const u = firebase.auth().currentUser; return u ? u.getIdToken() : null; })());
                if (!token) { showMessage(typeof getText === 'function' ? getText('sub-user-session-expired') : 'Session expired', 'error'); return; }
                const r = await fetch(getCreateSubUserFunctionUrl(), {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + token },
                    body: JSON.stringify({ email, password, name: name || email.split('@')[0], permissions })
                });
                const raw = await r.text();
                let data = {};
                try { data = raw ? JSON.parse(raw) : {}; } catch (_) { data = { message: raw.slice(0, 200) }; }
                if (data.success) {
                    hideAddSubUserModal();
                    loadSubUsersList();
                    const msg = typeof getText === 'function'
                        ? getText('sub-user-created', { email: data.email || email })
                        : ('Created: ' + (data.email || email));
                    showNotification(msg, 'success', 3000);
                } else {
                    const detail = data.message || data.error || raw || ('HTTP ' + r.status);
                    showMessage(
                        (typeof getText === 'function' ? getText('sub-user-create-failed') : 'Failed') + (detail ? ': ' + detail : ''),
                        'error'
                    );
                }
            } catch (e) {
                showMessage((typeof getText === 'function' ? getText('sub-user-network-error') : 'Network error') + (e.message ? ': ' + e.message : ''), 'error');
            }
        });
    }
    await loadSubUsersList();
}
async function loadSubUsersList() {
    const listEl = document.getElementById('subUsersList');
    if (!listEl) return;
    if (typeof isSubUser === 'function' && isSubUser()) {
        listEl.innerHTML = '';
        return;
    }
    const effUid = typeof getEffectiveDataOwnerId === 'function' ? getEffectiveDataOwnerId() : (currentUser && currentUser.uid);
    const authUid = (typeof currentUser === 'object' && currentUser && currentUser.uid) ? currentUser.uid : null;
    const isSuper = !!(typeof currentUser === 'object' && currentUser && currentUser.claims && (currentUser.claims.super_admin === true || currentUser.claims.superAdmin === true));
    if (authUid && effUid && authUid !== effUid && !isSuper) {
        listEl.innerHTML = '';
        return;
    }
    if (!effUid || !window.firebaseDbInstance) { listEl.innerHTML = ''; return; }
    const esc = typeof escapeHtml === 'function' ? escapeHtml : function (s) { return String(s || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); };
    const t = typeof getText === 'function' ? getText : function (k) { return k; };
    try {
        const subs = await window.firebaseDbInstance.getSubUsers(effUid);
        if (!subs || subs.length === 0) {
            listEl.innerHTML = '<p class="sub-users-empty-msg">' + esc(t('sub-users-empty')) + '</p>';
            return;
        }
        listEl.innerHTML = subs.map(s => {
            const p = s.permissions || {};
            const perms = [];
            if (p.canSell) perms.push(t('perm-sell'));
            if (p.canEditPrice) perms.push(t('perm-edit-price'));
            if (p.canViewSales) perms.push(t('perm-view-sales'));
            if (p.canViewProducts) perms.push(t('perm-view-products'));
            if (p.canAddProducts) perms.push(t('perm-add-products'));
            if (p.canEditProducts) perms.push(t('perm-edit-products'));
            if (p.canDeleteProducts) perms.push(t('perm-delete-products'));
            if (p.canImportProducts) perms.push(t('perm-import-products'));
            if (p.canExportProducts) perms.push(t('perm-export-products'));
            if (p.canViewCustomers) perms.push(t('perm-view-customers'));
            if (p.canViewReports) perms.push(t('perm-reports'));
            if (p.canViewSuppliers) perms.push(t('perm-suppliers'));
            if (p.canManageCashDrawer) perms.push(t('perm-cashbox'));
            if (p.canViewSettings) perms.push(t('perm-settings'));
            if (p.canEditSettings) perms.push(t('perm-edit-settings'));
            if (p.canViewCosts) perms.push(t('perm-view-costs'));
            if (p.canViewSensitiveData) perms.push(t('perm-sensitive-data'));
            if (p.canManageUsers) perms.push(t('perm-manage-users'));
            const nm = esc(s.fullName || s.name || s.email || '');
            const em = esc(s.email || '');
            const sid = String(s.id || '').replace(/\\/g, '\\\\').replace(/'/g, "\\'");
            const btnLabel = s.isActive ? t('sub-user-deactivate') : t('sub-user-activate');
            const permLine = perms.length ? esc(perms.join(' · ')) : esc(t('sub-user-no-perms'));
            const checked = (flag) => p[flag] ? 'checked' : '';
            return '<div class="sub-user-card">' +
                '<div><strong>' + nm + '</strong><div class="sub-user-meta">' + em + '</div><div class="sub-user-meta">' + permLine + '</div></div>' +
                '<div><button type="button" class="filter-btn sub-user-toggle-btn" onclick="toggleSubUserActive(\'' + sid + '\',' + (!s.isActive ? 'true' : 'false') + ')">' + esc(btnLabel) + '</button></div>' +
                '<div class="sub-user-perms-inline" data-sub-user-id="' + sid + '">' +
                    '<div class="sub-user-perm-col">' +
                        '<div class="sub-user-perm-col-title">' + esc(t('perm-section-products')) + '</div>' +
                        '<label><input type="checkbox" data-perm="canViewProducts" ' + checked('canViewProducts') + '> ' + esc(t('perm-view-products')) + '</label>' +
                        '<label><input type="checkbox" data-perm="canAddProducts" ' + checked('canAddProducts') + '> ' + esc(t('perm-add-products')) + '</label>' +
                        '<label><input type="checkbox" data-perm="canEditProducts" ' + checked('canEditProducts') + '> ' + esc(t('perm-edit-products')) + '</label>' +
                        '<label><input type="checkbox" data-perm="canDeleteProducts" ' + checked('canDeleteProducts') + '> ' + esc(t('perm-delete-products')) + '</label>' +
                        '<label><input type="checkbox" data-perm="canImportProducts" ' + checked('canImportProducts') + '> ' + esc(t('perm-import-products')) + '</label>' +
                        '<label><input type="checkbox" data-perm="canExportProducts" ' + checked('canExportProducts') + '> ' + esc(t('perm-export-products')) + '</label>' +
                    '</div>' +
                    '<div class="sub-user-perm-col">' +
                        '<div class="sub-user-perm-col-title">' + esc(t('perm-section-sales')) + '</div>' +
                        '<label><input type="checkbox" data-perm="canSell" ' + checked('canSell') + '> ' + esc(t('perm-sell')) + '</label>' +
                        '<label><input type="checkbox" data-perm="canEditPrice" ' + checked('canEditPrice') + '> ' + esc(t('perm-edit-price')) + '</label>' +
                        '<label><input type="checkbox" data-perm="canViewSales" ' + checked('canViewSales') + '> ' + esc(t('perm-view-sales')) + '</label>' +
                    '</div>' +
                    '<div class="sub-user-perm-col">' +
                        '<div class="sub-user-perm-col-title">' + esc(t('perm-section-management')) + '</div>' +
                        '<label><input type="checkbox" data-perm="canViewCustomers" ' + checked('canViewCustomers') + '> ' + esc(t('perm-view-customers')) + '</label>' +
                        '<label><input type="checkbox" data-perm="canViewReports" ' + checked('canViewReports') + '> ' + esc(t('perm-reports')) + '</label>' +
                        '<label><input type="checkbox" data-perm="canViewSuppliers" ' + checked('canViewSuppliers') + '> ' + esc(t('perm-suppliers')) + '</label>' +
                        '<label><input type="checkbox" data-perm="canManageCashDrawer" ' + checked('canManageCashDrawer') + '> ' + esc(t('perm-cashbox')) + '</label>' +
                        '<label><input type="checkbox" data-perm="canViewSettings" ' + checked('canViewSettings') + '> ' + esc(t('perm-settings')) + '</label>' +
                        '<label><input type="checkbox" data-perm="canEditSettings" ' + checked('canEditSettings') + '> ' + esc(t('perm-edit-settings')) + '</label>' +
                        '<label><input type="checkbox" data-perm="canViewCosts" ' + checked('canViewCosts') + '> ' + esc(t('perm-view-costs')) + '</label>' +
                        '<label><input type="checkbox" data-perm="canViewSensitiveData" ' + checked('canViewSensitiveData') + '> ' + esc(t('perm-sensitive-data')) + '</label>' +
                        '<label><input type="checkbox" data-perm="canManageUsers" ' + checked('canManageUsers') + '> ' + esc(t('perm-manage-users')) + '</label>' +
                    '</div>' +
                    '<div class="sub-user-perm-actions">' +
                        '<button type="button" class="save-btn sub-user-save-perms-btn" onclick="saveSubUserPermissions(\'' + sid + '\', this)">' + esc(t('sub-user-save-perms')) + '</button>' +
                    '</div>' +
                '</div>' +
                '</div>';
        }).join('');
    } catch (e) {
        listEl.innerHTML = '<p class="sub-users-error-msg">' + esc(t('sub-users-load-error')) + '</p>';
    }
}

async function saveSubUserPermissions(subUserId, btnEl) {
    if (!window.firebaseDbInstance) return;
    const card = btnEl && btnEl.closest ? btnEl.closest('.sub-user-card') : null;
    if (!card) return;
    const permissions = {};
    card.querySelectorAll('.sub-user-perms-inline input[data-perm]').forEach((inp) => {
        permissions[inp.getAttribute('data-perm')] = !!inp.checked;
    });
    if (!permissions.canViewProducts) {
        permissions.canAddProducts = false;
        permissions.canEditProducts = false;
        permissions.canDeleteProducts = false;
        permissions.canImportProducts = false;
        permissions.canExportProducts = false;
    }
    try {
        if (btnEl) btnEl.disabled = true;
        await window.firebaseDbInstance.updateUser(subUserId, { permissions });
        try {
            if (currentUser && String(currentUser.uid) === String(subUserId)) {
                currentUser.permissions = { ...(currentUser.permissions || {}), ...permissions };
                if (typeof applyNavPermissions === 'function') applyNavPermissions();
                if (typeof applyCostVisibility === 'function') applyCostVisibility();
            }
        } catch (_) {}
        showNotification(typeof getText === 'function' ? getText('sub-user-perms-updated') : 'Permissions updated', 'success', 1800);
        loadSubUsersList();
    } catch (e) {
        showMessage((typeof getText === 'function' ? getText('sub-user-toggle-failed') : 'Update failed') + (e.message ? ': ' + e.message : ''), 'error');
    } finally {
        if (btnEl) btnEl.disabled = false;
    }
}
function applyNavPermissions() {
    if (typeof hasPermission !== 'function' || typeof isSubUser !== 'function') return;
    const restrictedUser = isSubUser();
    document.querySelectorAll('.nav-item[data-permission]').forEach(function(el) {
        const perm = el.getAttribute('data-permission');
        if (restrictedUser && perm && !hasPermission(perm)) {
            el.style.display = 'none';
        } else {
            el.style.display = '';
        }
    });
    if (restrictedUser) {
        const activePage = document.querySelector('.page.active');
        const activeScreen = activePage ? activePage.id : null;
        if (activeScreen && !canCurrentUserAccessScreen(activeScreen, null)) {
            const dashboardNav = document.querySelector('.nav-item[data-screen="dashboard"]');
            if (dashboardNav) __navigateFromNavItem(dashboardNav);
        }
    }
    applyProductPermissionsUI();
}

async function toggleSubUserActive(subUserId, isActive) {
    if (!window.firebaseDbInstance) return;
    try {
        await window.firebaseDbInstance.updateUser(subUserId, { isActive });
        loadSubUsersList();
        const msg = typeof getText === 'function'
            ? getText(isActive ? 'sub-user-toggled-on' : 'sub-user-toggled-off')
            : (isActive ? 'Enabled' : 'Disabled');
        showNotification(msg, 'success', 2000);
    } catch (e) {
        showMessage((typeof getText === 'function' ? getText('sub-user-toggle-failed') : 'Update failed') + (e.message ? ': ' + e.message : ''), 'error');
    }
}

function updateCashDrawerSettings() {
    // Ensure the latest values ​​are loaded from storage before rendering (ensuring no outdated values ​​appear)
    const stored = loadFromStorage('cashDrawer', null);
    if (stored && typeof stored === 'object') {
        cashDrawer.cashUSD = Number(stored.cashUSD) ?? cashDrawer.cashUSD;
        cashDrawer.cashLBP = Number(stored.cashLBP) ?? cashDrawer.cashLBP;
        if (Array.isArray(stored.transactions)) cashDrawer.transactions = stored.transactions;
        if (stored.lastUpdate) cashDrawer.lastUpdate = stored.lastUpdate;
    }
    const currentUSD = document.getElementById('currentUSD');
    const currentLBP = document.getElementById('currentLBP');
    const editCashUSD = document.getElementById('editCashUSD');
    const editCashLBP = document.getElementById('editCashLBP');
    
    if (currentUSD) currentUSD.textContent = formatCurrency(cashDrawer.cashUSD ?? 0, 'USD');
    if (currentLBP) currentLBP.textContent = formatCurrency(cashDrawer.cashLBP ?? 0, 'LBP');
    if (editCashUSD) editCashUSD.value = cashDrawer.cashUSD ?? 0;
    if (editCashLBP) editCashLBP.value = cashDrawer.cashLBP ?? 0;
}

// Update exchange rate (save to local storage and Firestore to remain after update)
document.getElementById('updateExchangeRate').addEventListener('click', async function() {
    if (!canManageGlobalSettings()) {
        showMessage(getText('msg-permission-denied') || 'You do not have permission for this action.', 'error');
        return;
    }
    const btn = this;
    const newRate = parseFloat(document.getElementById('exchangeRateInput').value);
    if (!(newRate > 0)) {
        showMessage(getText('msg-enter-valid-exchange'), 'error');
        return;
    }
    setSettingsButtonLoading(btn, true, getText('saving') || 'Saving...');
    try {
        settings.exchangeRate = Math.round(newRate);
        saveToStorage('settings', settings);
        if (typeof saveAllData === 'function') await saveAllData();
        formatSettingsExchangeRateInput();
        const rateSuffix = (document.documentElement.lang || 'ar') === 'en' ? 'LBP' : 'L';
        const exchangeRateEl = document.getElementById('exchangeRate');
        if (exchangeRateEl) exchangeRateEl.textContent = `${getText('exchange-rate')}: ${Math.round(newRate).toLocaleString()} ${rateSuffix}`;
        const currentRateEl = document.getElementById('currentExchangeRate');
        if (currentRateEl) currentRateEl.textContent = Math.round(newRate).toLocaleString();
        showNotification('✅ ' + (getText('exchange-rate-updated') || 'Exchange rate updated.'), 'success', 2500);
    } finally {
        setSettingsButtonLoading(btn, false);
    }
});

