// Manage pop-ups
function getAppSidebarOffsetPx() {
    if (window.innerWidth <= 768) return 0;
    const main = document.querySelector('.main-content');
    if (!main || main.classList.contains('sidebar-hidden')) return 0;
    const sidebar = document.getElementById('sidebar') || document.querySelector('.sidebar');
    if (sidebar && sidebar.classList.contains('sidebar-compact')) return 78;
    return 200;
}

function getMainContentCenterX(sidebarOffset) {
    const offset = sidebarOffset == null ? getAppSidebarOffsetPx() : sidebarOffset;
    const vw = window.innerWidth;
    const dir = String(document.documentElement.getAttribute('dir') || 'rtl').toLowerCase();
    if (dir === 'ltr') {
        return offset + (vw - offset) / 2;
    }
    return (vw - offset) / 2;
}

function layoutPosFormModal(modalId) {
    const modal = document.getElementById(modalId);
    if (!modal || !modal.classList.contains('active')) return;

    const sidebarOffset = getAppSidebarOffsetPx();
    const vw = window.innerWidth;
    const contentW = Math.max(280, vw - sidebarOffset);
    const maxW = modalId === 'addQuantityModal' ? 560 : 900;
    const modalW = Math.min(maxW, contentW - 48);
    const centerX = getMainContentCenterX(sidebarOffset);

    modal.classList.add('is-main-centered');
    modal.style.inset = 'auto';
    modal.style.top = '50%';
    modal.style.left = centerX + 'px';
    modal.style.right = 'auto';
    modal.style.bottom = 'auto';
    modal.style.transform = 'translate(-50%, -50%)';
    modal.style.width = modalW + 'px';
    modal.style.maxWidth = maxW + 'px';
    modal.style.maxHeight = '85vh';
}

function layoutAddProductModal() {
    layoutPosFormModal('addProductModal');
}

function layoutEditProductModal() {
    layoutPosFormModal('editProductModal');
}

function resetPosFormModalLayout(modalId) {
    const modal = document.getElementById(modalId);
    if (!modal) return;
    modal.classList.remove('is-main-centered');
    modal.style.removeProperty('inset');
    modal.style.removeProperty('top');
    modal.style.removeProperty('left');
    modal.style.removeProperty('right');
    modal.style.removeProperty('bottom');
    modal.style.removeProperty('transform');
    modal.style.removeProperty('width');
    modal.style.removeProperty('max-width');
    modal.style.removeProperty('max-height');
}

function resetAddProductModalLayout() {
    resetPosFormModalLayout('addProductModal');
}

function resetEditProductModalLayout() {
    resetPosFormModalLayout('editProductModal');
}

function syncModalOpenBodyState() {
    const anyOpen = document.querySelector('.modal.active');
    document.body.classList.toggle('modal-open', !!anyOpen);
}

function showModal(modalId) {
    document.getElementById('overlay').classList.add('active');
    document.getElementById(modalId).classList.add('active');
    syncModalOpenBodyState();
    if (modalId === 'addProductModal') {
        if (typeof removeProductImage === 'function') removeProductImage();
        layoutAddProductModal();
    }
    if (modalId === 'editProductModal') {
        layoutEditProductModal();
    }
    if (modalId === 'addQuantityModal') {
        layoutPosFormModal('addQuantityModal');
    }
    closeAllProductActionsDropdowns();
}

function hideModal(modalId) {
    if (modalId === 'addProductModal') {
        if (typeof removeProductImage === 'function') removeProductImage();
        resetAddProductModalLayout();
    }
    if (modalId === 'editProductModal') {
        resetEditProductModalLayout();
        if (typeof removeEditProductImage === 'function') removeEditProductImage();
    }
    if (modalId === 'addQuantityModal') {
        resetPosFormModalLayout('addQuantityModal');
    }
    document.getElementById(modalId).classList.remove('active');
    // Keep overlay active if another modal is still open (nested modals like Add Supplier from Add Product)
    try {
        const anyOpen = document.querySelector('.modal.active');
        if (!anyOpen) document.getElementById('overlay').classList.remove('active');
    } catch (_) {
        document.getElementById('overlay').classList.remove('active');
    }
    syncModalOpenBodyState();
    if (document.getElementById('addProductModal')?.classList.contains('active')) {
        layoutAddProductModal();
    }
    if (document.getElementById('editProductModal')?.classList.contains('active')) {
        layoutEditProductModal();
    }
}

window.addEventListener('resize', function () {
    try {
        layoutAddProductModal();
        layoutEditProductModal();
        layoutPosFormModal('addQuantityModal');
    } catch (_) {}
});

// Close pop-ups
document.getElementById('overlay').addEventListener('click', function() {
    document.querySelectorAll('.modal').forEach(modal => {
        if (modal.id === 'addProductModal') {
            if (typeof removeProductImage === 'function') removeProductImage();
            resetAddProductModalLayout();
        }
        if (modal.id === 'editProductModal') {
            resetEditProductModalLayout();
            if (typeof removeEditProductImage === 'function') removeEditProductImage();
        }
        modal.classList.remove('active');
    });
    // Also: Close the mobile menu if it is open
    try {
        const sb = document.querySelector('.sidebar');
        if (sb && sb.classList.contains('open')) sb.classList.remove('open');
    } catch(_) {}
    this.classList.remove('active');
    syncModalOpenBodyState();
});

document.querySelectorAll('.close-btn, .cancel-btn').forEach(btn => {
    btn.addEventListener('click', function() {
        const modal = this.closest('.modal');
        if (modal) {
            hideModal(modal.id);
        }
    });
});

