function isReportPresetCustomRange(preset) {
    return preset === 'custom' || preset === 'custom_range';
}

function isReportPresetCustomDate(preset) {
    return preset === 'custom_date';
}

function updateReportsPagePeriodInputs(preset) {
    const fromInp = document.querySelector('#reports #reportFromDate');
    const toInp = document.querySelector('#reports #reportToDate');
    if (!fromInp || !toInp) return;

    const showFrom = isReportPresetCustomDate(preset) || isReportPresetCustomRange(preset);
    const showTo = isReportPresetCustomRange(preset);

    fromInp.classList.toggle('is-visible', showFrom);
    toInp.classList.toggle('is-visible', showTo);
    fromInp.disabled = !showFrom;
    toInp.disabled = !showTo;
}

function applyReportsPagePeriodFilter() {
    const presetSelect = document.querySelector('#reports #reportPreset');
    const fromInp = document.querySelector('#reports #reportFromDate');
    const toInp = document.querySelector('#reports #reportToDate');
    if (!presetSelect) return;

    const preset = presetSelect.value;
    const isEn = (document.documentElement.lang || 'ar') === 'en';

    if (isReportPresetCustomRange(preset) && (!fromInp?.value || !toInp?.value)) {
        showMessage(isEn ? 'Please select From and To dates' : 'يرجى تحديد تاريخ البداية والنهاية', 'warning');
        return;
    }
    if (isReportPresetCustomDate(preset) && !fromInp?.value) {
        showMessage(isEn ? 'Please select a date' : 'يرجى تحديد التاريخ', 'warning');
        return;
    }

    const { from, to } = getRangeByPreset(
        preset,
        fromInp?.value,
        isReportPresetCustomDate(preset) ? fromInp?.value : toInp?.value
    );
    setReportsPageMetricsLoading(true);
    window.currentReportRange = { from, to };
    requestAnimationFrame(() => {
        try { updateReportsPageMetrics(); } catch (_) {}
    });
}

function setupReportsPagePeriodFilter() {
    const presetSelect = document.querySelector('#reports #reportPreset');
    if (!presetSelect || presetSelect.dataset.bound === '1') return;
    presetSelect.dataset.bound = '1';

    if (!window.currentReportRange) {
        window.currentReportRange = getRangeByPreset('today');
    }

    const initialPreset = presetSelect.value || 'today';
    updateReportsPagePeriodInputs(initialPreset);

    presetSelect.addEventListener('change', (e) => {
        const preset = e.target.value;
        updateReportsPagePeriodInputs(preset);

        if (!isReportPresetCustomDate(preset) && !isReportPresetCustomRange(preset)) {
            const { from, to } = getRangeByPreset(preset);
            window.currentReportRange = { from, to };
            setReportsPageMetricsLoading(true);
            requestAnimationFrame(() => {
                try { updateReportsPageMetrics(); } catch (_) {}
            });
        }
    });

    const fromInp = document.querySelector('#reports #reportFromDate');
    const toInp = document.querySelector('#reports #reportToDate');
    [fromInp, toInp].forEach((input) => {
        if (!input || input.dataset.bound === '1') return;
        input.dataset.bound = '1';
        input.addEventListener('change', () => {
            const preset = presetSelect.value;
            if (isReportPresetCustomDate(preset) && fromInp?.value) {
                applyReportsPagePeriodFilter();
            } else if (isReportPresetCustomRange(preset) && fromInp?.value && toInp?.value) {
                applyReportsPagePeriodFilter();
            }
        });
    });

    const applyBtn = document.querySelector('#reports #applyReportFilter');
    if (applyBtn && applyBtn.dataset.bound !== '1') {
        applyBtn.dataset.bound = '1';
        applyBtn.addEventListener('click', applyReportsPagePeriodFilter);
    }
}

// Setup report filter event listeners
function getReportFilterElement(id) {
    const reportModal = document.getElementById('reportModal');
    if (reportModal) {
        const modalElement = reportModal.querySelector(`#${id}`);
        if (modalElement) return modalElement;
    }
    return document.getElementById(id);
}

function setupReportEventListeners() {
    console.log('🔄 Setting up filter event listeners...');
    
    // Auto-apply on preset change
    const presetSelect = getReportFilterElement('reportPreset');
    if (presetSelect) {
        presetSelect.addEventListener('change', (e) => {
            const preset = e.target.value;
            console.log('🔄 Preset changed to:', preset);
            
            const fromInp = getReportFilterElement('reportFromDate');
            const toInp = getReportFilterElement('reportToDate');
            const isCustomRange = isReportPresetCustomRange(preset);
            const isCustomDate = isReportPresetCustomDate(preset);
            
            if (fromInp) {
                fromInp.classList.toggle('is-visible', isCustomRange || isCustomDate);
                fromInp.disabled = !(isCustomRange || isCustomDate);
            }
            if (toInp) {
                toInp.classList.toggle('is-visible', isCustomRange);
                toInp.disabled = !isCustomRange;
            }
            
            if (!isCustomRange && !isCustomDate) {
                const { from, to } = getRangeByPreset(preset);
                if (fromInp) fromInp.value = toDateInputValue(from);
                if (toInp) toInp.value = toDateInputValue(to);
                
                window.currentReportRange = { from, to };
                console.log('🎯 Updated time range:', { from: from.toISOString(), to: to.toISOString() });
                
                // Apply filter immediately
                setTimeout(() => {
                    applyFilterDirectly();
                }, 100);
            }
        });
    }
    
    // Automatically applied when two dates are entered in Custom mode
    const fromDateInput = getReportFilterElement('reportFromDate');
    const toDateInput = getReportFilterElement('reportToDate');
    
    if (fromDateInput) {
        fromDateInput.addEventListener('change', () => {
            const presetSel = getReportFilterElement('reportPreset');
            if (!presetSel) return;
            const preset = presetSel.value;
            const fromVal = fromDateInput.value;
            const toVal = toDateInput ? toDateInput.value : '';

            if (isReportPresetCustomDate(preset) && fromVal) {
                const { from, to } = getRangeByPreset('custom_date', fromVal);
                window.currentReportRange = { from, to };
                setTimeout(() => applyFilterDirectly(), 100);
            } else if (isReportPresetCustomRange(preset) && fromVal && toVal) {
                const { from, to } = getRangeByPreset('custom_range', fromVal, toVal);
                window.currentReportRange = { from, to };
                setTimeout(() => applyFilterDirectly(), 100);
            }
        });
    }
    
    if (toDateInput) {
        toDateInput.addEventListener('change', () => {
            const presetSel = getReportFilterElement('reportPreset');
            if (!presetSel || !isReportPresetCustomRange(presetSel.value)) return;

            const fromVal = fromDateInput ? fromDateInput.value : '';
            const toVal = toDateInput.value;
            
            if (fromVal && toVal) {
                const { from, to } = getRangeByPreset('custom_range', fromVal, toVal);
                window.currentReportRange = { from, to };
                setTimeout(() => applyFilterDirectly(), 100);
            }
        });
    }
    
    // Application button
    const applyBtn = getReportFilterElement('applyReportFilter');
    if (applyBtn) {
        applyBtn.addEventListener('click', () => {
            const preset = getReportFilterElement('reportPreset')?.value || 'today';
            const fromInp = getReportFilterElement('reportFromDate');
            const toInp = getReportFilterElement('reportToDate');
            const isEn = (document.documentElement.lang || 'ar') === 'en';

            if (isReportPresetCustomRange(preset) && (!fromInp?.value || !toInp?.value)) {
                showMessage(isEn ? 'Please select From and To dates' : 'يرجى تحديد تاريخ البداية والنهاية', 'warning');
                return;
            }
            if (isReportPresetCustomDate(preset) && !fromInp?.value) {
                showMessage(isEn ? 'Please select a date' : 'يرجى تحديد التاريخ', 'warning');
                return;
            }

            applyFilterDirectly();
        });
    }
}

// Apply filtering immediately
function applySalesFilter() {
    console.log('🔄 Applying filter...');
    
    if (!window.currentReportRange) {
        console.warn('❌ No time range selected');
        return;
    }
    
    const range = window.currentReportRange;
    console.log('🎯 Time range:', { from: range.from.toISOString(), to: range.to.toISOString() });

    sales = getCurrentSales();
    const summary = calculateCompletedSalesSummaryForRange(range, sales);
    const filtered = summary.filteredSales;
    const totalSales = summary.totalSales;
    const totalProfit = summary.totalProfit;
    const totalTransactions = summary.totalTransactions;

    console.log(totalSales, totalProfit);
    console.log(`📊 Results: ${filtered.length} out of ${(Array.isArray(sales) ? sales.length : 0)} completed sale(s)`);

    // Update stats
    const averageTransaction = totalTransactions > 0 ? totalSales / totalTransactions : 0;
    
    // Update UI
    updateSalesReportStats(filtered, totalSales, totalTransactions, averageTransaction, 0);
    
    // Update table
    updateSalesReportTable(filtered);
    
    // User feedback
    showMessage(getText('filter-applied', { count: totalTransactions }), 'success');
}

// Simple helper: apply filter immediately
function applyFilterDirectly() {
    console.log('🔄 Applying filter directly...');
    
    const presetSelect = getReportFilterElement('reportPreset');
    if (!presetSelect) {
        console.warn('❌ Filter preset selector not found');
        return;
    }
    
    const preset = presetSelect.value;
    const fromInput = getReportFilterElement('reportFromDate');
    const toInput = getReportFilterElement('reportToDate');
    if (isReportPresetCustomRange(preset) && (!fromInput?.value || !toInput?.value)) {
        console.warn('❌ Custom range preset requires from/to dates');
        return;
    }
    if (isReportPresetCustomDate(preset) && !fromInput?.value) {
        console.warn('❌ Custom date preset requires a date');
        return;
    }

    const { from, to } = getRangeByPreset(
        preset,
        fromInput?.value,
        isReportPresetCustomDate(preset) ? fromInput?.value : toInput?.value
    );
    window.currentReportRange = { from, to };
    try { updateReportsPageMetrics(); } catch (_) {}
    rerenderCurrentReport();
}

// Update Sales Report table
function updateSalesReportTable(filtered) {
    console.log('🔄 Updating Sales Report table...');
    
    const tbody = document.getElementById('salesReportTableBody');
    if (!tbody) {
        console.warn('❌ Sales Report table body not found');
        return;
    }
    
    const defCust = typeof getText === 'function' ? getText('regular-customer') : 'Regular Customer';
    const defPay = typeof getText === 'function' ? getText('cash') : 'Cash';
    tbody.innerHTML = filtered.map(sale => {
        const cust = (sale.customer || sale.customerName || '').trim();
        const custDisp = (!cust || cust === 'عميل عادي' || cust === 'Regular Customer') ? defCust : cust;
        const pm = String(sale.paymentMethod || '').trim();
        const pmDisp = (!pm || pm === 'نقدي' || pm.toLowerCase() === 'cash') ? defPay : pm;
        return `<tr>
            <td class="report-col-invoice"><span class="report-invoice-no">${escapeHtml(sale.invoiceNumber || sale.id || 'N/A')}</span></td>
            <td class="report-col-date">${formatReportDateCell(sale.timestamp || sale.date)}</td>
            <td class="report-col-name">${escapeHtml(custDisp)}</td>
            <td class="report-col-amount">${formatCurrency(sale.amount || 0)}</td>
            <td class="report-col-method">${escapeHtml(pmDisp)}</td>
        </tr>`;
    }).join('');
    
    console.log(`✅ Sales Report table updated with ${filtered.length} row(s)`);
}
