function getNextThemeForHeaderToggle(currentTheme) {
    return currentTheme === 'professional-dark' ? 'clean-light' : 'professional-dark';
}

function syncHeaderThemeToggle(theme) {
    const btn = document.getElementById('headerThemeToggle');
    if (!btn) return;
    const isDark = theme === 'professional-dark';
    btn.setAttribute('data-mode', isDark ? 'dark' : 'light');
    const lang = document.documentElement.lang || 'ar';
    const title = isDark
        ? (lang === 'en' ? 'Switch to Light Mode' : 'التبديل إلى الوضع الفاتح')
        : (lang === 'en' ? 'Switch to Dark Mode' : 'التبديل إلى الوضع الداكن');
    btn.setAttribute('title', title);
    btn.setAttribute('aria-label', title);
}

function applyTheme(themeId) {
    const valid = ['default', 'professional-dark', 'clean-light'];
    const theme = valid.indexOf(themeId) >= 0 ? themeId : 'default';
    document.documentElement.setAttribute('data-theme', theme);
    try { localStorage.setItem('appTheme', theme); } catch (_) {}
    const meta = document.querySelector('meta[name="theme-color"]');
    if (meta) {
        if (theme === 'professional-dark') meta.content = '#0f172a';
        else if (theme === 'clean-light') meta.content = '#f8fafc';
        else meta.content = '#0f172a';
    }
    document.querySelectorAll('.theme-btn').forEach(btn => {
        btn.classList.toggle('active', btn.dataset.theme === theme);
    });
    syncHeaderThemeToggle(theme);
}

document.addEventListener('DOMContentLoaded', function() {
    const savedTheme = localStorage.getItem('appTheme') || 'default';
    applyTheme(savedTheme);
    document.querySelectorAll('.theme-btn').forEach(btn => {
        btn.addEventListener('click', function() { applyTheme(this.dataset.theme); });
    });
    const headerThemeToggle = document.getElementById('headerThemeToggle');
    if (headerThemeToggle) {
        headerThemeToggle.addEventListener('click', function () {
            const currentTheme = document.documentElement.getAttribute('data-theme') || 'default';
            const nextTheme = getNextThemeForHeaderToggle(currentTheme);
            applyTheme(nextTheme);
        });
    }
    const selectAll = document.getElementById('clearDataSelectAll');
    const selectNone = document.getElementById('clearDataSelectNone');
    const proceedBtn = document.getElementById('clearDataProceedBtn');
    const confirmBtn = document.getElementById('clearDataConfirmBtn');
    const confirmSection = document.getElementById('clearDataConfirmSection');
    const selectedList = document.getElementById('clearDataSelectedList');
    const typeInput = document.getElementById('clearDataTypeConfirmInput');
    const allCb = document.querySelectorAll('#clearDataModal .clear-data-cb');
    const syncClearConfirmBtn = () => {
        if (!confirmBtn || !typeInput) return;
        confirmBtn.disabled = String(typeInput.value || '').trim().toUpperCase() !== 'CLEAR ALL DATA';
    };
    if (typeInput && typeInput.dataset.bound !== '1') {
        typeInput.dataset.bound = '1';
        typeInput.addEventListener('input', syncClearConfirmBtn);
    }
    if (selectAll) selectAll.onclick = () => allCb.forEach(cb => { if (cb.value !== 'all') cb.checked = true; });
    if (selectNone) selectNone.onclick = () => allCb.forEach(cb => cb.checked = false);
    if (proceedBtn) proceedBtn.onclick = function() {
        const selected = Array.from(allCb).filter(cb => cb.checked).map(cb => cb.value);
        if (selected.length === 0) {
            const isEn = (document.documentElement.lang || 'ar') === 'en';
            showMessage(isEn ? 'Please select at least one option.' : 'يرجى اختيار خيار واحد على الأقل.', 'error');
            return;
        }
        const labels = { invoices: 'Invoices', customers: 'Customers', suppliers: 'Suppliers', salesHistory: 'Sales History', cashbox: 'Cashbox Records', items: 'Items', purchases: 'Purchases & Supplier Data', stockMovements: 'Stock Movements', reports: 'Reports', settings: 'Settings', all: 'All Data' };
        const labelsAr = { invoices: 'الفواتير', customers: 'العملاء', suppliers: 'الموردين', salesHistory: 'سجل المبيعات', cashbox: 'سجلات الصندوق', items: 'المنتجات', purchases: 'المشتريات وبيانات الموردين', stockMovements: 'حركات المخزون', reports: 'التقارير', settings: 'الإعدادات', all: 'جميع البيانات' };
        const isEn = (document.documentElement.lang || 'ar') === 'en';
        const list = selected.map(s => isEn ? (labels[s] || s) : (labelsAr[s] || s)).join(', ');
        if (selectedList) selectedList.textContent = list;
        if (confirmSection) confirmSection.style.display = 'block';
        if (typeInput) typeInput.value = '';
        syncClearConfirmBtn();
        if (confirmBtn) {
            confirmBtn.onclick = async function() {
                if (String(typeInput?.value || '').trim().toUpperCase() !== 'CLEAR ALL DATA') return;
                confirmBtn.disabled = true;
                await executeClearData(selected);
                confirmBtn.disabled = false;
            };
        }
    };
});

