// تحديث العربة الأفقية
function updateHorizontalCart(cartItems, currency) {
    const horizontalContainer = document.getElementById('cartItemsHorizontalPos');
    if (!horizontalContainer) return;
    
    horizontalContainer.innerHTML = '';
    
    cartItems.forEach((item, index) => {
        if (!item) return;
        let price;
        if (item.type === 'previous_account') {
            const pUSD = Number(item.customPriceUSD ?? item.priceUSD ?? item.price ?? 0) || 0;
            price = currency === 'USD' ? pUSD : Math.round(pUSD * (settings.exchangeRate || 1));
        } else {
            price = getCartLineUnitPriceInCurrency(item, currency);
        }
        const lineQty = posCartLineQuantity(item);
        const itemImgSrc = getCartItemImageUrl(item);
        const removeLabel = escapeAttr(getText('remove-previous-account') || ((document.documentElement.lang || 'en') === 'en' ? 'Remove previous account' : 'إزالة الحساب السابق'));

        if (item.type === 'previous_account') {
            const cartItemHorizontal = document.createElement('div');
            cartItemHorizontal.className = 'cart-item-horizontal-pos previous-account-item-horizontal';
            cartItemHorizontal.innerHTML = `
                <button type="button" class="previous-account-remove-btn" onclick="removePreviousAccountFromCart(${Number(item.customerId) || 0})" title="${removeLabel}" aria-label="${removeLabel}">×</button>
                <div class="cart-item-info-pos">
                    <div class="cart-item-name-pos">${escapeHtml(getText('previous-account') || 'Previous Balance')}</div>
                    <div class="cart-item-price-pos">${escapeHtml(getText('previous-debt') || 'Outstanding Debt')}: ${escapeHtml(item.customerName || '')} • ${escapeHtml(formatCurrency(price, currency))}</div>
                </div>
            `;
            horizontalContainer.appendChild(cartItemHorizontal);
            return;
        }

        const priceLineHtml = `${formatCurrency(price, currency)} × ${lineQty > 0 ? lineQty : 1}`;
        const qtySpan = String(lineQty > 0 ? lineQty : 1);
        
        const cartItemHorizontal = document.createElement('div');
        cartItemHorizontal.className = 'cart-item-horizontal-pos';
        cartItemHorizontal.innerHTML = `
            <div class="cart-item-thumb-pos">
                <img src="${itemImgSrc}" alt="${escapeAttr(item.name)}" class="cart-item-img-pos" onerror="this.src=typeof getDefaultProductImage==='function'?getDefaultProductImage():''">
            </div>
            <div class="cart-item-info-pos">
                <div class="cart-item-name-pos">${escapeHtml(item.name)}</div>
                <div class="cart-item-price-pos">${priceLineHtml}</div>
            </div>
            <div class="cart-item-controls-pos">
                <div class="quantity-controls-horizontal-pos">
                    <button class="quantity-btn-horizontal-pos" onclick="changeQuantity(${index}, -1)">-</button>
                    <span class="quantity-horizontal-pos">${qtySpan}</span>
                    <button class="quantity-btn-horizontal-pos" onclick="changeQuantity(${index}, 1)">+</button>
                </div>
                <button class="remove-btn-horizontal-pos" onclick="removeFromCart(${index})" title="${escapeAttr(getText('delete') || ((document.documentElement.lang || 'ar') === 'en' ? 'Delete' : 'حذف'))}" aria-label="${escapeAttr(getText('delete') || ((document.documentElement.lang || 'ar') === 'en' ? 'Delete' : 'حذف'))}">×</button>
            </div>
        `;
        
        horizontalContainer.appendChild(cartItemHorizontal);
    });
}

// تحديث ملخص العربة الأفقية
function updateHorizontalCartSummary(totalItems, totalAmount) {
    const totalItemsElement = document.getElementById('totalItemsPos');
    const totalAmountElement = document.getElementById('totalAmountPos');
    
    if (totalItemsElement) {
        totalItemsElement.textContent = totalItems;
    }
    
    if (totalAmountElement) {
        const currency = document.getElementById('currency').value;
        totalAmountElement.textContent = formatCurrency(totalAmount, currency);
    }
}

// Backward-compatible alias for legacy POS refresh calls.
function updateCartHorizontalDisplay() {
    const currencySelect = document.getElementById('currency');
    const currency = currencySelect ? currencySelect.value : 'USD';
    const cartItems = Array.isArray(cart) ? cart : [];
    updateHorizontalCart(cartItems, currency);
    const totals = sumPosCartTotalsFromScratch(currency);
    updateHorizontalCartSummary(totals.totalItems, totals.subtotal);
}


// عرض المنتجات في التصميم الجديد
function displayProductsNew() {
    const container = document.getElementById('productsArea');
    if (!container) return;
    
    container.innerHTML = '';
    
    const filteredProducts = products.filter(product => 
        product.name.toLowerCase().includes('') ||
        product.category.toLowerCase().includes('')
    );
    
    filteredProducts.forEach(product => {
        const price = getProductPrice(product, currentPriceType, 'USD');
        const priceFormatted = formatCurrency(price, 'USD');
        
        const productImgSrcNew = (product.imageUrl && (product.imageUrl.startsWith('data:image') || product.imageUrl.startsWith('http'))) ? product.imageUrl : getDefaultProductImage();
        const sellableStock = getProductSellableStock(product);
        const productCard = document.createElement('div');
        productCard.className = sellableStock <= 0 ? 'product-card-new out-of-stock' : 'product-card-new';
        productCard.innerHTML = `
            <div class="product-card-image-wrap">
                <img src="${productImgSrcNew}" alt="${escapeAttr(product.name)}" class="product-card-img" onerror="this.src=typeof getDefaultProductImage==='function'?getDefaultProductImage():''">
            </div>
            <div class="product-info">
                <h4>${escapeHtml(product.name)}</h4>
                <div class="product-price">${priceFormatted}</div>
                <div class="product-stock">متوفر: ${escapeHtml(getProductStockDisplay(product))}</div>
            </div>
        `;
        
        productCard.addEventListener('click', function() {
            addToCart(product);
            showMessage(getText('added-to-cart', { product: product.name }), 'success');
        });
        
        container.appendChild(productCard);
    });
}

// تحديث العربة في التصميم الجديد
function updateCartNew() {
    const totalDisplay = document.getElementById('totalDisplay');
    if (!totalDisplay) return;
    
    let total = 0;
    let totalItems = 0;
    
    cart.forEach(item => {
        if (!item || item.type === 'previous_account') {
            if (item && item.type === 'previous_account') {
                total += Number(item.customPriceUSD ?? item.priceUSD ?? 0) || 0;
                totalItems += 1;
            }
            return;
        }
        total += getCartLineEffectivePriceUSD(item) * posCartLineQuantity(item);
        totalItems += posCartLineQuantity(item);
    });
    
    totalDisplay.textContent = formatCurrency(total, 'USD');
}

