/** Bind USD/LBP pair: auto-calc on USD change, preserve manual LBP until USD changes again */
function bindLbpPricePair(usdId, lbpId) {
    const usdInput = document.getElementById(usdId);
    const lbpInput = document.getElementById(lbpId);
    if (!usdInput || !lbpInput) return;

    lbpInput._manual = false;
    if (!lbpInput._manualBound) {
        lbpInput._manualBound = true;
        lbpInput.addEventListener('input', () => { lbpInput._manual = true; });
    }
    if (!usdInput._lbpBound) {
        usdInput._lbpBound = true;
        usdInput.addEventListener('input', () => {
            lbpInput._manual = false;
            calculateAndDisplayLBP(usdInput, lbpInput);
        });
    }
    calculateAndDisplayLBP(usdInput, lbpInput);
}

function shouldPreserveManualLbp(usdEl, lbpEl, currentRate) {
    const rate = currentRate || ((typeof settings !== 'undefined' && settings.exchangeRate) ? Number(settings.exchangeRate) : 1);
    if (!usdEl || !lbpEl || !rate) return false;
    const usd = parseFloat(String(usdEl.value || '').replace(/,/g, '')) || 0;
    const lbpRaw = String(lbpEl.value || '').trim();
    if (!lbpRaw) return false;
    const lbp = parseInt(lbpRaw.replace(/[^\d\-]/g, ''), 10);
    if (!Number.isFinite(lbp) || lbp <= 0) return false;
    return lbp !== Math.round(usd * rate);
}

function markManualLbpFlagsForEditProduct() {
    const currentRate = (typeof settings !== 'undefined' && settings.exchangeRate) ? Number(settings.exchangeRate) : 1;
    const pairs = [
        ['editProductRetailUSD', 'editRetailLBPDisplay'],
        ['editProductVipUSD', 'editVipLBPDisplay'],
        ['editProductWholesaleUSD', 'editWholesaleLBPDisplay']
    ];
    pairs.forEach(([usdId, lbpId]) => {
        const usdEl = document.getElementById(usdId);
        const lbpEl = document.getElementById(lbpId);
        if (lbpEl) lbpEl._manual = shouldPreserveManualLbp(usdEl, lbpEl, currentRate);
    });
}

/** حساب وعرض السعر بالليرة من حقل USD (مشترك بين نموذج الإضافة والتعديل) */
function calculateAndDisplayLBP(usdInput, lbpInput) {
    if (!usdInput || !lbpInput) return;
    if (lbpInput._manual) return;
    const exchangeRate = (typeof settings !== 'undefined' && settings.exchangeRate) ? settings.exchangeRate : 1;
    const usdPrice = parseFloat(usdInput.value) || 0;
    const lbpPrice = Math.round(usdPrice * exchangeRate);
    lbpInput.value = lbpPrice > 0 ? lbpPrice : '';
}

// إضافة معالج للحساب التلقائي للأسعار
function setupPriceCalculations() {
    const exchangeRate = settings.exchangeRate;

    const exchangeRateDisplay = document.getElementById('currentExchangeRate');
    if (exchangeRateDisplay) {
        exchangeRateDisplay.textContent = exchangeRate.toLocaleString();
    }
    const editExchangeRateDisplay = document.getElementById('editCurrentExchangeRate');
    if (editExchangeRateDisplay) {
        editExchangeRateDisplay.textContent = exchangeRate.toLocaleString();
    }

    setTimeout(() => {
        bindLbpPricePair('productRetailUSD', 'retailLBPDisplay');
        bindLbpPricePair('productWholesaleUSD', 'wholesaleLBPDisplay');
        bindLbpPricePair('productVipUSD', 'vipLBPDisplay');
        bindLbpPricePair('editProductRetailUSD', 'editRetailLBPDisplay');
        bindLbpPricePair('editProductWholesaleUSD', 'editWholesaleLBPDisplay');
        bindLbpPricePair('editProductVipUSD', 'editVipLBPDisplay');
    }, 200);
}

