// Get cart item image URL: item.imageUrl, or product by id from catalog, or placeholder (ensures cart always shows image)
function getCartItemImageUrl(item) {
    if (item.imageUrl && (item.imageUrl.startsWith('data:image') || item.imageUrl.startsWith('http')))
        return item.imageUrl;
    const product = typeof getCurrentProducts === 'function' ? getCurrentProducts().find(p => p.id === item.id) : null;
    if (product && product.imageUrl && (product.imageUrl.startsWith('data:image') || product.imageUrl.startsWith('http')))
        return product.imageUrl;
    return getDefaultProductImage();
}

