/** إعادة حساب مخزون منتج يتتبع IMEI */
function recalcImeiProductStock(product) {
    if (!product || !product.imeiTracking || !Array.isArray(product.imeiList)) return;
    product.stock = product.imeiList.filter(e => (e.status || 'available') === 'available' || e.status === 'returned').length;
}

/**
 * بعد الاسترجاع: إن لم يكن IMEI محفوظاً على سطر البيع (قديم)، نعيد حتى N أجهزة من حالة sold → available
 * حتى يمكن البحث بالـ IMEI وإعادة البيع.
 */
function restoreImeisAfterReturnByQuantity(product, unitsToRestore) {
    if (!product || !product.imeiTracking || !Array.isArray(product.imeiList)) return;
    let n = Math.max(0, Math.floor(Number(unitsToRestore) || 0));
    if (n < 1) return;
    for (let i = 0; i < product.imeiList.length && n > 0; i++) {
        const e = product.imeiList[i];
        if ((e.status || 'available') === 'sold') {
            e.status = 'available';
            n--;
        }
    }
    recalcImeiProductStock(product);
}

// IMEI: البحث عن منتج بواسطة رقم IMEI (متوفر أو مرتجع). يرجع { product, imei } أو null
function findProductByImei(imeiStr) {
    if (!imeiStr || typeof imeiStr !== 'string') return null;
    const digits = imeiStr.replace(/\s/g, '');
    if (digits.length < 14 || !/^\d+$/.test(digits)) return null;
    products = getCurrentProducts();
    for (const p of products) {
        if (!p.imeiTracking || !Array.isArray(p.imeiList)) continue;
        for (const entry of p.imeiList) {
            const eImei = String(entry.imei || '').replace(/\s/g, '');
            if (eImei === digits || eImei.endsWith(digits) || digits.endsWith(eImei)) {
                const status = entry.status || 'available';
                if (status === 'sold') {
                    if (typeof showMessage === 'function') showMessage(getText('msg-imei-already-sold') || 'This device with this IMEI has already been sold.', 'error');
                    return null;
                }
                return { product: p, imei: entry.imei || eImei };
            }
        }
    }
    return null;
}

// IMEI: تحليل قائمة IMEI من النص (سطر واحد لكل IMEI)، إرجاع مصفوفة أرقام صالحة (15 رقم)
function parseImeiListFromText(text) {
    if (!text || typeof text !== 'string') return [];
    const lines = text.trim().split(/\r?\n/).map(s => s.trim()).filter(Boolean);
    const seen = new Set();
    const list = [];
    for (const line of lines) {
        const digits = line.replace(/\s/g, '');
        if (digits.length >= 14 && digits.length <= 18 && /^\d+$/.test(digits)) {
            const imei = digits.length === 15 ? digits : digits.slice(0, 15);
            if (!seen.has(imei)) {
                seen.add(imei);
                list.push(imei);
            }
        }
    }
    return list;
}

// IMEI: إظهار/إخفاء مجموعة قائمة IMEI وتحديث الكمية التلقائية
function setupImeiTrackingToggle() {
    const cb = document.getElementById('productImeiTracking');
    const panel = document.getElementById('productImeiExpandPanel');
    const textarea = document.getElementById('productImeiList');
    const qtyInp = document.getElementById('productQuantity');
    const countDisplay = document.getElementById('productImeiCountDisplay');
    if (!cb) return;
    const isEn = () => (document.documentElement.lang || 'ar') === 'en';
    function update() {
        const enabled = cb.checked;
        if (panel) panel.style.display = enabled ? 'block' : 'none';
        if (!enabled && textarea) textarea.value = '';
        if (enabled && textarea) {
            const list = parseImeiListFromText(textarea.value);
            if (countDisplay) {
                countDisplay.textContent = list.length
                    ? ('✓ ' + list.length + ' ' + (isEn() ? 'device(s)' : 'جهاز'))
                    : (isEn() ? 'Type or paste IMEI numbers (one per line).' : 'أدخل أرقام IMEI (سطر لكل رقم).');
            }
            if (qtyInp) {
                qtyInp.value = list.length || '';
                qtyInp.readOnly = true;
            }
        } else {
            if (countDisplay) countDisplay.textContent = '';
            if (qtyInp) qtyInp.readOnly = false;
        }
        try { updateAddProductSaveButtonState(); } catch (_) {}
    }
    cb.addEventListener('change', update);
    if (textarea) textarea.addEventListener('input', update);
    update();
}

// استدعاء الدالة عند تحميل الصفحة وإعداد معالج النموذج
document.addEventListener('DOMContentLoaded', function() {
    setupPriceCalculations();
    setupProductImagePreview();
    setupEditProductImagePreview();
    setupImeiTrackingToggle();
    try { setupAddProductFormValidation(); } catch (_) {}
    try { setupAddProductEnterNavigation(); } catch (_) {}
    // إعداد حقلَي إجمالي الكلفة و Pay Now عند اختيار مورّد
    try {
        const supplierSel = document.getElementById('productSupplier');
        const costInp = document.getElementById('productCostUSD');
        const qtyInp = document.getElementById('productQuantity');
        const group = document.getElementById('supplierCostGroup');
        const totalDisp = document.getElementById('productTotalCostDisplay');
        const payNowInp = document.getElementById('productPayNow');
        function recalcTotalCost() {
            const hasSupplier = (supplierSel && supplierSel.value && supplierSel.value.trim() !== '');
            if (group) group.style.display = hasSupplier ? 'flex' : 'none';
            const cost = Number(costInp?.value) || 0;
            const qty = Math.max(0, parseInt(qtyInp?.value) || 0);
            const total = cost * qty;
            if (totalDisp) totalDisp.value = `$${total.toFixed(2)}`;
            if (payNowInp) {
                // لا تتجاوز الإجمالي
                let val = Number(payNowInp.value) || 0;
                if (val > total) val = total;
                if (val < 0) val = 0;
                payNowInp.value = val ? String(val) : '';
                payNowInp.max = String(total);
                payNowInp.min = '0';
            }
            var hint = document.getElementById('supplierRemainingHint');
            if (hint && hasSupplier && total > 0) {
                var paid = Number(payNowInp && payNowInp.value) || 0;
                var rem = Math.max(0, total - paid);
                var en = (document.documentElement.lang || 'ar') === 'en';
                if (rem > 0.001) {
                    hint.style.display = 'block';
                    hint.textContent = en
                        ? ('Still to pay: ' + formatCurrency(rem, 'USD') + ' (recorded on supplier account)')
                        : ('المتبقي للمورد: ' + formatCurrency(rem, 'USD') + ' (مسجّل على حساب المورد)');
                } else {
                    hint.style.display = paid > 0 ? 'block' : 'none';
                    if (paid > 0) hint.textContent = en ? 'Fully paid for this purchase.' : 'تم سداد كامل المبلغ لهذه التوريدة.';
                    else hint.textContent = '';
                }
            } else if (hint) { hint.style.display = 'none'; }
        }
        supplierSel && (supplierSel.onchange = recalcTotalCost);
        costInp && (costInp.oninput = recalcTotalCost);
        qtyInp && (qtyInp.oninput = recalcTotalCost);
        payNowInp && (payNowInp.oninput = recalcTotalCost);
        recalcTotalCost();
    } catch(_) {}
    
    // إعداد حقل التصنيف القابل للبحث/الإنشاء
    try { setupProductCategorySearchableSelect(); } catch (_) {}
    try { setupEditProductCategorySearchableSelect(); } catch (_) {}

    // إعداد معالج حفظ المنتج
    const addProductForm = document.getElementById('addProductForm');
    if (addProductForm) {
        addProductForm.addEventListener('submit', async function(e) {
    e.preventDefault();
        const saveBtn = document.getElementById('addProductSaveBtn');
        const isEnSubmit = (document.documentElement.lang || 'ar') === 'en';
        if (saveBtn) {
            saveBtn.dataset.loading = '1';
            saveBtn.disabled = true;
            saveBtn.textContent = isEnSubmit ? 'Saving...' : 'جاري الحفظ...';
        }
        if (!hasProductPermission('canAddProducts')) {
            resetAddProductSaveButtonState();
            showPermissionDeniedMessage('إضافة المنتجات', 'add products');
            return;
        }
        if (!isAddProductFormValid()) {
            resetAddProductSaveButtonState();
            showAddProductValidationErrors();
            return;
        }
        console.log('Save button clicked');
            const pname = (document.getElementById('productName') && document.getElementById('productName').value || '').trim();
            if (pname.length < 2) {
                resetAddProductSaveButtonState();
                showMessage((document.documentElement.lang === 'en' ? 'Product name is required (min 2 characters).' : 'اسم المنتج إلزامي (حرفين على الأقل).'), 'error');
                return;
            }
            let selectedCategory = normalizeCategoryName(
                (document.getElementById('productCategory') && document.getElementById('productCategory').value) ||
                (document.getElementById('productCategorySearch') && document.getElementById('productCategorySearch').value)
            );
            if (!selectedCategory) {
                resetAddProductSaveButtonState();
                showMessage((document.documentElement.lang === 'en' ? 'Please select or create a category.' : 'يرجى اختيار أو إنشاء تصنيف.'), 'error');
                return;
            }
            selectedCategory = upsertProductCategory(selectedCategory);
            selectProductCategory(selectedCategory);
            const productExpiryDate = normalizeExpiryDate(document.getElementById('productExpiryDate')?.value);
            const barcodeNormAdd = normalizeProductBarcode(document.getElementById('productBarcode') && document.getElementById('productBarcode').value);
            if (barcodeNormAdd) {
                if (findProductWithBarcode(barcodeNormAdd, null)) {
                    resetAddProductSaveButtonState();
                    showMessage(getText('msg-barcode-exists'), 'error');
                    return;
                }
            }
            if (findProductWithNameSame(pname, null)) {
                const okDupName = await uiConfirm(getText('msg-duplicate-product-name-confirm'), {
                    title: getText('duplicate-name-title') || 'Duplicate name',
                    confirmText: getText('continue-anyway') || 'Continue',
                    cancelText: getText('cancel') || 'Cancel'
                });
                if (!okDupName) { resetAddProductSaveButtonState(); return; }
            }
            // التحقق من وجود الحقول
            const retailUSDInput = document.getElementById('productRetailUSD');
            const wholesaleUSDInput = document.getElementById('productWholesaleUSD');
            const vipUSDInput = document.getElementById('productVipUSD');
            
            if (!retailUSDInput || !wholesaleUSDInput || !vipUSDInput) {
                resetAddProductSaveButtonState();
                showMessage(getText('msg-price-fields-not-found'), 'error');
                return;
            }
            
            const retailUSD = parseFloat(retailUSDInput.value);
            const vipUSDRaw = parseFloat(vipUSDInput.value);
            const wholesaleUSDRaw = parseFloat(wholesaleUSDInput.value);
            const vipUSD = (!isNaN(vipUSDRaw) && vipUSDRaw > 0) ? vipUSDRaw : retailUSD;
            const wholesaleUSD = (!isNaN(wholesaleUSDRaw) && wholesaleUSDRaw > 0) ? wholesaleUSDRaw : retailUSD;
            const costUSD = parseFloat(document.getElementById('productCostUSD')?.value) || 0;
            
            console.log('Entered prices:', { retailUSD, wholesaleUSD, vipUSD, costUSD });
            
            if (!isValidProductDecimalValue(retailUSDInput.value) || !(retailUSD > 0)) {
                resetAddProductSaveButtonState();
                showMessage(getText('msg-enter-valid-prices'), 'error');
                return;
            }
            
            if (retailUSD < costUSD || wholesaleUSD < costUSD || vipUSD < costUSD) {
                resetAddProductSaveButtonState();
                showMessage(getText('msg-no-price-below-cost'), 'error');
                return;
            }
            
            const exchangeRate = settings.exchangeRate;
            console.log('Exchange rate:', exchangeRate);

            // قراءة الأسعار بالليرة (في حال قام المستخدم بتعديلها يدوياً)
            const retailLBPInput = document.getElementById('retailLBPDisplay');
            const wholesaleLBPInput = document.getElementById('wholesaleLBPDisplay');
            const vipLBPInput = document.getElementById('vipLBPDisplay');

            const autoRetailLBP = Math.round(retailUSD * exchangeRate);
            const autoWholesaleLBP = Math.round(wholesaleUSD * exchangeRate);
            const autoVipLBP = Math.round(vipUSD * exchangeRate);

            const parseManualLBP = (inputEl, autoVal) => {
                if (!inputEl) return autoVal;
                const raw = String(inputEl.value || '').replace(/[^\d\-]/g, '');
                const num = parseInt(raw, 10);
                if (!isNaN(num) && num > 0) return num;
                return autoVal;
            };

            const retailLBP = parseManualLBP(retailLBPInput, autoRetailLBP);
            const wholesaleLBP = parseManualLBP(wholesaleLBPInput, autoWholesaleLBP);
            const vipLBP = parseManualLBP(vipLBPInput, autoVipLBP);
    
    // Generate a fresh numeric id that does not collide with active products
    // and does not reuse tombstoned (deleted) ids.
    let deletedSetForId = (window.__deletedProductIds instanceof Set) ? window.__deletedProductIds : new Set();
    try {
        const persistedDeleted = await getDeletedProductIdSet();
        if (persistedDeleted && persistedDeleted.size) {
            deletedSetForId = new Set([...deletedSetForId, ...persistedDeleted]);
            window.__deletedProductIds = deletedSetForId;
        }
    } catch (_) {}
    const usedNumericIds = new Set();
    (Array.isArray(products) ? products : []).forEach((p) => {
        const n = Number(p && p.id);
        if (Number.isFinite(n) && n > 0) usedNumericIds.add(Math.floor(n));
    });
    deletedSetForId.forEach((id) => {
        const n = Number(id);
        if (Number.isFinite(n) && n > 0) usedNumericIds.add(Math.floor(n));
    });
    let nextProductId = usedNumericIds.size ? (Math.max(...Array.from(usedNumericIds)) + 1) : 1;
    while (
        (window.__deletedProductIds instanceof Set && window.__deletedProductIds.has(String(nextProductId))) ||
        (Array.isArray(products) && products.some((p) => String(p && p.id) === String(nextProductId)))
    ) {
        nextProductId += 1;
    }

    const imeiTrackingChecked = document.getElementById('productImeiTracking') && document.getElementById('productImeiTracking').checked;
    let stockQty = parseInt(document.getElementById('productQuantity').value, 10) || 0;
    let imeiTracking = false;
    let imeiList = [];
    let linkedUnitType = 'standard';
    let linkedPackProductId = null;
    let linkedUnitsPerCarton = null;
    if (imeiTrackingChecked) {
        const imeiText = (document.getElementById('productImeiList') && document.getElementById('productImeiList').value) || '';
        imeiList = parseImeiListFromText(imeiText);
        if (imeiList.length === 0) {
            resetAddProductSaveButtonState();
            showMessage(getText('msg-imei-list-required') || 'أدخل قائمة IMEI (سطر واحد لكل جهاز)', 'error');
            return;
        }
        imeiTracking = true;
        stockQty = imeiList.length;
    } else if (isCartonConversionEnabled()) {
        const conversionInput = readCartonConversionInputs('');
        if (!conversionInput.ok) {
            resetAddProductSaveButtonState();
            showMessage(conversionInput.message, 'error');
            return;
        }
        linkedUnitType = conversionInput.unitType;
        linkedPackProductId = conversionInput.linkedPackProductId || null;
        linkedUnitsPerCarton = conversionInput.unitsPerCarton || null;
    }

    // Handle image upload
    let imageUrl = null;
    let imagePath = null;
    const imageInput = document.getElementById('productImage');
    if (imageInput && imageInput.files && imageInput.files[0]) {
        try {
            const uploaded = await uploadProductImage(imageInput.files[0], nextProductId);
            imageUrl = uploaded.imageUrl;
            imagePath = uploaded.imagePath;
        } catch (error) {
            console.error('Error uploading image:', error);
            resetAddProductSaveButtonState();
            showMessage(getText('msg-upload-image-error'), 'error');
            return;
        }
    }

    const newProduct = {
        id: nextProductId,
        name: pname,
        category: selectedCategory,
                prices: {
                    retail: {
                        USD: retailUSD,
                        LBP: retailLBP
                    },
                    wholesale: {
                        USD: wholesaleUSD,
                        LBP: wholesaleLBP
                    },
                    vip: {
                        USD: vipUSD,
                        LBP: vipLBP
                    }
                },
                priceUSD: retailUSD,
                priceLBP: retailLBP,
        costUSD: parseFloat(document.getElementById('productCostUSD').value) || 0,
        stock: stockQty,
        barcode: barcodeNormAdd,
        imeiTracking: imeiTracking,
        imeiList: imeiTracking ? imeiList.map(imei => ({ imei: String(imei), status: 'available' })) : undefined,
        unitType: linkedUnitType,
        linked_pack_product_id: linkedUnitType === 'carton' ? linkedPackProductId : null,
        units_per_carton: linkedUnitType === 'carton' ? linkedUnitsPerCarton : null,
        supplier: document.getElementById('productSupplier').value,
        supplierName: (function () {
            const v = (document.getElementById('productSupplier') && document.getElementById('productSupplier').value) || '';
            const sup = v && Array.isArray(suppliers) ? suppliers.find(s => String(s.id) === String(v)) : null;
            return (sup && sup.name) ? String(sup.name).trim() : '';
        })(),
        expiryDate: productExpiryDate || undefined,
        minStock: 5,
        imageUrl: imageUrl || null,
        imagePath: imagePath || null,
        createdAt: new Date().toISOString(),
        updatedAt: Date.now(),
        createdBy: (typeof getCurrentUserName === 'function'
            ? getCurrentUserName()
            : (currentUser && currentUser.name) || (typeof currentUser === 'string' ? currentUser : null))
    };
            
            console.log('New product:', newProduct);
            if (imageUrl) {
                console.log('✅ Image saved with product:', imageUrl.substring(0, 50) + '...');
                console.log('📊 Image URL length:', imageUrl.length, 'chars');
            } else {
                console.log('⚠️ No product image provided');
            }
    
    products.push(newProduct);
    saveToStorage('products', products);
    try {
        const currentProducts = typeof getCurrentProducts === 'function' ? getCurrentProducts() : products;
        const existsAfterSave = Array.isArray(currentProducts) && currentProducts.some(p => String(p.id) === String(newProduct.id));
        console.log('[Add Product] save diagnostic:', {
            id: newProduct.id,
            name: newProduct.name,
            existsAfterSave,
            currentProductsCount: Array.isArray(currentProducts) ? currentProducts.length : 0
        });
    } catch (error) {
        console.warn('[Add Product] save diagnostic failed:', error);
    }
    try {
        enqueueSyncOp('products', 'upsert', newProduct.id, newProduct);
        scheduleSyncFlush();
        // رفع فوري إلى Firebase حتى لا تُستبدل القائمة بمزامنة دورية قبل وصول المنتج للسحابة
        await flushSyncQueue();
    } catch (e) {
        console.warn('[Add Product] Failed to schedule/flush immediate sync:', e);
        try {
            window.__posCatalogLog = window.__posCatalogLog || [];
            window.__posCatalogLog.push({ t: Date.now(), action: 'add_product_sync_warn', id: newProduct.id, name: newProduct.name, err: String(e && e.message || e) });
        } catch (_) {}
    }

    // سجل إنشاء المنتج في سجل المنتجات
    try {
        const lang = document.documentElement.lang || 'ar';
        const action = lang === 'en' ? 'Create' : 'إنشاء';
        const note = lang === 'en'
            ? `Product created: ${newProduct.name} (USD ${retailUSD.toFixed(2)}, LBP ${retailLBP})`
            : `إنشاء منتج ${newProduct.name} (سعر مفرق ${retailUSD.toFixed(2)}$ / ${retailLBP} L)`;
        appendProductLog(newProduct.id, action, note);
    } catch (e) {
        console.warn('product log (create) failed:', e);
    }
    
    // حفظ المنتج في Firestore مباشرة
    saveAllData();
    
    // تسجيل نفقة توريد المنتج تلقائياً
    try {
        const qty = Math.max(0, parseInt(document.getElementById('productQuantity').value) || 0);
        const unitCost = Number(document.getElementById('productCostUSD').value) || 0;
        
        if (qty > 0 && unitCost > 0) {
            recordProductSupplyExpense(newProduct.name, qty, unitCost, 'USD');
        }
    } catch(e) {
        console.warn('Error recording product supply expense:', e);
    }
    
    // إنشاء قيد شراء وفاتورة للمورد (القيمة = id المورد من القائمة)
    try {
        const supplierRaw = (newProduct.supplier || '').toString().trim();
        const sup = supplierRaw ? suppliers.find(s => String(s.id) === String(supplierRaw)) : null;
        if (sup && sup.id != null) {
            const supplierId = sup.id;
            const qty = Math.max(0, parseInt(document.getElementById('productQuantity').value) || 0);
            const unitCost = Number(document.getElementById('productCostUSD').value) || 0;
            const total = unitCost * qty;
            let paidNow = Number(document.getElementById('productPayNow')?.value || 0) || 0;
            if (paidNow < 0) paidNow = 0;
            if (paidNow > total) paidNow = total;
            const userNote = (document.getElementById('productSupplierPaymentNote')?.value || '').trim();
            const rem = Math.max(0, total - paidNow);
            const ledgerNote = [
                qty + '× @$' + unitCost.toFixed(2) + ' = $' + total.toFixed(2),
                userNote ? ('Note: ' + userNote) : ''
            ].filter(Boolean).join(' · ');

            const bill = {
                id: createRecordId('pu'),
                supplierId,
                date: new Date().toISOString().split('T')[0],
                dueDate: '',
                currency: 'USD',
                rate: exchangeRate,
                items: [{ productId: newProduct.id, quantity: qty, price: unitCost, name: newProduct.name }],
                total: total,
                totalUSD: total,
                paidUSD: paidNow,
                status: 'unpaid'
            };
            recalcPurchaseStatus(bill);
            purchases.push(bill);

            addSupplierLedgerEntry({
                supplier_id: supplierId,
                type: 'PURCHASE',
                ref_no: String(bill.id),
                product_name: newProduct.name,
                total_cost: total,
                paid_now: paidNow,
                remaining: rem,
                note: ledgerNote,
                currency: 'USD',
                rate: exchangeRate
            });

            if (paidNow > 0) {
                supplierPayments.push({
                    id: createRecordId('sp'),
                    supplierId,
                    date: new Date().toISOString(),
                    currency: 'USD',
                    amount: paidNow,
                    rate: exchangeRate,
                    method: 'cash',
                    note: userNote || ('Add product: ' + newProduct.name),
                    appliedTo: [{ billId: bill.id, amountUSD: paidNow }]
                });
                recordSupplierPaymentCash(paidNow, 'USD', 'cash', 'Supplier payment · ' + (newProduct.name || '') + ' #' + supplierId);
            }

            saveAllData();
            try {
                try { enqueueSyncOp('purchases', 'upsert', bill.id, bill); } catch (_) {}
                const led = supplierLedger[supplierLedger.length - 1];
                if (led && led.id != null) try { enqueueSyncOp('supplierLedger', 'upsert', led.id, led); } catch (_) {}
                if (paidNow > 0) {
                    const pr = supplierPayments[supplierPayments.length - 1];
                    if (pr && pr.id != null) try { enqueueSyncOp('supplierPayments', 'upsert', pr.id, pr); } catch (_) {}
                }
                saveToStorage('purchases', purchases);
                saveToStorage('supplierLedger', supplierLedger);
                saveToStorage('supplierPayments', supplierPayments);
                await flushSyncQueue();
            } catch (_) {}
            try { loadPurchases(); } catch(_) {}
            try { loadSuppliers(); } catch(_) {}

            sendTelegramNotification('supplier_payment', {
                operationLabel: 'Supplier · Add product',
                dateTime: new Date(),
                sellerName: typeof getCurrentUserName === 'function' ? getCurrentUserName() : undefined,
                supplierName: sup.name || '',
                productName: newProduct.name,
                totalCost: total,
                amountPaid: paidNow,
                remaining: rem,
                note: userNote || ledgerNote
            });
        }
    } catch (e) { console.warn('supplier purchase ledger', e); }

    // بعد إضافة منتج جديد، انتقل دائماً إلى الصفحة الأولى ليظهر في أعلى الجدول
    try {
        productsCurrentPage = 1;
        if (typeof saveProductsPaginationState === 'function') saveProductsPaginationState();
    } catch(_) {}
    loadProducts();
    hideModal('addProductModal');
    resetAddProductSaveButtonState();
    this.reset();
    selectProductCategory('');
    hideProductCategoryDropdown();
    const expiryInput = document.getElementById('productExpiryDate');
    if (expiryInput) expiryInput.value = '';
    // Reset image preview
    removeProductImage();
    
    // تحديث نقطة البيع إذا كانت مفتوحة حالياً
    console.log('🔄 Product added, attempting to refresh POS...');
    updatePOSIfActive();
    
    // إشعار جميع النوافذ المفتوحة بتحديث المنتجات
    notifyProductsUpdated();
    
    // تحديث إضافي مباشر لنقطة البيع
    setTimeout(() => {
        console.log('🔄 Extra POS refresh...');
        updatePOSIfActive();
    }, 100);
    
    // تحديث إضافي بعد تأخير أطول للتأكد
    setTimeout(() => {
        console.log('🔄 Final POS refresh...');
        updatePOSIfActive();
    }, 500);
    
    // تحديث تنبيهات المخزون
    updateStockAlertsDashboard();
    
    // تحديث لوحة التحكم
    updateDashboardIfActive();
    
    showMessage(getText('product-added'), 'success');
    
            // مسح شاشات العرض (وإعادة تعيين وضع التعديل اليدوي)
            const retailDisplay = document.getElementById('retailLBPDisplay');
            const wholesaleDisplay = document.getElementById('wholesaleLBPDisplay');
            const vipDisplay = document.getElementById('vipLBPDisplay');
            
            if (retailDisplay) { retailDisplay.value = ''; retailDisplay._manual = false; }
            if (wholesaleDisplay) { wholesaleDisplay.value = ''; wholesaleDisplay._manual = false; }
            if (vipDisplay) { vipDisplay.value = ''; vipDisplay._manual = false; }
            
            showMessage(getText('msg-product-added-success'));
            console.log('Product saved successfully');
        });
    }
});

// نظام استرجاع المبيعات
let currentSaleForReturn = null;

function initiateSaleReturn(saleIdOrNumber) {
    const key = String(saleIdOrNumber);
    currentSaleForReturn = sales.find(s => String(s.id) === key || String(s.invoiceNumber) === key);
    if (!currentSaleForReturn) {
        showMessage(getText('msg-sale-item-not-found'), 'error');
        return;
    }
    
    if (currentSaleForReturn.returned) {
        showMessage(getText('msg-already-returned'), 'error');
        return;
    }
    
    // التحقق من أن الفاتورة ليست من نوع مرتجع (RF-)
    // منع إنشاء "Refund Loop" - لا يمكن عمل مرتجع على فاتورة مرتجع
    if (currentSaleForReturn.invoiceNumber && currentSaleForReturn.invoiceNumber.startsWith('RF-')) {
        showMessage(getText('msg-no-return-on-return'), 'error');
        return;
    }
    
    // ملء بيانات المبيعة (ترجمة عميل عادي / نقدي عند اللغة الإنجليزية)
    document.getElementById('returnInvoiceNumber').textContent = currentSaleForReturn.invoiceNumber;
    const custRaw = (currentSaleForReturn.customer || currentSaleForReturn.customerName || '').trim();
    const customerDisplay = (!custRaw || custRaw === 'عميل عادي' || custRaw === 'Regular Customer')
        ? (typeof getText === 'function' ? getText('regular-customer') : 'Regular Customer')
        : custRaw;
    document.getElementById('returnCustomerName').textContent = customerDisplay;
    document.getElementById('returnTotalAmount').textContent = formatCurrency(currentSaleForReturn.amount);
    
    // عرض طريقة الدفع مع التفاصيل (ترجمة نقدي → Cash)
    const pmRaw = String(currentSaleForReturn.paymentMethod || '').trim();
    const pmBase = (pmRaw === 'نقدي' || pmRaw.toLowerCase() === 'cash')
        ? (typeof getText === 'function' ? getText('cash') : 'Cash')
        : pmRaw;
    let paymentMethodText = pmBase;
    if (currentSaleForReturn.cashDetails) {
        const currency = currentSaleForReturn.cashDetails.paymentCurrency;
        const paid = currentSaleForReturn.cashDetails.amountPaid;
        if (currency === 'USD') {
            paymentMethodText += ` ($${paid.toFixed(2)})`;
        } else {
            paymentMethodText += ` (${paid.toLocaleString()} L)`;
        }
    } else if (currentSaleForReturn.partialDetails) {
        const paidLabel = (document.documentElement.lang === 'en') ? 'Paid' : 'مدفوع';
        const paidParts = [];
        const paidUSD = Number(currentSaleForReturn.partialDetails.amountPaidUSD || 0);
        const paidLBP = Number(currentSaleForReturn.partialDetails.amountPaidLBP || 0);
        const currency = currentSaleForReturn.partialDetails.paymentCurrency;
        const paid = Number(currentSaleForReturn.partialDetails.amountPaid || 0);
        if (paidUSD > 0) paidParts.push(`$${paidUSD.toFixed(2)}`);
        if (paidLBP > 0) paidParts.push(`${paidLBP.toLocaleString()} L`);
        if (paidParts.length === 0 && paid > 0) {
            paidParts.push(currency === 'USD' ? `$${paid.toFixed(2)}` : `${paid.toLocaleString()} L`);
        }
        if (paidParts.length > 0) paymentMethodText += ` - ${paidLabel}: ${paidParts.join(' + ')}`;
    }
    document.getElementById('returnPaymentMethod').textContent = paymentMethodText;
    
    // إعادة تعيين النموذج
    const returnType = document.getElementById('returnType');
    const partialReturnAmount = document.getElementById('partialReturnAmount');
    const returnReason = document.getElementById('returnReason');
    const returnNotes = document.getElementById('returnNotes');
    
    if (returnType) returnType.value = 'full';
    if (partialReturnAmount) partialReturnAmount.value = '';
    if (returnReason) returnReason.value = 'defective';
    if (returnNotes) returnNotes.value = '';
    document.getElementById('partialAmountGroup').style.display = 'none';
    
    // بناء قائمة عناصر الفاتورة لاختيار إرجاع جزئي بالكمية
    try {
        const container = document.getElementById('returnItemsContainer');
        if (container) {
            const items = Array.isArray(currentSaleForReturn.items) ? currentSaleForReturn.items : [];
            const html = items.map((it, idx) => {
                const maxQty = Number(it.quantity || 0);
                const unitUSD = (it.finalPriceUSD ?? it.originalPriceUSD ?? it.priceUSD ?? 0);
                return `
                    <div class="return-item-row" style="display:flex;align-items:center;gap:8px;padding:8px;border-bottom:1px solid #eee;">
                        <input type="checkbox" class="ri-check" id="ri_chk_${idx}" data-index="${idx}">
                        <div style="flex:1;">
                            <div style="font-weight:600">${it.name || ('#'+it.id)}</div>
                            <div style="font-size:12px;color:#6b7280">Qty: ${maxQty} • $${Number(unitUSD||0).toFixed(2)}</div>
                        </div>
                        <input type="number" class="ri-qty" id="ri_qty_${idx}" data-index="${idx}" min="0" max="${maxQty}" value="0" style="width:80px;padding:6px;border:1px solid #ddd;border-radius:6px;">
                    </div>
                `;
            }).join('');
            container.innerHTML = html || `<div style="padding:10px;color:#6b7280">لا توجد عناصر</div>`;
            container.querySelectorAll('.ri-check, .ri-qty').forEach(el => {
                el.addEventListener('change', () => {
                    if (el.classList.contains('ri-check') && el.checked) {
                        const idx = Number(el.getAttribute('data-index'));
                        const qtyInput = container.querySelector(`#ri_qty_${idx}`);
                        if (qtyInput && Number(qtyInput.value) === 0) qtyInput.value = '1';
                    }
                    updateReturnSummary();
                });
            });
            // أخفِ قسم العناصر مبدئياً إذا كان النوع استرجاع كامل
            try {
                const itemsSection = document.getElementById('returnItemsSection');
                const rtSel = document.getElementById('returnType');
                if (itemsSection) itemsSection.style.display = (rtSel && rtSel.value === 'partial') ? 'block' : 'none';
            } catch(_) {}
        }
    } catch(_) {}
    
    // تحديث ملخص الاسترجاع
    updateReturnSummary();
    
    // عرض النافذة
    showModal('returnSaleModal');
    try { translateReturnModalUI(); } catch(e) {}
}
function updateReturnSummary() {
    if (!currentSaleForReturn) return;
    
    const returnType = document.getElementById('returnType').value;
    const partialAmount = parseFloat(document.getElementById('partialReturnAmount').value) || 0;
    
    let refundDisplayText = '';
    let refundMethodText = '';
    let computedRefundUSDFromItems = 0;
    // عند اختيار عناصر جزئية، احسب المبلغ بدقة من الكميات
    try {
        const container = document.getElementById('returnItemsContainer');
        if (container && returnType === 'partial') {
            const items = Array.isArray(currentSaleForReturn.items) ? currentSaleForReturn.items : [];
            items.forEach((it, idx) => {
                const chk = container.querySelector(`#ri_chk_${idx}`);
                const qEl = container.querySelector(`#ri_qty_${idx}`);
                if (!chk || !qEl) return;
                const q = Math.min(Number(qEl.value || 0), Number(it.quantity || 0));
                if (chk.checked && q > 0) {
                    const unitUSD = (it.finalPriceUSD ?? it.originalPriceUSD ?? it.priceUSD ?? 0);
                    computedRefundUSDFromItems += Number(unitUSD || 0) * q;
                }
            });
        }
    } catch(_) {}
    
    if (currentSaleForReturn.cashDetails) {
        // مبيعة نقدية
        const originalCurrency = currentSaleForReturn.cashDetails.paymentCurrency;
        const originalPaid = currentSaleForReturn.cashDetails.amountPaid;
        
        if (returnType === 'full') {
            if (originalCurrency === 'USD') {
                refundDisplayText = `$${originalPaid.toFixed(2)}`;
            } else {
                refundDisplayText = `${originalPaid.toLocaleString()} L`;
            }
        } else if (returnType === 'partial') {
            const effectiveUSD = computedRefundUSDFromItems > 0 ? computedRefundUSDFromItems : partialAmount;
            const refundRatio = Math.min(1, Math.max(0, effectiveUSD / (currentSaleForReturn.amount || 1)));
            const refundInOriginalCurrency = originalPaid * refundRatio;
            
            if (originalCurrency === 'USD') {
                refundDisplayText = `$${refundInOriginalCurrency.toFixed(2)}`;
            } else {
                refundDisplayText = `${refundInOriginalCurrency.toLocaleString()} L`;
            }
        }
        refundMethodText = (document.documentElement.lang === 'en') ? 'Cash' : 'نقدي';
        
    } else if (currentSaleForReturn.partialDetails) {
        // مبيعة جزئية
        const originalCurrency = currentSaleForReturn.partialDetails.paymentCurrency;
        const originalPaid = currentSaleForReturn.partialDetails.amountPaid;
        
        if (returnType === 'full') {
            if (originalCurrency === 'USD') {
                refundDisplayText = `$${originalPaid.toFixed(2)}`;
            } else {
                refundDisplayText = `${originalPaid.toLocaleString()} L`;
            }
        } else if (returnType === 'partial') {
            const effectiveUSD = computedRefundUSDFromItems > 0 ? computedRefundUSDFromItems : partialAmount;
            const refundRatio = Math.min(1, Math.max(0, effectiveUSD / (currentSaleForReturn.amount || 1)));
            const refundInOriginalCurrency = Math.min(originalPaid * refundRatio, originalPaid);
            
            if (originalCurrency === 'USD') {
                refundDisplayText = `$${refundInOriginalCurrency.toFixed(2)}`;
            } else {
                refundDisplayText = `${refundInOriginalCurrency.toLocaleString()} L`;
            }
        }
        refundMethodText = 'نقدي (من المبلغ المدفوع)';
        
    } else {
        // مبيعة قديمة - افتراض
        let refundAmount = 0;
        if (returnType === 'full') {
            refundAmount = currentSaleForReturn.amount;
        } else if (returnType === 'partial') {
            const effectiveUSD = computedRefundUSDFromItems > 0 ? computedRefundUSDFromItems : partialAmount;
            refundAmount = Math.min(effectiveUSD, currentSaleForReturn.amount);
        }
        
        if (currentSaleForReturn.amount < 50) {
            refundDisplayText = `$${refundAmount.toFixed(2)}`;
        } else {
            refundDisplayText = `${(refundAmount * settings.exchangeRate).toLocaleString()} L`;
        }
        refundMethodText = 'نقدي';
    }
    
    document.getElementById('refundAmount').textContent = refundDisplayText;
    document.getElementById('refundMethod').textContent = refundMethodText;
}

async function processReturn() {
    products = getCurrentProducts();
    if (!currentSaleForReturn) {
        showMessage(getText('msg-data-error'), 'error');
        return;
    }
    
    console.log('🔍 Starting sale return process:', currentSaleForReturn);
    
    const returnTypeEl = document.getElementById('returnType');
    const partialAmountEl = document.getElementById('partialReturnAmount');
    const returnReasonEl = document.getElementById('returnReason');
    const returnNotesEl = document.getElementById('returnNotes');
    
    if (!returnTypeEl || !returnReasonEl || !returnNotesEl) {
        console.error('❌ Return form elements not found');
        showMessage(getText('msg-return-ui-error'), 'error');
        return;
    }
    
    const returnType = returnTypeEl.value;
    const partialAmount = parseFloat(partialAmountEl ? partialAmountEl.value : '0') || 0;
    const partialAmountUSDCents = toUSDCents(partialAmount);
    const returnReason = returnReasonEl.value;
    const returnNotes = returnNotesEl.value;
    
    console.log('📋 Return data:', { returnType, partialAmount, returnReason });
    
    // التحقق من صحة البيانات (قبول اختيار العناصر بدون إدخال مبلغ)
    if (returnType === 'partial') {
        let hasSelected = false;
        try {
            const cont = document.getElementById('returnItemsContainer');
            if (cont) {
                cont.querySelectorAll('.ri-check').forEach(c => { if (c.checked) hasSelected = true; });
            }
        } catch(_) {}
        if (!hasSelected && (partialAmount <= 0 || partialAmount > currentSaleForReturn.amount)) {
            showMessage(getText('msg-select-items-or-amount'), 'error');
            return;
        }
    }
    
    // حساب مبلغ الاسترجاع مع دعم اختيار العناصر
    let refundAmountUSDCents = returnType === 'full'
        ? toUSDCents(currentSaleForReturn.amount || 0)
        : partialAmountUSDCents;
    // تفاصيل المبلغ المُرجع (قد تكون عملة واحدة أو أكثر) — تُستخدم أيضاً في رسالة النجاح آخر الدالة
    let refundDetails = [];
    let selectedReturnByItems = [];
    try {
        const container = document.getElementById('returnItemsContainer');
        if (container && returnType === 'partial') {
            const items = Array.isArray(currentSaleForReturn.items) ? currentSaleForReturn.items : [];
            let sumUSDCents = 0;
            items.forEach((it, idx) => {
                const chk = container.querySelector(`#ri_chk_${idx}`);
                const qEl = container.querySelector(`#ri_qty_${idx}`);
                if (!chk || !qEl) return;
                const qty = Math.min(Number(qEl.value || 0), Number(it.quantity || 0));
                if (chk.checked && qty > 0) {
                    const unitUSD = (it.finalPriceUSD ?? it.originalPriceUSD ?? it.priceUSD ?? 0);
                    sumUSDCents += toUSDCents(unitUSD || 0) * qty;
                    selectedReturnByItems.push({ id: it.id, name: it.name, quantity: qty, unitUSD: Number(unitUSD||0), imei: it.imei || null });
                }
            });
            if (sumUSDCents > 0) refundAmountUSDCents = sumUSDCents;
        }
    } catch(_) {}
    const refundAmount = refundAmountUSDCents / 100;
    
    // F6: التحقق من كفاية رصيد الصندوق قبل الاسترجاع (قبل تعديل أي بيانات)
    const pmRaw = String(currentSaleForReturn.paymentMethod || '').toLowerCase();
    const shouldAffectDrawer = pmRaw.includes('cash') || /نقد/.test(currentSaleForReturn.paymentMethod || '') || pmRaw.includes('partial') || /جزئي/.test(currentSaleForReturn.paymentMethod || '') || !!currentSaleForReturn.cashDetails || !!currentSaleForReturn.partialDetails;
    if (shouldAffectDrawer) {
        const drawerForCheck = loadFromStorage('cashDrawer', { cashUSD: 0, cashLBP: 0 });
        let dUSD = 0, dLBP = 0;
        if (currentSaleForReturn.cashDetails) {
            const curr = currentSaleForReturn.cashDetails.paymentCurrency;
            const paid = currentSaleForReturn.cashDetails.amountPaid;
            if (returnType === 'full') { if (curr === 'USD') dUSD = paid; else dLBP = paid; }
            else {
                const totalCents = Math.max(1, toUSDCents(currentSaleForReturn.amount || 0));
                const rNum = Math.min(totalCents, refundAmountUSDCents);
                if (curr === 'USD') dUSD = (toUSDCents(paid) * rNum / totalCents) / 100;
                else dLBP = Math.round((toLBPUnits(paid) * rNum) / totalCents);
            }
        } else if (currentSaleForReturn.partialDetails) {
            const curr = currentSaleForReturn.partialDetails.paymentCurrency;
            const paid = Number(currentSaleForReturn.partialDetails.amountPaid || 0);
            const paidUSD = Number(currentSaleForReturn.partialDetails.amountPaidUSD || (curr === 'USD' ? paid : 0));
            const paidLBP = Number(currentSaleForReturn.partialDetails.amountPaidLBP || (curr === 'LBP' ? paid : 0));
            if (returnType === 'full') {
                dUSD = paidUSD;
                dLBP = paidLBP;
            } else {
                const totalCents = Math.max(1, toUSDCents(currentSaleForReturn.amount || 0));
                const rNum = Math.min(totalCents, refundAmountUSDCents);
                dUSD = Math.min((toUSDCents(paidUSD) * rNum / totalCents) / 100, paidUSD);
                dLBP = Math.min(Math.round(toLBPUnits(paidLBP) * rNum / totalCents), paidLBP);
            }
        } else {
            if (currentSaleForReturn.amount < 50) dUSD = refundAmountUSDCents / 100;
            else dLBP = Math.round(refundAmountUSDCents * (settings.exchangeRate || 1) / 100);
        }
        if ((drawerForCheck.cashUSD || 0) < dUSD || (drawerForCheck.cashLBP || 0) < dLBP) {
            showMessage(getText('msg-insufficient-cash-refund'), 'error');
            return;
        }
    }
    
    // تحديث بيانات المبيعة
    currentSaleForReturn.returned = true;
    currentSaleForReturn.returnType = returnType;
    currentSaleForReturn.returnAmount = refundAmount;
    currentSaleForReturn.returnAmountUSDCents = refundAmountUSDCents;
    // خزّن تاريخ الإرجاع بالتاريخ المحلي (YYYY-MM-DD) لتفادي اختلاف UTC
    try {
        const localIso = getLocalDateTimeISO ? getLocalDateTimeISO() : new Date().toISOString();
        currentSaleForReturn.returnDate = (localIso.split('T')[0]);
    } catch(_) {
        const nowLocal = new Date();
        currentSaleForReturn.returnDate = `${nowLocal.getFullYear()}-${String(nowLocal.getMonth()+1).padStart(2, '0')}-${String(nowLocal.getDate()).padStart(2, '0')}`;
    }
    currentSaleForReturn.returnReason = returnReason;
    currentSaleForReturn.returnNotes = returnNotes;
    
    // إرجاع المنتجات للمخزون + استعادة حالة IMEI إلى available (حتى يُباع الجهاز من جديد)
    function imeiNorm(s) { return String(s || '').replace(/\s/g, ''); }
    function restoreImeiOnProduct(product, imeiStr) {
        if (!product || !product.imeiTracking || !Array.isArray(product.imeiList) || !imeiStr) return false;
        const entry = product.imeiList.find(e => imeiNorm(e.imei) === imeiNorm(imeiStr));
        if (entry) {
            entry.status = 'available';
            product.stock = product.imeiList.filter(e => e.status === 'available' || e.status === 'returned').length;
            return true;
        }
        return false;
    }
    if (currentSaleForReturn.items) {
        if (selectedReturnByItems.length > 0) {
            selectedReturnByItems.forEach(sel => {
                const product = products.find(p => p.id === sel.id || String(p.id) === String(sel.id));
                if (!product) return;
                const q = Math.max(1, Number(sel.quantity) || 1);
                if (product.imeiTracking && Array.isArray(product.imeiList)) {
                    if (sel.imei) restoreImeiOnProduct(product, sel.imei);
                    else restoreImeisAfterReturnByQuantity(product, q);
                    recalcImeiProductStock(product);
                } else {
                    addPackStockToProduct(product, q);
                }
                touchProductClientTimestamp(product);
                // سجل حركة مخزون للمرتجع (زيادة الكمية)
                try {
                    recordStockMovement(
                        'refund',
                        product.id,
                        q,
                        currentSaleForReturn.invoiceNumber || 'REFUND',
                        `استرجاع ${q} من ${product.name || sel.name || ''}`
                    );
                } catch (_) {}
            });
        } else {
            currentSaleForReturn.items.forEach(item => {
                const pid = item.productId != null ? item.productId : item.id;
                const product = products.find(p => p.id === pid || String(p.id) === String(pid));
                if (!product) return;
                const lineQty = Math.max(1, Number(item.quantity) || 1);
                const returnQuantity = returnType === 'full' ? lineQty :
                    Math.max(1, Math.min(lineQty, Math.floor((lineQty * refundAmountUSDCents) / Math.max(1, toUSDCents(currentSaleForReturn.amount || 0))) || 1));
                let appliedQty = returnType === 'full' ? lineQty : returnQuantity;
                if (product.imeiTracking && Array.isArray(product.imeiList)) {
                    if (item.imei) restoreImeiOnProduct(product, item.imei);
                    else restoreImeisAfterReturnByQuantity(product, returnType === 'full' ? lineQty : returnQuantity);
                    recalcImeiProductStock(product);
                } else {
                    addPackStockToProduct(product, appliedQty);
                }
                touchProductClientTimestamp(product);
                // سجل حركة مخزون للمرتجع (زيادة تقريبية حسب الكمية المحتسبة)
                try {
                    recordStockMovement(
                        'refund',
                        product.id,
                        appliedQty,
                        currentSaleForReturn.invoiceNumber || 'REFUND',
                        `استرجاع ${appliedQty} من ${product.name || item.name || ''}`
                    );
                } catch (_) {}
            });
        }
    }
    try { saveToStorage('products', products); } catch (_) {}
    
    // تحديث الصندوق - إرجاع المال
    // توسيع التحقق ليشمل الحالات الإنجليزية/العربية والاعتماد على تفاصيل الدفع المتوفرة
    {
        const pm = String(currentSaleForReturn.paymentMethod || '').toLowerCase();
        const isCashLike = pm.includes('cash') || /نقد/.test(currentSaleForReturn.paymentMethod || '');
        const isPartialLike = pm.includes('partial') || /جزئي/.test(currentSaleForReturn.paymentMethod || '');
        const shouldAffectCashDrawer = isCashLike || isPartialLike || !!currentSaleForReturn.cashDetails || !!currentSaleForReturn.partialDetails;
        if (!shouldAffectCashDrawer) {
            console.log('❌ Cash drawer not updated — payment method is not cash/partial:', currentSaleForReturn.paymentMethod);
        }
    }
    if (
        (function(pm, sale){ 
            pm = String(pm || '').toLowerCase(); 
            return pm.includes('cash') || /نقد/.test(String(pm)) || pm.includes('partial') || /جزئي/.test(String(pm)) || !!sale.cashDetails || !!sale.partialDetails; 
        })(currentSaleForReturn.paymentMethod, currentSaleForReturn)
    ) {
        console.log('🔄 Updating cash drawer for return — payment method:', currentSaleForReturn.paymentMethod);
        
        // التأكد من تحميل الصندوق من التخزين (بدون قيم افتراضية خاطئة)
        const stored = loadFromStorage('cashDrawer', null);
        if (stored && typeof stored === 'object') {
            cashDrawer = { ...cashDrawer, ...stored };
            cashDrawer.cashUSD = (toUSDCents(stored.cashUSD || 0)) / 100;
            cashDrawer.cashLBP = toLBPUnits(stored.cashLBP || 0);
            if (Array.isArray(stored.transactions)) cashDrawer.transactions = stored.transactions;
            if (stored.lastUpdate) cashDrawer.lastUpdate = stored.lastUpdate;
        }
        
        console.log('🏦 Loaded cash drawer data:', cashDrawer);
        
        if (currentSaleForReturn.cashDetails) {
            // مبيعة نقدية
            const originalCurrency = currentSaleForReturn.cashDetails.paymentCurrency;
            const originalPaid = currentSaleForReturn.cashDetails.amountPaid;
            
            console.log('💰 Cash sale details:', { originalCurrency, originalPaid, returnType });
            console.log('💳 Cash drawer before return:', { USD: cashDrawer.cashUSD, LBP: cashDrawer.cashLBP });
            
            if (returnType === 'full') {
                // استرجاع كامل - نرجع نفس المبلغ والعملة المدفوعة
                if (originalCurrency === 'USD') {
                    cashDrawer.cashUSD = (toUSDCents(cashDrawer.cashUSD || 0) - toUSDCents(originalPaid)) / 100;
                    refundDetails.push(`$${originalPaid.toFixed(2)}`);
                    console.log('💵 Deducted from USD:', originalPaid);
                } else {
                    cashDrawer.cashLBP = toLBPUnits(cashDrawer.cashLBP || 0) - toLBPUnits(originalPaid);
                    refundDetails.push(`${originalPaid.toLocaleString()} L`);
                    console.log('💴 Deducted from LBP:', originalPaid);
                }
            } else {
                // استرجاع جزئي - نحسب النسبة
                const totalCents = Math.max(1, toUSDCents(currentSaleForReturn.amount || 0));
                const refundInOriginalCurrency = originalCurrency === 'USD'
                    ? ((toUSDCents(originalPaid) * refundAmountUSDCents / totalCents) / 100)
                    : Math.round(toLBPUnits(originalPaid) * refundAmountUSDCents / totalCents);
                
                if (originalCurrency === 'USD') {
                    cashDrawer.cashUSD = (toUSDCents(cashDrawer.cashUSD || 0) - toUSDCents(refundInOriginalCurrency)) / 100;
                    refundDetails.push(`$${refundInOriginalCurrency.toFixed(2)}`);
                } else {
                    cashDrawer.cashLBP = toLBPUnits(cashDrawer.cashLBP || 0) - toLBPUnits(refundInOriginalCurrency);
                    refundDetails.push(`${refundInOriginalCurrency.toLocaleString()} L`);
                }
            }
        } else if (currentSaleForReturn.partialDetails) {
            // مبيعة جزئية - نرجع فقط المبلغ المدفوع
            const originalCurrency = currentSaleForReturn.partialDetails.paymentCurrency;
            const originalPaid = Number(currentSaleForReturn.partialDetails.amountPaid || 0);
            const originalPaidUSD = Number(currentSaleForReturn.partialDetails.amountPaidUSD || (originalCurrency === 'USD' ? originalPaid : 0));
            const originalPaidLBP = Number(currentSaleForReturn.partialDetails.amountPaidLBP || (originalCurrency === 'LBP' ? originalPaid : 0));
            
            if (returnType === 'full') {
                if (originalPaidUSD > 0) {
                    cashDrawer.cashUSD = (toUSDCents(cashDrawer.cashUSD || 0) - toUSDCents(originalPaidUSD)) / 100;
                    refundDetails.push(`$${originalPaidUSD.toFixed(2)}`);
                }
                if (originalPaidLBP > 0) {
                    cashDrawer.cashLBP = toLBPUnits(cashDrawer.cashLBP || 0) - toLBPUnits(originalPaidLBP);
                    refundDetails.push(`${originalPaidLBP.toLocaleString()} L`);
                }
            } else {
                // استرجاع جزئي للمبيعة الجزئية
                const totalCents = Math.max(1, toUSDCents(currentSaleForReturn.amount || 0));
                const refundUSD = Math.min((toUSDCents(originalPaidUSD) * refundAmountUSDCents / totalCents) / 100, originalPaidUSD);
                const refundLBP = Math.min(Math.round(toLBPUnits(originalPaidLBP) * refundAmountUSDCents / totalCents), originalPaidLBP);
                if (refundUSD > 0) {
                    cashDrawer.cashUSD = (toUSDCents(cashDrawer.cashUSD || 0) - toUSDCents(refundUSD)) / 100;
                    refundDetails.push(`$${refundUSD.toFixed(2)}`);
                }
                if (refundLBP > 0) {
                    cashDrawer.cashLBP = toLBPUnits(cashDrawer.cashLBP || 0) - toLBPUnits(refundLBP);
                    refundDetails.push(`${refundLBP.toLocaleString()} L`);
                }
            }
        } else {
            // مبيعة قديمة بدون تفاصيل - افتراض بالدولار
            if (currentSaleForReturn.amount < 50) { // افتراض مبالغ صغيرة بالدولار
                cashDrawer.cashUSD = (toUSDCents(cashDrawer.cashUSD || 0) - refundAmountUSDCents) / 100;
                refundDetails.push(`$${(refundAmountUSDCents / 100).toFixed(2)}`);
            } else {
                // تحويل للليرة
                const refundLBP = Math.round(refundAmountUSDCents * (settings.exchangeRate || 1) / 100);
                cashDrawer.cashLBP = toLBPUnits(cashDrawer.cashLBP || 0) - toLBPUnits(refundLBP);
                refundDetails.push(`${refundLBP.toLocaleString()} L`);
            }
        }
        
        // إضافة سجل معاملة
        addCashDrawerTransaction({
            timestamp: new Date().toISOString(),
            type: 'refund',
            amount: refundAmount,
            amountUSDCents: refundAmountUSDCents,
            description: `استرجاع ${returnType === 'full' ? 'كامل' : 'جزئي'} للفاتورة ${currentSaleForReturn.invoiceNumber} - المبلغ المرجع: ${refundDetails.join(' + ')}`,
            balanceAfter: {
                USD: cashDrawer.cashUSD,
                LBP: cashDrawer.cashLBP
            }
        });
        
        cashDrawer.lastUpdate = new Date().toISOString();
        console.log('💳 Cash drawer after return:', { USD: cashDrawer.cashUSD, LBP: cashDrawer.cashLBP });
        saveToStorage('cashDrawer', cashDrawer);
        updateCashDrawerDisplay();
        pushCashDrawerSummaryToCloud();
        console.log('✅ Cash drawer saved and UI updated');
    } else {
        console.log('❌ Cash drawer not updated — payment method:', currentSaleForReturn.paymentMethod);
    }
    
    // مزامنة المنتجات المُعدَّلة (إعادة كميات للمخزون) إلى السحابة
    if (currentSaleForReturn.items) {
        const toSync = [];
        if (selectedReturnByItems.length > 0) {
            selectedReturnByItems.forEach(sel => {
                const p = products.find(pr => pr.id === sel.id);
                if (p) toSync.push(p);
            });
        } else {
            currentSaleForReturn.items.forEach(item => {
                const p = products.find(pr => pr.id === (item.productId || item.id));
                if (p && !toSync.some(x => x.id === p.id)) toSync.push(p);
            });
        }
        toSync.forEach(p => { try { enqueueSyncOp('products', 'upsert', p.id, p); } catch(_) {} });
        if (toSync.length) scheduleSyncFlush();
    }
    
    // في حالة البيع بالدَّين: تقليل دين العميل
    try {
        const pm = String(currentSaleForReturn.paymentMethod || '').toLowerCase();
        const isCreditSale = pm.includes('credit') || (currentSaleForReturn.invoiceNumber || '').startsWith('CR-') || currentSaleForReturn.paymentMethod === 'credit';
        if (isCreditSale && currentSaleForReturn.customerId) {
            const customer = customers.find(c => c.id === currentSaleForReturn.customerId);
            if (customer) {
                const before = customer.creditBalance || 0;
                customer.creditBalance = Math.max(0, before - (refundAmountUSDCents / 100));
                customer.currentDebt = customer.creditBalance;
                touchCustomerClientTimestamp(customer);
                if (!Array.isArray(customer.creditHistory)) customer.creditHistory = [];
                customer.creditHistory.push({
                    timestamp: new Date().toISOString(),
                    type: 'refund',
                    amount: -(refundAmountUSDCents / 100),
                    amountUSDCents: -refundAmountUSDCents,
                    description: creditHistoryDescriptionText('refund_invoice', { invoice: currentSaleForReturn.invoiceNumber }),
                    balanceAfter: customer.creditBalance
                });
                await persistCustomerRecord(customer, { requireCloudConfirm: true, context: 'refund_credit_adjust' });
                // سجل العميل العام
                const logs = loadFromStorage('customerLogs', {});
                const key = String(customer.id);
                if (!Array.isArray(logs[key])) logs[key] = [];
                logs[key].push({
                    timestamp: new Date().toLocaleString(),
                    action: (document.documentElement.lang === 'en' ? 'Refund (Credit)' : 'استرجاع (دين)'),
                    user: (typeof getCurrentUserName === 'function' ? getCurrentUserName() : (currentUser && currentUser.name) || (typeof currentUser === 'string' ? currentUser : (document.documentElement.lang === 'en' ? 'User' : 'المستخدم'))),
                    note: (document.documentElement.lang === 'en' ? `Refund ${formatCurrency(refundAmount)} from invoice ${currentSaleForReturn.invoiceNumber}` : `تم استرجاع بقيمة ${formatCurrency(refundAmount)} من الفاتورة ${currentSaleForReturn.invoiceNumber}`)
                });
                saveToStorage('customerLogs', logs);
            }
        }
    } catch (e) {
        console.warn('refund credit adjust error', e);
    }
    
    // توليد فاتورة استرجاع للطباعة والتوثيق
    try {
        let returnedItems;
        if (selectedReturnByItems.length > 0) {
            returnedItems = selectedReturnByItems.map(sel => ({
                id: sel.id,
                name: sel.name,
                quantity: sel.quantity,
                price: sel.unitUSD,
                originalPriceUSD: sel.unitUSD,
                finalPriceUSD: sel.unitUSD,
                discountUSD: 0,
                discountPct: 0
            }));
        } else {
            const ratio = currentSaleForReturn.returnType === 'full'
                ? 1
                : ((refundAmountUSDCents / 100) / (currentSaleForReturn.amount || 1));
            returnedItems = (currentSaleForReturn.items || []).map(it => ({
                id: it.id,
                name: it.name,
                quantity: Math.max(1, Math.floor((it.quantity || 1) * ratio)),
                price: it.price,
                originalPriceUSD: it.originalPriceUSD,
                finalPriceUSD: it.finalPriceUSD,
                discountUSD: it.discountUSD,
                discountPct: it.discountPct
            }));
        }
        const now = new Date();
        const localDateTimeISO = getLocalDateTimeISO();
        const refundInvoice = {
            customerId: currentSaleForReturn.customerId,
            customer: currentSaleForReturn.customer,
            amount: refundAmount,
            amountUSDCents: refundAmountUSDCents,
            paymentMethod: 'refund',
            status: 'completed',
            date: `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`,
            timestamp: localDateTimeISO, // استخدام timestamp محلي صحيح
            items: returnedItems
        };
        // حفظ آمن وموحّد (F2: id و invoiceNumber من Firestore بادئة RF)
        await secureSaveSale(refundInvoice);
        var retItemsText = Array.isArray(refundInvoice.items) && refundInvoice.items.length
            ? refundInvoice.items.map(function(it) {
                var line = (it.name || 'Item') + ' x' + (it.quantity || 1);
                if (it.imei && String(it.imei).trim()) line += ' | IMEI: ' + String(it.imei).trim();
                return line;
            }).join(', ')
            : '';
        var profitImpactReturn = 0;
        (refundInvoice.items || []).forEach(function(it) {
            var prod = products.find(function(p) { return p.id === it.id; });
            var costUSD = (prod && typeof prod.costUSD === 'number') ? prod.costUSD : 0;
            var unitUSD = it.finalPriceUSD != null ? it.finalPriceUSD : (it.price != null ? (typeof it.price === 'number' ? it.price : 0) : 0);
            profitImpactReturn -= (unitUSD - costUSD) * (it.quantity || 0);
        });
        sendTelegramNotification('sale_returned', {
            operationLabel: 'Invoice Return / Refund',
            invoiceNumber: refundInvoice.invoiceNumber,
            amount: refundInvoice.amount,
            currency: 'USD',
            dateTime: refundInvoice.timestamp || getLocalDateTimeISO(),
            sellerName: typeof getCurrentUserName === 'function' ? getCurrentUserName() : undefined,
            productsText: retItemsText,
            note: (refundInvoice.customer || '') + ' | Refund',
            profit: profitImpactReturn
        });
        // عرض فاتورة الاسترجاع
        try { showInvoice(refundInvoice); } catch(e) {}
    } catch (e) {
        console.warn('generate refund invoice error', e);
    }
    
    
    // حفظ البيانات المحدثة
    saveToStorage('sales', sales);
    saveToStorage('products', products);
    
    // تحديث الواجهات
    loadSales();
    displayProducts();
    
    // تحديث تنبيهات المخزون
    updateStockAlertsDashboard();
    
    // تحديث لوحة التحكم
    updateDashboardIfActive();
    
    // إخفاء النافذة
    hideModal('returnSaleModal');
    
    // إظهار رسالة نجاح مع تفاصيل المبلغ المرجع
    const refundText = refundDetails.length > 0 ? refundDetails.join(' + ') : formatCurrency(refundAmount);
    showMessage('✅ ' + getText('sale-returned', { amount: refundText }), 'success');
    
    currentSaleForReturn = null;
}

