function getLocalDateYYYYMMDD() {
    const now = new Date();
    return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
}
let __lastDashboardDate = getLocalDateYYYYMMDD();
setInterval(() => {
    const d = getLocalDateYYYYMMDD();
    if (d !== __lastDashboardDate) {
        __lastDashboardDate = d;
        try {
            // تحديث لوحة التحكم فور تغير اليوم
            if (document.getElementById('dashboard')?.classList.contains('active')) {
                loadDashboard();
            }
        } catch (_) {}
    }
}, 60000); // تحقق كل دقيقة

