// تحديث شبه لحظي للـ Dashboard بدون refresh
const DASHBOARD_REALTIME_INTERVAL_MS = 5000;
let dashboardRealtimeTimer = null;

function runRealtimeDashboardRefresh() {
    const dashboardPage = document.getElementById('dashboard');
    if (!dashboardPage || !dashboardPage.classList.contains('active')) return;
    updateDashboardDirectly();
    updateStockAlertsDashboard();
    if (typeof updateExpiryDashboardAlert === 'function') {
        updateExpiryDashboardAlert();
    }
}

function ensureDashboardRealtimeRefresh() {
    if (dashboardRealtimeTimer !== null) return;
    dashboardRealtimeTimer = window.setInterval(runRealtimeDashboardRefresh, DASHBOARD_REALTIME_INTERVAL_MS);
}

document.addEventListener('DOMContentLoaded', () => {
    ensureDashboardRealtimeRefresh();
    runRealtimeDashboardRefresh();
});

document.addEventListener('visibilitychange', () => {
    if (!document.hidden) {
        runRealtimeDashboardRefresh();
    }
});

window.addEventListener('storage', (event) => {
    const key = event && event.key ? event.key : '';
    if (key === 'products' || key === 'sales' || key === 'customers' || key === 'settings') {
        runRealtimeDashboardRefresh();
    }
});

// تحديث مباشر للوحة التحكم
function updateDashboardDirectly() {
    try {
        // إعادة تحميل البيانات من التخزين المحلي
        const currentProducts = loadFromStorage('products', []);
        const currentCustomers = loadFromStorage('customers', []);
        const currentSales = loadFromStorage('sales', []);
        
        // حساب إيرادات اليوم (باستخدام التاريخ المحلي، ليس UTC)
        const now = new Date();
        const today = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
        const todaySales = currentSales.filter(sale => {
            try {
                const dateValue = sale.timestamp || sale.date;
                const saleDate = new Date(dateValue);
                if (isNaN(saleDate.getTime())) return false;
                const saleLocal = `${saleDate.getFullYear()}-${String(saleDate.getMonth() + 1).padStart(2, '0')}-${String(saleDate.getDate()).padStart(2, '0')}`;
                return saleLocal === today;
            } catch (error) {
                return false;
            }
        });
        // صافي اليوم = مجموع المبيعات غير المرتجعة - مجموع الاسترجاعات المنفذة اليوم
        const isRefundPm = (pm) => {
            const v = String(pm || '').toLowerCase();
            return v === 'refund' || /refund|مرتج|مرجعة|استرجاع|ارجاع/.test(v);
        };
        const addToday = todaySales
            .filter(s => !isRefundPm(s.paymentMethod))
            .reduce((sum, s) => sum + (s.amount || 0), 0);
        const subtractReturnsToday = currentSales
            .filter(s => s.returned === true && s.returnAmount > 0 && (s.returnDate || '').trim() === today)
            .reduce((sum, s) => sum + Number(s.returnAmount || 0), 0);
        const todayRevenue = addToday - subtractReturnsToday;
        
        // احسب أيضاً عدد معاملات اليوم الصافي (يستثني فواتير المرتجع ويطرح المرتجعات المنفذة اليوم لفواتير اليوم)
        const todayNonRefundCountDir = todaySales.filter(s => !isRefundPm(s.paymentMethod)).length;
        const subtractReturnCountDir = currentSales
            .filter(s => s.returned === true && s.returnType === 'full' && s.returnAmount > 0 && (s.returnDate || '').trim() === today)
            .filter(s => {
                try {
                    const dv = s.timestamp || s.date;
                    const d = new Date(dv);
                    if (isNaN(d.getTime())) return false;
                    const ds = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
                    return ds === today;
                } catch { return false; }
            }).length;
        const netTodaySalesCountDir = Math.max(0, todayNonRefundCountDir - subtractReturnCountDir);

        // تحديث العناصر مباشرة
        const todayRevenueEl = document.getElementById('todayRevenue');
        const todaySalesEl = document.getElementById('todaySales');
        const totalProductsEl = document.getElementById('totalProducts');
        const totalCustomersEl = document.getElementById('totalCustomers');
        
        if (todayRevenueEl) {
            todayRevenueEl.textContent = formatCurrency(todayRevenue, 'USD');
        }
        if (todaySalesEl) {
            todaySalesEl.textContent = netTodaySalesCountDir;
        }
        if (totalProductsEl) {
            totalProductsEl.textContent = currentProducts.length;
        }
        if (totalCustomersEl) {
            totalCustomersEl.textContent = currentCustomers.length;
        }

        syncDashboardStatCardHints({
            todayRevenue: todayRevenue,
            todaySalesCount: netTodaySalesCountDir
        });
        
        console.log('Dashboard updated immediately:', {
            todayRevenue: todayRevenue,
            todaySales: todaySales.length,
            totalProducts: currentProducts.length,
            totalCustomers: currentCustomers.length
        });
        
    } catch (error) {
        console.error('Error updating dashboard immediately:', error);
    }
}

