// Pagination لتنبيهات المخزون — عرض جزء فقط لتحسين الأداء
const STOCK_ALERTS_DASHBOARD_LIMIT = 5;
let stockAlertsShowAll = false;

function normalizeStockAlertName(name) {
    return String(name || '').trim().toLowerCase().replace(/\s+/g, ' ');
}

function getStockAlertProductKey(product) {
    if (!product) return '';
    const normName = normalizeStockAlertName(product.name);
    if (normName) return 'name:' + normName;
    if (product.barcode && String(product.barcode).trim()) {
        return 'barcode:' + String(product.barcode).trim().toLowerCase();
    }
    if (product.id != null && product.id !== '') return 'id:' + String(product.id);
    return '';
}

function dedupeLowStockProducts(list) {
    const map = new Map();
    (Array.isArray(list) ? list : []).forEach((product) => {
        if (!product || !product.name) return;
        const key = getStockAlertProductKey(product);
        if (!key) return;
        const existing = map.get(key);
        if (!existing || getProductSellableStock(product) < getProductSellableStock(existing)) {
            map.set(key, product);
        }
    });
    return Array.from(map.values());
}

function dashboardGoToExpired() {
    const nav = document.querySelector('.nav-item[data-screen="expiryManagement"]');
    if (nav) __navigateFromNavItem(nav);
    window.setTimeout(() => {
        const filter = document.getElementById('expiryFilter');
        if (filter) filter.value = 'expired';
        try { loadExpiryManagement(); } catch (_) {}
    }, 80);
}

function dashboardOpenProduct(productId) {
    const nav = document.querySelector('.nav-item[data-screen="products"]');
    if (nav) __navigateFromNavItem(nav);
    window.setTimeout(() => {
        try {
            const idStr = String(productId);
            const numericId = Number(idStr);
            const resolvedId = Number.isFinite(numericId) && String(numericId) === idStr ? numericId : productId;
            const match = (Array.isArray(products) ? products : []).find((p) => String(p.id) === idStr || p.id === resolvedId);
            editProduct(match ? match.id : resolvedId);
        } catch (_) {}
    }, 100);
}

function renderDashboardRecentActivity() {
    const el = document.getElementById('dashboardRecentActivity');
    if (!el) return;

    const isEn = (document.documentElement.lang || 'ar') === 'en';
    const emptyMsg = getText('dashboard-recent-empty') || (isEn ? 'No recent sales yet' : 'لا مبيعات حديثة');
    const saleLabel = isEn ? 'Sale' : 'بيع';

    const isRefundPm = (pm) => {
        const v = String(pm || '').toLowerCase();
        return v === 'refund' || /refund|مرتج|مرجعة|استرجاع|ارجاع/.test(v);
    };

    const recent = (Array.isArray(sales) ? sales.slice() : [])
        .filter((sale) => sale && !isRefundPm(sale.paymentMethod))
        .sort((a, b) => {
            const ta = new Date(a.timestamp || a.date || 0).getTime();
            const tb = new Date(b.timestamp || b.date || 0).getTime();
            return tb - ta;
        })
        .slice(0, 5);

    if (!recent.length) {
        el.innerHTML = `<div class="dashboard-activity-empty">${escapeHtml(emptyMsg)}</div>`;
        return;
    }

    el.innerHTML = recent.map((sale) => {
        const ts = sale.timestamp || sale.date;
        let when = '';
        try {
            if (ts) {
                when = new Date(ts).toLocaleString([], {
                    month: 'short',
                    day: 'numeric',
                    hour: 'numeric',
                    minute: '2-digit'
                });
            }
        } catch (_) {}

        const invoiceRef = sale.invoiceNumber || sale.invoiceId || sale.id || '';
        const title = invoiceRef ? `${saleLabel} #${invoiceRef}` : saleLabel;
        const amount = formatCurrency(Number(sale.amount || 0), 'USD');

        return `
            <div class="dashboard-activity-item">
                <div class="dashboard-activity-item__main">
                    <div class="dashboard-activity-item__title">${escapeHtml(String(title))}</div>
                    <div class="dashboard-activity-item__meta">${escapeHtml(when)}</div>
                </div>
                <div class="dashboard-activity-item__amount">${escapeHtml(amount)}</div>
            </div>
        `;
    }).join('');
}

let dashboardQuickActionsBound = false;
function initDashboardQuickActions() {
    if (dashboardQuickActionsBound) return;

    const saleBtn = document.getElementById('dashboardQuickSale');
    const prodBtn = document.getElementById('dashboardQuickProduct');
    const expBtn = document.getElementById('dashboardQuickExpired');
    if (!saleBtn && !prodBtn && !expBtn) return;

    dashboardQuickActionsBound = true;

    if (saleBtn) {
        saleBtn.addEventListener('click', () => {
            const nav = document.querySelector('.nav-item[data-screen="pos"]');
            if (nav) __navigateFromNavItem(nav);
        });
    }

    if (prodBtn) {
        prodBtn.addEventListener('click', () => {
            const nav = document.querySelector('.nav-item[data-screen="products"]');
            if (nav) __navigateFromNavItem(nav);
            window.setTimeout(() => {
                const addBtn = document.getElementById('addProductBtn');
                if (addBtn) addBtn.click();
            }, 100);
        });
    }

    if (expBtn) {
        expBtn.addEventListener('click', dashboardGoToExpired);
    }
}

function toggleStockAlertsShowAll() {
    stockAlertsShowAll = !stockAlertsShowAll;
    updateStockAlertsDashboard();
}

// تحديث تنبيهات المخزون في لوحة التحكم
function updateStockAlertsDashboard() {
    const alertsList = document.getElementById('stockAlertsList');
    const summaryEl = document.getElementById('stockAlertsSummary');
    if (!alertsList) return;
    
    const isEn = (document.documentElement.lang || 'ar') === 'en';
    const t = {
        all_safe: getText('msg-all-products-safe') || (isEn ? 'All products in stock are safe' : 'جميع المنتجات في المخزون آمن'),
        out: getText('dashboard-stock-out') || (isEn ? 'Out of stock' : 'نفد المخزون'),
        critical: getText('dashboard-stock-critical') || (isEn ? 'Critical' : 'مخزون حرج'),
        low: getText('dashboard-stock-low') || (isEn ? 'Low stock' : 'مخزون منخفض'),
        product: getText('dashboard-stock-product') || (isEn ? 'Product' : 'المنتج'),
        remaining: getText('dashboard-stock-remaining') || (isEn ? 'Remaining' : 'المتبقي'),
        status: getText('dashboard-stock-status') || (isEn ? 'Status' : 'الحالة'),
        view_product: getText('dashboard-view-product') || (isEn ? 'View Product' : 'عرض المنتج'),
        restock: getText('dashboard-restock') || (isEn ? 'Restock' : 'إعادة تخزين'),
        view_all: (n) => {
            const base = getText('dashboard-view-all-alerts') || (isEn ? 'View all stock alerts' : 'عرض كل تنبيهات المخزون');
            return `${base} (${n})`;
        },
        pcs: isEn ? 'pcs' : 'قطعة'
    };

    const threshold = settings.lowStockThreshold || 10;
    const lowStockProducts = dedupeLowStockProducts(
        (Array.isArray(products) ? products : []).filter((product) =>
        product && 
        product.name && 
        getProductSellableStock(product) <= threshold
        )
    );

    if (summaryEl) {
        summaryEl.textContent = lowStockProducts.length
            ? (isEn ? `${lowStockProducts.length} alert${lowStockProducts.length === 1 ? '' : 's'}` : `${lowStockProducts.length} تنبيه`)
            : '';
    }
    
    if (lowStockProducts.length === 0) {
        stockAlertsShowAll = false;
        alertsList.innerHTML = `<div class="stock-alerts-empty">${escapeHtml(t.all_safe)}</div>`;
        return;
    }
    
    const sortedProducts = lowStockProducts.slice().sort((a, b) => getProductSellableStock(a) - getProductSellableStock(b));
    const totalCount = sortedProducts.length;
    const visibleProducts = stockAlertsShowAll
        ? sortedProducts
        : sortedProducts.slice(0, STOCK_ALERTS_DASHBOARD_LIMIT);

    const rowsHtml = visibleProducts.map((product) => {
        const stockQty = getProductSellableStock(product);
        let rowClass = 'is-low';
        let statusClass = 'is-low';
        let statusLabel = t.low;
        
        if (stockQty === 0) {
            rowClass = 'is-out';
            statusClass = '';
            statusLabel = t.out;
        } else if (stockQty <= 3) {
            rowClass = 'is-critical';
            statusClass = 'is-critical';
            statusLabel = t.critical;
        }

        const actionLabel = stockQty === 0 ? t.restock : t.view_product;
        const productId = product.id;

        return `
            <tr class="stock-alert-row ${rowClass}">
                <td><span class="stock-alert-name" title="${escapeHtml(String(product.name))}">${escapeHtml(String(product.name))}</span></td>
                <td><span class="stock-alert-qty ${rowClass}">${escapeHtml(getProductStockDisplay(product))} ${t.pcs}</span></td>
                <td><span class="stock-alert-status-pill ${statusClass}">${escapeHtml(statusLabel)}</span></td>
                <td class="stock-alert-action-cell">
                    <button type="button" class="stock-alert-action-btn" data-product-id="${escapeHtml(String(productId))}">${escapeHtml(actionLabel)}</button>
                </td>
            </tr>
        `;
    }).join('');
    
    const viewAllHtml = (!stockAlertsShowAll && totalCount > STOCK_ALERTS_DASHBOARD_LIMIT) ? `
        <div class="stock-alerts-view-all">
            <button type="button" class="stock-alerts-view-all-btn" id="stockAlertsViewAllBtn">${escapeHtml(t.view_all(totalCount))}</button>
        </div>
    ` : (stockAlertsShowAll && totalCount > STOCK_ALERTS_DASHBOARD_LIMIT) ? `
        <div class="stock-alerts-view-all">
            <button type="button" class="stock-alerts-view-all-btn" id="stockAlertsViewAllBtn">${escapeHtml(isEn ? 'Show less' : 'عرض أقل')}</button>
        </div>
    ` : '';
    
    alertsList.innerHTML = `
        <div class="stock-alerts-table-wrap">
            <table class="stock-alerts-table">
                <thead>
                    <tr>
                        <th>${escapeHtml(t.product)}</th>
                        <th>${escapeHtml(t.remaining)}</th>
                        <th>${escapeHtml(t.status)}</th>
                        <th></th>
                    </tr>
                </thead>
                <tbody>${rowsHtml}</tbody>
            </table>
        </div>
        ${viewAllHtml}
    `;

    alertsList.querySelectorAll('.stock-alert-action-btn[data-product-id]').forEach((btn) => {
        btn.addEventListener('click', (e) => {
            e.preventDefault();
            const id = btn.getAttribute('data-product-id');
            if (id != null && id !== '') dashboardOpenProduct(id);
        });
    });

    const viewAllBtn = document.getElementById('stockAlertsViewAllBtn');
    if (viewAllBtn) viewAllBtn.addEventListener('click', toggleStockAlertsShowAll);
}

// تحديث حد تحذير المخزون
document.addEventListener('DOMContentLoaded', function() {
    const thresholdInput = document.getElementById('lowStockThreshold');
    if (thresholdInput) {
        thresholdInput.addEventListener('change', function() {
            const newThreshold = parseInt(this.value);
            if (newThreshold > 0) {
                settings.lowStockThreshold = newThreshold;
                saveToStorage('settings', settings);
                showNotification('✅ تم تحديث حد تحذير المخزون', 'success', 3000);
            }
        });
    }
    
    // تفعيل/إلغاء تحذيرات المخزون
    const alertCheckbox = document.getElementById('lowStockAlertCheckbox');
    if (alertCheckbox) {
        alertCheckbox.addEventListener('change', function() {
            settings.lowStockAlert = this.checked;
            saveToStorage('settings', settings);
            toggleStockThresholdGroup();
            
            if (this.checked) {
                showNotification('✅ ' + (getText('msg-stock-alerts-enabled') || 'Stock alerts have been enabled'), 'success', 3000);
            } else {
                showNotification('🔕 ' + (getText('msg-stock-alerts-disabled') || 'Stock alerts have been disabled'), 'info', 3000);
            }
        });
    }
    
    // تحديث الصندوق
    const updateCashBtn = document.getElementById('updateCashDrawer');
    if (updateCashBtn) {
        updateCashBtn.addEventListener('click', async function() {
            const newUSD = (toUSDCents(parseFloat(document.getElementById('editCashUSD').value) || 0)) / 100;
            const newLBP = toLBPUnits(parseFloat(document.getElementById('editCashLBP').value) || 0);
            
            if (!(await uiConfirm(getText('confirm-update-cashbox').replace('{newUSD}', formatCurrency(newUSD, 'USD')).replace('{newLBP}', formatCurrency(newLBP, 'LBP')), { title: (getText('confirm') || 'Confirm') }))) {
                return;
            }
            
            // حفظ الرصيد القديم قبل التعديل (لإشعار Telegram)
            const oldUSD = (toUSDCents(cashDrawer.cashUSD || 0)) / 100;
            const oldLBP = toLBPUnits(cashDrawer.cashLBP || 0);
            const diffUSD = (toUSDCents(newUSD) - toUSDCents(oldUSD)) / 100;
            const diffLBP = toLBPUnits(newLBP) - toLBPUnits(oldLBP);
            
            // تحديث الصندوق
            cashDrawer.cashUSD = newUSD;
            cashDrawer.cashLBP = newLBP;
            cashDrawer.lastUpdate = new Date().toISOString();
            
            // إضافة معاملة توضيحية
            if (diffUSD !== 0 || diffLBP !== 0) {
                addCashDrawerTransaction({
                    date: new Date().toISOString(),
                    type: 'adjustment',
                    amountUSD: diffUSD,
                    amountLBP: diffLBP,
                    description: getText('cashbox-manual-adjustment')
                });
                
            }
            
            // حفظ وتحديث (مع مزامنة للسحابة)
            saveToStorage('cashDrawer', cashDrawer);
            pushCashDrawerSummaryToCloud();
            updateCashDrawerDisplay();
            updateCashDrawerSettings();
            sendTelegramNotification('cash_drawer', {
                operationLabel: 'Cash Drawer Updated',
                invoiceNumber: '-',
                amount: null,
                currency: '',
                dateTime: new Date(),
                sellerName: typeof getCurrentUserName === 'function' ? getCurrentUserName() : undefined,
                balanceBefore: { USD: oldUSD, LBP: oldLBP },
                balanceAfter: { USD: newUSD, LBP: newLBP },
                balanceChange: { USD: diffUSD, LBP: diffLBP }
            });
            // إغلاق نافذة إدارة الصندوق بعد نجاح التحديث
            try { hideCashDrawerModal(); } catch (_) {}
            // Toast قصير يؤكد التحديث (بدون تفاصيل طويلة)
            const toastMsg = getText('cash_drawer_updated') || getText('msg-cashbox-updated') || 'Cash drawer updated successfully';
            try {
                if (typeof showNotification === 'function') {
                    showNotification('✅ ' + toastMsg, 'success', 3000);
                } else {
                    showMessage('✅ ' + toastMsg, 'success');
                }
            } catch (_) {
                showMessage('✅ ' + toastMsg, 'success');
            }
        });
    }
});

// تم تعطيل منطق الجوال لإبقاء القائمة ثابتة دائماً
// تحسين الحسابات التلقائية
function ensureCalculationsWork() {
    // التأكد من عمل الحسابات التلقائية
    const currencySelect = document.getElementById('currency');
    const amountPaidInput = document.getElementById('amountPaid');
    const paymentCurrencySelect = document.getElementById('paymentCurrency');
    const changeCurrencySelect = document.getElementById('changeCurrency');
    
    // تهيئة: ضمان التزامن عند تحميل الصفحة
    if (currencySelect && paymentCurrencySelect && paymentCurrencySelect.value !== currencySelect.value) {
        paymentCurrencySelect.value = currencySelect.value;
    }
    
    // إضافة مستمعات إضافية للتأكد
    if (currencySelect) {
        currencySelect.addEventListener('change', function() {
            // مزامنة تلقائية مع Pay Currency
            if (paymentCurrencySelect) {
                paymentCurrencySelect.value = currencySelect.value;
                // إطلاق حدث change يدويًا لضمان تحديث الحسابات
                paymentCurrencySelect.dispatchEvent(new Event('change', { bubbles: true }));
            }
            // تحديث فوري للعربة
            setTimeout(() => {
                updateCart();
                const amountPaid = document.getElementById('amountPaid');
                if (amountPaid && amountPaid.value && amountPaid.value > 0) {
                    calculateAndDisplayChange();
                }
            }, 100);
        });
    }
    
    // مزامنة عكسية: عند تغيير Pay Currency، تحديث Currency تلقائياً
    if (paymentCurrencySelect) {
        paymentCurrencySelect.addEventListener('change', function() {
            // مزامنة عكسية مع Currency لضمان التزامن دائماً
            if (currencySelect && currencySelect.value !== paymentCurrencySelect.value) {
                currencySelect.value = paymentCurrencySelect.value;
                // إطلاق حدث change يدويًا لضمان تحديث الحسابات
                currencySelect.dispatchEvent(new Event('change', { bubbles: true }));
            }
        });
    }
    
    // تحسين الاستجابة للتغييرات
    document.addEventListener('change', function(e) {
        if (e.target.id === 'amountPaid' || 
            e.target.id === 'paymentCurrency' || 
            e.target.id === 'changeCurrency') {
            if (e.target.id === 'paymentCurrency' && typeof window.clearRemainderLBPField === 'function') window.clearRemainderLBPField();
            const amountPaid = document.getElementById('amountPaid');
            if (amountPaid && amountPaid.value && amountPaid.value > 0) {
                setTimeout(() => {
                    calculateAndDisplayChange();
                }, 50);
            }
        }
    });
    
    // إعادة حساب كل شيء عند تحميل نقطة البيع
    const posPage = document.getElementById('pos');
    if (posPage && posPage.classList.contains('active')) {
        setTimeout(() => {
            updateCart();
            const amountPaid = document.getElementById('amountPaid');
            if (amountPaid && amountPaid.value && amountPaid.value > 0) {
                calculateAndDisplayChange();
            }
        }, 200);
    }
}
// تشغيل التحسينات
setTimeout(ensureCalculationsWork, 1000);

