// Purchases system state
let purchaseInvoices = loadFromStorage('purchaseInvoices', []);

// Initialize purchases system
function initPurchasesSystem() {
    loadPurchases();
    setupPurchasesEventListeners();
    populatePurchaseSuppliers();
    populatePurchaseProducts();
}

// Add Purchase Invoice button handler
function handleAddPurchaseClick() {
    console.log('🖱️ Add Purchase Invoice button clicked');
    showModal('addPurchaseInvoiceModal');
    resetPurchaseForm();
}

// Load purchases list
function loadPurchases() {
    const tbody = document.getElementById('purchasesTableBody');
    if (!tbody) return;
    
    if (purchaseInvoices.length === 0) {
        tbody.innerHTML = '<tr><td colspan="6" style="text-align: center; padding: 20px; color: #666;">No purchase invoices</td></tr>';
        return;
    }
    
    // Sort newest first
    const sortedPurchases = [...purchaseInvoices].sort((a, b) => new Date(b.timestamp) - new Date(a.timestamp));
    
    tbody.innerHTML = sortedPurchases.map(purchase => `
        <tr>
            <td>${purchase.invoiceNumber}</td>
            <td>${purchase.supplierName}</td>
            <td>${formatCurrency(purchase.total)}</td>
            <td>${purchase.paymentMethod}</td>
            <td>${formatDateTime(purchase.timestamp)}</td>
            <td>
                <button class="action-btn print-btn" onclick="printPurchaseInvoice('${purchase.id}')" title="Print">
                    <i class="fas fa-print"></i>
                </button>
            </td>
        </tr>
    `).join('');
}

// Setup purchases event listeners
function setupPurchasesEventListeners() {
    // Add purchase invoice button
    const addBtn = document.getElementById('addPurchaseBtn');
    if (addBtn) {
        // Remove old event listeners first
        addBtn.removeEventListener('click', openAddPurchaseModal);
        // Add a new event listener
        addBtn.addEventListener('click', openAddPurchaseModal);
        console.log('✅ Add Purchase Invoice button bound (setupPurchasesEventListeners)');
    } else {
        console.warn('❌ Add Purchase Invoice button not found (setupPurchasesEventListeners)');
    }
    
    // Purchase invoice addition form
    const form = document.getElementById('addPurchaseInvoiceForm');
    if (form) {
        form.addEventListener('submit', handlePurchaseFormSubmit);
    }
    
    // Update the total when quantities or prices change
    document.addEventListener('input', (e) => {
        if (e.target.classList.contains('purchase-quantity') || e.target.classList.contains('purchase-cost')) {
            updatePurchaseSubtotal(e.target);
            updatePurchaseTotal();
        }
    });
}

// Fill out the supplier list in the purchasing form
function populatePurchaseSuppliers() {
    const select = document.getElementById('purchaseSupplier');
    if (!select) return;
    
    const suppliers = loadFromStorage('suppliers', []);
    const selectSupplierText = getText('select-supplier');
    select.innerHTML = `<option value="">${selectSupplierText}</option>` + 
        suppliers.map(s => `<option value="${s.id}">${s.name}</option>`).join('');
    
    // Update the translation of the first option
    const firstOption = select.querySelector('option[value=""]');
    if (firstOption) {
        firstOption.setAttribute('data-i18n', 'select-supplier');
        firstOption.textContent = selectSupplierText;
    }
}

// Fill out the product list in the purchase form
function populatePurchaseProducts() {
    const selects = document.querySelectorAll('.purchase-product');
    const products = loadFromStorage('products', []);
    const selectProductText = getText('select-product');
    
    selects.forEach(select => {
        if (select.children.length <= 1) { // Only if it is empty
            select.innerHTML = `<option value="" data-i18n="select-product">${selectProductText}</option>` + 
                products.map(p => `<option value="${p.id}">${p.name}</option>`).join('');
        }
    });
}

// Add a new item to the purchase form
function addPurchaseItem() {
    const container = document.querySelector('.purchase-items-container');
    if (!container) return;
    
    const selectProductText = getText('select-product');
    const quantityText = getText('quantity');
    const costPerUnitText = getText('cost-per-unit');
    
    const newRow = document.createElement('div');
    newRow.className = 'purchase-item-row';
    newRow.innerHTML = `
        <select class="purchase-product" required>
            <option value="" data-i18n="select-product">${selectProductText}</option>
        </select>
        <input type="number" class="purchase-quantity" data-i18n-placeholder="quantity" placeholder="${quantityText}" min="1" required>
        <input type="number" class="purchase-cost" data-i18n-placeholder="cost-per-unit" placeholder="${costPerUnitText}" min="0" step="0.01" required>
        <span class="purchase-subtotal">0.00</span>
        <button type="button" class="remove-purchase-item" onclick="removePurchaseItem(this)">
            <i class="fas fa-trash"></i>
        </button>
    `;
    
    container.appendChild(newRow);
    populatePurchaseProducts();
    
    // Apply translations to new items
    applyTranslations();
}

// Delete an item from the purchase form
function removePurchaseItem(button) {
    const container = document.querySelector('.purchase-items-container');
    if (container.children.length > 1) {
        button.closest('.purchase-item-row').remove();
        updatePurchaseTotal();
    }
}

// Update the item subtotal
function updatePurchaseSubtotal(input) {
    const row = input.closest('.purchase-item-row');
    const quantity = parseFloat(row.querySelector('.purchase-quantity').value) || 0;
    const cost = parseFloat(row.querySelector('.purchase-cost').value) || 0;
    const subtotal = quantity * cost;
    
    row.querySelector('.purchase-subtotal').textContent = subtotal.toFixed(2);
}

// Update the grand total of the invoice
function updatePurchaseTotal() {
    const subtotals = document.querySelectorAll('.purchase-subtotal');
    const total = Array.from(subtotals).reduce((sum, element) => {
        return sum + parseFloat(element.textContent) || 0;
    }, 0);
    
    const totalElement = document.getElementById('purchaseTotalAmount');
    if (totalElement) {
        totalElement.textContent = total.toFixed(2);
    }
}

// Reset purchase form
function resetPurchaseForm() {
    const form = document.getElementById('addPurchaseInvoiceForm');
    if (form) form.reset();
    
    // Set the current date
    const dateInput = document.getElementById('purchaseDate');
    if (dateInput) {
        const now = new Date();
        dateInput.value = now.toISOString().slice(0, 16);
    }
    
    // Reassign items
    const container = document.querySelector('.purchase-items-container');
    if (container) {
        const selectProductText = getText('select-product');
        const quantityText = getText('quantity');
        const costPerUnitText = getText('cost-per-unit');
        
        container.innerHTML = `
            <div class="purchase-item-row">
                <select class="purchase-product" required>
                    <option value="" data-i18n="select-product">${selectProductText}</option>
                </select>
                <input type="number" class="purchase-quantity" data-i18n-placeholder="quantity" placeholder="${quantityText}" min="1" required>
                <input type="number" class="purchase-cost" data-i18n-placeholder="cost-per-unit" placeholder="${costPerUnitText}" min="0" step="0.01" required>
                <span class="purchase-subtotal">0.00</span>
                <button type="button" class="remove-purchase-item" onclick="removePurchaseItem(this)">
                    <i class="fas fa-trash"></i>
                </button>
            </div>
        `;
        populatePurchaseProducts();
        // Apply translations to new items
        applyTranslations();
    }
    
    updatePurchaseTotal();
}

// Purchase form submission processing
function handlePurchaseFormSubmit(e) {
    e.preventDefault();
    
    const supplierId = document.getElementById('purchaseSupplier').value;
    const date = document.getElementById('purchaseDate').value;
    const notes = document.getElementById('purchaseNotes').value;
    
    if (!supplierId) {
        showMessage(getText('msg-choose-supplier'), 'error');
        return;
    }
    
    // Collection of items
    const items = [];
    const rows = document.querySelectorAll('.purchase-item-row');
    
    for (let row of rows) {
        const productId = row.querySelector('.purchase-product').value;
        const quantity = parseFloat(row.querySelector('.purchase-quantity').value);
        const cost = parseFloat(row.querySelector('.purchase-cost').value);
        
        if (productId && quantity > 0 && cost >= 0) {
            const product = products.find(p => p.id === productId);
            if (product) {
                items.push({
                    productId: productId,
                    productName: product.name,
                    quantity: quantity,
                    cost: cost,
                    subtotal: quantity * cost
                });
            }
        }
    }
    
    if (items.length === 0) {
        showMessage(getText('msg-add-items-to-invoice'), 'error');
        return;
    }
    
    // Calculate the total
    const total = items.reduce((sum, item) => sum + item.subtotal, 0);
    
    // Create purchase invoice
    const purchaseInvoice = {
        id: generateInvoiceId(),
        invoiceNumber: `PR-${String(purchaseInvoices.length + 1).padStart(4, '0')}`,
        supplierId: supplierId,
        supplierName: suppliers.find(s => s.id === supplierId)?.name || 'غير محدد',
        items: items,
        total: total,
        paymentMethod: 'cash', // hypothetical
        timestamp: new Date().toISOString(),
        date: date,
        notes: notes,
        type: 'purchase_record'
    };
    
    // Save the invoice
    purchaseInvoices.push(purchaseInvoice);
    saveToStorage('purchaseInvoices', purchaseInvoices);
    
    // Interface update
    loadPurchases();
    hideModal('addPurchaseInvoiceModal');
    
    showMessage(getText('purchase-invoice-created', { invoice: purchaseInvoice.invoiceNumber }), 'success');
}

// Print purchase invoice
function printPurchaseInvoice(purchaseId) {
    const purchase = purchaseInvoices.find(p => p.id === purchaseId);
    if (!purchase) {
        showMessage(getText('msg-purchase-invoice-not-found'), 'error');
        return;
    }
    
    // Create print content
    const printContent = generatePurchasePrintContent(purchase);
    
    // print
    printReceipt(printContent);
}

// Create purchase invoice print content
function generatePurchasePrintContent(purchase) {
    const storeName = settings.storeName || 'المتجر';
    const storeAddress = settings.storeAddress || '';
    const now = new Date();
    const dateTime = formatDateTime(purchase.timestamp);
    
    let content = `
        <div style="text-align: center; font-family: 'Courier New', monospace; font-size: 14px; max-width: 300px; margin: 0 auto;">
            <h2 style="margin: 0; font-size: 18px; font-weight: bold;">${storeName}</h2>
            ${storeAddress ? `<p style="margin: 5px 0; font-size: 12px;">${storeAddress}</p>` : ''}
            <hr style="border: 1px dashed #000; margin: 10px 0;">
            
            <h3 style="margin: 10px 0; font-size: 16px;">فاتورة شراء</h3>
            <p style="margin: 5px 0;"><strong>رقم الفاتورة:</strong> ${purchase.invoiceNumber}</p>
            <p style="margin: 5px 0;"><strong>المورد:</strong> ${purchase.supplierName}</p>
            <p style="margin: 5px 0;"><strong>التاريخ:</strong> ${dateTime}</p>
            
            <hr style="border: 1px dashed #000; margin: 10px 0;">
            
            <table style="width: 100%; border-collapse: collapse; margin: 10px 0;">
                <thead>
                    <tr style="border-bottom: 1px solid #000;">
                        <th style="text-align: right; padding: 5px; font-size: 12px;">الصنف</th>
                        <th style="text-align: center; padding: 5px; font-size: 12px;">الكمية</th>
                        <th style="text-align: center; padding: 5px; font-size: 12px;">السعر</th>
                        <th style="text-align: center; padding: 5px; font-size: 12px;">المجموع</th>
                    </tr>
                </thead>
                <tbody>
    `;
    
    purchase.items.forEach(item => {
        content += `
            <tr style="border-bottom: 1px dashed #ccc;">
                <td style="text-align: right; padding: 3px; font-size: 11px;">${item.productName}</td>
                <td style="text-align: center; padding: 3px; font-size: 11px;">${item.quantity}</td>
                <td style="text-align: center; padding: 3px; font-size: 11px;">${item.cost.toFixed(2)}</td>
                <td style="text-align: center; padding: 3px; font-size: 11px;">${item.subtotal.toFixed(2)}</td>
            </tr>
        `;
    });
    
    content += `
                </tbody>
            </table>
            
            <hr style="border: 1px dashed #000; margin: 10px 0;">
            
            <div style="text-align: center; margin: 10px 0;">
                <p style="font-size: 16px; font-weight: bold; margin: 5px 0;">
                    الإجمالي: ${formatCurrency(purchase.total)}
                </p>
            </div>
            
            ${purchase.notes ? `
                <hr style="border: 1px dashed #000; margin: 10px 0;">
                <p style="margin: 5px 0; font-size: 11px;"><strong>ملاحظات:</strong></p>
                <p style="margin: 5px 0; font-size: 11px; text-align: right;">${purchase.notes}</p>
            ` : ''}
            
            <hr style="border: 1px dashed #000; margin: 10px 0;">
            
            <p style="margin: 10px 0; font-size: 10px; text-align: center;">
                شكراً لتعاملكم معنا<br>
                ${now.toLocaleDateString('ar-SA')} - ${now.toLocaleTimeString('ar-SA')}
            </p>
        </div>
    `;
    
    return content;
}

