// Check subdomain in URL when page loads
async function checkSubdomainFromURL() {
    const path = window.location.pathname;
    const pathParts = path.split('/').filter(p => p);
    
    // If there is a subdomain in the URL (eg /catchcafe)
    if (pathParts.length > 0 && pathParts[0] !== '') {
        const subdomain = pathParts[0];
        
        // Avoid known subdomains (such as admin, api, etc.)
        const reservedSubdomains = ['admin', 'api', 'www', 'app', 'dashboard', 'login', 'signup'];
        if (reservedSubdomains.includes(subdomain.toLowerCase())) {
            return;
        }
        
        try {
            // Search for the user with this subdomain
            if (window.firebaseDbInstance) {
                const store = await window.firebaseDbInstance.getStoreBySubdomain(subdomain);
                if (store && store.ownerId) {
                    // If the current logged in user is the owner of this subdomain, do nothing
                    const currentUser = window.firebaseAuthInstance?.getCurrentUser();
                    if (currentUser && currentUser.uid === store.ownerId) {
                        console.log(`✅ User is on their own subdomain: ${subdomain}`);
                        return;
                    }
                    
                    // If it is another user, the store page can be shown or directed
                    console.log(`ℹ️ Subdomain found: ${subdomain} (Store: ${store.storeName})`);
                    // Additional logic can be added here to display the general store page
                }
            }
        } catch (error) {
            console.warn('Error checking subdomain from URL:', error);
        }
    }
}

// Load user data from subdomain
async function loadUserBySubdomain(subdomain) {
    try {
        if (!window.firebaseDbInstance) {
            return null;
        }
        
        const store = await window.firebaseDbInstance.getStoreBySubdomain(subdomain);
        if (store && store.ownerId) {
            const user = await window.firebaseDbInstance.getUser(store.ownerId);
            return user;
        }
        return null;
    } catch (error) {
        console.error('Error loading user by subdomain:', error);
        return null;
    }
}

// Call subdomain check on page load
if (typeof window !== 'undefined') {
    // Wait for Firebase to load
    const checkSubdomain = () => {
        if (window.firebaseDbInstance) {
            checkSubdomainFromURL();
        } else {
            setTimeout(checkSubdomain, 500);
        }
    };
    
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', checkSubdomain);
    } else {
        checkSubdomain();
    }
}

