// Promote the current user to Super Admin
window.makeMeSuperAdmin = async function() {
    try {
        if (!window.firebaseAuthInstance || !window.firebaseDbInstance) {
            throw new Error('Firebase not initialized');
        }

        const user = window.firebaseAuthInstance.getCurrentUser();
        if (!user) {
            await uiAlert('❌ ' + getText('msg-login-required'), { title: (getText('error') || 'Error') });
            return;
        }

        const userId = user.uid;
        await window.firebaseDbInstance.updateUser(userId, {
            role: 'superAdmin'
        });

        await uiAlert(getText('msg-super-admin-set'), { title: (getText('ok') || 'OK') });
        console.log('✅ You have been set as Super Admin successfully!');
        console.log('🔄 Please log out and log back in');
    } catch (error) {
        console.error('❌ Error:', error);
        await uiAlert('❌ ' + getText('msg-error-occurred', { message: error.message }), { title: (getText('error') || 'Error') });
    }
};

// Create a new Super Admin account
window.createSuperAdminAccount = async function(email, password, fullName, storeName) {
    try {
        if (!window.firebaseAuthInstance || !window.firebaseDbInstance) {
            throw new Error('Firebase not initialized');
        }

        // Create user in Firebase Auth
        const userCredential = await window.firebaseAuthInstance.auth.createUserWithEmailAndPassword(email, password);
        const user = userCredential.user;

        // Create user profile in Firestore with role = superAdmin
        await window.firebaseDbInstance.db.collection('users').doc(user.uid).set({
            uid: user.uid,
            fullName: fullName,
            email: email,
            storeName: storeName || 'Admin Store',
            subdomain: 'admin',
            role: 'superAdmin',
            createdAt: firebase.firestore.FieldValue.serverTimestamp(),
            isActive: true
        });

        // Create store
        await window.firebaseDbInstance.db.collection('stores').doc(user.uid).set({
            ownerId: user.uid,
            storeName: storeName || 'Admin Store',
            subdomain: 'admin',
            createdAt: firebase.firestore.FieldValue.serverTimestamp(),
            isActive: true
        });

        console.log('✅ Super Admin created successfully!');
        console.log('📧 Email: ' + email);
        await uiAlert(getText('msg-super-admin-created', { email: email }), { title: (getText('ok') || 'OK') });
    } catch (error) {
        console.error('❌ Error:', error);
        await uiAlert('❌ ' + getText('msg-error-occurred', { message: error.message }), { title: (getText('error') || 'Error') });
    }
};

// Check current user's role
window.checkMyRole = async function() {
    try {
        if (!window.firebaseAuthInstance) {
            throw new Error('Firebase not initialized');
        }

        const user = window.firebaseAuthInstance.getCurrentUser();
        if (!user) {
            await uiAlert('❌ ' + getText('msg-login-required'), { title: (getText('error') || 'Error') });
            return;
        }

        const userData = await window.firebaseDbInstance.getUser(user.uid);
        const role = userData ? userData.role : 'unknown';
        
        console.log('👤 Current user:', user.email);
        console.log('🔑 Role:', role);
        
        const claims = await getCurrentAuthClaims();
        const isClaimSuper = !!(claims && (claims.super_admin === true || claims.superAdmin === true));
        if (isClaimSuper) {
            await uiAlert(getText('msg-you-are-super-admin'), { title: (getText('ok') || 'OK') });
        } else {
            await uiAlert(getText('msg-not-super-admin', { role: role }), { title: (getText('error') || 'Error') });
        }
    } catch (error) {
        console.error('❌ Error:', error);
        await uiAlert('❌ ' + getText('msg-error-occurred', { message: error.message }), { title: (getText('error') || 'Error') });
    }
};

